{"command":"cd /workspace && cat > src/bgzf.c <<'EOF'
#include "bgzf.h"
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <zlib.h>

static const uint8_t g_magic[19] = "\037\213\010\4\0\0\0\0\0\377\6\0\102\103\2\0\0\0";
static const uint8_t g_eof[28] = "\037\213\010\4\0\0\0\0\0\377\6\0\102\103\2\0\033\0\3\0\0\0\0\0\0\0\0\0";

#define RBUF_SIZE 65536

static bgzf_t *bgzf_new(void) {
    bgzf_t *fp = calloc(1, sizeof(bgzf_t));
    return fp;
}

/* raw buffered reading */
static int raw_fill(bgzf_t *fp) {
    if (fp->rbuf_off < fp->rbuf_len) return fp->rbuf_len - fp->rbuf_off;
    fp->rpos += fp->rbuf_len;
    fp->rbuf_off = 0; fp->rbuf_len = 0;
    for (;;) {
        ssize_t n = read(fp->fd, fp->rbuf, RBUF_SIZE);
        if (n < 0) { if (errno == EINTR) continue; fp->errcode = 1; return -1; }
        fp->rbuf_len = (int)n;
        return (int)n;
    }
}

static ssize_t raw_read(bgzf_t *fp, uint8_t *dst, size_t n) {
    size_t got = 0;
    while (got < n) {
        if (fp->rbuf_off >= fp->rbuf_len) {
            int r = raw_fill(fp);
            if (r < 0) return -1;
            if (r == 0) break;
        }
        size_t avail = fp->rbuf_len - fp->rbuf_off;
        size_t take = n - got < avail ? n - got : avail;
        memcpy(dst + got, fp->rbuf + fp->rbuf_off, take);
        fp->rbuf_off += (int)take; got += take;
    }
    fp->raw_total += got;
    return (ssize_t)got;
}

/* ensure at least n bytes buffered (if possible) without consuming; returns available count */
static int raw_peek(bgzf_t *fp, int n) {
    if (fp->rbuf_len - fp->rbuf_off >= n) return n;
    /* compact */
    if (fp->rbuf_off > 0) {
        memmove(fp->rbuf, fp->rbuf + fp->rbuf_off, fp->rbuf_len - fp->rbuf_off);
        fp->rpos += fp->rbuf_off;
        fp->rbuf_len -= fp->rbuf_off; fp->rbuf_off = 0;
    }
    while (fp->rbuf_len < n && fp->rbuf_len < RBUF_SIZE) {
        ssize_t r = read(fp->fd, fp->rbuf + fp->rbuf_len, RBUF_SIZE - fp->rbuf_len);
        if (r < 0) { if (errno == EINTR) continue; return -1; }
        if (r == 0) break;
        fp->rbuf_len += (int)r;
    }
    return fp->rbuf_len < n ? fp->rbuf_len : n;
}

static int64_t raw_offset(bgzf_t *fp) { return fp->rpos + fp->rbuf_off; }

static int is_bgzf_header(const uint8_t *h, int n) {
    if (n < 18) return 0;
    if (h[0] != 0x1f || h[1] != 0x8b || h[2] != 8) return 0;
    if (!(h[3] & 4)) return 0;
    int xlen = h[10] | (h[11] << 8);
    /* scan extra subfields */
    int p = 12, end = 12 + xlen;
    if (end > n) end = n;
    while (p + 4 <= end) {
        int slen = h[p+2] | (h[p+3] << 8);
        if (h[p] == 'B' && h[p+1] == 'C' && slen == 2) return 1;
        p += 4 + slen;
    }
    return 0;
}

static bgzf_t *bgzf_init_read(int fd) {
    bgzf_t *fp = bgzf_new();
    fp->fd = fd;
    fp->rbuf = malloc(RBUF_SIZE);
    fp->ubuf = malloc(BGZF_MAX_BLOCK_SIZE);
    fp->cbuf = malloc(BGZF_MAX_BLOCK_SIZE);
    int n = raw_peek(fp, 18);
    if (n < 0) { fp->errcode = 1; }
    if (n >= 2 && fp->rbuf[0] == 0x1f && fp->rbuf[1] == 0x8b) {
        fp->is_compressed = 1;
        if (is_bgzf_header(fp->rbuf, n)) fp->is_gzip = 0;
        else fp->is_gzip = 1;
    } else {
        fp->is_compressed = 0;
    }
    return fp;
}

bgzf_t *bgzf_fdopen_read(int fd) { return bgzf_init_read(fd); }

bgzf_t *bgzf_open_read(const char *path) {
    int fd;
    if (strcmp(path, "-") == 0) fd = dup(0);
    else fd = open(path, O_RDONLY);
    if (fd < 0) return NULL;
    bgzf_t *fp = bgzf_init_read(fd);
    fp->owns_fd = 1;
    return fp;
}

static uint32_t le32(const uint8_t *p) { return p[0] | (p[1]<<8) | (p[2]<<16) | ((uint32_t)p[3]<<24); }

/* read next BGZF block into ubuf; returns 0 ok, -1 error, 1 EOF */
static int read_block_bgzf(bgzf_t *fp) {
    uint8_t hdr[12];
    fp->block_address = raw_offset(fp);
    ssize_t n = raw_read(fp, hdr, 12);
    if (n == 0) { fp->ublock_len = 0; fp->ublock_off = 0; return 1; }
    if (n < 12) { fp->errcode = 2; return -1; }
    if (hdr[0] != 0x1f || hdr[1] != 0x8b || hdr[2] != 8 || !(hdr[3] & 4)) { fp->errcode = 3; return -1; }
    int xlen = hdr[10] | (hdr[11] << 8);
    uint8_t *extra = fp->cbuf;
    if (raw_read(fp, extra, xlen) != xlen) { fp->errcode = 2; return -1; }
    int bsize = -1, p = 0;
    while (p + 4 <= xlen) {
        int slen = extra[p+2] | (extra[p+3] << 8);
        if (extra[p] == 'B' && extra[p+1] == 'C' && slen == 2) { bsize = extra[p+4] | (extra[p+5] << 8); break; }
        p += 4 + slen;
    }
    if (bsize < 0) { fp->errcode = 3; return -1; }
    int remaining = bsize + 1 - 12 - xlen; /* compressed data + 8 byte footer */
    if (remaining < 8 || remaining > BGZF_MAX_BLOCK_SIZE) { fp->errcode = 3; return -1; }
    if (raw_read(fp, fp->cbuf, remaining) != remaining) { fp->errcode = 2; return -1; }
    int clen = remaining - 8;
    uint32_t crc = le32(fp->cbuf + clen), isize = le32(fp->cbuf + clen + 4);
    if (isize > BGZF_MAX_BLOCK_SIZE) { fp->errcode = 3; return -1; }
    z_stream zs; memset(&zs, 0, sizeof zs);
    if (inflateInit2(&zs, -15) != Z_OK) { fp->errcode = 4; return -1; }
    zs.next_in = fp->cbuf; zs.avail_in = clen;
    zs.next_out = fp->ubuf; zs.avail_out = BGZF_MAX_BLOCK_SIZE;
    int ret = inflate(&zs, Z_FINISH);
    if (ret != Z_STREAM_END) { inflateEnd(&zs); fp->errcode = 4; return -1; }
    int ulen = (int)zs.total_out;
    inflateEnd(&zs);
    if ((uint32_t)ulen != isize) { fp->errcode = 4; return -1; }
    if (crc32(0L, fp->ubuf, ulen) != crc) { fp->errcode = 5; return -1; }
    fp->ublock_len = ulen; fp->ublock_off = 0;
    return 0;
}

static int read_block_gzip(bgzf_t *fp) {
    z_stream *zs = (z_stream*)fp->zs;
    if (!zs) {
        zs = calloc(1, sizeof(z_stream));
        fp->zs = zs;
        if (inflateInit2(zs, 15 + 32) != Z_OK) { fp->errcode = 4; return -1; }
        fp->zs_init = 1;
    }
    fp->block_address = raw_offset(fp);
    zs->next_out = fp->ubuf; zs->avail_out = BGZF_MAX_BLOCK_SIZE;
    fp->ublock_len = 0; fp->ublock_off = 0;
    for (;;) {
        if (zs->avail_in == 0) {
            if (fp->rbuf_off >= fp->rbuf_len) {
                int r = raw_fill(fp);
                if (r < 0) return -1;
                if (r == 0) {
                    fp->ublock_len = BGZF_MAX_BLOCK_SIZE - zs->avail_out;
                    return fp->ublock_len ? 0 : 1;
                }
            }
            zs->next_in = fp->rbuf + fp->rbuf_off; zs->avail_in = fp->rbuf_len - fp->rbuf_off;
        }
        int ret = inflate(zs, Z_NO_FLUSH);
        fp->rbuf_off = fp->rbuf_len - zs->avail_in;
        if (ret == Z_STREAM_END) {
            /* possibly another member */
            inflateReset(zs);
            if (zs->avail_in == 0 && fp->rbuf_off >= fp->rbuf_len) {
                int r = raw_fill(fp);
                if (r < 0) return -1;
                if (r == 0) { fp->ublock_len = BGZF_MAX_BLOCK_SIZE - zs->avail_out; return fp->ublock_len ? 0 : 1; }
                zs->next_in = fp->rbuf + fp->rbuf_off; zs->avail_in = fp->rbuf_len - fp->rbuf_off;
            }
            /* check for gzip magic; if trailing garbage, stop */
            if (zs->avail_in >= 2 && !(zs->next_in[0] == 0x1f && zs->next_in[1] == 0x8b)) {
                fp->rbuf_off = fp->rbuf_len; zs->avail_in = 0;
                fp->ublock_len = BGZF_MAX_BLOCK_SIZE - zs->avail_out; fp->eof_seen = 1;
                return fp->ublock_len ? 0 : 1;
            }
            if (zs->avail_out == 0) { fp->ublock_len = BGZF_MAX_BLOCK_SIZE; return 0; }
            continue;
        }
        if (ret != Z_OK && ret != Z_BUF_ERROR) { fp->errcode = 4; return -1; }
        if (zs->avail_out == 0) { fp->ublock_len = BGZF_MAX_BLOCK_SIZE; return 0; }
        if (ret == Z_BUF_ERROR && zs->avail_in == 0) continue;
    }
}

static int read_block_plain(bgzf_t *fp) {
    fp->block_address = raw_offset(fp);
    ssize_t n = raw_read(fp, fp->ubuf, BGZF_MAX_BLOCK_SIZE);
    if (n < 0) return -1;
    fp->ublock_len = (int)n; fp->ublock_off = 0;
    return n == 0 ? 1 : 0;
}

static int read_block(bgzf_t *fp) {
    if (!fp->is_compressed) return read_block_plain(fp);
    if (fp->is_gzip) return read_block_gzip(fp);
    return read_block_bgzf(fp);
}

ssize_t bgzf_read(bgzf_t *fp, void *buf, size_t len) {
    size_t got = 0;
    uint8_t *dst = buf;
    while (got < len) {
        if (fp->ublock_off >= fp->ublock_len) {
            int r = read_block(fp);
            if (r < 0) return -1;
            if (r == 1) break;
            if (fp->ublock_len == 0) continue;
        }
        size_t avail = fp->ublock_len - fp->ublock_off;
        size_t take = len - got < avail ? len - got : avail;
        memcpy(dst + got, fp->ubuf + fp->ublock_off, take);
        fp->ublock_off += (int)take; got += take;
    }
    return (ssize_t)got;
}

int bgzf_getc(bgzf_t *fp) {
    while (fp->ublock_off >= fp->ublock_len) {
        int r = read_block(fp);
        if (r < 0) return -2;
        if (r == 1) return -1;
    }
    return fp->ubuf[fp->ublock_off++];
}

int bgzf_peek(bgzf_t *fp, uint8_t *dst, int n) {
    /* only supports peeking within the current block, refill if empty */
    if (fp->ublock_off >= fp->ublock_len) {
        int r = read_block(fp);
        if (r < 0) return -1;
        if (r == 1) return 0;
    }
    int avail = fp->ublock_len - fp->ublock_off;
    if (n > avail) n = avail;
    memcpy(dst, fp->ubuf + fp->ublock_off, n);
    return n;
}

int bgzf_getline(bgzf_t *fp, char **buf, size_t *cap) {
    size_t l = 0;
    int state = 0;
    for (;;) {
        if (fp->ublock_off >= fp->ublock_len) {
            int r = read_block(fp);
            if (r < 0) return -2;
            if (r == 1) { state = 1; break; }
            if (fp->ublock_len == 0) continue;
        }
        uint8_t *p = fp->ubuf + fp->ublock_off;
        int avail = fp->ublock_len - fp->ublock_off;
        uint8_t *nl = memchr(p, '\n', avail);
        int take = nl ? (int)(nl - p) : avail;
        if (l + take + 1 > *cap) {
            size_t nc = *cap ? *cap : 256;
            while (nc < l + take + 1) nc *= 2;
            *buf = realloc(*buf, nc); *cap = nc;
        }
        memcpy(*buf + l, p, take); l += take;
        fp->ublock_off += take + (nl ? 1 : 0);
        if (nl) break;
    }
    if (state == 1 && l == 0) return -1;
    if (l + 1 > *cap) { *buf = realloc(*buf, l + 1); *cap = l + 1; }
    if (l > 0 && (*buf)[l-1] == '\r') l--;
    (*buf)[l] = 0;
    return (int)l;
}

int64_t bgzf_tell(bgzf_t *fp) {
    if (fp->is_write) {
        return (fp->waddr << 16) | (fp->wbuf_len & 0xffff);
    }
    if (!fp->is_compressed) return fp->block_address + fp->ublock_off;
    return (fp->block_address << 16) | (fp->ublock_off & 0xffff);
}

int bgzf_seek(bgzf_t *fp, int64_t vaddr) {
    if (fp->is_write) return -1;
    if (!fp->is_compressed) {
        if (lseek(fp->fd, vaddr, SEEK_SET) < 0) return -1;
        fp->rpos = vaddr; fp->rbuf_len = fp->rbuf_off = 0;
        fp->ublock_len = fp->ublock_off = 0; fp->block_address = vaddr;
        return 0;
    }
    if (fp->is_gzip) return -1;
    int64_t baddr = vaddr >> 16; int boff = vaddr & 0xffff;
    if (lseek(fp->fd, baddr, SEEK_SET) < 0) return -1;
    fp->rpos = baddr; fp->rbuf_len = fp->rbuf_off = 0;
    fp->ublock_len = fp->ublock_off = 0;
    fp->block_address = baddr;
    if (boff > 0) {
        int r = read_block(fp);
        if (r < 0) return -1;
        if (boff > fp->ublock_len) return -1;
        fp->ublock_off = boff;
    }
    return 0;
}

int bgzf_is_bgzf(bgzf_t *fp) { return fp->is_compressed && !fp->is_gzip; }

int bgzf_check_EOF(bgzf_t *fp) {
    if (!fp->is_compressed || fp->is_gzip) return 2;
    off_t cur = lseek(fp->fd, 0, SEEK_CUR);
    if (cur < 0) return 2; /* unseekable */
    off_t end = lseek(fp->fd, 0, SEEK_END);
    if (end < 28) { lseek(fp->fd, cur, SEEK_SET); return 0; }
    uint8_t buf[28];
    lseek(fp->fd, end - 28, SEEK_SET);
    ssize_t n = read(fp->fd, buf, 28);
    lseek(fp->fd, cur, SEEK_SET);
    if (n != 28) return 0;
    return memcmp(buf, g_eof, 28) == 0;
}

/* ---- writing ---- */

int bgzf_compress_block(uint8_t *dst, size_t *dlen, const uint8_t *src, size_t slen, int level) {
    const int HDR = 18, FTR = 8;
    if (level == 0) {
        dst[HDR] = 1;
        dst[HDR+1] = slen & 0xff; dst[HDR+2] = (slen >> 8) & 0xff;
        uint16_t nl = ~(uint16_t)slen;
        dst[HDR+3] = nl & 0xff; dst[HDR+4] = (nl >> 8) & 0xff;
        memcpy(dst + HDR + 5, src, slen);
        *dlen = slen + 5 + HDR + FTR;
    } else {
        z_stream zs; memset(&zs, 0, sizeof zs);
        if (deflateInit2(&zs, level, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY) != Z_OK) return -1;
        zs.next_in = (Bytef*)src; zs.avail_in = (uInt)slen;
        zs.next_out = dst + HDR; zs.avail_out = (uInt)(*dlen - HDR - FTR);
        int ret = deflate(&zs, Z_FINISH);
        if (ret != Z_STREAM_END) { deflateEnd(&zs); return -1; }
        size_t out = zs.total_out;
        deflateEnd(&zs);
        *dlen = out + HDR + FTR;
    }
    memcpy(dst, g_magic, HDR);
    uint32_t bs = (uint32_t)(*dlen - 1);
    dst[16] = bs & 0xff; dst[17] = (bs >> 8) & 0xff;
    uint32_t crc = crc32(crc32(0L, NULL, 0), src, (uInt)slen);
    uint8_t *f = dst + *dlen - 8;
    f[0] = crc & 0xff; f[1] = (crc>>8)&0xff; f[2] = (crc>>16)&0xff; f[3] = (crc>>24)&0xff;
    f[4] = slen & 0xff; f[5] = (slen>>8)&0xff; f[6] = (slen>>16)&0xff; f[7] = (slen>>24)&0xff;
    return 0;
}

static int write_all(int fd, const uint8_t *buf, size_t len) {
    while (len > 0) {
        ssize_t n = write(fd, buf, len);
        if (n < 0) { if (errno == EINTR) continue; return -1; }
        buf += n; len -= n;
    }
    return 0;
}

static bgzf_t *bgzf_init_write(int fd, int level) {
    bgzf_t *fp = bgzf_new();
    fp->fd = fd; fp->is_write = 1; fp->is_compressed = 1;
    fp->level = level < 0 ? -1 : (level > 9 ? 9 : level);
    fp->wbuf = malloc(BGZF_MAX_BLOCK_SIZE);
    fp->wcbuf = malloc(BGZF_MAX_BLOCK_SIZE + 1024);
    return fp;
}

bgzf_t *bgzf_fdopen_write(int fd, int level) { return bgzf_init_write(fd, level); }

bgzf_t *bgzf_open_write(const char *path, int level) {
    int fd;
    if (strcmp(path, "-") == 0) fd = dup(1);
    else fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (fd < 0) return NULL;
    bgzf_t *fp = bgzf_init_write(fd, level);
    fp->owns_fd = 1;
    return fp;
}

int bgzf_set_uncompressed(bgzf_t *fp) { fp->is_compressed = 0; return 0; }

int bgzf_flush(bgzf_t *fp) {
    if (!fp->is_write) return 0;
    if (!fp->is_compressed) {
        if (fp->wbuf_len > 0) {
            if (write_all(fp->fd, fp->wbuf, fp->wbuf_len) < 0) { fp->errcode = 6; return -1; }
            fp->waddr += fp->wbuf_len;
            fp->wbuf_len = 0;
        }
        return 0;
    }
    while (fp->wbuf_len > 0) {
        size_t dlen = BGZF_MAX_BLOCK_SIZE + 1024;
        int blen = fp->wbuf_len;
        if (bgzf_compress_block(fp->wcbuf, &dlen, fp->wbuf, blen, fp->level) < 0) {
            /* try smaller block if compression grows beyond limits */
            fp->errcode = 7; return -1;
        }
        if (dlen > BGZF_MAX_BLOCK_SIZE) {
            /* re-compress half the block */
            int half = blen / 2;
            dlen = BGZF_MAX_BLOCK_SIZE + 1024;
            if (bgzf_compress_block(fp->wcbuf, &dlen, fp->wbuf, half, fp->level) < 0) { fp->errcode = 7; return -1; }
            if (write_all(fp->fd, fp->wcbuf, dlen) < 0) { fp->errcode = 6; return -1; }
            fp->waddr += dlen;
            memmove(fp->wbuf, fp->wbuf + half, blen - half);
            fp->wbuf_len = blen - half;
            continue;
        }
        if (write_all(fp->fd, fp->wcbuf, dlen) < 0) { fp->errcode = 6; return -1; }
        fp->waddr += dlen;
        fp->wbuf_len = 0;
    }
    return 0;
}

int bgzf_flush_try(bgzf_t *fp, ssize_t size) {
    if (fp->wbuf_len + size > BGZF_BLOCK_SIZE) return bgzf_flush(fp);
    return 0;
}

ssize_t bgzf_write(bgzf_t *fp, const void *buf, size_t len) {
    const uint8_t *src = buf;
    size_t remaining = len;
    if (!fp->is_compressed) {
        while (remaining > 0) {
            int copy = BGZF_MAX_BLOCK_SIZE - fp->wbuf_len;
            if ((size_t)copy > remaining) copy = (int)remaining;
            memcpy(fp->wbuf + fp->wbuf_len, src, copy);
            fp->wbuf_len += copy; src += copy; remaining -= copy;
            if (fp->wbuf_len == BGZF_MAX_BLOCK_SIZE) if (bgzf_flush(fp) < 0) return -1;
        }
        return (ssize_t)len;
    }
    while (remaining > 0) {
        int copy = BGZF_BLOCK_SIZE - fp->wbuf_len;
        if ((size_t)copy > remaining) copy = (int)remaining;
        memcpy(fp->wbuf + fp->wbuf_len, src, copy);
        fp->wbuf_len += copy; src += copy; remaining -= copy;
        if (fp->wbuf_len == BGZF_BLOCK_SIZE) if (bgzf_flush(fp) < 0) return -1;
    }
    return (ssize_t)len;
}

int bgzf_flush_raw(bgzf_t *fp) { return bgzf_flush(fp); }
int bgzf_raw_fd(bgzf_t *fp) { return fp->fd; }

int bgzf_close(bgzf_t *fp) {
    int ret = 0;
    if (!fp) return -1;
    if (fp->is_write) {
        if (bgzf_flush(fp) < 0) ret = -1;
        if (fp->is_compressed && ret == 0) {
            if (write_all(fp->fd, g_eof, 28) < 0) ret = -1;
        }
    }
    if (fp->zs_init) { inflateEnd((z_stream*)fp->zs); }
    free(fp->zs);
    if (fp->owns_fd || fp->is_write) { if (close(fp->fd) < 0) ret = -1; }
    free(fp->rbuf); free(fp->ubuf); free(fp->cbuf); free(fp->wbuf); free(fp->wcbuf);
    free(fp);
    return ret;
}
