#ifndef SAMX_KSTRING_H
#define SAMX_KSTRING_H
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include <stdio.h>
typedef struct kstring_t { size_t l, m; char *s; } kstring_t;
#define KS_INITIALIZE { 0, 0, NULL }
static inline int ks_resize(kstring_t *s, size_t size) {
    if (s->m < size) {
        size_t m = size; m += m >> 1; m = (m + 15) & ~(size_t)15;
        char *t = realloc(s->s, m); if (!t) return -1; s->s = t; s->m = m;
    }
    return 0;
}
static inline int kputsn(const char *p, size_t l, kstring_t *s) {
    if (ks_resize(s, s->l + l + 2) < 0) return -1;
    memcpy(s->s + s->l, p, l); s->l += l; s->s[s->l] = 0; return (int)l;
}
static inline int kputs(const char *p, kstring_t *s) { return kputsn(p, strlen(p), s); }
static inline int kputc(int c, kstring_t *s) {
    if (ks_resize(s, s->l + 2) < 0) return -1;
    s->s[s->l++] = (char)c; s->s[s->l] = 0; return c;
}
static inline int kputw(int c, kstring_t *s) { char buf[16]; int n = snprintf(buf, sizeof buf, "%d", c); return kputsn(buf, n, s); }
static inline int kputuw(unsigned c, kstring_t *s) { char buf[16]; int n = snprintf(buf, sizeof buf, "%u", c); return kputsn(buf, n, s); }
static inline int kputl(long long c, kstring_t *s) { char buf[32]; int n = snprintf(buf, sizeof buf, "%lld", c); return kputsn(buf, n, s); }
static inline int kputull(unsigned long long c, kstring_t *s) { char buf[32]; int n = snprintf(buf, sizeof buf, "%llu", c); return kputsn(buf, n, s); }
static inline int ksprintf(kstring_t *s, const char *fmt, ...) {
    va_list ap; va_start(ap, fmt);
    char *tmp = NULL; int n = vasprintf(&tmp, fmt, ap); va_end(ap);
    if (n < 0) return -1;
    kputsn(tmp, n, s); free(tmp); return n;
}
static inline void ks_free(kstring_t *s) { free(s->s); s->s = NULL; s->l = s->m = 0; }
static inline char *ks_release(kstring_t *s) { char *p = s->s; s->s = NULL; s->l = s->m = 0; return p; }
