#ifndef SAMX_STRMAP_H
#define SAMX_STRMAP_H
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
/* simple string -> int64/ptr hash map with open addressing */
typedef struct { char *key; int64_t val; void *ptr; int used; } strmap_entry_t;
typedef struct { strmap_entry_t *e; size_t n, cap; } strmap_t;

static inline uint64_t strmap_hash(const char *s) {
    uint64_t h = 1469598103934665603ULL;
    while (*s) { h ^= (unsigned char)*s++; h *= 1099511628211ULL; }
    return h;
}
static inline strmap_t *strmap_new(void) { strmap_t *m = calloc(1, sizeof *m); m->cap = 64; m->e = calloc(m->cap, sizeof *m->e); return m; }
static inline void strmap_free(strmap_t *m) { if (!m) return; for (size_t i = 0; i < m->cap; i++) free(m->e[i].key); free(m->e); free(m); }
static inline strmap_entry_t *strmap_find(strmap_t *m, const char *key) {
    size_t i = strmap_hash(key) & (m->cap - 1);
    while (m->e[i].used) { if (strcmp(m->e[i].key, key) == 0) return &m->e[i]; i = (i + 1) & (m->cap - 1); }
    return NULL;
}
static inline void strmap_grow(strmap_t *m) {
    size_t ncap = m->cap * 2; strmap_entry_t *ne = calloc(ncap, sizeof *ne);
    for (size_t i = 0; i < m->cap; i++) if (m->e[i].used) {
        size_t j = strmap_hash(m->e[i].key) & (ncap - 1);
        while (ne[j].used) j = (j + 1) & (ncap - 1);
        ne[j] = m->e[i];
    }
    free(m->e); m->e = ne; m->cap = ncap;
}
/* returns entry; *is_new set if newly created */
static inline strmap_entry_t *strmap_put(strmap_t *m, const char *key, int *is_new) {
    strmap_entry_t *x = strmap_find(m, key);
    if (x) { if (is_new) *is_new = 0; return x; }
    if (m->n * 2 >= m->cap) strmap_grow(m);
    size_t i = strmap_hash(key) & (m->cap - 1);
    while (m->e[i].used) i = (i + 1) & (m->cap - 1);
    m->e[i].used = 1; m->e[i].key = strdup(key); m->e[i].val = 0; m->e[i].ptr = NULL; m->n++;
    if (is_new) *is_new = 1;
    return &m->e[i];
}
static inline int strmap_del(strmap_t *m, const char *key) {
    strmap_entry_t *x = strmap_find(m, key);
    if (!x) return -1;
    /* rebuild: simple approach */
    free(x->key); x->key = NULL; x->used = 0; m->n--;
    /* re-insert subsequent cluster entries */
    size_t i = ((size_t)(x - m->e) + 1) & (m->cap - 1);
    while (m->e[i].used) {
        strmap_entry_t t = m->e[i]; m->e[i].used = 0; m->e[i].key = NULL; m->n--;
        strmap_entry_t *y = strmap_put(m, t.key, NULL); y->val = t.val; y->ptr = t.ptr; free(t.key);
        i = (i + 1) & (m->cap - 1);
    }
    return 0;
}
static inline int strmap_get(strmap_t *m, const char *key, int64_t *val) {
    strmap_entry_t *x = strmap_find(m, key); if (!x) return -1; if (val) *val = x->val; return 0;
}
static inline void strmap_set(strmap_t *m, const char *key, int64_t val) { strmap_entry_t *x = strmap_put(m, key, NULL); x->val = val; }
#endif
EOF
