cd /workspace && cat > src/sam_hdr.c <<'EOF'
#include "sam.h"
#include "strmap.h"
#include "log.h"
#include <string.h>
#include <ctype.h>

sam_hdr_t *sam_hdr_init(void) {
    sam_hdr_t *h = calloc(1, sizeof(sam_hdr_t));
    h->name2tid = strmap_new();
    h->ref_count = 1;
    return h;
}

void sam_hdr_destroy(sam_hdr_t *h) {
    if (!h) return;
    if (--h->ref_count > 0) return;
    for (int i = 0; i < h->n_lines; i++) free(h->lines[i]);
    free(h->lines);
    for (int i = 0; i < h->n_targets; i++) free(h->targets[i].name);
    free(h->targets);
    strmap_free((strmap_t*)h->name2tid);
    free(h->text);
    free(h);
}

sam_hdr_t *sam_hdr_dup(const sam_hdr_t *h) {
    sam_hdr_t *n = sam_hdr_init();
    for (int i = 0; i < h->n_lines; i++) sam_hdr_add_line_str(n, h->lines[i]);
    /* copy targets exactly (binary refs may differ from SQ lines) */
    for (int i = 0; i < n->n_targets; i++) free(n->targets[i].name);
    free(n->targets); n->targets = NULL; n->n_targets = n->m_targets = 0;
    strmap_free((strmap_t*)n->name2tid); n->name2tid = strmap_new();
    for (int i = 0; i < h->n_targets; i++) {
        if (n->n_targets == n->m_targets) { n->m_targets = n->m_targets ? n->m_targets * 2 : 16; n->targets = realloc(n->targets, n->m_targets * sizeof(sam_target_t)); }
        n->targets[n->n_targets].name = strdup(h->targets[i].name);
        n->targets[n->n_targets].len = h->targets[i].len;
        strmap_set((strmap_t*)n->name2tid, h->targets[i].name, n->n_targets);
        n->n_targets++;
    }
    if (h->text) { n->text = malloc(h->l_text + 1); memcpy(n->text, h->text, h->l_text); n->text[h->l_text] = 0; n->l_text = h->l_text; }
    n->dirty = h->dirty;
    return n;
}

int sam_hdr_line_type_is(const char *line, const char *type) {
    return line[0] == '@' && line[1] == type[0] && line[2] == type[1];
}

char *hdr_line_tag(const char *line, const char *tag) {
    const char *p = line;
    /* skip the @XX type */
    p = strchr(p, '\t');
    while (p) {
        p++;
        if (p[0] == tag[0] && p[1] == tag[1] && p[2] == ':') {
            const char *e = strchr(p, '\t');
            size_t l = e ? (size_t)(e - p - 3) : strlen(p + 3);
            char *r = malloc(l + 1); memcpy(r, p + 3, l); r[l] = 0;
            return r;
        }
        p = strchr(p, '\t');
    }
    return NULL;
}

static int add_target(sam_hdr_t *h, const char *name, int64_t len) {
    if (h->n_targets == h->m_targets) {
        h->m_targets = h->m_targets ? h->m_targets * 2 : 16;
        h->targets = realloc(h->targets, h->m_targets * sizeof(sam_target_t));
    }
    h->targets[h->n_targets].name = strdup(name);
    h->targets[h->n_targets].len = len;
    strmap_set((strmap_t*)h->name2tid, name, h->n_targets);
    h->n_targets++;
    return h->n_targets - 1;
}

/* validate a line; returns 0 ok, -1 error (message printed) */
static int validate_line(sam_hdr_t *h, const char *line, int lineno, int add_sq) {
    if (line[0] != '@') return -1;
    const char *type = line + 1;
    if (!(strncmp(type, "HD", 2) == 0 || strncmp(type, "SQ", 2) == 0 || strncmp(type, "RG", 2) == 0 ||
          strncmp(type, "PG", 2) == 0 || strncmp(type, "CO", 2) == 0)) {
        return -2;
    }
    if (strncmp(type, "CO", 2) == 0) return 0;
    /* check key:value pairs */
    const char *p = line + 3;
    if (*p && *p != '\t') { return -2; }
    while (*p == '\t') {
        p++;
        const char *e = strchr(p, '\t');
        size_t l = e ? (size_t)(e - p) : strlen(p);
        if (l < 3 || p[2] != ':') {
            log_error("sam_hrecs_error", "Malformed key:value pair at line %d: \"%s\"", lineno, line + 3);
            return -1;
        }
        p += l;
    }
    if (strncmp(type, "SQ", 2) == 0) {
        char *sn = hdr_line_tag(line, "SN");
        if (!sn) { log_error("sam_hrecs_update_hashes", "Header includes @SQ line with no SN: tag"); return -1; }
        char *ln = hdr_line_tag(line, "LN");
        if (!ln) { log_error("sam_hrecs_update_hashes", "Header includes @SQ line \"%s\" with no LN: tag", sn); free(sn); return -1; }
        if (add_sq) {
            int64_t v;
            if (strmap_get((strmap_t*)h->name2tid, sn, &v) == 0) {
                log_error("sam_hrecs_update_hashes", "Duplicate entry \"%s\" in sam header", sn);
                free(sn); free(ln); return -1;
            }
            add_target(h, sn, strtoll(ln, NULL, 10));
        }
        free(sn); free(ln);
    } else if (strncmp(type, "RG", 2) == 0) {
        char *id = hdr_line_tag(line, "ID");
        if (!id) { log_error("sam_hrecs_update_hashes", "Header includes @RG line with no ID: tag"); return -1; }
        /* duplicate check */
        for (int i = 0; i < h->n_lines; i++) {
            if (sam_hdr_line_type_is(h->lines[i], "RG")) {
                char *o = hdr_line_tag(h->lines[i], "ID");
                if (o && strcmp(o, id) == 0) { log_error("sam_hrecs_update_hashes", "Duplicate entry \"%s\" in sam header", id); free(o); free(id); return -1; }
                free(o);
            }
        }
        free(id);
    } else if (strncmp(type, "PG", 2) == 0) {
        char *id = hdr_line_tag(line, "ID");
        if (!id) { return -1; }
        for (int i = 0; i < h->n_lines; i++) {
            if (sam_hdr_line_type_is(h->lines[i], "PG")) {
                char *o = hdr_line_tag(h->lines[i], "ID");
                if (o && strcmp(o, id) == 0) { log_warning("sam_hrecs_update_hashes", "Duplicate entry \"%s\" in sam header", id); }
                free(o);
            }
        }
        free(id);
    }
    return 0;
}

static void push_line(sam_hdr_t *h, const char *line, size_t len) {
    if (h->n_lines == h->m_lines) {
        h->m_lines = h->m_lines ? h->m_lines * 2 : 32;
        h->lines = realloc(h->lines, h->m_lines * sizeof(char*));
    }
    char *s = malloc(len + 1); memcpy(s, line, len); s[len] = 0;
    h->lines[h->n_lines++] = s;
    h->dirty = 1;
}

int sam_hdr_add_line_str(sam_hdr_t *h, const char *line) {
    int r = validate_line(h, line, h->n_lines + 1, 1);
    if (r < 0) return -1;
    push_line(h, line, strlen(line));
    return 0;
}

int sam_hdr_parse_text_lines(sam_hdr_t *h, const char *text, size_t len, int *bad) {
    size_t i = 0; int lineno = 0;
    while (i < len) {
        size_t j = i;
        while (j < len && text[j] != '\n') j++;
        size_t l = j - i;
        if (l > 0 && text[i + l - 1] == '\r') l--;
        lineno++;
        if (l == 0) { i = j + 1; continue; }
        char *tmp = malloc(l + 1); memcpy(tmp, text + i, l); tmp[l] = 0;
        int r = validate_line(h, tmp, lineno, 1);
        if (r < 0) { free(tmp); if (bad) *bad = r; return -1; }
        push_line(h, tmp, l);
        free(tmp);
        i = j + 1;
    }
    return 0;
}

int sam_hdr_parse_text(sam_hdr_t *h, const char *text, size_t len) {
    int bad = 0;
    if (sam_hdr_parse_text_lines(h, text, len, &bad) < 0) return -1;
    free(h->text);
    h->text = malloc(len + 1); memcpy(h->text, text, len); h->text[len] = 0; h->l_text = len;
    h->dirty = 0;
    return 0;
}

int sam_hdr_add_lines(sam_hdr_t *h, const char *text, size_t len) {
    return sam_hdr_parse_text_lines(h, text, len, NULL);
}

int sam_hdr_add_sq(sam_hdr_t *h, const char *name, int64_t len) {
    char *line = NULL;
    if (asprintf(&line, "@SQ\tSN:%s\tLN:%lld", name, (long long)len) < 0) return -1;
    int r = sam_hdr_add_line_str(h, line);
    free(line);
    return r;
}

int sam_hdr_name2tid(sam_hdr_t *h, const char *name) {
    int64_t v;
    if (strmap_get((strmap_t*)h->name2tid, name, &v) < 0) return -1;
    return (int)v;
}

const char *sam_hdr_tid2name(const sam_hdr_t *h, int tid) {
    if (tid < 0 || tid >= h->n_targets) return NULL;
    return h->targets[tid].name;
}

int64_t sam_hdr_tid2len(const sam_hdr_t *h, int tid) {
    if (tid < 0 || tid >= h->n_targets) return 0;
    return h->targets[tid].len;
}

int sam_hdr_nref(const sam_hdr_t *h) { return h->n_targets; }

static void rebuild_text(sam_hdr_t *h) {
    kstring_t ks = KS_INITIALIZE;
    /* @HD lines first */
    for (int i = 0; i < h->n_lines; i++) if (sam_hdr_line_type_is(h->lines[i], "HD")) { kputs(h->lines[i], &ks); kputc('\n', &ks); }
    for (int i = 0; i < h->n_lines; i++) if (!sam_hdr_line_type_is(h->lines[i], "HD")) { kputs(h->lines[i], &ks); kputc('\n', &ks); }
    free(h->text);
    if (ks.s == NULL) { ks.s = calloc(1, 1); }
    h->text = ks.s; h->l_text = ks.l;
    h->dirty = 0;
}

const char *sam_hdr_str(sam_hdr_t *h) {
    if (h->dirty || !h->text) rebuild_text(h);
    return h->text;
}

size_t sam_hdr_length(sam_hdr_t *h) {
    if (h->dirty || !h->text) rebuild_text(h);
    return h->l_text;
}

int sam_hdr_find_line_id(sam_hdr_t *h, const char *type, const char *idtag, const char *idval) {
    for (int i = 0; i < h->n_lines; i++) {
        if (!sam_hdr_line_type_is(h->lines[i], type)) continue;
        if (!idtag) return i;
        char *v = hdr_line_tag(h->lines[i], idtag);
        if (v && strcmp(v, idval) == 0) { free(v); return i; }
        free(v);
    }
    return -1;
}

int sam_hdr_find_line_pos(sam_hdr_t *h, const char *type, int pos) {
    int n = 0;
    for (int i = 0; i < h->n_lines; i++) {
        if (!sam_hdr_line_type_is(h->lines[i], type)) continue;
        if (n == pos) return i;
        n++;
    }
    return -1;
}

int sam_hdr_count_lines(sam_hdr_t *h, const char *type) {
    int n = 0;
    for (int i = 0; i < h->n_lines; i++) if (sam_hdr_line_type_is(h->lines[i], type)) n++;
    return n;
}

char *sam_hdr_find_tag_id(sam_hdr_t *h, const char *type, const char *idtag, const char *idval, const char *tag) {
    int i = sam_hdr_find_line_id(h, type, idtag, idval);
    if (i < 0) return NULL;
    return hdr_line_tag(h->lines[i], tag);
}

char *sam_hdr_find_tag_pos(sam_hdr_t *h, const char *type, int pos, const char *tag) {
    int i = sam_hdr_find_line_pos(h, type, pos);
    if (i < 0) return NULL;
    return hdr_line_tag(h->lines[i], tag);
}

void sam_hdr_rebuild_targets(sam_hdr_t *h) {
    for (int i = 0; i < h->n_targets; i++) free(h->targets[i].name);
    h->n_targets = 0;
    strmap_free((strmap_t*)h->name2tid); h->name2tid = strmap_new();
    for (int i = 0; i < h->n_lines; i++) {
        if (!sam_hdr_line_type_is(h->lines[i], "SQ")) continue;
        char *sn = hdr_line_tag(h->lines[i], "SN");
        char *ln = hdr_line_tag(h->lines[i], "LN");
        if (sn && ln) add_target(h, sn, strtoll(ln, NULL, 10));
        free(sn); free(ln);
    }
}

int sam_hdr_remove_line_idx(sam_hdr_t *h, int idx) {
    if (idx < 0 || idx >= h->n_lines) return -1;
    int was_sq = sam_hdr_line_type_is(h->lines[idx], "SQ");
    free(h->lines[idx]);
    memmove(h->lines + idx, h->lines + idx + 1, (h->n_lines - idx - 1) * sizeof(char*));
    h->n_lines--;
    h->dirty = 1;
    if (was_sq) sam_hdr_rebuild_targets(h);
    return 0;
}

int sam_hdr_remove_lines_type(sam_hdr_t *h, const char *type) {
    int j = 0, removed = 0;
    for (int i = 0; i < h->n_lines; i++) {
        if (sam_hdr_line_type_is(h->lines[i], type)) { free(h->lines[i]); removed++; }
        else h->lines[j++] = h->lines[i];
    }
    h->n_lines = j;
    if (removed) { h->dirty = 1; if (strcmp(type, "SQ") == 0) sam_hdr_rebuild_targets(h); }
    return 0;
}

int sam_hdr_remove_line_id(sam_hdr_t *h, const char *type, const char *idtag, const char *idval) {
    int i = sam_hdr_find_line_id(h, type, idtag, idval);
    if (i < 0) return -1;
    return sam_hdr_remove_line_idx(h, i);
}

int sam_hdr_update_line_idx(sam_hdr_t *h, int idx, const char *tag, const char *value) {
    if (idx < 0 || idx >= h->n_lines) return -1;
    char *line = h->lines[idx];
    kstring_t ks = KS_INITIALIZE;
    kputsn(line, 3, &ks);
    const char *p = line + 3;
    int found = 0;
    while (*p == '\t') {
        p++;
        const char *e = strchr(p, '\t');
        size_t l = e ? (size_t)(e - p) : strlen(p);
        if (l >= 3 && p[0] == tag[0] && p[1] == tag[1] && p[2] == ':') {
            found = 1;
            if (value) { kputc('\t', &ks); kputsn(tag, 2, &ks); kputc(':', &ks); kputs(value, &ks); }
        } else {
            kputc('\t', &ks); kputsn(p, l, &ks);
        }
        p += l;
    }
    if (!found && value) { kputc('\t', &ks); kputsn(tag, 2, &ks); kputc(':', &ks); kputs(value, &ks); }
    free(h->lines[idx]);
    h->lines[idx] = ks.s;
    h->dirty = 1;
    if (sam_hdr_line_type_is(h->lines[idx], "SQ")) sam_hdr_rebuild_targets(h);
    return 0;
}

int sam_hdr_update_hd(sam_hdr_t *h, const char *tag, const char *value) {
    int i = sam_hdr_find_line_id(h, "HD", NULL, NULL);
    if (i < 0) {
        char *line = NULL;
        if (asprintf(&line, "@HD\tVN:1.6\t%s:%s", tag, value) < 0) return -1;
        /* insert at front */
        if (h->n_lines == h->m_lines) { h->m_lines = h->m_lines ? h->m_lines * 2 : 32; h->lines = realloc(h->lines, h->m_lines * sizeof(char*)); }
        memmove(h->lines + 1, h->lines, h->n_lines * sizeof(char*));
        h->lines[0] = line; h->n_lines++; h->dirty = 1;
        return 0;
    }
    return sam_hdr_update_line_idx(h, i, tag, value);
}

/* Determine PG chain end following observed htslib behaviour */
int sam_hdr_pg_chain_end(sam_hdr_t *h, char **id_out) {
    int npg = 0;
    for (int i = 0; i < h->n_lines; i++) if (sam_hdr_line_type_is(h->lines[i], "PG")) npg++;
    *id_out = NULL;
    if (npg == 0) return -1;
    char **ids = calloc(npg, sizeof(char*));
    char **pps = calloc(npg, sizeof(char*));
    int *is_parent = calloc(npg, sizeof(int));
    int *has_pp = calloc(npg, sizeof(int));
    int k = 0;
    for (int i = 0; i < h->n_lines; i++) if (sam_hdr_line_type_is(h->lines[i], "PG")) {
        ids[k] = hdr_line_tag(h->lines[i], "ID");
        pps[k] = hdr_line_tag(h->lines[i], "PP");
        k++;
    }
    for (int i = 0; i < npg; i++) {
        if (!pps[i]) continue;
        for (int j = 0; j < npg; j++) if (ids[j] && strcmp(ids[j], pps[i]) == 0) { is_parent[j] = 1; has_pp[i] = 1; break; }
    }
    int chosen = -1;
    for (int i = 0; i < npg; i++) if (!is_parent[i] && has_pp[i]) chosen = i;
    if (chosen < 0) for (int i = 0; i < npg; i++) if (!is_parent[i]) chosen = i;
    if (chosen >= 0 && ids[chosen]) *id_out = strdup(ids[chosen]);
    for (int i = 0; i < npg; i++) { free(ids[i]); free(pps[i]); }
    free(ids); free(pps); free(is_parent); free(has_pp);
    return *id_out ? 0 : -1;
}

char *sam_hdr_unique_pg_id(sam_hdr_t *h, const char *name) {
    if (sam_hdr_find_line_id(h, "PG", "ID", name) < 0) return strdup(name);
    char *buf = NULL;
    for (int cnt = 1; ; cnt++) {
        free(buf);
        if (asprintf(&buf, "%s.%d", name, cnt) < 0) return NULL;
        if (sam_hdr_find_line_id(h, "PG", "ID", buf) < 0) return buf;
    }
}

int sam_hdr_add_pg(sam_hdr_t *h, const char *name, const char *version, const char *cl, const char *unused) {
    (void)unused;
    char *pp = NULL;
    sam_hdr_pg_chain_end(h, &pp);
    char *id = sam_hdr_unique_pg_id(h, name);
    kstring_t ks = KS_INITIALIZE;
    kputs("@PG\tID:", &ks); kputs(id, &ks);
    kputs("\tPN:", &ks); kputs(name, &ks);
    if (pp) { kputs("\tPP:", &ks); kputs(pp, &ks); }
    if (version) { kputs("\tVN:", &ks); kputs(version, &ks); }
    if (cl) { kputs("\tCL:", &ks); kputs(cl, &ks); }
    push_line(h, ks.s, ks.l);
    free(ks.s); free(id); free(pp);
    return 0;
}
