bam1_t *bam_init1(void) { return calloc(1, sizeof(bam1_t)); }
void bam_destroy1(bam1_t *b) { if (!b) return; free(b->data); free(b); }

int bam_set_data_cap(bam1_t *b, size_t need) {
    if (need <= b->m_data) return 0;
    size_t m = need; m += 32; m = (m + 7) & ~(size_t)7;
    uint8_t *d = realloc(b->data, m);
    if (!d) return -1;
    b->data = d; b->m_data = (uint32_t)m;
    return 0;
}

bam1_t *bam_copy1(bam1_t *dst, const bam1_t *src) {
    if (bam_set_data_cap(dst, src->l_data) < 0) return NULL;
    memcpy(dst->data, src->data, src->l_data);
    dst->l_data = src->l_data;
    dst->core = src->core;
    dst->id = src->id;
    return dst;
}

bam1_t *bam_dup1(const bam1_t *src) {
    bam1_t *b = bam_init1();
    if (!bam_copy1(b, src)) { bam_destroy1(b); return NULL; }
    return b;
}

int64_t bam_cigar2qlen(int n_cigar, const uint32_t *cigar) {
    int64_t l = 0;
    for (int k = 0; k < n_cigar; k++) if (bam_cigar_type(bam_cigar_op(cigar[k])) & 1) l += bam_cigar_oplen(cigar[k]);
    return l;
}

int64_t bam_cigar2rlen(int n_cigar, const uint32_t *cigar) {
    int64_t l = 0;
    for (int k = 0; k < n_cigar; k++) if (bam_cigar_type(bam_cigar_op(cigar[k])) & 2) l += bam_cigar_oplen(cigar[k]);
    return l;
}

int64_t bam_endpos(const bam1_t *b) {
    int64_t rlen = (b->core.flag & BAM_FUNMAP) ? 0 : bam_cigar2rlen(b->core.n_cigar, bam_get_cigar(b));
    if (rlen == 0) rlen = 1;
    return b->core.pos + rlen;
}

int hts_reg2bin(int64_t beg, int64_t end, int min_shift, int depth) {
    int l, s = min_shift, t = ((1 << ((depth << 1) + depth)) - 1) / 7;
    for (--end, l = depth; l > 0; --l, s += 3, t -= 1 << ((l << 1) + l))
        if (beg >> s == end >> s) return t + (int)(beg >> s);
    return 0;
}

int bam_reg2bin(int64_t beg, int64_t end) { return hts_reg2bin(beg, end, 14, 5); }

int bam_set1(bam1_t *b, size_t l_qname, const char *qname, uint16_t flag, int32_t tid, int64_t pos, uint8_t mapq,
             size_t n_cigar, const uint32_t *cigar, int32_t mtid, int64_t mpos, int64_t isize, size_t l_seq, const char *seq, const char *qual, size_t l_aux) {
    if (l_qname == 0) { qname = "*"; l_qname = 1; }
    size_t qname_nuls = 4 - l_qname % 4;
    size_t need = l_qname + qname_nuls + n_cigar * 4 + (l_seq + 1) / 2 + l_seq + l_aux;
    if (bam_set_data_cap(b, need) < 0) return -1;
    b->core.pos = pos; b->core.tid = tid;
    b->core.bin = bam_reg2bin(pos, pos + (n_cigar ? bam_cigar2rlen((int)n_cigar, cigar) : 1));
    b->core.qual = mapq; b->core.l_extranul = (uint8_t)(qname_nuls - 1);
    b->core.flag = flag; b->core.l_qname = (uint16_t)(l_qname + qname_nuls);
    b->core.n_cigar = (uint32_t)n_cigar; b->core.l_qseq = (int32_t)l_seq;
    b->core.mtid = mtid; b->core.mpos = mpos; b->core.isize = isize;
    uint8_t *d = b->data;
    memcpy(d, qname, l_qname); d += l_qname;
    for (size_t i = 0; i < qname_nuls; i++) *d++ = 0;
    memcpy(d, cigar, n_cigar * 4); d += n_cigar * 4;
    for (size_t i = 0; i + 1 < l_seq; i += 2) *d++ = (seq_nt16_table[(unsigned char)seq[i]] << 4) | seq_nt16_table[(unsigned char)seq[i+1]];
    if (l_seq & 1) *d++ = seq_nt16_table[(unsigned char)seq[l_seq - 1]] << 4;
    if (qual) memcpy(d, qual, l_seq); else memset(d, 0xff, l_seq);
    d += l_seq;
    b->l_data = (int)(d - b->data);
    return (int)b->l_data;
}

int bam_set_qname(bam1_t *b, const char *qname) {
    size_t l = strlen(qname) + 1;
    size_t nuls = (4 - l % 4) % 4;
    int old = b->core.l_qname;
    int newl = (int)(l + nuls);
    if (bam_set_data_cap(b, b->l_data - old + newl) < 0) return -1;
    memmove(b->data + newl, b->data + old, b->l_data - old);
    memcpy(b->data, qname, l);
    memset(b->data + l, 0, nuls);
    b->l_data += newl - old;
    b->core.l_qname = (uint16_t)newl; b->core.l_extranul = (uint8_t)nuls;
    return 0;
}

int bam_set_cigar(bam1_t *b, const uint32_t *cigar, int n_cigar) {
    int old = b->core.n_cigar * 4, newl = n_cigar * 4;
    if (bam_set_data_cap(b, b->l_data - old + newl) < 0) return -1;
    uint8_t *p = b->data + b->core.l_qname;
    memmove(p + newl, p + old, b->l_data - b->core.l_qname - old);
    memcpy(p, cigar, newl);
    b->l_data += newl - old;
    b->core.n_cigar = n_cigar;
    return 0;
}

/* ---- aux ---- */
int bam_aux_type2size(uint8_t type) {
    switch (type) {
    case 'A': case 'c': case 'C': return 1;
    case 's': case 'S': return 2;
    case 'i': case 'I': case 'f': return 4;
    case 'd': return 8;
    default: return 0;
    }
}

uint8_t *bam_aux_skip(const uint8_t *s, const uint8_t *end) {
    /* s points at type byte */
    if (s >= end) return NULL;
    uint8_t t = *s++;
    int sz = bam_aux_type2size(t);
    if (sz) { if (s + sz > end) return NULL; return (uint8_t*)s + sz; }
    if (t == 'Z' || t == 'H') {
        while (s < end && *s) s++;
        if (s >= end) return NULL;
        return (uint8_t*)s + 1;
    }
    if (t == 'B') {
        if (s + 5 > end) return NULL;
        uint8_t st = *s; int esz = bam_aux_type2size(st);
        if (!esz) return NULL;
        uint32_t n = s[1] | (s[2] << 8) | (s[3] << 16) | ((uint32_t)s[4] << 24);
        s += 5;
        if ((uint64_t)n * esz > (uint64_t)(end - s)) return NULL;
        return (uint8_t*)s + (size_t)n * esz;
    }
    return NULL;
}

uint8_t *bam_aux_first(const bam1_t *b) {
    uint8_t *s = bam_get_aux(b), *end = b->data + b->l_data;
    if (s + 3 > end) return NULL;
    return s + 2;
}

uint8_t *bam_aux_next(const bam1_t *b, const uint8_t *s) {
    uint8_t *end = b->data + b->l_data;
    uint8_t *n = bam_aux_skip(s, end);
    if (!n) return NULL;
    if (n + 3 > end) return NULL;
    return n + 2;
}

uint8_t *bam_aux_get(const bam1_t *b, const char tag[2]) {
    uint8_t *s = bam_get_aux(b), *end = b->data + b->l_data;
    while (s + 3 <= end) {
        if (s[0] == tag[0] && s[1] == tag[1]) return s + 2;
        uint8_t *n = bam_aux_skip(s + 2, end);
        if (!n) return NULL;
        s = n;
    }
    return NULL;
}

int bam_aux_del(bam1_t *b, uint8_t *s) {
    uint8_t *end = b->data + b->l_data;
    uint8_t *n = bam_aux_skip(s, end);
    if (!n) return -1;
    uint8_t *start = s - 2;
    memmove(start, n, end - n);
    b->l_data -= (int)(n - start);
    return 0;
}

int bam_aux_append(bam1_t *b, const char tag[2], char type, int len, const uint8_t *data) {
    if (bam_set_data_cap(b, b->l_data + 3 + len) < 0) return -1;
    uint8_t *s = b->data + b->l_data;
    s[0] = tag[0]; s[1] = tag[1]; s[2] = type;
    memcpy(s + 3, data, len);
    b->l_data += 3 + len;
    return 0;
}

int bam_aux_append_int(bam1_t *b, const char tag[2], int64_t val) {
    uint8_t buf[4]; char t;
    if (val < INT32_MIN || val > UINT32_MAX) return -1;
    if (val < 0) {
        if (val >= INT8_MIN) { t = 'c'; buf[0] = (int8_t)val; return bam_aux_append(b, tag, t, 1, buf); }
        if (val >= INT16_MIN) { t = 's'; int16_t v = (int16_t)val; memcpy(buf, &v, 2); return bam_aux_append(b, tag, t, 2, buf); }
        t = 'i'; int32_t v = (int32_t)val; memcpy(buf, &v, 4); return bam_aux_append(b, tag, t, 4, buf);
    } else {
        if (val <= UINT8_MAX) { t = 'C'; buf[0] = (uint8_t)val; return bam_aux_append(b, tag, t, 1, buf); }
        if (val <= UINT16_MAX) { t = 'S'; uint16_t v = (uint16_t)val; memcpy(buf, &v, 2); return bam_aux_append(b, tag, t, 2, buf); }
        t = 'I'; uint32_t v = (uint32_t)val; memcpy(buf, &v, 4); return bam_aux_append(b, tag, t, 4, buf);
    }
}

int bam_aux_update_int(bam1_t *b, const char tag[2], int64_t val) {
    uint8_t *s = bam_aux_get(b, tag);
    if (s) bam_aux_del(b, s);
    return bam_aux_append_int(b, tag, val);
}

int bam_aux_update_str(bam1_t *b, const char tag[2], int len, const char *data) {
    uint8_t *s = bam_aux_get(b, tag);
    if (s) bam_aux_del(b, s);
    /* len includes NUL if data[len-1]==0, else add */
    if (len > 0 && data[len-1] == 0) return bam_aux_append(b, tag, 'Z', len, (const uint8_t*)data);
    if (bam_set_data_cap(b, b->l_data + 4 + len) < 0) return -1;
    uint8_t *p = b->data + b->l_data;
    p[0] = tag[0]; p[1] = tag[1]; p[2] = 'Z'; memcpy(p + 3, data, len); p[3 + len] = 0;
    b->l_data += 4 + len;
    return 0;
}

int bam_aux_update_float(bam1_t *b, const char tag[2], float val) {
    uint8_t *s = bam_aux_get(b, tag);
    if (s) bam_aux_del(b, s);
    return bam_aux_append(b, tag, 'f', 4, (uint8_t*)&val);
}

int bam_aux_is_int(const uint8_t *s) {
    switch (*s) { case 'c': case 'C': case 's': case 'S': case 'i': case 'I': return 1; default: return 0; }
}

int64_t bam_aux2i(const uint8_t *s) {
    int type = *s++;
    switch (type) {
    case 'c': return *(int8_t*)s;
    case 'C': return *(uint8_t*)s;
    case 's': { int16_t v; memcpy(&v, s, 2); return v; }
    case 'S': { uint16_t v; memcpy(&v, s, 2); return v; }
    case 'i': { int32_t v; memcpy(&v, s, 4); return v; }
    case 'I': { uint32_t v; memcpy(&v, s, 4); return v; }
    default: errno = EINVAL; return 0;
    }
}

double bam_aux2f(const uint8_t *s) {
    int type = *s++;
    if (type == 'f') { float f; memcpy(&f, s, 4); return f; }
    if (type == 'd') { double d; memcpy(&d, s, 8); return d; }
    if (bam_aux_is_int(s - 1)) return (double)bam_aux2i(s - 1);
    errno = EINVAL; return 0;
}

char *bam_aux2Z(const uint8_t *s) {
    if (*s == 'Z' || *s == 'H') return (char*)s + 1;
    errno = EINVAL; return NULL;
}

char bam_aux2A(const uint8_t *s) {
    if (*s == 'A') return *(char*)(s + 1);
    errno = EINVAL; return 0;
}

/* ---- CIGAR parsing ---- */
int sam_parse_cigar(const char *in, char **end, uint32_t **a_cigar, size_t *a_mem, int *n_cigar) {
    const char *p = in;
    int n = 0;
    if (*p == '*') { if (end) *end = (char*)p + 1; *n_cigar = 0; return 0; }
    while (*p && *p != '\t') {
        if (!isdigit((unsigned char)*p)) { log_error("read_ncigar", "Corrupted CIGAR string"); *n_cigar = 0; return -1; }
        unsigned long len = 0;
        while (isdigit((unsigned char)*p)) { len = len * 10 + (*p - '0'); if (len > 0xfffffff) { log_error("sam_parse_cigar", "CIGAR length too long"); return -1; } p++; }
        const char *op = strchr(BAM_CIGAR_STR, *p);
        if (!*p || !op || *p == '\0') {
            if (!*p || *p == '\t') { log_error("read_ncigar", "No CIGAR operations"); return -1; }
            log_error("sam_parse_cigar", "Unrecognized CIGAR operator '%c'", *p); return -1;
        }
        if ((size_t)n + 1 > *a_mem) {
            *a_mem = *a_mem ? *a_mem * 2 : 16;
            *a_cigar = realloc(*a_cigar, *a_mem * 4);
        }
        (*a_cigar)[n++] = bam_cigar_gen(len, op - BAM_CIGAR_STR);
        p++;
    }
    if (n == 0) { log_error("read_ncigar", "No CIGAR operations"); return -1; }
    if (end) *end = (char*)p;
    *n_cigar = n;
    return n;
}

int bam_cigar_str(const bam1_t *b, kstring_t *str) {
    const uint32_t *c = bam_get_cigar(b);
    if (b->core.n_cigar == 0) return kputc('*', str);
    for (uint32_t i = 0; i < b->core.n_cigar; i++) { kputuw(bam_cigar_oplen(c[i]), str); kputc(bam_cigar_opchr(c[i]), str); }
    return 0;
}

/* ---- parsing a SAM line ---- */
static int parse_uint(const char **pp, uint64_t max, uint64_t *out) {
    const char *p = *pp;
    if (!isdigit((unsigned char)*p)) return -1;
    uint64_t v = 0;
    while (isdigit((unsigned char)*p)) {
        if (v > (max - (*p - '0')) / 10) return -2;
        v = v * 10 + (*p - '0'); p++;
    }
    *out = v; *pp = p;
    return 0;
}

static int parse_int64(const char **pp, int64_t *out) {
    const char *p = *pp; int neg = 0;
    if (*p == '-') { neg = 1; p++; } else if (*p == '+') p++;
    if (!isdigit((unsigned char)*p)) return -1;
    uint64_t v = 0;
    while (isdigit((unsigned char)*p)) { if (v > (uint64_t)INT64_MAX / 10) return -2; v = v * 10 + (*p - '0'); p++; }
    *out = neg ? -(int64_t)v : (int64_t)v; *pp = p;
    return 0;
}

static int aux_add(bam1_t *b, const void *data, int len) {
    if (bam_set_data_cap(b, b->l_data + len) < 0) return -1;
    memcpy(b->data + b->l_data, data, len); b->l_data += len;
    return 0;
}

static int aux_parse(const char *s, const char *end, bam1_t *b) {
    /* s points at first aux field (after tab) */
    while (s < end) {
        const char *q = s;
        /* find end of this field */
        const char *fe = memchr(q, '\t', end - q); if (!fe) fe = end;
        if (fe - q < 5 || q[2] != ':' || q[4] != ':') { log_error("aux_parse", "Incomplete aux field"); return -1; }
        char tag[2] = { q[0], q[1] };
        char type = q[3];
        const char *v = q + 5;
        if (type == 'A') {
            if (fe - v < 1) { log_error("aux_parse", "Incomplete aux field"); return -1; }
            aux_add(b, tag, 2); aux_add(b, &type, 1); aux_add(b, v, 1);
        } else if (type == 'i') {
            const char *p = v; int neg = 0;
            if (*p == '-') { neg = 1; p++; } else if (*p == '+') p++;
            uint64_t uv = 0; int overflow = 0;
            while (p < fe && isdigit((unsigned char)*p)) { if (uv > 0xfffffffffULL) overflow = 1; uv = uv * 10 + (*p - '0'); p++; }
            if (overflow || (neg && uv > (uint64_t)INT32_MAX + 1) || (!neg && uv > UINT32_MAX)) { log_error("aux_parse", "numeric value out of allowed range"); return -1; }
            int64_t val = neg ? -(int64_t)uv : (int64_t)uv;
            aux_add(b, tag, 2);
            if (val < 0) {
                if (val >= INT8_MIN) { char t = 'c'; int8_t x = (int8_t)val; aux_add(b, &t, 1); aux_add(b, &x, 1); }
                else if (val >= INT16_MIN) { char t = 's'; int16_t x = (int16_t)val; aux_add(b, &t, 1); aux_add(b, &x, 2); }
                else { char t = 'i'; int32_t x = (int32_t)val; aux_add(b, &t, 1); aux_add(b, &x, 4); }
            } else {
                if (val <= UINT8_MAX) { char t = 'C'; uint8_t x = (uint8_t)val; aux_add(b, &t, 1); aux_add(b, &x, 1); }
                else if (val <= UINT16_MAX) { char t = 'S'; uint16_t x = (uint16_t)val; aux_add(b, &t, 1); aux_add(b, &x, 2); }
                else { char t = 'I'; uint32_t x = (uint32_t)val; aux_add(b, &t, 1); aux_add(b, &x, 4); }
            }
        } else if (type == 'f') {
            char *e; float f = strtof(v, &e); (void)e;
            aux_add(b, tag, 2); aux_add(b, &type, 1); aux_add(b, &f, 4);
        } else if (type == 'd') {
            char *e; double d = strtod(v, &e); (void)e;
            aux_add(b, tag, 2); aux_add(b, &type, 1); aux_add(b, &d, 8);
        } else if (type == 'Z' || type == 'H') {
            aux_add(b, tag, 2); aux_add(b, &type, 1); aux_add(b, v, (int)(fe - v)); char z = 0; aux_add(b, &z, 1);
        } else if (type == 'B') {
            if (fe - v < 1) { log_error("aux_parse", "Incomplete aux field"); return -1; }
            char st = *v;
            int esz = bam_aux_type2size((uint8_t)st);
            if (!esz || st == 'A' || st == 'd') { log_error("aux_parse", "Unrecognized type B:%c", st); return -1; }
            /* count elements */
            const char *p = v + 1; uint32_t n = 0;
            for (const char *x = p; x < fe; x++) if (*x == ',') n++;
            aux_add(b, tag, 2); aux_add(b, &type, 1); aux_add(b, &st, 1); aux_add(b, &n, 4);
            for (uint32_t i = 0; i < n; i++) {
                if (p >= fe || *p != ',') { log_error("aux_parse", "Incomplete aux field"); return -1; }
                p++;
                char *e;
                switch (st) {
                case 'c': { long x = strtol(p, &e, 10); int8_t y = (int8_t)x; aux_add(b, &y, 1); break; }
                case 'C': { unsigned long x = strtoul(p, &e, 10); uint8_t y = (uint8_t)x; aux_add(b, &y, 1); break; }
                case 's': { long x = strtol(p, &e, 10); int16_t y = (int16_t)x; aux_add(b, &y, 2); break; }
                case 'S': { unsigned long x = strtoul(p, &e, 10); uint16_t y = (uint16_t)x; aux_add(b, &y, 2); break; }
                case 'i': { long long x = strtoll(p, &e, 10); int32_t y = (int32_t)x; aux_add(b, &y, 4); break; }
                case 'I': { unsigned long long x = strtoull(p, &e, 10); uint32_t y = (uint32_t)x; aux_add(b, &y, 4); break; }
                case 'f': { float y = strtof(p, &e); aux_add(b, &y, 4); break; }
                default: e = (char*)p;
                }
                p = e;
            }
        } else {
            log_error("aux_parse", "unrecognized type '%c'", type);
            return -1;
        }
        s = fe < end ? fe + 1 : end;
    }
    return 0;
}

int sam_parse1(const char *line, int len, sam_hdr_t *h, bam1_t *b) {
    const char *p = line, *end = line + len, *q;
    b->l_data = 0;
    memset(&b->core, 0, sizeof b->core);
    /* 1 QNAME */
    q = memchr(p, '\t', end - p); if (!q) return -1;
    size_t lq = q - p;
    if (lq == 0) { log_error("sam_parse1", "empty query name"); return -1; }
    if (lq > 254) { log_error("sam_parse1", "query name too long"); return -1; }
    int extranul = (int)((4 - ((lq + 1) % 4)) % 4);
    if (bam_set_data_cap(b, lq + 1 + extranul) < 0) return -1;
    memcpy(b->data, p, lq); memset(b->data + lq, 0, 1 + extranul);
    b->l_data = (int)(lq + 1 + extranul);
    b->core.l_qname = (uint16_t)b->l_data; b->core.l_extranul = (uint8_t)extranul;
    p = q + 1;
    /* 2 FLAG */
    uint64_t uv;
    if (parse_uint(&p, 0xffff, &uv) < 0) return -1;
    b->core.flag = (uint16_t)uv;
    if (*p != '\t') return -1; p++;
    /* 3 RNAME */
    q = memchr(p, '\t', end - p); if (!q) return -1;
    if (q - p == 1 && *p == '*') b->core.tid = -1;
    else {
        char tmp[1024]; size_t l = q - p; if (l >= sizeof tmp) l = sizeof tmp - 1;
        memcpy(tmp, p, l); tmp[l] = 0;
        b->core.tid = sam_hdr_name2tid(h, tmp);
        if (b->core.tid < 0) {
            if (h->n_targets == 0) { log_error("sam_parse1", "no SQ lines present in the header"); return -1; }
            log_warning("sam_parse1", "unrecognized reference name \"%s\"; treated as unmapped", tmp);
            b->core.flag |= BAM_FUNMAP;
        }
    }
    p = q + 1;
    /* 4 POS */
    if (parse_uint(&p, INT64_MAX, &uv) < 0) return -1;
    b->core.pos = (int64_t)uv - 1;
    if (*p != '\t') return -1; p++;
    if (b->core.pos < 0 && b->core.tid >= 0) {
        log_warning("sam_parse1", "mapped query cannot have zero coordinate; treated as unmapped");
        b->core.flag |= BAM_FUNMAP;
    }
    if (b->core.tid < 0) b->core.flag |= BAM_FUNMAP;
    /* 5 MAPQ */
    if (parse_uint(&p, 0xff, &uv) < 0) return -1;
    b->core.qual = (uint8_t)uv;
    if (*p != '\t') return -1; p++;
    /* 6 CIGAR */
    if (*p == '*') { b->core.n_cigar = 0; p++; if (*p != '\t') return -1; p++; }
    else {
        uint32_t *cig = NULL; size_t mem = 0; int n = 0; char *e;
        if (sam_parse_cigar(p, &e, &cig, &mem, &n) < 0) { free(cig); return -1; }
        if (*e != '\t') { free(cig); return -1; }
        if (bam_set_data_cap(b, b->l_data + n * 4) < 0) { free(cig); return -1; }
        memcpy(b->data + b->l_data, cig, n * 4); b->l_data += n * 4;
        b->core.n_cigar = n;
        free(cig);
        p = e + 1;
        if (!(b->core.flag & BAM_FUNMAP) || 1) {
            uint32_t *c = bam_get_cigar(b);
            b->core.bin = bam_reg2bin(b->core.pos, b->core.pos + bam_cigar2rlen(n, c));
        }
    }
    if (b->core.n_cigar == 0 || (b->core.flag & BAM_FUNMAP)) {
        if (b->core.n_cigar == 0) b->core.bin = bam_reg2bin(b->core.pos, b->core.pos + 1);
        else {
            uint32_t *c = bam_get_cigar(b);
            int64_t rlen = bam_cigar2rlen(b->core.n_cigar, c); if (rlen == 0) rlen = 1;
            b->core.bin = bam_reg2bin(b->core.pos, b->core.pos + rlen);
        }
    }
    /* 7 RNEXT */
    q = memchr(p, '\t', end - p); if (!q) return -1;
    if (q - p == 1 && *p == '*') b->core.mtid = -1;
    else if (q - p == 1 && *p == '=') b->core.mtid = b->core.tid;
    else {
        char tmp[1024]; size_t l = q - p; if (l >= sizeof tmp) l = sizeof tmp - 1;
        memcpy(tmp, p, l); tmp[l] = 0;
        b->core.mtid = sam_hdr_name2tid(h, tmp);
        if (b->core.mtid < 0) {
            if (h->n_targets == 0) { log_error("sam_parse1", "no SQ lines present in the header"); return -1; }
            log_warning("sam_parse1", "unrecognized mate reference name \"%s\"; treated as unmapped", tmp);
            b->core.flag |= BAM_FMUNMAP;
        }
    }
    p = q + 1;
    /* 8 PNEXT */
    if (parse_uint(&p, INT64_MAX, &uv) < 0) return -1;
    b->core.mpos = (int64_t)uv - 1;
    if (*p != '\t') return -1; p++;
    if (b->core.mpos < 0 && b->core.mtid >= 0) {
        log_warning("sam_parse1", "mapped mate cannot have zero coordinate; treated as unmapped");
        b->core.flag |= BAM_FMUNMAP;
        b->core.mtid = -1;
    }
    /* 9 TLEN */
    int64_t iv;
    if (parse_int64(&p, &iv) < 0) return -1;
    b->core.isize = iv;
    if (*p != '\t') return -1; p++;
    /* 10 SEQ */
    q = memchr(p, '\t', end - p); if (!q) q = end;
    int lseq;
    if (q - p == 1 && *p == '*') { lseq = 0; }
    else {
        lseq = (int)(q - p);
        if (bam_set_data_cap(b, b->l_data + (lseq + 1) / 2 + lseq) < 0) return -1;
        uint8_t *d = b->data + b->l_data;
        int i;
        for (i = 0; i + 1 < lseq; i += 2) d[i >> 1] = (seq_nt16_table[(unsigned char)p[i]] << 4) | seq_nt16_table[(unsigned char)p[i+1]];
        if (i < lseq) d[i >> 1] = seq_nt16_table[(unsigned char)p[i]] << 4;
        b->l_data += (lseq + 1) / 2;
    }
    b->core.l_qseq = lseq;
    if (b->core.n_cigar && lseq) {
        int64_t ql = bam_cigar2qlen(b->core.n_cigar, bam_get_cigar(b));
        if (ql != lseq) { log_error("sam_parse1", "CIGAR and query sequence are of different length"); return -1; }
    }
    if (q >= end) {
        return -1; /* QUAL missing */
    }
    p = q + 1;
    /* 11 QUAL */
    q = memchr(p, '\t', end - p); if (!q) q = end;
    if (bam_set_data_cap(b, b->l_data + lseq) < 0) return -1;
    if (q - p == 1 && *p == '*') { memset(b->data + b->l_data, 0xff, lseq); b->l_data += lseq; }
    else {
        if (q - p != lseq) { log_error("sam_parse1", "SEQ and QUAL are of different length"); return -1; }
        uint8_t *d = b->data + b->l_data;
        for (int i = 0; i < lseq; i++) d[i] = (uint8_t)(p[i] - 33);
        b->l_data += lseq;
    }
    if (q < end) {
        if (aux_parse(q + 1, end, b) < 0) return -1;
    }
    return 0;
}

/* ---- formatting ---- */
int sam_format_aux1(const uint8_t *key, uint8_t type, const uint8_t *s, const uint8_t *end, kstring_t *str) {
    kputc('\t', str); kputsn((const char*)key, 2, str); kputc(':', str);
    switch (type) {
    case 'A': kputc('A', str); kputc(':', str); kputc(*s, str); s++; break;
    case 'c': kputs("i:", str); kputw(*(int8_t*)s, str); s++; break;
    case 'C': kputs("i:", str); kputw(*(uint8_t*)s, str); s++; break;
    case 's': { int16_t v; memcpy(&v, s, 2); kputs("i:", str); kputw(v, str); s += 2; break; }
    case 'S': { uint16_t v; memcpy(&v, s, 2); kputs("i:", str); kputw(v, str); s += 2; break; }
    case 'i': { int32_t v; memcpy(&v, s, 4); kputs("i:", str); kputw(v, str); s += 4; break; }
    case 'I': { uint32_t v; memcpy(&v, s, 4); kputs("i:", str); kputuw(v, str); s += 4; break; }
    case 'f': { float v; memcpy(&v, s, 4); ksprintf(str, "f:%g", v); s += 4; break; }
    case 'd': { double v; memcpy(&v, s, 8); ksprintf(str, "d:%g", v); s += 8; break; }
    case 'Z': case 'H': kputc(type, str); kputc(':', str); while (s < end && *s) kputc(*s++, str); break;
    case 'B': {
        uint8_t st = *s; uint32_t n; memcpy(&n, s + 1, 4); s += 5;
        kputs("B:", str); kputc(st, str);
        for (uint32_t i = 0; i < n; i++) {
            kputc(',', str);
            switch (st) {
            case 'c': kputw(*(int8_t*)s, str); s++; break;
            case 'C': kputw(*(uint8_t*)s, str); s++; break;
            case 's': { int16_t v; memcpy(&v, s, 2); kputw(v, str); s += 2; break; }
            case 'S': { uint16_t v; memcpy(&v, s, 2); kputw(v, str); s += 2; break; }
            case 'i': { int32_t v; memcpy(&v, s, 4); kputw(v, str); s += 4; break; }
            case 'I': { uint32_t v; memcpy(&v, s, 4); kputuw(v, str); s += 4; break; }
            case 'f': { float v; memcpy(&v, s, 4); ksprintf(str, "%g", v); s += 4; break; }
            default: return -1;
            }
        }
        break;
    }
    default: return -1;
    }
    return 0;
}

int sam_format1(const sam_hdr_t *h, const bam1_t *b, kstring_t *str) {
    const bam1_core_t *c = &b->core;
    str->l = 0;
    kputsn(bam_get_qname(b), c->l_qname - 1 - c->l_extranul, str); kputc('\t', str);
    kputw(c->flag, str); kputc('\t', str);
    if (c->tid >= 0 && c->tid < h->n_targets) kputs(h->targets[c->tid].name, str); else kputc('*', str);
    kputc('\t', str);
    kputl(c->pos + 1, str); kputc('\t', str);
    kputw(c->qual, str); kputc('\t', str);
    bam_cigar_str(b, str); kputc('\t', str);
    if (c->mtid < 0) kputc('*', str);
    else if (c->mtid == c->tid) kputc('=', str);
    else if (c->mtid < h->n_targets) kputs(h->targets[c->mtid].name, str);
    else kputc('*', str);
    kputc('\t', str);
    kputl(c->mpos + 1, str); kputc('\t', str);
    kputl(c->isize, str); kputc('\t', str);
    if (c->l_qseq) {
        uint8_t *s = bam_get_seq(b);
        if (ks_resize(str, str->l + c->l_qseq * 2 + 4) < 0) return -1;
        for (int i = 0; i < c->l_qseq; i++) str->s[str->l++] = seq_nt16_str[bam_seqi(s, i)];
        str->s[str->l++] = '\t';
        uint8_t *q = bam_get_qual(b);
        if (q[0] == 0xff) str->s[str->l++] = '*';
        else for (int i = 0; i < c->l_qseq; i++) str->s[str->l++] = (char)(q[i] + 33);
        str->s[str->l] = 0;
    } else kputs("*\t*", str);
    uint8_t *s = bam_get_aux(b), *end = b->data + b->l_data;
    while (s + 3 <= end) {
        uint8_t *key = s; uint8_t type = s[2];
        uint8_t *n = bam_aux_skip(s + 2, end);
        if (!n) { log_error("sam_format1", "Corrupted aux data for read %s", bam_get_qname(b)); return -1; }
        if (sam_format_aux1(key, type, s + 3, end, str) < 0) return -1;
        s = n;
    }
    return (int)str->l;
}

/* ---- BAM binary ---- */
static inline uint32_t rd32(const uint8_t *p) { uint32_t v; memcpy(&v, p, 4); return v; }
static inline void wr32(uint8_t *p, uint32_t v) { memcpy(p, &v, 4); }

int bam_read1(bgzf_t *fp, bam1_t *b) {
    uint8_t x[36];
    ssize_t n = bgzf_read(fp, x, 4);
    if (n == 0) return -1;
    if (n != 4) return -2;
    int32_t block_len = (int32_t)rd32(x);
    if (block_len < 32) return -4;
    if (bgzf_read(fp, x + 4, 32) != 32) return -3;
    bam1_core_t *c = &b->core;
    c->tid = (int32_t)rd32(x + 4);
    c->pos = (int32_t)rd32(x + 8);
    uint32_t v = rd32(x + 12);
    c->bin = v >> 16; c->qual = (v >> 8) & 0xff; uint32_t l_qname = v & 0xff;
    v = rd32(x + 16);
    c->flag = v >> 16; c->n_cigar = v & 0xffff;
    c->l_qseq = (int32_t)rd32(x + 20);
    c->mtid = (int32_t)rd32(x + 24);
    c->mpos = (int32_t)rd32(x + 28);
    c->isize = (int32_t)rd32(x + 32);
    int new_l_data = block_len - 32;
    if (new_l_data < 0 || (uint32_t)new_l_data < l_qname + c->n_cigar * 4 + (c->l_qseq + 1) / 2 + c->l_qseq) return -4;
    c->l_extranul = (l_qname % 4 != 0) ? (uint8_t)(4 - l_qname % 4) : 0;
    if (bam_set_data_cap(b, new_l_data + c->l_extranul) < 0) return -4;
    if (bgzf_read(fp, b->data, l_qname) != (ssize_t)l_qname) return -3;
    memset(b->data + l_qname, 0, c->l_extranul);
    c->l_qname = (uint16_t)(l_qname + c->l_extranul);
    int rest = new_l_data - (int)l_qname;
    if (bgzf_read(fp, b->data + c->l_qname, rest) != rest) return -3;
    b->l_data = new_l_data + c->l_extranul;
    if (c->n_cigar && c->l_qseq) {
        /* handle CG tag for long cigars: skip */
    }
    return 4 + block_len;
}

int bam_write1(bgzf_t *fp, const bam1_t *b) {
    const bam1_core_t *c = &b->core;
    uint8_t x[36];
    uint32_t block_len = b->l_data - c->l_extranul + 32;
    wr32(x, block_len);
    wr32(x + 4, (uint32_t)c->tid);
    wr32(x + 8, (uint32_t)(int32_t)c->pos);
    uint32_t bin = c->bin;
    wr32(x + 12, ((uint32_t)bin << 16) | ((uint32_t)c->qual << 8) | (uint32_t)(c->l_qname - c->l_extranul));
    wr32(x + 16, ((uint32_t)c->flag << 16) | (c->n_cigar & 0xffff));
    wr32(x + 20, (uint32_t)c->l_qseq);
    wr32(x + 24, (uint32_t)c->mtid);
    wr32(x + 28, (uint32_t)(int32_t)c->mpos);
    wr32(x + 32, (uint32_t)(int32_t)c->isize);
    if (bgzf_flush_try(fp, 4 + block_len) < 0) return -1;
    if (bgzf_write(fp, x, 36) < 0) return -1;
    if (bgzf_write(fp, b->data, c->l_qname - c->l_extranul) < 0) return -1;
    if (bgzf_write(fp, b->data + c->l_qname, b->l_data - c->l_qname) < 0) return -1;
    return 4 + (int)block_len;
}

int bam_hdr_read(bgzf_t *fp, sam_hdr_t **hp) {
    uint8_t buf[8];
    if (bgzf_read(fp, buf, 4) != 4 || memcmp(buf, "BAM\1", 4) != 0) {
        log_error("bam_hdr_read", "Invalid BAM binary header");
        return -1;
    }
    if (bgzf_read(fp, buf, 4) != 4) return -1;
    int32_t l_text = (int32_t)rd32(buf);
    if (l_text < 0) return -1;
    char *text = malloc(l_text + 1);
    if (bgzf_read(fp, text, l_text) != l_text) { free(text); return -1; }
    text[l_text] = 0;
    /* strip trailing NULs */
    size_t tl = l_text; while (tl > 0 && text[tl-1] == 0) tl--;
    if (bgzf_read(fp, buf, 4) != 4) { free(text); return -1; }
    int32_t n_ref = (int32_t)rd32(buf);
    sam_hdr_t *h = sam_hdr_init();
    char **names = calloc(n_ref > 0 ? n_ref : 1, sizeof(char*));
    int64_t *lens = calloc(n_ref > 0 ? n_ref : 1, sizeof(int64_t));
    for (int i = 0; i < n_ref; i++) {
        if (bgzf_read(fp, buf, 4) != 4) goto fail;
        int32_t l_name = (int32_t)rd32(buf);
        if (l_name <= 0) goto fail;
        names[i] = malloc(l_name + 1);
        if (bgzf_read(fp, names[i], l_name) != l_name) goto fail;
        names[i][l_name] = 0;
        if (bgzf_read(fp, buf, 4) != 4) goto fail;
        lens[i] = (uint32_t)rd32(buf);
    }
    /* parse text but build targets from binary list */
    {
        int bad = 0;
        /* parse lines without SQ registration: do a two-phase approach */
        sam_hdr_t *tmp = h;
        if (sam_hdr_parse_text_lines(tmp, text, tl, &bad) < 0) goto fail;
        /* reset targets to binary list */
        for (int i = 0; i < h->n_targets; i++) free(h->targets[i].name);
        h->n_targets = 0;
        extern void sam_hdr_reset_targets(sam_hdr_t*);
        sam_hdr_reset_targets(h);
        int nsq = sam_hdr_count_lines(h, "SQ");
        for (int i = 0; i < n_ref; i++) {
            if (h->n_targets == h->m_targets) { h->m_targets = h->m_targets ? h->m_targets * 2 : 16; h->targets = realloc(h->targets, h->m_targets * sizeof(sam_target_t)); }
            h->targets[h->n_targets].name = strdup(names[i]);
            h->targets[h->n_targets].len = lens[i];
            extern void sam_hdr_register_name(sam_hdr_t*, const char*, int);
            sam_hdr_register_name(h, names[i], h->n_targets);
            h->n_targets++;
        }
        if (nsq == 0 && n_ref > 0) {
            for (int i = 0; i < n_ref; i++) {
                char *line = NULL;
                if (asprintf(&line, "@SQ\tSN:%s\tLN:%lld", names[i], (long long)lens[i]) < 0) goto fail;
                if (h->n_lines == h->m_lines) { h->m_lines = h->m_lines ? h->m_lines * 2 : 32; h->lines = realloc(h->lines, h->m_lines * sizeof(char*)); }
                h->lines[h->n_lines++] = line;
            }
            h->dirty = 1;
        } else {
            h->text = malloc(tl + 1); memcpy(h->text, text, tl); h->text[tl] = 0; h->l_text = tl; h->dirty = 0;
        }
    }
    for (int i = 0; i < n_ref; i++) free(names[i]);
    free(names); free(lens); free(text);
    *hp = h;
    return 0;
fail:
    for (int i = 0; i < n_ref; i++) free(names[i]);
    free(names); free(lens); free(text);
    sam_hdr_destroy(h);
    return -1;
}

int bam_hdr_write(bgzf_t *fp, sam_hdr_t *h) {
    const char *text = sam_hdr_str(h);
    uint32_t l_text = (uint32_t)sam_hdr_length(h);
    uint8_t buf[4];
    if (bgzf_write(fp, "BAM\1", 4) < 0) return -1;
    wr32(buf, l_text); if (bgzf_write(fp, buf, 4) < 0) return -1;
    if (bgzf_write(fp, text, l_text) < 0) return -1;
    wr32(buf, (uint32_t)h->n_targets); if (bgzf_write(fp, buf, 4) < 0) return -1;
    for (int i = 0; i < h->n_targets; i++) {
        uint32_t l_name = (uint32_t)strlen(h->targets[i].name) + 1;
        wr32(buf, l_name); if (bgzf_write(fp, buf, 4) < 0) return -1;
        if (bgzf_write(fp, h->targets[i].name, l_name) < 0) return -1;
        wr32(buf, (uint32_t)h->targets[i].len); if (bgzf_write(fp, buf, 4) < 0) return -1;
    }
    if (bgzf_flush(fp) < 0) return -1;
    return 0;
}
