#include "samfile.h"
#include "log.h"
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>

const char *hts_format_name(int fmt) {
    switch (fmt) {
    case FMT_SAM: return "SAM"; case FMT_BAM: return "BAM"; case FMT_CRAM: return "CRAM";
    case FMT_FASTA: return "FASTA"; case FMT_FASTQ: return "FASTQ"; case FMT_TEXT: return "text";
    case FMT_EMPTY: return "empty"; case FMT_BAI: return "BAI"; case FMT_CSI: return "CSI";
    case FMT_VCF: return "VCF"; case FMT_BCF: return "BCF"; case FMT_FAI: return "FAI"; case FMT_BED: return "BED";
    default: return "unknown";
    }
}

static int is_text_only(const unsigned char *s, int len) {
    for (int i = 0; i < len; i++) {
        unsigned char c = s[i];
        if (c >= 0x80) continue;
        if (c < 0x20 && c != '\t' && c != '\n' && c != '\r' && c != '\f' && c != '\v') return 0;
        if (c == 0x7f) return 0;
    }
    return 1;
}

static int all_digits(const unsigned char *p, const unsigned char *e) {
    if (p >= e) return 0;
    for (; p < e; p++) if (!isdigit(*p)) return 0;
    return 1;
}

static int looks_like_sam(const unsigned char *s, int len) {
    /* examine first line: 11+ tab separated fields with numeric flag/pos/mapq/pnext/tlen */
    const unsigned char *e = s + len, *nl = memchr(s, '\n', len);
    const unsigned char *le = nl ? nl : e;
    const unsigned char *f[12]; int nf = 0;
    const unsigned char *p = s;
    while (nf < 12 && p <= le) {
        f[nf++] = p;
        const unsigned char *t = memchr(p, '\t', le - p);
        if (!t) { if (nf < 12) f[nf] = le + 1; break; }
        p = t + 1;
    }
    if (nf < 11) {
        /* could be truncated by peek length: accept if no newline seen and we have >= 9 fields */
        if (!nl && nf >= 10) {} else return 0;
    }
    /* field ends */
    const unsigned char *fe[12];
    for (int i = 0; i < nf; i++) { const unsigned char *t = memchr(f[i], '\t', le - f[i]); fe[i] = t ? t : le; }
    if (!all_digits(f[1], fe[1])) return 0;
    if (!all_digits(f[3], fe[3])) return 0;
    if (!all_digits(f[4], fe[4])) return 0;
    if (nf > 7 && !all_digits(f[7], fe[7])) return 0;
    if (nf > 8) { const unsigned char *q = f[8]; if (q < fe[8] && (*q == '-' || *q == '+')) q++; if (!all_digits(q, fe[8])) return 0; }
    /* cigar */
    if (nf > 5) {
        const unsigned char *q = f[5];
        if (!(fe[5] - q == 1 && *q == '*')) {
            while (q < fe[5]) { if (!isdigit(*q)) return 0; while (q < fe[5] && isdigit(*q)) q++; if (q >= fe[5] || !strchr("MIDNSHP=XB", *q)) return 0; q++; }
        }
    }
    return 1;
}

static int looks_like_fastq(const unsigned char *s, int len) {
    /* @name\nSEQ\n+... */
    const unsigned char *e = s + len;
    if (len < 1 || s[0] != '@') return 0;
    const unsigned char *nl = memchr(s, '\n', len);
    if (!nl) return 0;
    const unsigned char *p = nl + 1;
    while (p < e && *p != '\n') { if (!isalpha(*p) && *p != '*' && *p != '-' && *p != '.' && *p != '=') return 0; p++; }
    if (p >= e) return 1; /* truncated: assume */
    p++;
    if (p < e && *p == '+') return 1;
    return 0;
}

int hts_detect_format(const unsigned char *s, int len, int *compression) {
    *compression = COMP_NONE;
    if (len == 0) return FMT_EMPTY;
    if (len >= 4 && memcmp(s, "CRAM", 4) == 0) return FMT_CRAM;
    if (len >= 4 && memcmp(s, "BAM\1", 4) == 0) return FMT_BAM;
    if (len >= 4 && memcmp(s, "BAI\1", 4) == 0) return FMT_BAI;
    if (len >= 4 && memcmp(s, "CSI\1", 4) == 0) return FMT_CSI;
    if (len >= 3 && memcmp(s, "BCF", 3) == 0 && len >= 4 && s[3] <= 4) return FMT_BCF;
    if (len >= 16 && memcmp(s, "##fileformat=VCF", 16) == 0) return FMT_VCF;
    if (len >= 4 && s[0] == '@' && (memcmp(s, "@HD\t", 4) == 0 || memcmp(s, "@SQ\t", 4) == 0 || memcmp(s, "@RG\t", 4) == 0 || memcmp(s, "@PG\t", 4) == 0 || memcmp(s, "@CO\t", 4) == 0 || memcmp(s, "@CO\n", 4) == 0)) return FMT_SAM;
    if (len >= 3 && s[0] == '@' && s[3] == '\n' && (memcmp(s, "@HD", 3) == 0 || memcmp(s, "@SQ", 3) == 0 || memcmp(s, "@RG", 3) == 0 || memcmp(s, "@PG", 3) == 0 || memcmp(s, "@CO", 3) == 0)) return FMT_SAM;
    if (!is_text_only(s, len)) return FMT_UNKNOWN;
    if (s[0] == '>') return FMT_FASTA;
    if (s[0] == '@' && looks_like_fastq(s, len)) return FMT_FASTQ;
    if (looks_like_sam(s, len)) return FMT_SAM;
    return FMT_TEXT;
}

static samfile_t *samfile_new(void) { return calloc(1, sizeof(samfile_t)); }

samfile_t *sam_open_read_nohdr(const char *fn) {
    bgzf_t *bg = bgzf_open_read(fn);
    if (!bg) return NULL;
    samfile_t *fp = samfile_new();
    fp->bg = bg; fp->fn = strdup(fn);
    fp->compression = bg->is_compressed ? (bg->is_gzip ? COMP_GZIP : COMP_BGZF) : COMP_NONE;
    unsigned char buf[4096];
    int n = bgzf_peek(bg, buf, sizeof buf);
    if (n < 0) { bgzf_close(bg); free(fp->fn); free(fp); errno = EIO; return NULL; }
    int comp;
    fp->fmt = hts_detect_format(buf, n, &comp);
    return fp;
}

int sam_hdr_add_fai_refs(sam_hdr_t *h, const char *fn) {
    textfile_t *t = text_open(fn);
    if (!t) return -1;
    while (text_getline(t) >= 0) {
        char *line = t->line;
        char *tab = strchr(line, '\t'); if (!tab) tab = strchr(line, ' ');
        if (!tab) continue;
        *tab = 0;
        char *p = tab + 1; while (*p == ' ' || *p == '\t') p++;
        long long len = strtoll(p, NULL, 10);
        if (sam_hdr_find_line_id(h, "SQ", "SN", line) >= 0) continue;
        sam_hdr_add_sq(h, line, len);
    }
    text_close(t);
    return 0;
}

int sam_read_header(samfile_t *fp) {
    if (fp->hdr) return 0;
    if (fp->fmt == FMT_BAM) {
        if (bam_hdr_read(fp->bg, &fp->hdr) < 0) return -1;
        return 0;
    }
    if (fp->fmt == FMT_SAM || fp->fmt == FMT_TEXT || fp->fmt == FMT_EMPTY) {
        sam_hdr_t *h = sam_hdr_init();
        kstring_t text = KS_INITIALIZE;
        for (;;) {
            int c = bgzf_getc(fp->bg);
            if (c < 0) break;
            if (c != '@') {
                /* not header: read line and keep */
                int l = bgzf_getline(fp->bg, &fp->line, &fp->line_cap);
                if (l < 0) { /* line was single char */
                    if (fp->line_cap < 2) { fp->line = realloc(fp->line, 2); fp->line_cap = 2; }
                    fp->line[0] = (char)c; fp->line[1] = 0; fp->line_len = 1; fp->have_line = 1; fp->lineno++;
                    break;
                }
                /* prepend c */
                if (fp->line_cap < (size_t)l + 2) { fp->line = realloc(fp->line, l + 2); fp->line_cap = l + 2; }
                memmove(fp->line + 1, fp->line, l + 1);
                fp->line[0] = (char)c; fp->line_len = l + 1; fp->have_line = 1; fp->lineno++;
                break;
            }
            int l = bgzf_getline(fp->bg, &fp->line, &fp->line_cap);
            fp->lineno++;
            kputc('@', &text);
            if (l >= 0) kputsn(fp->line, l, &text);
            kputc('\n', &text);
        }
        int bad = 0;
        if (sam_hdr_parse_text_lines(h, text.s ? text.s : "", text.l, &bad) < 0) {
            if (bad == -2) log_error("sam_hdr_build_from_sam_file", "Invalid header line: must start with @HD/@SQ/@RG/@PG/@CO");
            sam_hdr_destroy(h); free(text.s); return -1;
        }
        free(h->text); h->text = text.s ? text.s : calloc(1,1); h->l_text = text.l; h->dirty = 0;
        if (fp->ref_fn && h->n_targets == 0) {
            sam_hdr_add_fai_refs(h, fp->ref_fn);
        }
        fp->hdr = h;
        return 0;
    }
    if (fp->fmt == FMT_FASTA || fp->fmt == FMT_FASTQ) {
        fp->hdr = sam_hdr_init();
        return 0;
    }
    return -1;
}

void sam_set_fai_filename(samfile_t *fp, const char *fn) { free(fp->ref_fn); fp->ref_fn = fn ? strdup(fn) : NULL; }

samfile_t *sam_open_read(const char *fn) {
    samfile_t *fp = sam_open_read_nohdr(fn);
    if (!fp) return NULL;
    if (sam_read_header(fp) < 0) { sam_close(fp); errno = 0; return NULL; }
    return fp;
}

int sam_getline(samfile_t *fp) {
    if (fp->have_line) { fp->have_line = 0; return fp->line_len; }
    int l = bgzf_getline(fp->bg, &fp->line, &fp->line_cap);
    if (l >= 0) { fp->lineno++; fp->line_len = l; }
    return l;
}

/* FASTA/FASTQ record reading into bam1_t */
static int fastx_read1(samfile_t *fp, sam_hdr_t *h, bam1_t *b) {
    (void)h;
    int l;
    /* find header line */
    for (;;) {
        l = sam_getline(fp);
        if (l < 0) return -1;
        if (l == 0) continue;
        break;
    }
    char first = fp->line[0];
    if (!((fp->fmt == FMT_FASTQ && first == '@') || (fp->fmt == FMT_FASTA && first == '>'))) {
        log_error("fastq_parse1", "Bad FASTQ/FASTA record");
        return -2;
    }
    char *name = fp->line + 1; char *sp = name; while (*sp && !isspace((unsigned char)*sp)) sp++;
    char *comment = NULL;
    if (*sp) { *sp = 0; comment = sp + 1; while (*comment == ' ' || *comment == '\t') comment++; }
    char *qname = strdup(name);
    char *cmt = comment && *comment ? strdup(comment) : NULL;
    kstring_t seq = KS_INITIALIZE, qual = KS_INITIALIZE;
    int flag = BAM_FUNMAP;
    /* /1 /2 suffix */
    size_t ql = strlen(qname);
    if (ql > 2 && qname[ql-2] == '/' && (qname[ql-1] == '1' || qname[ql-1] == '2')) {
        flag |= BAM_FPAIRED | (qname[ql-1] == '1' ? BAM_FREAD1 : BAM_FREAD2) | BAM_FMUNMAP;
        qname[ql-2] = 0;
    }
    if (fp->fmt == FMT_FASTQ) {
        for (;;) {
            l = sam_getline(fp);
            if (l < 0) break;
            if (l > 0 && fp->line[0] == '+') break;
            kputsn(fp->line, l, &seq);
        }
        while (qual.l < seq.l) {
            l = sam_getline(fp);
            if (l < 0) break;
            kputsn(fp->line, l, &qual);
        }
        if (qual.l != seq.l) { log_error("fastq_parse1", "Mismatched sequence and quality lengths for %s", qname); free(qname); free(cmt); free(seq.s); free(qual.s); return -2; }
    } else {
        for (;;) {
            unsigned char c; int n = bgzf_peek(fp->bg, &c, 1);
            if (n <= 0) break;
            if (c == '>') break;
            l = sam_getline(fp);
            if (l < 0) break;
            kputsn(fp->line, l, &seq);
        }
    }
    uint8_t *q = NULL;
    if (qual.l) { q = malloc(qual.l); for (size_t i = 0; i < qual.l; i++) q[i] = (uint8_t)(qual.s[i] - 33); }
    bam_set1(b, strlen(qname), qname, (uint16_t)flag, -1, -1, 0, 0, NULL, -1, -1, 0, seq.l, seq.s ? seq.s : "", (char*)q, 0);
    if (q) free(q); else { if (seq.l) memset(bam_get_qual(b), 0xff, seq.l); }
    if (cmt && fp->fastq_aux_all) {
        /* parse SAM-style aux tags from comment */
        char *p = cmt;
        while (*p) {
            char *e = p; while (*e && *e != '\t' && *e != ' ') e++;
            char save = *e; *e = 0;
            if (strlen(p) >= 5 && p[2] == ':' && p[4] == ':') {
                char tmp[1024]; snprintf(tmp, sizeof tmp, "%s", p);
                bam1_t *t = bam_init1();
                char line[2048]; snprintf(line, sizeof line, "q\t4\t*\t0\t0\t*\t*\t0\t0\t*\t*\t%s", tmp);
                sam_hdr_t *hh = sam_hdr_init();
                if (sam_parse1(line, (int)strlen(line), hh, t) == 0) {
                    uint8_t *a = bam_get_aux(t); int la = bam_get_l_aux(t);
                    bam_set_data_cap(b, b->l_data + la); memcpy(b->data + b->l_data, a, la); b->l_data += la;
                }
                sam_hdr_destroy(hh); bam_destroy1(t);
            }
            *e = save; p = e; while (*p == ' ' || *p == '\t') p++;
        }
    }
    free(qname); free(cmt); free(seq.s); free(qual.s);
    return 0;
}

int sam_read1(samfile_t *fp, sam_hdr_t *h, bam1_t *b) {
    if (fp->fmt == FMT_BAM) {
        int r = bam_read1(fp->bg, b);
        if (r >= 0) { b->id = fp->n_read++; return 0; }
        if (r == -1) return -1;
        return r;
    }
    if (fp->fmt == FMT_FASTA || fp->fmt == FMT_FASTQ) {
        int r = fastx_read1(fp, h, b);
        if (r == 0) b->id = fp->n_read++;
        return r;
    }
    for (;;) {
        int l = sam_getline(fp);
        if (l < 0) return -1;
        if (l == 0) {
            /* htslib treats an empty line as a parse error */
            log_warning("sam_read1_sam", "Parse error at line %ld", fp->lineno);
            return -2;
        }
        if (fp->line[0] == '@') {
            /* header line in the middle: treated as parse error by htslib */
            log_warning("sam_read1_sam", "Parse error at line %ld", fp->lineno);
            return -2;
        }
        int r = sam_parse1(fp->line, l, h, b);
        if (r < 0) { log_warning("sam_read1_sam", "Parse error at line %ld", fp->lineno); return -2; }
        b->id = fp->n_read++;
        return 0;
    }
}

int sam_output_format_from_name(const char *fn, int *compression) {
    *compression = COMP_NONE;
    size_t l = strlen(fn);
    const char *ext = NULL;
    for (size_t i = l; i > 0; i--) if (fn[i-1] == '.') { ext = fn + i; break; } else if (fn[i-1] == '/') break;
    if (!ext) return FMT_UNKNOWN;
    if (strcasecmp(ext, "bam") == 0) return FMT_BAM;
    if (strcasecmp(ext, "cram") == 0) return FMT_CRAM;
    if (strcasecmp(ext, "sam") == 0) return FMT_SAM;
    if (strcasecmp(ext, "gz") == 0 || strcasecmp(ext, "bgz") == 0 || strcasecmp(ext, "bgzf") == 0) {
        /* look at previous extension */
        size_t el = (size_t)(ext - fn) - 1; const char *ext2 = NULL;
        for (size_t i = el; i > 0; i--) if (fn[i-1] == '.') { ext2 = fn + i; break; } else if (fn[i-1] == '/') break;
        if (ext2 && strncasecmp(ext2, "sam.", 4) == 0) { *compression = COMP_BGZF; return FMT_SAM; }
        return FMT_UNKNOWN;
    }
    return FMT_UNKNOWN;
}

samfile_t *sam_open_write(const char *fn, const char *mode, int level) {
    samfile_t *fp = samfile_new();
    fp->is_write = 1; fp->fn = strdup(fn); fp->level = level;
    int fmt = FMT_SAM, comp = COMP_NONE;
    for (const char *m = mode; *m; m++) {
        if (*m == 'b') fmt = FMT_BAM;
        else if (*m == 'c') fmt = FMT_CRAM;
        else if (*m == 'z') comp = COMP_BGZF;
        else if (*m == 'u') level = 0;
        else if (isdigit((unsigned char)*m)) level = *m - '0';
    }
    fp->level = level;
    fp->fmt = fmt;
    if (fmt == FMT_CRAM) { free(fp->fn); free(fp); errno = EINVAL; return NULL; }
    if (fmt == FMT_BAM) {
        fp->bg = bgzf_open_write(fn, level);
        if (!fp->bg) { free(fp->fn); free(fp); return NULL; }
        fp->compression = COMP_BGZF;
    } else {
        if (comp == COMP_BGZF) { fp->bg = bgzf_open_write(fn, level); fp->compression = COMP_BGZF; }
        else { fp->bg = bgzf_open_write(fn, 0); if (fp->bg) bgzf_set_uncompressed(fp->bg); fp->compression = COMP_NONE; }
        if (!fp->bg) { free(fp->fn); free(fp); return NULL; }
    }
    return fp;
}

int sam_write_hdr(samfile_t *fp, sam_hdr_t *h) {
    if (fp->fmt == FMT_BAM) return bam_hdr_write(fp->bg, h);
    const char *text = sam_hdr_str(h);
    size_t l = sam_hdr_length(h);
    if (l > 0 && bgzf_write(fp->bg, text, l) < 0) return -1;
    return 0;
}

int sam_write1(samfile_t *fp, sam_hdr_t *h, const bam1_t *b) {
    if (fp->fmt == FMT_BAM) return bam_write1(fp->bg, b);
    if (sam_format1(h, b, &fp->ks) < 0) return -1;
    kputc('\n', &fp->ks);
    if (bgzf_write(fp->bg, fp->ks.s, fp->ks.l) < 0) return -1;
    return (int)fp->ks.l;
}

int sam_flush(samfile_t *fp) { return bgzf_flush(fp->bg); }

int sam_close(samfile_t *fp) {
    if (!fp) return 0;
    int r = 0;
    if (fp->bg) r = bgzf_close(fp->bg);
    if (fp->hdr) sam_hdr_destroy(fp->hdr);
    free(fp->line); free(fp->ks.s); free(fp->fn); free(fp->ref_fn);
    free(fp);
    return r;
}

textfile_t *text_open(const char *fn) {
    bgzf_t *bg = bgzf_open_read(fn);
    if (!bg) return NULL;
    textfile_t *t = calloc(1, sizeof *t);
    t->bg = bg;
    return t;
}
int text_getline(textfile_t *t) {
    int l = bgzf_getline(t->bg, &t->line, &t->cap);
    t->len = l;
    return l;
}
void text_close(textfile_t *t) { if (!t) return; bgzf_close(t->bg); free(t->line); free(t); }
