static void usage(FILE *fp) {
    fprintf(fp,
"\n"
"Program: samtools (Tools for alignments in the SAM format)\n"
"Version: %s (using htslib %s)\n\n", SAMTOOLS_VERSION, HTSLIB_VERSION);
    fprintf(fp,
"Usage:   samtools <command> [options]\n"
