}

char *stringify_argv(int argc, char **argv) {
    size_t len = 1;
    for (int i = 0; i < argc; i++) len += strlen(argv[i]) + 1;
    char *s = malloc(len + 1), *p = s;
    for (int i = 0; i < argc; i++) {
        if (i) *p++ = ' ';
        size_t l = strlen(argv[i]);
        memcpy(p, argv[i], l); p += l;
    }
    *p = 0;
    /* replace tabs/newlines with spaces as samtools does */
    for (char *q = s; *q; q++) if (*q == '\t' || *q == '\n') *q = ' ';
    return s;
}

int print_error(const char *subcommand, const char *fmt, ...) {
    va_list ap; va_start(ap, fmt);
    fflush(stdout);
    fprintf(stderr, "samtools %s: ", subcommand);
    vfprintf(stderr, fmt, ap);
    fputc('\n', stderr);
    va_end(ap);
    return 0;
}

int print_error_errno(const char *subcommand, const char *fmt, ...) {
    int err = errno;
    va_list ap; va_start(ap, fmt);
    fflush(stdout);
    fprintf(stderr, "samtools %s: ", subcommand);
    vfprintf(stderr, fmt, ap);
    if (err) fprintf(stderr, ": %s\n", strerror(err)); else fputc('\n', stderr);
    va_end(ap);
    return 0;
}

static const struct { const char *name; int flag; } flag_names[] = {
    { "PAIRED", 1 }, { "PROPER_PAIR", 2 }, { "UNMAP", 4 }, { "MUNMAP", 8 }, { "REVERSE", 16 }, { "MREVERSE", 32 },
    { "READ1", 64 }, { "READ2", 128 }, { "SECONDARY", 256 }, { "QCFAIL", 512 }, { "DUP", 1024 }, { "SUPPLEMENTARY", 2048 },
};

int bam_str2flag(const char *str) {
    char *end, *beg = (char*)str;
    long flag = strtol(str, &end, 0);
    if (end != str && *end == 0) return (int)flag;
    if (*str == 0) return 0; /* empty string = 0 as in htslib? Actually fails */
    flag = 0;
    beg = (char*)str;
    for (;;) {
        char *e = strchr(beg, ',');
        size_t l = e ? (size_t)(e - beg) : strlen(beg);
        int i, found = 0;
        for (i = 0; i < 12; i++) {
            if (strlen(flag_names[i].name) == l && strncasecmp(beg, flag_names[i].name, l) == 0) { flag |= flag_names[i].flag; found = 1; break; }
        }
        if (!found) return -1;
        if (!e) break;
        beg = e + 1;
    }
    return (int)flag;
}

char *bam_flag2str(int flag) {
    kstring_t ks = KS_INITIALIZE;
    for (int i = 0; i < 12; i++) if (flag & flag_names[i].flag) { if (ks.l) kputc(',', &ks); kputs(flag_names[i].name, &ks); }
    if (!ks.s) ks.s = calloc(1, 1);
    return ks.s;
}

int parse_flags_arg(const char *s, const char *subcmd, const char *optname) {
    int f = bam_str2flag(s);
    if (f < 0) { print_error(subcmd, "Unknown flag value: %s", s); return -1; }
    (void)optname;
    return f;
}

int64_t parse_int_arg(const char *s, int base) { return strtoll(s, NULL, base); }

int parse_format_string(const char *s, int *fmt, int *comp, int *level, int is_output) {
    (void)is_output;
    /* format[,opt[=val]]... */
    char *dup = strdup(s);
    char *p = dup, *comma = strchr(p, ',');
    if (comma) *comma = 0;
    int ok = 0;
    if (strcasecmp(p, "bam") == 0) { *fmt = FMT_BAM; *comp = COMP_BGZF; ok = 1; }
    else if (strcasecmp(p, "sam") == 0) { *fmt = FMT_SAM; *comp = COMP_NONE; ok = 1; }
    else if (strcasecmp(p, "sam.gz") == 0) { *fmt = FMT_SAM; *comp = COMP_BGZF; ok = 1; }
    else if (strcasecmp(p, "cram") == 0) { *fmt = FMT_CRAM; *comp = COMP_NONE; ok = 1; }
    else if (strcasecmp(p, "fastq") == 0 || strcasecmp(p, "fq") == 0) { *fmt = FMT_FASTQ; *comp = COMP_NONE; ok = 1; }
    else if (strcasecmp(p, "fasta") == 0 || strcasecmp(p, "fa") == 0) { *fmt = FMT_FASTA; *comp = COMP_NONE; ok = 1; }
    else if (strcasecmp(p, "fastq.gz") == 0 || strcasecmp(p, "fq.gz") == 0) { *fmt = FMT_FASTQ; *comp = COMP_BGZF; ok = 1; }
    else if (strcasecmp(p, "fasta.gz") == 0 || strcasecmp(p, "fa.gz") == 0) { *fmt = FMT_FASTA; *comp = COMP_BGZF; ok = 1; }
    else if (*p == 0) ok = 1;
    if (!ok) { free(dup); return -1; }
    while (comma) {
        p = comma + 1; comma = strchr(p, ','); if (comma) *comma = 0;
        if (parse_format_option(p, level, fmt) < 0) { free(dup); return -1; }
    }
    free(dup);
    return 0;
}

int parse_format_option(const char *s, int *level, int *fmt) {
    (void)fmt;
    const char *eq = strchr(s, '=');
    size_t kl = eq ? (size_t)(eq - s) : strlen(s);
    if (kl == 5 && strncmp(s, "level", 5) == 0) {
        if (!eq) return -1;
        *level = atoi(eq + 1);
        return 0;
    }
    /* accept and ignore other known options */
    return 0;
}

void sam_global_args_free(sam_global_args *ga) { free(ga->reference); free(ga->fmt_opts_str); }

int sam_open_mode(char *mode, const char *fn, const char *format) {
    if (format == NULL) {
        int comp; int fmt = sam_output_format_from_name(fn, &comp);
        if (fmt == FMT_BAM) strcpy(mode, "b");
        else if (fmt == FMT_CRAM) strcpy(mode, "c");
        else if (fmt == FMT_SAM && comp == COMP_BGZF) strcpy(mode, "z");
        else if (fmt == FMT_SAM) strcpy(mode, "");
        else return -1;
        return 0;
    }
    if (strcasecmp(format, "bam") == 0) strcpy(mode, "b");
    else if (strcasecmp(format, "cram") == 0) strcpy(mode, "c");
    else if (strcasecmp(format, "sam") == 0) strcpy(mode, "");
    else if (strcasecmp(format, "sam.gz") == 0) strcpy(mode, "z");
    else return -1;
    return 0;
}

samfile_t *sam_open_output(const char *fn, const char *base_mode, sam_global_args *ga, int explicit_fmt) {
    char mode[16]; strcpy(mode, base_mode);
    if (!explicit_fmt) {
        if (ga->out_fmt == FMT_BAM) strcat(mode, "b");
        else if (ga->out_fmt == FMT_CRAM) strcat(mode, "c");
        else if (ga->out_fmt == FMT_SAM) { if (ga->out_comp == COMP_BGZF) strcat(mode, "z"); }
        else {
            char m[8];
            if (sam_open_mode(m, fn, NULL) == 0) strcat(mode, m);
        }
    }
    return sam_open_write(fn, mode, ga->out_level);
}

void sam_global_opt_help(FILE *fp, const char *shortopts) {
    /* shortopts: string of characters where '-' means no short option. Order: input-fmt, input-fmt-option, output-fmt, output-fmt-option, reference, threads, write-index, verbosity */
    const char *p = shortopts;
    static const char *names[] = { "input-fmt FORMAT[,OPT[=VAL]]...\n               Specify input format (SAM, BAM, CRAM)",
        "input-fmt-option OPT[=VAL]\n               Specify a single input file format option in the form\n               of OPTION or OPTION=VALUE",
        "output-fmt FORMAT[,OPT[=VAL]]...\n               Specify output format (SAM, BAM, CRAM)",
        "output-fmt-option OPT[=VAL]\n               Specify a single output file format option in the form\n               of OPTION or OPTION=VALUE",
        "reference FILE\n               Reference sequence FASTA FILE [null]",
        "threads INT\n               Number of additional threads to use [0]",
        "write-index\n               Automatically index the output files [off]",
        "verbosity INT\n               Set level of verbosity" };
    for (int i = 0; i < 8 && *p; i++, p++) {
        if (*p == '.') continue;
        if (*p == '-') fprintf(fp, "      --%s\n", names[i]);
        else fprintf(fp, "  -%c, --%s\n", *p, names[i]);
    }
    fprintf(fp, "\nSee https://www.htslib.org/doc/samtools.html#GLOBAL_COMMAND_OPTIONS\nfor more details.\n");
}

int parse_sam_global_opt(int c, const char *optarg, const int *lopt_map, sam_global_args *ga) {
    (void)lopt_map;
    switch (c) {
    case 1001: /* input-fmt */ return 0;
    case 1002: /* input-fmt-option */ return 0;
    case 1003: /* output-fmt */ {
        int fmt = 0, comp = 0, level = ga->out_level;
        if (parse_format_string(optarg, &fmt, &comp, &level, 1) < 0) { fprintf(stderr, "Unknown output format \"%s\"\n", optarg); return -2; }
        ga->out_fmt = fmt; ga->out_comp = comp; ga->out_level = level;
        return 0;
    }
    case 1004: /* output-fmt-option */ {
        int level = ga->out_level, fmt = ga->out_fmt;
        if (parse_format_option(optarg, &level, &fmt) < 0) return -2;
        ga->out_level = level;
        return 0;
    }
    case 1005: /* reference */ free(ga->reference); ga->reference = strdup(optarg); return 0;
    case 1006: /* threads */ ga->nthreads = atoi(optarg); return 0;
    case 1007: /* write-index */ ga->write_index = 1; return 0;
    case 1008: /* verbosity */ ga->verbosity = atoi(optarg); hts_verbose = ga->verbosity; return 0;
    }
    return -1;
}
