{"command":"cd /workspace && cat > src/index.c <<'EOF'
#include "index.h"
#include "log.h"
#include <string.h>
#include <errno.h>
#include <ctype.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

#define META_BIN(idx) ((idx)->n_bins + 1)
#define HTS_MIN_MARKER_DIST 0x10000

static inline int hts_bin_first(int l) { return (((1<<(((l)<<1) + (l))) - 1) / 7); }
static inline int hts_bin_parent(int l) { return (((l) - 1) >> 3); }
static inline int hts_bin_bot(int bin, int n_lvls) {
    int l, b;
    for (l = 0, b = bin; b; ++l, b = hts_bin_parent(b));
    return (bin - hts_bin_first(l)) << (n_lvls - l) * 3;
}

hts_idx_t *hts_idx_init(int n, int fmt, uint64_t offset0, int min_shift, int n_lvls) {
    hts_idx_t *idx = calloc(1, sizeof(hts_idx_t));
    idx->fmt = fmt; idx->min_shift = min_shift; idx->n_lvls = n_lvls;
    idx->n_bins = ((1 << (3 * n_lvls + 3)) - 1) / 7;
    idx->z.save_tid = idx->z.last_tid = -1;
    idx->z.save_bin = idx->z.last_bin = 0xffffffffu;
    idx->z.save_off = idx->z.last_off = idx->z.off_beg = idx->z.off_end = offset0;
    idx->z.last_coor = 0xffffffffu;
    if (n) {
        idx->n = idx->m = n;
        idx->bidx = calloc(n, sizeof(kh32_t*));
        idx->lidx = calloc(n, sizeof(lidx_t));
    }
    return idx;
}

void hts_idx_destroy(hts_idx_t *idx) {
    if (!idx) return;
    for (int i = 0; i < idx->m; i++) {
        kh32_t *b = idx->bidx[i];
        if (b) {
            for (uint32_t k = kh32_begin(b); k != kh32_end(b); k++) if (kh32_exist(b, k)) { bins_t *p = kh32_val(b, k); free(p->list); free(p); }
            kh32_destroy(b);
        }
        free(idx->lidx[i].offset);
    }
    free(idx->bidx); free(idx->lidx); free(idx->meta); free(idx);
}

static int insert_to_b(kh32_t *b, int bin, uint64_t beg, uint64_t end) {
    int absent;
    uint32_t k = kh32_put(b, bin, &absent);
    bins_t *l;
    if (absent) { l = calloc(1, sizeof(bins_t)); l->m = 1; l->list = calloc(1, sizeof(hts_pair64_t)); kh32_val(b, k) = l; }
    l = kh32_val(b, k);
    if (l->n == l->m) { l->m <<= 1; l->list = realloc(l->list, l->m * sizeof(hts_pair64_t)); }
    l->list[l->n].u = beg; l->list[l->n++].v = end;
    return 0;
}

static int insert_to_l(lidx_t *l, int64_t _beg, int64_t _end, uint64_t offset, int min_shift) {
    int64_t beg = _beg >> min_shift, end = (_end - 1) >> min_shift;
    if (l->m < end + 1) {
        int old_m = l->m;
        l->m = (int)(end + 1); { int x = l->m; --x; x|=x>>1; x|=x>>2; x|=x>>4; x|=x>>8; x|=x>>16; ++x; l->m = x; }
        l->offset = realloc(l->offset, l->m * sizeof(uint64_t));
        memset(l->offset + old_m, 0, (l->m - old_m) * sizeof(uint64_t));
    }
    for (int64_t i = beg; i <= end; i++) if (l->offset[i] == 0) l->offset[i] = offset;
    if (l->n < end + 1) l->n = (int)(end + 1);
    return 0;
}

int hts_idx_push(hts_idx_t *idx, int tid, int64_t beg, int64_t end, uint64_t offset, int is_mapped) {
    int bin;
    if (tid < 0) beg = -1, end = 0;
    if (tid >= idx->m) {
        int oldm = idx->m;
        idx->m = idx->m ? idx->m << 1 : 2;
        while (tid >= idx->m) idx->m <<= 1;
        idx->bidx = realloc(idx->bidx, idx->m * sizeof(kh32_t*));
        memset(idx->bidx + oldm, 0, (idx->m - oldm) * sizeof(kh32_t*));
        idx->lidx = realloc(idx->lidx, idx->m * sizeof(lidx_t));
        memset(idx->lidx + oldm, 0, (idx->m - oldm) * sizeof(lidx_t));
    }
    if (idx->n < tid + 1) idx->n = tid + 1;
    if (idx->z.finished) return 0;
    if (idx->z.last_tid != tid || (idx->z.last_tid >= 0 && tid < 0)) {
        if (tid >= 0 && idx->n_no_coor) { log_error("hts_idx_push", "NO_COOR reads not in a single block at the end %d %d", tid, idx->z.last_tid); return -1; }
        if (tid >= 0 && idx->bidx[tid] != 0) { log_error("hts_idx_push", "Chromosome blocks not continuous"); return -1; }
        idx->z.last_tid = tid;
        idx->z.last_bin = 0xffffffffu;
    } else if (tid >= 0 && idx->z.last_coor > beg) {
        log_error("hts_idx_push", "Unsorted positions on sequence #%d: %lld followed by %lld", tid + 1, (long long)idx->z.last_coor + 1, (long long)beg + 1);
        return -1;
    }
    if (end < beg) { log_error("hts_idx_push", "Invalid record on sequence #%d: end %lld < begin %lld", tid + 1, (long long)end, (long long)beg + 1); return -1; }
    if (tid >= 0) {
        if (idx->bidx[tid] == 0) idx->bidx[tid] = kh32_init();
        if (beg < 0) beg = 0;
        if (end <= 0) end = 1;
        insert_to_l(&idx->lidx[tid], beg, end, idx->z.last_off, idx->min_shift);
    } else idx->n_no_coor++;
    bin = hts_reg2bin(beg, end, idx->min_shift, idx->n_lvls);
    if ((int)idx->z.last_bin != bin) {
        if (idx->z.save_bin != 0xffffffffu) insert_to_b(idx->bidx[idx->z.save_tid], idx->z.save_bin, idx->z.save_off, idx->z.last_off);
        if (idx->z.last_bin == 0xffffffffu && idx->z.save_bin != 0xffffffffu) {
            idx->z.off_end = idx->z.last_off;
            insert_to_b(idx->bidx[idx->z.save_tid], META_BIN(idx), idx->z.off_beg, idx->z.off_end);
            insert_to_b(idx->bidx[idx->z.save_tid], META_BIN(idx), idx->z.n_mapped, idx->z.n_unmapped);
            idx->z.n_mapped = idx->z.n_unmapped = 0;
            idx->z.off_beg = idx->z.off_end;
        }
        idx->z.save_off = idx->z.last_off;
        idx->z.save_bin = idx->z.last_bin = bin;
        idx->z.save_tid = tid;
    }
    if (is_mapped) ++idx->z.n_mapped; else ++idx->z.n_unmapped;
    idx->z.last_off = offset;
    idx->z.last_coor = beg;
    return 0;
}

static void update_loff(hts_idx_t *idx, int i, int free_lidx) {
    kh32_t *bidx = idx->bidx[i];
    lidx_t *lidx = &idx->lidx[i];
    for (int l = lidx->n - 2; l >= 0; l--) if (lidx->offset[l] == 0) lidx->offset[l] = lidx->offset[l+1];
    if (bidx == 0) return;
    for (uint32_t k = kh32_begin(bidx); k != kh32_end(bidx); ++k) if (kh32_exist(bidx, k)) {
        bins_t *p = kh32_val(bidx, k);
        if (kh32_key(bidx, k) < (uint32_t)idx->n_bins) {
            int bot_bin = hts_bin_bot(kh32_key(bidx, k), idx->n_lvls);
            if (bot_bin >= lidx->n) p->loff = 0; else p->loff = lidx->offset[bot_bin];
        } else p->loff = 0;
    }
    if (free_lidx) { free(lidx->offset); lidx->m = lidx->n = 0; lidx->offset = 0; }
}

static int pair_cmp_u(const void *a, const void *b) {
    const hts_pair64_t *x = a, *y = b;
    return x->u < y->u ? -1 : x->u > y->u ? 1 : 0;
}

/* introsort replacement: since keys (chunk starts) are distinct, any correct sort is fine */
static void sort_pairs(int n, hts_pair64_t *a) { qsort(a, n, sizeof(hts_pair64_t), pair_cmp_u); }

static void compress_binning(hts_idx_t *idx, int i) {
    kh32_t *bidx = idx->bidx[i];
    if (bidx == 0) return;
    for (int l = idx->n_lvls; l > 0; --l) {
        unsigned start = hts_bin_first(l);
        for (uint32_t k = kh32_begin(bidx); k != kh32_end(bidx); ++k) {
            if (!kh32_exist(bidx, k) || kh32_key(bidx, k) >= (uint32_t)idx->n_bins || kh32_key(bidx, k) < start) continue;
            bins_t *p = kh32_val(bidx, k);
            if (l < idx->n_lvls && p->n > 1) sort_pairs(p->n, p->list);
            if ((p->list[p->n - 1].v >> 16) - (p->list[0].u >> 16) < HTS_MIN_MARKER_DIST) {
                uint32_t kp = kh32_get(bidx, hts_bin_parent(kh32_key(bidx, k)));
                if (kp == kh32_end(bidx)) continue;
                bins_t *q = kh32_val(bidx, kp);
                if (q->n + p->n > q->m) {
                    q->m = q->n + p->n; { int x = q->m; --x; x|=x>>1; x|=x>>2; x|=x>>4; x|=x>>8; x|=x>>16; ++x; q->m = x; }
                    q->list = realloc(q->list, q->m * sizeof(hts_pair64_t));
                }
                memcpy(q->list + q->n, p->list, p->n * sizeof(hts_pair64_t));
                q->n += p->n;
                free(p->list); free(p);
                kh32_del(bidx, k);
            }
        }
    }
    uint32_t k = kh32_get(bidx, 0);
    if (k != kh32_end(bidx)) sort_pairs(kh32_val(bidx, k)->n, kh32_val(bidx, k)->list);
    for (k = kh32_begin(bidx); k != kh32_end(bidx); ++k) {
        if (!kh32_exist(bidx, k) || kh32_key(bidx, k) >= (uint32_t)idx->n_bins) continue;
        bins_t *p = kh32_val(bidx, k);
        int l, m;
        for (l = 1, m = 0; l < p->n; ++l) {
            if (p->list[m].v >> 16 >= p->list[l].u >> 16) { if (p->list[m].v < p->list[l].v) p->list[m].v = p->list[l].v; }
            else p->list[++m] = p->list[l];
        }
        p->n = m + 1;
    }
}

void hts_idx_finish(hts_idx_t *idx, uint64_t final_offset) {
    if (idx == NULL || idx->z.finished) return;
    if (idx->z.save_tid >= 0) {
        insert_to_b(idx->bidx[idx->z.save_tid], idx->z.save_bin, idx->z.save_off, final_offset);
        insert_to_b(idx->bidx[idx->z.save_tid], META_BIN(idx), idx->z.off_beg, final_offset);
        insert_to_b(idx->bidx[idx->z.save_tid], META_BIN(idx), idx->z.n_mapped, idx->z.n_unmapped);
    }
    for (int i = 0; i < idx->n; ++i) {
        update_loff(idx, i, (idx->fmt == HTS_FMT_CSI));
        compress_binning(idx, i);
    }
    idx->z.finished = 1;
}

static void w32(kstring_t *ks, uint32_t v) { kputsn((char*)&v, 4, ks); }
static void w64(kstring_t *ks, uint64_t v) { kputsn((char*)&v, 8, ks); }

int hts_idx_save_as(const hts_idx_t *idx, const char *fn, const char *fnidx, int fmt) {
    (void)fn;
    kstring_t ks = KS_INITIALIZE;
    if (fmt == HTS_FMT_CSI) {
        kputsn("CSI\1", 4, &ks);
        w32(&ks, idx->min_shift); w32(&ks, idx->n_lvls); w32(&ks, idx->l_meta);
        if (idx->l_meta) kputsn((char*)idx->meta, idx->l_meta, &ks);
    } else {
        kputsn("BAI\1", 4, &ks);
    }
    w32(&ks, idx->n);
    for (int i = 0; i < idx->n; ++i) {
        kh32_t *bidx = idx->bidx[i];
        lidx_t *lidx = &idx->lidx[i];
        uint32_t size = bidx ? kh32_size(bidx) : 0;
        w32(&ks, size);
        if (bidx) for (uint32_t k = kh32_begin(bidx); k != kh32_end(bidx); ++k) if (kh32_exist(bidx, k)) {
            bins_t *p = kh32_val(bidx, k);
            w32(&ks, kh32_key(bidx, k));
            if (fmt == HTS_FMT_CSI) w64(&ks, p->loff);
            w32(&ks, p->n);
            for (int j = 0; j < p->n; ++j) { w64(&ks, p->list[j].u); w64(&ks, p->list[j].v); }
        }
        if (fmt != HTS_FMT_CSI) {
            w32(&ks, lidx->n);
            for (int j = 0; j < lidx->n; ++j) w64(&ks, lidx->offset[j]);
        }
    }
    w64(&ks, idx->n_no_coor);
    int ret = 0;
    if (fmt == HTS_FMT_CSI) {
        bgzf_t *fp = bgzf_open_write(fnidx, -1);
        if (!fp) { free(ks.s); return -1; }
        if (bgzf_write(fp, ks.s, ks.l) < 0) ret = -1;
        if (bgzf_close(fp) < 0) ret = -1;
    } else {
        int fd = open(fnidx, O_WRONLY | O_CREAT | O_TRUNC, 0666);
        if (fd < 0) { free(ks.s); return -1; }
        size_t off = 0;
        while (off < ks.l) { ssize_t n = write(fd, ks.s + off, ks.l - off); if (n < 0) { ret = -1; break; } off += n; }
        close(fd);
    }
    free(ks.s);
    return ret;
}

/* ---- loading ---- */
typedef struct { const uint8_t *p, *end; int err; } rd_t;
static uint32_t r32(rd_t *r) { if (r->p + 4 > r->end) { r->err = 1; return 0; } uint32_t v; memcpy(&v, r->p, 4); r->p += 4; return v; }
static uint64_t r64(rd_t *r) { if (r->p + 8 > r->end) { r->err = 1; return 0; } uint64_t v; memcpy(&v, r->p, 8); r->p += 8; return v; }

static hts_idx_t *idx_read_core(rd_t *r, int fmt, int n, int min_shift, int n_lvls) {
    hts_idx_t *idx = hts_idx_init(n, fmt, 0, min_shift, n_lvls);
    for (int i = 0; i < n; i++) {
        int32_t n_bin = (int32_t)r32(r);
        if (r->err) goto fail;
        if (n_bin < 0) goto fail;
        kh32_t *h = idx->bidx[i] = kh32_init();
        for (int j = 0; j < n_bin; j++) {
            uint32_t key = r32(r);
            int absent; uint32_t k = kh32_put(h, key, &absent);
            bins_t *p;
            if (absent) { p = calloc(1, sizeof(bins_t)); kh32_val(h, k) = p; } else p = kh32_val(h, k);
            if (fmt == HTS_FMT_CSI) p->loff = r64(r);
            int32_t n_chunk = (int32_t)r32(r);
            if (r->err || n_chunk < 0) goto fail;
            p->list = realloc(p->list, (p->n + n_chunk) * sizeof(hts_pair64_t)); p->m = p->n + n_chunk;
            for (int c = 0; c < n_chunk; c++) { p->list[p->n].u = r64(r); p->list[p->n].v = r64(r); p->n++; }
            if (r->err) goto fail;
        }
        if (fmt != HTS_FMT_CSI) {
            int32_t n_intv = (int32_t)r32(r);
            if (r->err || n_intv < 0) goto fail;
            lidx_t *l = &idx->lidx[i];
            l->n = l->m = n_intv; l->offset = calloc(n_intv ? n_intv : 1, sizeof(uint64_t));
            for (int j = 0; j < n_intv; j++) l->offset[j] = r64(r);
            if (r->err) goto fail;
        }
    }
    if (r->p + 8 <= r->end) idx->n_no_coor = r64(r); else idx->n_no_coor = 0;
    idx->z.finished = 1;
    return idx;
fail:
    hts_idx_destroy(idx);
    return NULL;
}

hts_idx_t *hts_idx_load_file(const char *fnidx) {
    bgzf_t *fp = bgzf_open_read(fnidx);
    if (!fp) return NULL;
    kstring_t ks = KS_INITIALIZE;
    uint8_t buf[65536];
    for (;;) { ssize_t n = bgzf_read(fp, buf, sizeof buf); if (n <= 0) break; kputsn((char*)buf, n, &ks); }
    bgzf_close(fp);
    if (ks.l < 4) { free(ks.s); return NULL; }
    rd_t r = { (uint8_t*)ks.s, (uint8_t*)ks.s + ks.l, 0 };
    hts_idx_t *idx = NULL;
    if (memcmp(ks.s, "BAI\1", 4) == 0) {
        r.p += 4;
        int n = (int)r32(&r);
        idx = idx_read_core(&r, HTS_FMT_BAI, n, 14, 5);
    } else if (memcmp(ks.s, "CSI\1", 4) == 0) {
        r.p += 4;
        int min_shift = (int)r32(&r), n_lvls = (int)r32(&r); uint32_t l_meta = r32(&r);
        uint8_t *meta = NULL;
        if (l_meta) { meta = malloc(l_meta); if (r.p + l_meta > r.end) { free(meta); free(ks.s); return NULL; } memcpy(meta, r.p, l_meta); r.p += l_meta; }
        int n = (int)r32(&r);
        idx = idx_read_core(&r, HTS_FMT_CSI, n, min_shift, n_lvls);
        if (idx) { idx->l_meta = l_meta; idx->meta = meta; } else free(meta);
    }
    free(ks.s);
    return idx;
}

static int file_exists(const char *fn) { struct stat st; return stat(fn, &st) == 0; }

static char *try_idx_name(const char *fn, const char *ext) {
    char *s = malloc(strlen(fn) + strlen(ext) + 1);
    sprintf(s, "%s%s", fn, ext);
    if (file_exists(s)) return s;
    free(s);
    /* replace extension */
    const char *dot = strrchr(fn, '.');
    const char *slash = strrchr(fn, '/');
    if (dot && (!slash || dot > slash)) {
        s = malloc(strlen(fn) + strlen(ext) + 1);
        memcpy(s, fn, dot - fn); strcpy(s + (dot - fn), ext);
        if (file_exists(s)) return s;
        free(s);
    }
    return NULL;
}

char *sam_index_find_fn(const char *fn) {
    char *s = try_idx_name(fn, ".csi");
    if (s) return s;
    s = try_idx_name(fn, ".bai");
    return s;
}

hts_idx_t *sam_index_load2(const char *fn, const char *fnidx) {
    char *found = NULL;
    if (!fnidx) {
        found = sam_index_find_fn(fn);
        if (!found) return NULL;
        fnidx = found;
    }
    hts_idx_t *idx = hts_idx_load_file(fnidx);
    free(found);
    return idx;
}

int hts_idx_get_stat(const hts_idx_t *idx, int tid, uint64_t *mapped, uint64_t *unmapped) {
    if (tid < 0 || tid >= idx->n || !idx->bidx[tid]) { *mapped = *unmapped = 0; return -1; }
    uint32_t k = kh32_get(idx->bidx[tid], META_BIN(idx));
    if (k == kh32_end(idx->bidx[tid])) { *mapped = *unmapped = 0; return -1; }
    bins_t *p = kh32_val(idx->bidx[tid], k);
    if (p->n < 2) { *mapped = *unmapped = 0; return -1; }
    *mapped = p->list[1].u; *unmapped = p->list[1].v;
    return 0;
}

uint64_t hts_idx_get_n_no_coor(const hts_idx_t *idx) { return idx->n_no_coor; }
int hts_idx_nseq(const hts_idx_t *idx) { return idx->n; }

/* ---- region parsing ---- */
int64_t hts_parse_decimal(const char *str, char **strend, int flags) {
    (void)flags;
    const char *s = str; int neg = 0;
    while (*s == ' ' || *s == '\t') s++;
    if (*s == '-') { neg = 1; s++; } else if (*s == '+') s++;
    int64_t v = 0; int digits = 0, decimals = 0, e = 0, in_frac = 0;
    for (; *s; s++) {
        if (isdigit((unsigned char)*s)) { if (in_frac) decimals++; else v = v * 10 + (*s - '0'); digits++; }
        else if (*s == ',' && !in_frac) continue;
        else if (*s == '.' && !in_frac) in_frac = 1;
        else break;
    }
    if (*s == 'e' || *s == 'E') {
        char *ee; long ex = strtol(s + 1, &ee, 10);
        if (ee != s + 1) { e = (int)ex; s = ee; }
    }
    if (*s == 'k' || *s == 'K') { e += 3; s++; }
    else if (*s == 'm' || *s == 'M') { e += 6; s++; }
    else if (*s == 'g' || *s == 'G') { e += 9; s++; }
    (void)decimals;
    for (int i = 0; i < e; i++) v *= 10;
    if (strend) *strend = (char*)(digits ? s : str);
    return neg ? -v : v;
}

const char *hts_parse_reg(const char *s, int64_t *beg, int64_t *end) {
    const char *colon = strrchr(s, ':');
    if (!colon) { *beg = 0; *end = HTS_POS_MAX; return s + strlen(s); }
    const char *p = colon + 1; char *e;
    *beg = 0; *end = HTS_POS_MAX;
    if (*p == '-') { /* -end */
        p++;
        int64_t v = hts_parse_decimal(p, &e, 0); if (e == p || *e) return NULL;
        *beg = 0; *end = v; return colon;
    }
    int64_t b = hts_parse_decimal(p, &e, 0);
    if (e == p) return NULL;
    *beg = b > 0 ? b - 1 : 0;
    if (*e == 0) { *end = HTS_POS_MAX; return colon; }
    if (*e != '-') return NULL;
    p = e + 1;
    if (*p == 0) { *end = HTS_POS_MAX; return colon; }
    int64_t en = hts_parse_decimal(p, &e, 0);
    if (e == p || *e) return NULL;
    *end = en;
    if (*beg > *end) return NULL;
    return colon;
}

int hts_parse_region(const char *s, sam_hdr_t *h, int *tid, int64_t *beg, int64_t *end) {
    if (strcmp(s, "*") == 0) { *tid = HTS_IDX_NOCOOR; *beg = 0; *end = HTS_POS_MAX; return 0; }
    int t = sam_hdr_name2tid(h, s);
    if (t >= 0) { *tid = t; *beg = 0; *end = HTS_POS_MAX; return 0; }
    /* {name} braces */
    if (s[0] == '{') {
        const char *close = strchr(s, '}');
        if (!close) return -1;
        char *name = strndup(s + 1, close - s - 1);
        t = sam_hdr_name2tid(h, name); free(name);
        if (t < 0) return -1;
        *tid = t;
        if (close[1] == 0) { *beg = 0; *end = HTS_POS_MAX; return 0; }
        if (close[1] != ':') return -1;
        char tmp[64]; snprintf(tmp, sizeof tmp, "x%s", close + 1);
        if (!hts_parse_reg(tmp, beg, end)) return -1;
        return 0;
    }
    const char *colon = strrchr(s, ':');
    if (!colon) return -1;
    char *name = strndup(s, colon - s);
    t = sam_hdr_name2tid(h, name); free(name);
    if (t < 0) return -1;
    if (!hts_parse_reg(s, beg, end)) return -1;
    *tid = t;
    return 0;
}

/* ---- iterator ---- */
static int reg2bins(int64_t beg, int64_t end, int min_shift, int n_lvls, int **bins, int *nb, int *mb) {
    int l, t, s = min_shift + (n_lvls << 1) + n_lvls;
    if (beg >= end) return 0;
    if (end >= 1LL << s) end = 1LL << s;
    for (--end, l = 0, t = 0; l <= n_lvls; s -= 3, t += 1 << ((l << 1) + l), ++l) {
        int b = t + (int)(beg >> s), e = t + (int)(end >> s);
        for (int i = b; i <= e; ++i) {
            if (*nb == *mb) { *mb = *mb ? *mb * 2 : 64; *bins = realloc(*bins, *mb * sizeof(int)); }
            (*bins)[(*nb)++] = i;
        }
    }
    return *nb;
}

static int pair_cmp_uv(const void *a, const void *b) {
    const hts_pair64_t *x = a, *y = b;
    if (x->u != y->u) return x->u < y->u ? -1 : 1;
    return x->v < y->v ? -1 : x->v > y->v ? 1 : 0;
}

static hts_itr_t *itr_build(const hts_idx_t *idx, int tid, int n, const int64_t *rbeg, const int64_t *rend) {
    hts_itr_t *iter = calloc(1, sizeof(hts_itr_t));
    iter->tid = tid; iter->i = -1;
    iter->n_reg = n; iter->reg_beg = malloc(n * sizeof(int64_t)); iter->reg_end = malloc(n * sizeof(int64_t));
    memcpy(iter->reg_beg, rbeg, n * sizeof(int64_t)); memcpy(iter->reg_end, rend, n * sizeof(int64_t));
    iter->beg = rbeg[0]; iter->end = rend[n-1];
    if (tid < 0 || tid >= idx->n || !idx->bidx[tid]) { iter->finished = 1; return iter; }
    kh32_t *bidx = idx->bidx[tid];
    int n_off = 0, m_off = 0; hts_pair64_t *off = NULL;
    for (int r = 0; r < n; r++) {
        int64_t beg = rbeg[r], end = rend[r];
        if (beg < 0) beg = 0;
        if (end > (int64_t)1 << (idx->min_shift + 3 * idx->n_lvls)) end = (int64_t)1 << (idx->min_shift + 3 * idx->n_lvls);
        if (beg >= end) continue;
        uint64_t min_off = 0, max_off = UINT64_MAX;
        /* min_off from linear index (BAI) or loff (CSI) */
        if (idx->fmt == HTS_FMT_BAI) {
            lidx_t *l = &idx->lidx[tid];
            if (l->n > 0) {
                int64_t ri = beg >> idx->min_shift;
                min_off = ri >= l->n ? l->offset[l->n - 1] : l->offset[ri];
                if (min_off == 0) {
                    int64_t nn = ri; if (nn > l->n) nn = l->n;
                    int64_t i;
                    for (i = nn - 1; i >= 0; --i) if (l->offset[i] != 0) break;
                    if (i >= 0) min_off = l->offset[i];
                }
            }
        } else {
            int bin = hts_bin_first(idx->n_lvls) + (int)(beg >> idx->min_shift);
            uint32_t k = kh32_end(bidx);
            do {
                k = kh32_get(bidx, bin);
                if (k != kh32_end(bidx)) break;
                int first = (hts_bin_parent(bin) << 3) + 1;
                if (bin > first) --bin; else bin = hts_bin_parent(bin);
            } while (bin);
            if (bin == 0) k = kh32_get(bidx, bin);
            min_off = k != kh32_end(bidx) ? kh32_val(bidx, k)->loff : 0;
        }
        {
            int bin = hts_bin_first(idx->n_lvls) + (int)((end - 1) >> idx->min_shift) + 1;
            if (bin >= idx->n_bins) bin = 0;
            while (1) {
                while (bin % 8 == 1) bin = hts_bin_parent(bin);
                if (bin == 0) { max_off = UINT64_MAX; break; }
                uint32_t k = kh32_get(bidx, bin);
                if (k != kh32_end(bidx) && kh32_val(bidx, k)->n > 0) { max_off = kh32_val(bidx, k)->list[0].u; break; }
                bin++;
            }
        }
        int *bins = NULL, nb = 0, mb = 0;
        reg2bins(beg, end, idx->min_shift, idx->n_lvls, &bins, &nb, &mb);
        for (int i = 0; i < nb; i++) {
            uint32_t k = kh32_get(bidx, bins[i]);
            if (k == kh32_end(bidx)) continue;
            bins_t *p = kh32_val(bidx, k);
            for (int j = 0; j < p->n; j++) {
                if (p->list[j].v > min_off && p->list[j].u < max_off) {
                    if (n_off == m_off) { m_off = m_off ? m_off * 2 : 16; off = realloc(off, m_off * sizeof(hts_pair64_t)); }
                    off[n_off].u = min_off > p->list[j].u ? min_off : p->list[j].u;
                    off[n_off].v = max_off < p->list[j].v ? max_off : p->list[j].v;
                    n_off++;
                }
            }
        }
        free(bins);
    }
    if (n_off == 0) { iter->finished = 1; free(off); return iter; }
    qsort(off, n_off, sizeof(hts_pair64_t), pair_cmp_uv);
    int i, l;
    for (i = 1, l = 0; i < n_off; ++i) if (off[l].v < off[i].v) off[++l] = off[i];
    n_off = l + 1;
    for (i = 1; i < n_off; ++i) if (off[i-1].v >= off[i].u) off[i-1].v = off[i].u;
    for (i = 1, l = 0; i < n_off; ++i) {
        if (off[l].v >> 16 == off[i].u >> 16) off[l].v = off[i].v;
        else off[++l] = off[i];
    }
    n_off = l + 1;
    iter->n_off = n_off; iter->off = off;
    return iter;
}

hts_itr_t *sam_itr_queryi(const hts_idx_t *idx, int tid, int64_t beg, int64_t end) {
    if (tid == HTS_IDX_NOCOOR) {
        hts_itr_t *iter = calloc(1, sizeof(hts_itr_t));
        iter->tid = tid; iter->nocoor = 1; iter->read_rest = 1; iter->curr_off = 0;
        if (idx && idx->n > 0) {
            /* start after the last ref with data */
            for (int t = idx->n - 1; t >= 0; t--) {
                if (!idx->bidx[t]) continue;
                uint32_t k = kh32_get(idx->bidx[t], META_BIN(idx));
                if (k != kh32_end(idx->bidx[t]) && kh32_val(idx->bidx[t], k)->n >= 1) { iter->curr_off = kh32_val(idx->bidx[t], k)->list[0].v; break; }
            }
            if (idx->n_no_coor == 0) iter->finished = 1;
        }
        return iter;
    }
    if (tid == HTS_IDX_START || tid == HTS_IDX_REST) {
        hts_itr_t *iter = calloc(1, sizeof(hts_itr_t));
        iter->tid = tid; iter->read_rest = 1; iter->curr_off = 0;
        return iter;
    }
    return itr_build(idx, tid, 1, &beg, &end);
}

hts_itr_t *sam_itr_query_multi(const hts_idx_t *idx, int tid, int n, const int64_t *beg, const int64_t *end) {
    return itr_build(idx, tid, n, beg, end);
}

hts_itr_t *sam_itr_querys(const hts_idx_t *idx, sam_hdr_t *h, const char *region) {
    int tid; int64_t beg, end;
    if (hts_parse_region(region, h, &tid, &beg, &end) < 0) return NULL;
    return sam_itr_queryi(idx, tid, beg, end);
}

void hts_itr_destroy(hts_itr_t *itr) { if (!itr) return; free(itr->off); free(itr->reg_beg); free(itr->reg_end); free(itr); }

int sam_itr_next(samfile_t *fp, hts_itr_t *iter, bam1_t *b) {
    if (iter->finished) return -1;
    if (iter->read_rest) {
        if (iter->curr_off) { if (bgzf_seek(fp->bg, iter->curr_off, 0) < 0) return -2; iter->curr_off = 0; }
        for (;;) {
            int ret = sam_read1(fp, fp->hdr, b);
            if (ret < 0) { iter->finished = 1; return ret; }
            if (iter->nocoor) { if (b->core.tid < 0) return ret; else continue; }
            return ret;
        }
    }
    for (;;) {
        if (iter->i < 0 || iter->curr_off >= iter->off[iter->i].v) {
            if (iter->i == iter->n_off - 1) { iter->finished = 1; return -1; }
            if (iter->i < 0 || iter->off[iter->i].v != iter->off[iter->i+1].u) {
                if (bgzf_seek(fp->bg, iter->off[iter->i+1].u, 0) < 0) return -2;
                iter->curr_off = bgzf_tell(fp->bg);
            }
            ++iter->i;
        }
        int ret = sam_read1(fp, fp->hdr, b);
        if (ret >= 0) {
            iter->curr_off = bgzf_tell(fp->bg);
            int64_t beg = b->core.pos, end = bam_endpos(b);
            if (b->core.tid != iter->tid || beg >= iter->end) { iter->finished = 1; return -1; }
            for (int r = 0; r < iter->n_reg; r++) {
                if (end > iter->reg_beg[r] && iter->reg_end[r] > beg) return ret;
            }
        } else { iter->finished = 1; return ret; }
    }
}

void reglist_add(hts_reglist_t *l, int tid, int64_t beg, int64_t end) {
    if (l->n == l->m) { l->m = l->m ? l->m * 2 : 16; l->a = realloc(l->a, l->m * sizeof(hts_reglist_item_t)); }
    l->a[l->n].tid = tid; l->a[l->n].beg = beg; l->a[l->n].end = end; l->n++;
}

static int reg_cmp(const void *a, const void *b) {
    const hts_reglist_item_t *x = a, *y = b;
    if (x->tid != y->tid) return x->tid < y->tid ? -1 : 1;
    if (x->beg != y->beg) return x->beg < y->beg ? -1 : 1;
    return x->end < y->end ? -1 : x->end > y->end ? 1 : 0;
}

void reglist_sort_merge(hts_reglist_t *l) {
    if (l->n == 0) return;
    qsort(l->a, l->n, sizeof(hts_reglist_item_t), reg_cmp);
    int j = 0;
    for (int i = 1; i < l->n; i++) {
        if (l->a[i].tid == l->a[j].tid && l->a[i].beg <= l->a[j].end) { if (l->a[i].end > l->a[j].end) l->a[j].end = l->a[i].end; }
        else l->a[++j] = l->a[i];
    }
    l->n = j + 1;
}
