#include "bedidx.h"
#include "samfile.h"
#include "strmap.h"
#include "samtools.h"
#include <string.h>
#include <ctype.h>

typedef struct { int64_t beg, end; } intv_t;
typedef struct { char *name; int n, m; intv_t *a; int sorted; } bed_chr_t;
struct bed_t { int n, m; bed_chr_t *c; strmap_t *map; int nraw, mraw; struct { int chr; int64_t beg, end; } *raw; };

static int intv_cmp(const void *a, const void *b) {
    const intv_t *x = a, *y = b;
    if (x->beg != y->beg) return x->beg < y->beg ? -1 : 1;
    return x->end < y->end ? -1 : x->end > y->end ? 1 : 0;
}

static bed_chr_t *bed_get_chr(bed_t *b, const char *name) {
    int is_new; strmap_entry_t *e = strmap_put(b->map, name, &is_new);
    if (is_new) {
        if (b->n == b->m) { b->m = b->m ? b->m * 2 : 16; b->c = realloc(b->c, b->m * sizeof(bed_chr_t)); }
        bed_chr_t *c = &b->c[b->n]; memset(c, 0, sizeof *c); c->name = strdup(name);
        e->val = b->n++;
    }
    return &b->c[e->val];
}

bed_t *bed_read(const char *fn) {
    textfile_t *t = text_open(fn);
    if (!t) return NULL;
    bed_t *b = calloc(1, sizeof(bed_t)); b->map = strmap_new();
    int lineno = 0;
    while (text_getline(t) >= 0) {
        lineno++;
        char *line = t->line;
        if (strncmp(line, "track ", 6) == 0 || strncmp(line, "browser ", 8) == 0 || line[0] == '#' || line[0] == 0) continue;
        /* fields separated by whitespace */
        char *f[4] = {0,0,0,0}; int nf = 0;
        char *p = line;
        while (*p && nf < 4) {
            while (*p == ' ' || *p == '\t') p++;
            if (!*p) break;
            f[nf++] = p;
            while (*p && *p != ' ' && *p != '\t') p++;
            if (*p) *p++ = 0;
        }
        if (nf < 2) continue;
        char *e; int64_t beg, end;
        beg = strtoll(f[1], &e, 10);
        if (*e) continue;
        if (nf >= 3) {
            end = strtoll(f[2], &e, 10);
            if (*e) { end = beg; beg = beg - 1; }
        } else { end = beg; beg = beg - 1; }
        if (beg < 0) beg = 0;
        if (end < beg) {
            fprintf(stderr, "[bed_read] Parse error reading \"%s\" at line %d : end (%lld) must not be less than start (%lld)\n", fn, lineno, (long long)end, (long long)beg);
            text_close(t); bed_destroy(b); return NULL;
        }
        bed_chr_t *c = bed_get_chr(b, f[0]);
        if (c->n == c->m) { c->m = c->m ? c->m * 2 : 16; c->a = realloc(c->a, c->m * sizeof(intv_t)); }
        c->a[c->n].beg = beg; c->a[c->n].end = end; c->n++;
        if (b->nraw == b->mraw) { b->mraw = b->mraw ? b->mraw * 2 : 16; b->raw = realloc(b->raw, b->mraw * sizeof(*b->raw)); }
        b->raw[b->nraw].chr = (int)(c - b->c); b->raw[b->nraw].beg = beg; b->raw[b->nraw].end = end; b->nraw++;
    }
    text_close(t);
    for (int i = 0; i < b->n; i++) { qsort(b->c[i].a, b->c[i].n, sizeof(intv_t), intv_cmp); b->c[i].sorted = 1; }
    return b;
}

void bed_unify(bed_t *b) {
    for (int i = 0; i < b->n; i++) {
        bed_chr_t *c = &b->c[i];
        if (c->n == 0) continue;
        int j = 0;
        for (int k = 1; k < c->n; k++) {
            if (c->a[k].beg <= c->a[j].end) { if (c->a[k].end > c->a[j].end) c->a[j].end = c->a[k].end; }
            else c->a[++j] = c->a[k];
        }
        c->n = j + 1;
    }
}

void bed_destroy(bed_t *b) {
    if (!b) return;
    for (int i = 0; i < b->n; i++) { free(b->c[i].name); free(b->c[i].a); }
    free(b->c); free(b->raw); strmap_free(b->map); free(b);
}

int bed_overlap(const bed_t *b, const char *chr, int64_t beg, int64_t end) {
    int64_t idx;
    if (strmap_get(b->map, chr, &idx) < 0) return 0;
    const bed_chr_t *c = &b->c[idx];
    /* sorted by beg: binary search for first interval with end > beg, scan */
    int lo = 0, hi = c->n;
    /* find first interval whose beg < end */
    for (int i = 0; i < c->n; i++) {
        if (c->a[i].beg >= end) break;
        if (c->a[i].end > beg) return 1;
    }
    (void)lo; (void)hi;
    return 0;
}

int bed_nchr(const bed_t *b) { return b->n; }
const char *bed_chr_name(const bed_t *b, int i) { return b->c[i].name; }
int bed_chr_nintv(const bed_t *b, int i) { return b->c[i].n; }
void bed_chr_intv(const bed_t *b, int i, int j, int64_t *beg, int64_t *end) { *beg = b->c[i].a[j].beg; *end = b->c[i].a[j].end; }
int64_t bed_total_len(const bed_t *b) {
    int64_t tot = 0;
    for (int i = 0; i < b->n; i++) {
        const bed_chr_t *c = &b->c[i];
        int64_t last_end = -1;
        for (int j = 0; j < c->n; j++) {
            int64_t s = c->a[j].beg > last_end ? c->a[j].beg : last_end;
            if (c->a[j].end > s) tot += c->a[j].end - s;
            if (c->a[j].end > last_end) last_end = c->a[j].end;
        }
    }
    return tot;
}
int bed_nraw(const bed_t *b) { return b->nraw; }
void bed_raw(const bed_t *b, int i, const char **chr, int64_t *beg, int64_t *end) { *chr = b->c[b->raw[i].chr].name; *beg = b->raw[i].beg; *end = b->raw[i].end; }
