    return h;
}
static inline uint32_t Wang_hash(uint32_t key) {
    key += ~(key << 15); key ^= (key >> 10); key += (key << 3); key ^= (key >> 6); key += ~(key << 11); key ^= (key >> 16);
    return key;
}

static const char *bam_get_library(sam_hdr_t *h, const bam1_t *b, char *buf, size_t bufsz) {
    uint8_t *rg = bam_aux_get(b, "RG");
    if (!rg) return NULL;
    char *lb = sam_hdr_find_tag_id(h, "RG", "ID", (char*)rg + 1, "LB");
    if (!lb) return NULL;
    snprintf(buf, bufsz, "%s", lb); free(lb);
    return buf;
}

static void bam_remove_B(bam1_t *b) {
    /* collapse the backward CIGAR operation */
    int k, has_B = 0;
    uint32_t *cigar = bam_get_cigar(b);
    for (k = 0; k < (int)b->core.n_cigar; k++) if (bam_cigar_op(cigar[k]) == BAM_CBACK) { has_B = 1; break; }
    if (!has_B) return;
    /* simplified: remove B ops by merging */
    /* full implementation follows htslib's bam_remove_B algorithm */
    int i, j, l, end_j, no_qual = (bam_get_qual(b)[0] == 0xff);
    uint32_t *new_cigar = malloc(b->core.n_cigar * 4 + 8); int nc = 0;
    uint8_t *seq = bam_get_seq(b), *qual = bam_get_qual(b);
    uint8_t *new_seq = calloc((b->core.l_qseq + 1) / 2 + 1, 1), *new_qual = malloc(b->core.l_qseq + 1);
    for (k = 0, i = 0, j = 0, end_j = -1; k < (int)b->core.n_cigar; k++) {
        int op = bam_cigar_op(cigar[k]); l = bam_cigar_oplen(cigar[k]);
        if (op == BAM_CBACK) {
            if (i - l < 0) { free(new_cigar); free(new_seq); free(new_qual); return; }
            if (k == (int)b->core.n_cigar - 1) break;
            /* rewind */
            int t, u;
            for (t = 0, u = l; t < nc && u > 0; ) {
                int op2 = bam_cigar_op(new_cigar[nc-1]), l2 = bam_cigar_oplen(new_cigar[nc-1]);
                if (!(bam_cigar_type(op2) & 1)) { nc--; continue; }
                if (l2 <= u) { u -= l2; nc--; } else { new_cigar[nc-1] = bam_cigar_gen(l2 - u, op2); u = 0; }
            }
            i -= l; j = i;
            end_j = i + l;
        } else {
            if (bam_cigar_type(op) & 1) {
                for (int x = 0; x < l; x++) {
                    bam_set_seqi(new_seq, j, bam_seqi(seq, i));
                    if (!no_qual) new_qual[j] = qual[i];
                    i++; j++;
                }
            }
            if (nc && bam_cigar_op(new_cigar[nc-1]) == op) new_cigar[nc-1] = bam_cigar_gen(bam_cigar_oplen(new_cigar[nc-1]) + l, op);
            else new_cigar[nc++] = cigar[k];
        }
    }
    (void)end_j;
    int new_lq = j;
    /* rebuild record */
    int l_aux = bam_get_l_aux(b);
    uint8_t *aux = malloc(l_aux + 1); memcpy(aux, bam_get_aux(b), l_aux);
    int ql = b->core.l_qname;
    int need = ql + nc * 4 + (new_lq + 1) / 2 + new_lq + l_aux;
    bam_set_data_cap(b, need);
    uint8_t *p = b->data + ql;
    memcpy(p, new_cigar, nc * 4); p += nc * 4;
    memcpy(p, new_seq, (new_lq + 1) / 2); p += (new_lq + 1) / 2;
    if (no_qual) memset(p, 0xff, new_lq); else memcpy(p, new_qual, new_lq);
    p += new_lq;
    memcpy(p, aux, l_aux); p += l_aux;
    b->l_data = (int)(p - b->data);
    b->core.n_cigar = nc; b->core.l_qseq = new_lq;
    free(aux); free(new_cigar); free(new_seq); free(new_qual);
}

static void remove_aux_tags(bam1_t *b, view_settings_t *s) {
    uint8_t *p = bam_get_aux(b), *end = b->data + b->l_data;
    while (p + 3 <= end) {
        char tag[3] = { (char)p[0], (char)p[1], 0 };
        uint8_t *next = bam_aux_skip(p + 2, end);
        if (!next) break;
        int in = strmap_find(s->remove_aux, tag) != NULL;
        int remove = s->keep_aux_mode ? !in : in;
        if (remove) {
            memmove(p, next, end - next);
            b->l_data -= (int)(next - p);
            end = b->data + b->l_data;
        } else p = next;
    }
}

static int process_aln(sam_hdr_t *h, bam1_t *b, view_settings_t *s) {
    if (s->remove_B) bam_remove_B(b);
    if (s->min_qlen > 0) {
        int qlen = 0; uint32_t *cigar = bam_get_cigar(b);
        for (uint32_t k = 0; k < b->core.n_cigar; k++)
            if ((bam_cigar_type(bam_cigar_op(cigar[k])) & 1) || bam_cigar_op(cigar[k]) == BAM_CHARD_CLIP) qlen += bam_cigar_oplen(cigar[k]);
        if (qlen < s->min_qlen) return 1;
    }
    if (b->core.qual < s->min_mapQ || ((b->core.flag & s->flag_on) != s->flag_on) || (b->core.flag & s->flag_off)) return 1;
    if (s->flag_alloff && ((b->core.flag & s->flag_alloff) == s->flag_alloff)) return 1;
    if (s->flag_anyon && ((b->core.flag & s->flag_anyon) == 0)) return 1;
    if (s->bed && (b->core.tid < 0 || !bed_overlap(s->bed, sam_hdr_tid2name(h, b->core.tid), b->core.pos, bam_endpos(b)))) return 1;
    if (s->subsam_frac > 0.) {
        uint32_t k = Wang_hash(X31_hash_string(bam_get_qname(b)) ^ s->subsam_seed);
        if ((double)(k & 0xffffff) / 0x1000000 >= s->subsam_frac) return 1;
    }
    if (s->rghash) {
        uint8_t *rg = bam_aux_get(b, "RG");
        if (rg) { if (!strmap_find(s->rghash, (char*)rg + 1)) return 1; }
        else if (s->exclude_no_rg) return 1;
    } else if (s->exclude_no_rg) {
        if (!bam_aux_get(b, "RG")) return 1;
    }
    if (s->tag[0]) {
        uint8_t *t = bam_aux_get(b, s->tag);
        if (t) {
            if (s->tvhash) {
                char buf[32]; const char *val;
                if (bam_aux_is_int(t)) { snprintf(buf, sizeof buf, "%lld", (long long)bam_aux2i(t)); val = buf; }
                else if (*t == 'A') { buf[0] = (char)t[1]; buf[1] = 0; val = buf; }
                else if (*t == 'f' || *t == 'd') { snprintf(buf, sizeof buf, "%g", bam_aux2f(t)); val = buf; }
                else val = (char*)t + 1;
                if (!strmap_find(s->tvhash, val)) return 1;
            }
        } else return 1;
    }
    if (s->rnhash) {
        int in = strmap_find(s->rnhash, bam_get_qname(b)) != NULL;
        if (s->rn_negate ? in : !in) return 1;
    }
    if (s->library) {
        char buf[1024];
        const char *lib = bam_get_library(h, b, buf, sizeof buf);
        if (!lib || strcmp(lib, s->library) != 0) return 1;
    }
    if (s->filter) {
        int r = hts_filter_eval_bam(s->filter, h, b);
        if (r < 0) return -1;
        if (r == 0) return 1;
    }
    return 0;
}

static void change_flag(bam1_t *b, view_settings_t *s) {
    if (s->add_flags) b->core.flag |= s->add_flags;
    if (s->remove_flags) b->core.flag &= ~s->remove_flags;
}

static int add_read_group_single(const char *subcmd, view_settings_t *s, const char *name) {
    if (!s->rghash) s->rghash = strmap_new();
    strmap_set(s->rghash, name, 1);
    (void)subcmd;
    return 0;
}

static int add_read_groups_file(const char *subcmd, view_settings_t *s, const char *fn) {
    int negate = 0;
    if (fn[0] == '^') { negate = 1; fn++; }
    textfile_t *t = text_open(fn);
    if (!t) { print_error_errno(subcmd, "failed to open \"%s\" for reading", fn); return -1; }
    strmap_t *m = strmap_new();
    while (text_getline(t) >= 0) {
        char *line = t->line; char *e = line; while (*e && *e != '\t' && *e != ' ' && *e != '\r') e++; *e = 0;
        if (*line) strmap_set(m, line, 1);
    }
    text_close(t);
    (void)negate;
    if (!s->rghash) s->rghash = strmap_new();
    for (size_t i = 0; i < m->cap; i++) if (m->e[i].used) strmap_set(s->rghash, m->e[i].key, 1);
    strmap_free(m);
    return 0;
}

static strmap_t *load_names_file(const char *subcmd, const char *fn, int *negate) {
    *negate = 0;
    if (fn[0] == '^') { *negate = 1; fn++; }
    textfile_t *t = text_open(fn);
    if (!t) { print_error_errno(subcmd, "failed to open \"%s\" for reading", fn); return NULL; }
    strmap_t *m = strmap_new();
    while (text_getline(t) >= 0) {
        char *line = t->line; char *e = line; while (*e && *e != '\t' && *e != '\r') e++; *e = 0;
        if (*line) strmap_set(m, line, 1);
    }
    text_close(t);
    return m;
}

static int parse_aux_list(view_settings_t *s, const char *optarg, int keep) {
    const char *p = optarg;
    if (*p == '^') { keep = !keep; p++; }
    if (!s->remove_aux) s->remove_aux = strmap_new();
    if (keep) s->keep_aux_mode = 1;
    while (*p) {
        if (strlen(p) < 2 || (p[2] != ',' && p[2] != 0)) { print_error("view", "Expected a two character tag name in -x option '%s'", optarg); return -1; }
        char tag[3] = { p[0], p[1], 0 };
        strmap_set(s->remove_aux, tag, 1);
        s->n_remove_aux++;
        p += 2;
        if (*p == ',') p++;
    }
    return 0;
}

static int write_counts(const char *fn, int64_t processed, int64_t accepted, int64_t rejected) {
    FILE *fp = fopen(fn, "w");
    if (!fp) { print_error_errno("view", "failed to open \"%s\" for writing", fn); return -1; }
    fprintf(fp, "{\n    \"records_processed\" : %lld,\n    \"records_filter_accepted\" : %lld,\n    \"records_filter_rejected\" : %lld\n}\n", (long long)processed, (long long)accepted, (long long)rejected);
    fclose(fp);
    return 0;
}

int main_samview(int argc, char **argv) {
    view_settings_t s; memset(&s, 0, sizeof s);
    sam_global_args ga = SAM_GLOBAL_ARGS_INIT;
    int c, is_header = 0, is_header_only = 0, ret = 0, compress_level = -1, is_count = 0;
    int is_long_help = 0, has_index_file = 0, multi_region = 0, fetch_pairs = 0;
    int out_fmt_set = 0, out_bam = 0, out_cram = 0;
    char *fn_in = NULL, *fn_out = NULL, *fn_list = NULL, *fn_un_out = NULL, *fn_counts = NULL, *fn_region_file = NULL, *fn_bed = NULL;
    char *fn_idx_in = NULL;
    int64_t count = 0, count_filtered = 0, count_processed = 0;
    int no_pg = 0;
    const char *out_mode_fmt = NULL;

    enum { OPT_RF = 1000, OPT_NO_HEADER = 1010, OPT_SAVE_COUNTS, OPT_SUBSAMPLE, OPT_SUBSAMPLE_SEED, OPT_ADD_FLAGS, OPT_REMOVE_FLAGS, OPT_KEEP_TAG, OPT_NO_PG, OPT_REGION_FILE,
           OPT_INPUT_FMT = 1001, OPT_INPUT_FMT_OPTION = 1002, OPT_OUTPUT_FMT = 1003, OPT_OUTPUT_FMT_OPTION = 1004, OPT_REFERENCE = 1005, OPT_THREADS = 1006, OPT_WRITE_INDEX = 1007, OPT_VERBOSITY = 1008 };
    static const struct option lopts[] = {
        { "bam", no_argument, NULL, 'b' }, { "cram", no_argument, NULL, 'C' }, { "fast", no_argument, NULL, '1' },
        { "uncompressed", no_argument, NULL, 'u' }, { "with-header", no_argument, NULL, 'h' }, { "header-only", no_argument, NULL, 'H' },
        { "no-header", no_argument, NULL, OPT_NO_HEADER }, { "count", no_argument, NULL, 'c' }, { "save-counts", required_argument, NULL, OPT_SAVE_COUNTS },
        { "output", required_argument, NULL, 'o' }, { "unoutput", required_argument, NULL, 'U' }, { "output-unselected", required_argument, NULL, 'U' },
        { "unmap", no_argument, NULL, 'p' }, { "fetch-pairs", no_argument, NULL, 'P' },
        { "fai-reference", required_argument, NULL, 't' }, { "use-index", no_argument, NULL, 'M' },
        { "region-file", required_argument, NULL, OPT_REGION_FILE }, { "regions-file", required_argument, NULL, OPT_REGION_FILE },
        { "customized-index", no_argument, NULL, 'X' },
        { "target-file", required_argument, NULL, 'L' }, { "targets-file", required_argument, NULL, 'L' },
        { "qname-file", required_argument, NULL, 'N' }, { "read-group", required_argument, NULL, 'r' }, { "read-group-file", required_argument, NULL, 'R' },
        { "exclude-no-read_group", no_argument, NULL, 'n' }, { "exclude-no-read-group", no_argument, NULL, 'n' },
        { "tag", required_argument, NULL, 'd' }, { "tag-file", required_argument, NULL, 'D' },
        { "min-MQ", required_argument, NULL, 'q' }, { "min-mq", required_argument, NULL, 'q' }, { "library", required_argument, NULL, 'l' }, { "min-qlen", required_argument, NULL, 'm' },
        { "expr", required_argument, NULL, 'e' }, { "require-flags", required_argument, NULL, 'f' }, { "excl-flags", required_argument, NULL, 'F' }, { "exclude-flags", required_argument, NULL, 'F' },
        { "rf", required_argument, NULL, OPT_RF }, { "incl-flags", required_argument, NULL, OPT_RF }, { "include-flags", required_argument, NULL, OPT_RF },
        { "subsample", required_argument, NULL, OPT_SUBSAMPLE }, { "subsample-seed", required_argument, NULL, OPT_SUBSAMPLE_SEED },
        { "add-flags", required_argument, NULL, OPT_ADD_FLAGS }, { "remove-flags", required_argument, NULL, OPT_REMOVE_FLAGS },
        { "remove-tag", required_argument, NULL, 'x' }, { "keep-tag", required_argument, NULL, OPT_KEEP_TAG }, { "remove-B", no_argument, NULL, 'B' },
        { "sanitize", required_argument, NULL, 'z' }, { "help", no_argument, NULL, '?' }, { "no-PG", no_argument, NULL, OPT_NO_PG },
        { "input-fmt", required_argument, NULL, OPT_INPUT_FMT }, { "input-fmt-option", required_argument, NULL, OPT_INPUT_FMT_OPTION },
        { "output-fmt", required_argument, NULL, OPT_OUTPUT_FMT }, { "output-fmt-option", required_argument, NULL, OPT_OUTPUT_FMT_OPTION },
        { "reference", required_argument, NULL, OPT_REFERENCE }, { "threads", required_argument, NULL, OPT_THREADS },
        { "write-index", no_argument, NULL, OPT_WRITE_INDEX }, { "verbosity", required_argument, NULL, OPT_VERBOSITY },
        { NULL, 0, NULL, 0 }
    };

    char *tag_file = NULL;
    double subsam_frac_opt = -1; long subsam_seed_opt = 0; int seed_set = 0;
    char *fn_rn = NULL;
    opterr = 0;
    while ((c = getopt_long(argc, argv, "SbBcCt:h1Ho:O:q:f:F:G:ul:r:?T:R:d:D:L:s:@:m:x:U:MXe:pPnz:N:", lopts, NULL)) >= 0) {
        switch (c) {
        case 's': {
            char *q;
            s.subsam_seed = (uint32_t)strtol(optarg, &q, 10);
            if (s.subsam_seed != 0) { srand(s.subsam_seed); s.subsam_seed = (uint32_t)rand(); }
            if (q && *q == '.') s.subsam_frac = strtod(q, &q);
            else if (q && *q) { print_error("view", "Incorrect sampling argument \"%s\"", optarg); ret = 1; goto view_end; }
            break;
        }
        case OPT_SUBSAMPLE: subsam_frac_opt = strtod(optarg, NULL); break;
        case OPT_SUBSAMPLE_SEED: subsam_seed_opt = strtol(optarg, NULL, 10); seed_set = 1; break;
        case 'm': s.min_qlen = atoi(optarg); break;
        case 'c': is_count = 1; break;
        case 'S': break;
        case 'b': out_bam = 1; out_fmt_set = 1; break;
        case 'C': out_cram = 1; out_fmt_set = 1; break;
        case 't': fn_list = strdup(optarg); break;
        case 'h': is_header = 1; break;
        case 'H': is_header_only = 1; break;
        case OPT_NO_HEADER: is_header = is_header_only = 0; break;
        case 'o': fn_out = strdup(optarg); break;
        case 'U': fn_un_out = strdup(optarg); break;
        case 'X': has_index_file = 1; break;
        case 'f': { int f = bam_str2flag(optarg); if (f < 0) { print_error("view", "Unknown flag '%s'", optarg); ret = 1; goto view_end; } s.flag_on |= f; break; }
        case 'F': { int f = bam_str2flag(optarg); if (f < 0) { print_error("view", "Unknown flag '%s'", optarg); ret = 1; goto view_end; } s.flag_off |= f; break; }
        case 'G': { int f = bam_str2flag(optarg); if (f < 0) { print_error("view", "Unknown flag '%s'", optarg); ret = 1; goto view_end; } s.flag_alloff |= f; break; }
        case OPT_RF: { int f = bam_str2flag(optarg); if (f < 0) { print_error("view", "Unknown flag '%s'", optarg); ret = 1; goto view_end; } s.flag_anyon |= f; break; }
        case 'q': s.min_mapQ = atoi(optarg); break;
        case 'u': compress_level = 0; out_bam = out_cram ? out_bam : 1; if (!out_fmt_set) { out_bam = 1; } break;
        case '1': compress_level = 1; if (!out_fmt_set) out_bam = 1; break;
        case 'l': s.library = strdup(optarg); break;
        case 'p': s.unmap = 1; break;
        case 'P': fetch_pairs = 1; break;
        case 'L': fn_bed = strdup(optarg); break;
        case 'N': fn_rn = strdup(optarg); break;
        case 'r': if (add_read_group_single("view", &s, optarg) != 0) { ret = 1; goto view_end; } break;
        case 'R': if (add_read_groups_file("view", &s, optarg) != 0) { ret = 1; goto view_end; } break;
        case 'n': s.exclude_no_rg = 1; break;
        case 'd': {
            if (strlen(optarg) < 2 || (strlen(optarg) > 2 && optarg[2] != ':')) { print_error("view", "Invalid \"tag:value\" option: \"%s\"", optarg); ret = 1; goto view_end; }
            if (s.tag[0] && (s.tag[0] != optarg[0] || s.tag[1] != optarg[1])) { print_error("view", "Different tag \"%s\" was specified", optarg); ret = 1; goto view_end; }
            s.tag[0] = optarg[0]; s.tag[1] = optarg[1]; s.tag[2] = 0;
            if (strlen(optarg) > 3) { if (!s.tvhash) s.tvhash = strmap_new(); strmap_set(s.tvhash, optarg + 3, 1); }
            break;
        }
        case 'D': {
            if (strlen(optarg) < 4 || optarg[2] != ':') { print_error("view", "Invalid \"tag:file\" option: \"%s\"", optarg); ret = 1; goto view_end; }
            if (s.tag[0] && (s.tag[0] != optarg[0] || s.tag[1] != optarg[1])) { print_error("view", "Different tag \"%s\" was specified", optarg); ret = 1; goto view_end; }
            s.tag[0] = optarg[0]; s.tag[1] = optarg[1]; s.tag[2] = 0;
            tag_file = strdup(optarg + 3);
            break;
        }
        case 'x': if (parse_aux_list(&s, optarg, 0) < 0) { ret = 1; goto view_end; } break;
        case OPT_KEEP_TAG: if (parse_aux_list(&s, optarg, 1) < 0) { ret = 1; goto view_end; } break;
        case 'B': s.remove_B = 1; break;
        case 'z': s.sanitize = bam_sanitize_options(optarg); if (s.sanitize < 0) { ret = 1; goto view_end; } break;
        case 'M': multi_region = 1; break;
        case OPT_REGION_FILE: fn_region_file = strdup(optarg); multi_region = 1; break;
        case OPT_SAVE_COUNTS: fn_counts = strdup(optarg); break;
        case OPT_ADD_FLAGS: { int f = bam_str2flag(optarg); if (f < 0) { print_error("view", "Unknown flag '%s'", optarg); ret = 1; goto view_end; } s.add_flags |= f; break; }
        case OPT_REMOVE_FLAGS: { int f = bam_str2flag(optarg); if (f < 0) { print_error("view", "Unknown flag '%s'", optarg); ret = 1; goto view_end; } s.remove_flags |= f; break; }
        case 'e': s.filter = hts_filter_init(optarg); if (!s.filter) { print_error("view", "Couldn't initialise filter"); ret = 1; goto view_end; } break;
        case OPT_NO_PG: no_pg = 1; break;
        case 'T': free(ga.reference); ga.reference = strdup(optarg); break;
        case '@': ga.nthreads = atoi(optarg); break;
        case 'O': {
            int fmt = 0, comp = 0, level = ga.out_level;
            if (parse_format_string(optarg, &fmt, &comp, &level, 1) < 0 || fmt == 0) { return usage(stderr, 1, 0); }
            ga.out_fmt = fmt; ga.out_comp = comp; ga.out_level = level; out_fmt_set = 1;
            break;
        }
        case OPT_OUTPUT_FMT: {
            int fmt = 0, comp = 0, level = ga.out_level;
            if (parse_format_string(optarg, &fmt, &comp, &level, 1) < 0 || fmt == 0) { return usage(stderr, 1, 0); }
            ga.out_fmt = fmt; ga.out_comp = comp; ga.out_level = level; out_fmt_set = 1;
            break;
        }
        case OPT_INPUT_FMT: case OPT_INPUT_FMT_OPTION: break;
        case OPT_OUTPUT_FMT_OPTION: { int level = ga.out_level, fmt = ga.out_fmt; parse_format_option(optarg, &level, &fmt); ga.out_level = level; break; }
        case OPT_REFERENCE: free(ga.reference); ga.reference = strdup(optarg); break;
        case OPT_THREADS: ga.nthreads = atoi(optarg); break;
        case OPT_WRITE_INDEX: ga.write_index = 1; break;
        case OPT_VERBOSITY: hts_verbose = atoi(optarg); break;
        case '?':
            if (optopt == '?' || (optind > 0 && strcmp(argv[optind-1], "-?") == 0) || strcmp(argv[optind-1], "--help") == 0) { is_long_help = 1; return usage(stdout, 0, is_long_help); }
            if (optopt) { fprintf(stderr, "samtools view: invalid option -- '%c'\n", optopt); }
            else fprintf(stderr, "samtools view: unrecognized option '%s'\n", argv[optind-1]);
            return usage(stderr, 1, 0);
        default:
            return usage(stderr, 1, 0);
        }
    }
    if (subsam_frac_opt >= 0) {
        s.subsam_frac = subsam_frac_opt;
        if (seed_set) { s.subsam_seed = (uint32_t)subsam_seed_opt; if (s.subsam_seed != 0) { srand(s.subsam_seed); s.subsam_seed = (uint32_t)rand(); } }
    }
    if (compress_level >= 0 && ga.out_level < 0) ga.out_level = compress_level;
    if (out_cram) ga.out_fmt = FMT_CRAM;
    else if (out_bam && (ga.out_fmt == 0 || ga.out_fmt == FMT_SAM)) { if (ga.out_fmt == 0) ga.out_fmt = FMT_BAM; }
    (void)out_mode_fmt;

    if (fn_un_out && fn_out == NULL && !is_count) { /* fine: un_out separate */ }

    if (is_header_only) is_header = 1;
    if (argc == optind && isatty(STDIN_FILENO)) return usage(stderr, 1, is_long_help);

    fn_in = (optind < argc) ? argv[optind] : "-";
    if (has_index_file) {
        if (optind + 1 < argc) fn_idx_in = argv[optind + 1];
        else { print_error("view", "Incorrect number of arguments for -X option. Aborting."); ret = 1; goto view_end; }
    }
    int region_start = optind + 1 + (has_index_file ? 1 : 0);

    if (fn_rn) {
        s.rnhash = load_names_file("view", fn_rn, &s.rn_negate);
        if (!s.rnhash) { ret = 1; goto view_end; }
    }
    if (tag_file) {
        int neg;
        s.tvhash = load_names_file("view", tag_file, &neg);
        if (!s.tvhash) { ret = 1; goto view_end; }
    }
    if (fn_bed) {
        s.bed = bed_read(fn_bed);
        if (!s.bed) { print_error_errno("view", "Could not read file \"%s\"", fn_bed); ret = 1; goto view_end; }
    }
    if (fn_region_file) {
        if (fn_bed) { /* --regions-file equivalent to -M -L: later one ignored */ }
        else {
            s.bed = NULL;
            bed_t *rb = bed_read(fn_region_file);
            if (!rb) { print_error_errno("view", "Could not read file \"%s\"", fn_region_file); ret = 1; goto view_end; }
            s.bed = rb;
        }
    }

    samfile_t *in = sam_open_read_nohdr(fn_in);
    if (!in) {
        log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn_in, strerror(errno));
        print_error_errno("view", "failed to open \"%s\" for reading", fn_in);
        ret = 1; goto view_end;
    }
    if (in->fmt == FMT_CRAM) { print_error("view", "CRAM format is not supported by this build"); ret = 1; sam_close(in); goto view_end; }
    if (fn_list) sam_set_fai_filename(in, fn_list);
    if (sam_read_header(in) < 0) {
        fprintf(stderr, "[main_samview] fail to read the header from \"%s\".\n", fn_in);
        ret = 1; sam_close(in); goto view_end;
    }
    sam_hdr_t *header = in->hdr;
    if (fn_list && header->n_targets == 0) sam_hdr_add_fai_refs(header, fn_list);

    char *arg_list = NULL;
    if (!no_pg) {
        arg_list = stringify_argv(argc + 1, argv - 1);
        if (sam_hdr_add_pg(header, "samtools", samtools_version(), arg_list, NULL) != 0) { print_error("view", "failed to add PG line to the header"); ret = 1; sam_close(in); free(arg_list); goto view_end; }
    }

    samfile_t *out = NULL, *un_out = NULL;
    if (!is_count) {
        const char *fo = fn_out ? fn_out : "-";
        if (ga.out_fmt == FMT_CRAM) { print_error("view", "CRAM output is not supported by this build"); ret = 1; sam_close(in); free(arg_list); goto view_end; }
        out = sam_open_output(fo, "w", &ga, 0);
        if (!out) { print_error_errno("view", "failed to open \"%s\" for writing", fo); ret = 1; sam_close(in); free(arg_list); goto view_end; }
        if (fn_un_out) {
            un_out = sam_open_output(fn_un_out, "w", &ga, 0);
            if (!un_out) { print_error_errno("view", "failed to open \"%s\" for writing", fn_un_out); ret = 1; sam_close(in); sam_close(out); free(arg_list); goto view_end; }
        }
        if (out->fmt != FMT_SAM || is_header) {
            if (sam_write_hdr(out, header) != 0) { print_error_errno("view", "failed to write the SAM header"); ret = 1; goto done_files; }
        }
        if (un_out && (un_out->fmt != FMT_SAM || is_header)) {
            if (sam_write_hdr(un_out, header) != 0) { print_error_errno("view", "failed to write the SAM header"); ret = 1; goto done_files; }
        }
        if (is_header_only) goto done_files;
    }

    {
        bam1_t *b = bam_init1();
        int r;
        if (region_start >= argc && !(fn_region_file && multi_region)) {
            while ((r = sam_read1(in, header, b)) >= 0) {
                count_processed++;
                if (s.sanitize) bam_sanitize(header, b, s.sanitize);
                int pr = process_aln(header, b, &s);
                if (pr < 0) { ret = 1; break; }
                if (pr == 0) {
                    if (!is_count) {
                        change_flag(b, &s);
                        if (s.remove_aux) remove_aux_tags(b, &s);
                        if (sam_write1(out, header, b) < 0) { print_error_errno("view", "writing to \"%s\" failed", fn_out ? fn_out : "standard output"); ret = 1; break; }
                    }
                    count++;
                } else {
                    count_filtered++;
                    if (!is_count) {
                        if (s.unmap) {
                            b->core.flag |= BAM_FUNMAP;
                            change_flag(b, &s);
                            if (s.remove_aux) remove_aux_tags(b, &s);
                            if (sam_write1(out, header, b) < 0) { print_error_errno("view", "writing to \"%s\" failed", fn_out ? fn_out : "standard output"); ret = 1; break; }
                        } else if (un_out) {
                            if (sam_write1(un_out, header, b) < 0) { print_error_errno("view", "writing to \"%s\" failed", fn_un_out); ret = 1; break; }
                        }
                    }
                }
            }
            if (r < -1) { print_error("view", "error reading file \"%s\"", fn_in); ret = 1; }
        } else {
            /* region-based */
            if (in->fmt != FMT_BAM || !bgzf_is_bgzf(in->bg)) {
                if (!fn_idx_in) log_error("idx_find_and_load", "Could not retrieve index file for '%s'", fn_in);
                print_error("view", "Random alignment retrieval only works for indexed SAM.gz, BAM or CRAM files.");
                ret = 1; bam_destroy1(b); goto done_files;
            }
            hts_idx_t *idx = sam_index_load2(fn_in, fn_idx_in);
            if (!idx) {
                if (!fn_idx_in) log_error("idx_find_and_load", "Could not retrieve index file for '%s'", fn_in);
                print_error("view", "Random alignment retrieval only works for indexed SAM.gz, BAM or CRAM files.");
                ret = 1; bam_destroy1(b); goto done_files;
            }
            if (multi_region) {
                hts_reglist_t rl = { 0, 0, NULL };
                int nocoor = 0;
                if (fn_region_file && s.bed) {
                    for (int i = 0; i < bed_nchr(s.bed); i++) {
                        int tid = sam_hdr_name2tid(header, bed_chr_name(s.bed, i));
                        if (tid < 0) continue;
                        for (int j = 0; j < bed_chr_nintv(s.bed, i); j++) { int64_t bb, ee; bed_chr_intv(s.bed, i, j, &bb, &ee); reglist_add(&rl, tid, bb, ee); }
                    }
                    if (fn_region_file) { bed_destroy(s.bed); s.bed = NULL; }
                }
                for (int i = region_start; i < argc; i++) {
                    int tid; int64_t bb, ee;
                    if (hts_parse_region(argv[i], header, &tid, &bb, &ee) < 0) {
                        fprintf(stderr, "[main_samview] region \"%s\" specifies an invalid region or unknown reference. Continue anyway.\n", argv[i]);
                        continue;
                    }
                    if (tid == HTS_IDX_NOCOOR) { nocoor = 1; continue; }
                    reglist_add(&rl, tid, bb, ee);
                }
                reglist_sort_merge(&rl);
                int i = 0;
                while (i < rl.n && ret == 0) {
                    int tid = rl.a[i].tid; int j = i;
                    while (j < rl.n && rl.a[j].tid == tid) j++;
                    int64_t *bb = malloc((j - i) * sizeof(int64_t)), *ee = malloc((j - i) * sizeof(int64_t));
                    for (int k = i; k < j; k++) { bb[k-i] = rl.a[k].beg; ee[k-i] = rl.a[k].end; }
                    hts_itr_t *itr = sam_itr_query_multi(idx, tid, j - i, bb, ee);
                    free(bb); free(ee);
                    while ((r = sam_itr_next(in, itr, b)) >= 0) {
                        count_processed++;
                        if (s.sanitize) bam_sanitize(header, b, s.sanitize);
                        int pr = process_aln(header, b, &s);
                        if (pr < 0) { ret = 1; break; }
                        if (pr == 0) {
                            if (!is_count) { change_flag(b, &s); if (s.remove_aux) remove_aux_tags(b, &s); if (sam_write1(out, header, b) < 0) { ret = 1; break; } }
                            count++;
                        } else {
                            count_filtered++;
                            if (!is_count) {
                                if (s.unmap) { b->core.flag |= BAM_FUNMAP; change_flag(b, &s); if (s.remove_aux) remove_aux_tags(b, &s); if (sam_write1(out, header, b) < 0) { ret = 1; break; } }
                                else if (un_out) { if (sam_write1(un_out, header, b) < 0) { ret = 1; break; } }
                            }
                        }
                    }
                    if (r < -1) { print_error("view", "retrieval of region failed due to truncated file or corrupt BAM index file"); ret = 1; }
                    hts_itr_destroy(itr);
                    i = j;
                }
                if (nocoor && ret == 0) {
                    hts_itr_t *itr = sam_itr_queryi(idx, HTS_IDX_NOCOOR, 0, 0);
                    while ((r = sam_itr_next(in, itr, b)) >= 0) {
                        count_processed++;
                        int pr = process_aln(header, b, &s);
                        if (pr == 0) { if (!is_count) { change_flag(b, &s); if (s.remove_aux) remove_aux_tags(b, &s); sam_write1(out, header, b); } count++; }
                        else { count_filtered++; if (!is_count && un_out) sam_write1(un_out, header, b); }
                    }
                    hts_itr_destroy(itr);
                }
                free(rl.a);
            } else {
                for (int i = region_start; i < argc; ++i) {
                    hts_itr_t *iter = sam_itr_querys(idx, header, argv[i]);
                    if (iter == NULL) {
                        fprintf(stderr, "[main_samview] region \"%s\" specifies an invalid region or unknown reference. Continue anyway.\n", argv[i]);
                        continue;
                    }
                    while ((r = sam_itr_next(in, iter, b)) >= 0) {
                        count_processed++;
                        if (s.sanitize) bam_sanitize(header, b, s.sanitize);
                        int pr = process_aln(header, b, &s);
                        if (pr < 0) { ret = 1; break; }
                        if (pr == 0) {
                            if (!is_count) { change_flag(b, &s); if (s.remove_aux) remove_aux_tags(b, &s); if (sam_write1(out, header, b) < 0) { print_error_errno("view", "writing to \"%s\" failed", fn_out ? fn_out : "standard output"); ret = 1; break; } }
                            count++;
                        } else {
                            count_filtered++;
                            if (!is_count) {
                                if (s.unmap) { b->core.flag |= BAM_FUNMAP; change_flag(b, &s); if (s.remove_aux) remove_aux_tags(b, &s); if (sam_write1(out, header, b) < 0) { ret = 1; break; } }
                                else if (un_out) { if (sam_write1(un_out, header, b) < 0) { ret = 1; break; } }
                            }
                        }
                    }
                    hts_itr_destroy(iter);
                    if (r < -1) { print_error("view", "retrieval of region \"%s\" failed due to truncated file or corrupt BAM index file", argv[i]); ret = 1; break; }
                }
            }
            hts_idx_destroy(idx);
            (void)fetch_pairs;
        }
        bam_destroy1(b);
    }

done_files:
    if (out) {
        if (sam_close(out) < 0) { print_error_errno("view", "error closing \"%s\"", fn_out ? fn_out : "standard output"); ret = 1; }
    }
    if (un_out) { if (sam_close(un_out) < 0) { print_error_errno("view", "error closing \"%s\"", fn_un_out); ret = 1; } }
    sam_close(in);
    free(arg_list);
    if (is_count && ret == 0) {
        if (fn_out) { FILE *fp = fopen(fn_out, "w"); if (fp) { fprintf(fp, "%lld\n", (long long)count); fclose(fp); } else { print_error_errno("view", "failed to open \"%s\" for writing", fn_out); ret = 1; } }
        else printf("%lld\n", (long long)count);
    }
    if (fn_counts && ret == 0) write_counts(fn_counts, count_processed, count, count_filtered);
view_end:
    free(fn_out); free(fn_list); free(fn_un_out); free(fn_counts); free(fn_region_file); free(fn_bed); free(fn_rn); free(tag_file);
    free(s.library); if (s.bed) bed_destroy(s.bed);
    strmap_free(s.rghash); strmap_free(s.rnhash); strmap_free(s.tvhash); strmap_free(s.remove_aux);
    if (s.filter) hts_filter_free(s.filter);
    sam_global_args_free(&ga);
    return ret;
}

static int usage(FILE *fp, int exit_status, int is_long_help) {
    fprintf(fp,
"\n"
"Usage: samtools view [options] <in.bam>|<in.sam>|<in.cram> [region ...]\n"
"\n"
"Output options:\n"
"  -b, --bam                  Output BAM\n"
"  -C, --cram                 Output CRAM (requires -T)\n"
"  -1, --fast                 Use fast BAM compression (and default to --bam)\n"
"  -u, --uncompressed         Uncompressed BAM output (and default to --bam)\n"
"  -h, --with-header          Include header in SAM output\n"
"  -H, --header-only          Print SAM header only (no alignments)\n"
"      --no-header            Print SAM alignment records only [default]\n"
"  -c, --count                Print only the count of matching records\n"
"      --save-counts FILE     Write counts of passed/failed records to FILE\n"
"  -o, --output FILE          Write output to FILE [standard output]\n"
"  -U, --unoutput FILE, --output-unselected FILE\n"
"                             Output reads not selected by filters to FILE\n"
"  -p, --unmap                Set flag to UNMAP on reads not selected\n"
"                             then write to output file.\n"
"  -P, --fetch-pairs          Retrieve complete pairs even when outside of region\n"
"\n"
"Input options:\n"
"  -t, --fai-reference FILE   FILE listing reference names and lengths\n"
"  -M, --use-index            Use index and multi-region iterator for regions\n"
"      --region[s]-file FILE  Use index to include only reads overlapping FILE\n"
"  -X, --customized-index     Expect extra index file argument after <in.bam>\n"
"\n"
"Filtering options (Only include in output reads that...):\n"
"  -L, --target[s]-file FILE  ...overlap (BED) regions in FILE\n"
"  -N, --qname-file [^]FILE   ...whose read name is listed in FILE (\"^\" negates)\n"
"  -r, --read-group STR       ...are in read group STR or in no read group\n"
"  -R, --read-group-file [^]FILE\n"
"                             ...are in a read group listed in FILE or in none\n"
"  -n, --exclude-no-read_group\n"
"                             ...have a read group, exclude those that have not\n"
"  -d, --tag STR1[:STR2]      ...have a tag STR1 (with associated value STR2)\n"
"  -D, --tag-file STR:FILE    ...have a tag STR whose value is listed in FILE\n"
"  -q, --min-MQ INT           ...have mapping quality >= INT\n"
"  -l, --library STR          ...are in library STR\n"
"  -m, --min-qlen INT         ...cover >= INT query bases (as measured via CIGAR)\n"
"  -e, --expr STR             ...match the filter expression STR\n"
"  -f, --require-flags FLAG   ...have all of the FLAGs present\n"
"  -F, --excl[ude]-flags FLAG ...have none of the FLAGs present\n"
"      --rf, --incl-flags, --include-flags FLAG\n"
"                             ...have some of the FLAGs present\n"
"  -G FLAG                    EXCLUDE reads with all of the FLAGs present\n"
"      --subsample FLOAT      Keep only FLOAT fraction of templates/read pairs\n"
"      --subsample-seed INT   Influence WHICH reads are kept in subsampling [0]\n"
"  -s INT.FRAC                Same as --subsample 0.FRAC --subsample-seed INT\n"
"\n"
"Processing options:\n"
"      --add-flags FLAG       Add FLAGs to reads\n"
"      --remove-flags FLAG    Remove FLAGs from reads\n"
"  -x, --remove-tag STR\n"
"               Comma-separated read tags to strip (repeatable) [null]\n"
"      --keep-tag STR\n"
"               Comma-separated read tags to preserve (repeatable) [null].\n"
"               Equivalent to \"-x ^STR\"\n"
"  -B, --remove-B             Collapse the backward CIGAR operation\n"
"  -z, --sanitize FLAGS       Perform sanitity checking and fixing on records.\n"
"                             FLAGS is comma separated (see manual). [off]\n"
"\n"
"General options:\n"
"  -?, --help   Print long help, including note about region specification\n"
"  -S           Ignored (input format is auto-detected)\n"
"      --no-PG  Do not add a PG line\n");
    sam_global_opt_help(fp, "-.O.T@..");
    fprintf(fp, "\n");
    if (is_long_help)
        fprintf(fp,
"Notes:\n"
"\n"
"1. This command now auto-detects the input format (BAM/CRAM/SAM).\n"
"   Further control over the CRAM format can be specified by using the\n"
"   --output-fmt-option, e.g. to specify the number of sequences per slice\n"
"   and to use avoid reference based compression:\n"
"\n"
"\tsamtools view -C --output-fmt-option seqs_per_slice=5000 \\\n"
"\t   --output-fmt-option no_ref -o out.cram in.bam\n"
"\n"
"   Options can also be specified as a comma separated list within the\n"
"   --output-fmt value too.  For example this is equivalent to the above\n"
"\n"
"\tsamtools view --output-fmt cram,seqs_per_slice=5000,no_ref \\\n"
"\t   -o out.cram in.bam\n"
"\n"
"2. The file supplied with `-t' is SPACE/TAB delimited with the first\n"
"   two fields of each line consisting of the reference name and the\n"
"   corresponding sequence length. The `.fai' file generated by \n"
"   `samtools faidx' is suitable for use as this file. This may be an\n"
"   empty file if reads are unaligned.\n"
"\n"
"3. SAM->BAM conversion:  samtools view -bT ref.fa in.sam.gz\n"
"\n"
"4. BAM->SAM conversion:  samtools view -h in.bam\n"
"\n"
"5. A region should be presented in one of the following formats:\n"
"   `chr1', `chr2:1,000' and `chr3:1000-2,000'. When a region is\n"
"   specified, the input alignment file must be a sorted and indexed\n"
"   alignment (BAM/CRAM) file.\n"
"\n"
"6. Option `-u' is preferred over `-b' when the output is piped to\n"
"   another samtools command.\n"
"\n"
"7. Option `-M`/`--use-index` causes overlaps with `-L` BED file regions and\n"
"   command-line region arguments to be computed using the multi-region iterator\n"
"   and an index. This increases speed, omits duplicates, and outputs the reads\n"
"   as they are ordered in the input SAM/BAM/CRAM file.\n"
"\n"
"8. Options `-L`/`--target[s]-file` and `--region[s]-file` may not be used\n"
"   together. `--region[s]-file FILE` is simply equivalent to `-M -L FILE`,\n"
"   so using both causes one of the specified BED files to be ignored.\n"
"\n");
    return exit_status;
}
EOF
echo ok"}

actions.command:
cd /workspace && cat > src/view.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <errno.h>
#include <ctype.h>
#include <math.h>
#include "samtools.h"
#include "index.h"
#include "bedidx.h"
#include "strmap.h"
#include "log.h"
#include "filter.h"
#include "sanitize.h"

typedef struct {
    int min_mapQ, flag_on, flag_off, flag_alloff, flag_anyon, min_qlen;
    int remove_B, unmap;
    uint32_t subsam_seed; double subsam_frac;
    char *library;
    bed_t *bed;
    strmap_t *rghash; int exclude_no_rg;
    strmap_t *rnhash; int rn_negate;
    char tag[3]; strmap_t *tvhash; char *tagval;
    strmap_t *remove_aux; int keep_aux_mode; int n_remove_aux;
    uint16_t add_flags, remove_flags;
    hts_filter_t *filter;
    int sanitize;
} view_settings_t;

static int usage(FILE *fp, int exit_status, int is_long_help);

static inline uint32_t X31_hash_string(const char *s) {
    uint32_t h = (uint32_t)*s;
    if (h) for (++s; *s; ++s) h = (h << 5) - h + (uint32_t)*s;
    return h;
}
static inline uint32_t Wang_hash(uint32_t key) {
    key += ~(key << 15); key ^= (key >> 10); key += (key << 3); key ^= (key >> 6); key += ~(key << 11); key ^= (key >> 16);
    return key;
}

static const char *bam_get_library(sam_hdr_t *h, const bam1_t *b, char *buf, size_t bufsz) {
    uint8_t *rg = bam_aux_get(b, "RG");
    if (!rg) return NULL;
    char *lb = sam_hdr_find_tag_id(h, "RG", "ID", (char*)rg + 1, "LB");
    if (!lb) return NULL;
    snprintf(buf, bufsz, "%s", lb); free(lb);
    return buf;
}

static void bam_remove_B(bam1_t *b) {
    /* collapse the backward CIGAR operation */
    int k, has_B = 0;
    uint32_t *cigar = bam_get_cigar(b);
    for (k = 0; k < (int)b->core.n_cigar; k++) if (bam_cigar_op(cigar[k]) == BAM_CBACK) { has_B = 1; break; }
    if (!has_B) return;
    /* simplified: remove B ops by merging */
    /* full implementation follows htslib's bam_remove_B algorithm */
    int i, j, l, end_j, no_qual = (bam_get_qual(b)[0] == 0xff);
    uint32_t *new_cigar = malloc(b->core.n_cigar * 4 + 8); int nc = 0;
    uint8_t *seq = bam_get_seq(b), *qual = bam_get_qual(b);
    uint8_t *new_seq = calloc((b->core.l_qseq + 1) / 2 + 1, 1), *new_qual = malloc(b->core.l_qseq + 1);
    for (k = 0, i = 0, j = 0, end_j = -1; k < (int)b->core.n_cigar; k++) {
        int op = bam_cigar_op(cigar[k]); l = bam_cigar_oplen(cigar[k]);
        if (op == BAM_CBACK) {
            if (i - l < 0) { free(new_cigar); free(new_seq); free(new_qual); return; }
            if (k == (int)b->core.n_cigar - 1) break;
            /* rewind */
            int t, u;
            for (t = 0, u = l; t < nc && u > 0; ) {
                int op2 = bam_cigar_op(new_cigar[nc-1]), l2 = bam_cigar_oplen(new_cigar[nc-1]);
                if (!(bam_cigar_type(op2) & 1)) { nc--; continue; }
                if (l2 <= u) { u -= l2; nc--; } else { new_cigar[nc-1] = bam_cigar_gen(l2 - u, op2); u = 0; }
            }
            i -= l; j = i;
            end_j = i + l;
        } else {
            if (bam_cigar_type(op) & 1) {
                for (int x = 0; x < l; x++) {
                    bam_set_seqi(new_seq, j, bam_seqi(seq, i));
                    if (!no_qual) new_qual[j] = qual[i];
                    i++; j++;
                }
            }
            if (nc && bam_cigar_op(new_cigar[nc-1]) == op) new_cigar[nc-1] = bam_cigar_gen(bam_cigar_oplen(new_cigar[nc-1]) + l, op);
            else new_cigar[nc++] = cigar[k];
        }
    }
    (void)end_j;
    int new_lq = j;
    /* rebuild record */
    int l_aux = bam_get_l_aux(b);
    uint8_t *aux = malloc(l_aux + 1); memcpy(aux, bam_get_aux(b), l_aux);
    int ql = b->core.l_qname;
    int need = ql + nc * 4 + (new_lq + 1) / 2 + new_lq + l_aux;
    bam_set_data_cap(b, need);
    uint8_t *p = b->data + ql;
    memcpy(p, new_cigar, nc * 4); p += nc * 4;
    memcpy(p, new_seq, (new_lq + 1) / 2); p += (new_lq + 1) / 2;
    if (no_qual) memset(p, 0xff, new_lq); else memcpy(p, new_qual, new_lq);
    p += new_lq;
    memcpy(p, aux, l_aux); p += l_aux;
    b->l_data = (int)(p - b->data);
    b->core.n_cigar = nc; b->core.l_qseq = new_lq;
    free(aux); free(new_cigar); free(new_seq); free(new_qual);
}

static void remove_aux_tags(bam1_t *b, view_settings_t *s) {
    uint8_t *p = bam_get_aux(b), *end = b->data + b->l_data;
    while (p + 3 <= end) {
        char tag[3] = { (char)p[0], (char)p[1], 0 };
        uint8_t *next = bam_aux_skip(p + 2, end);
        if (!next) break;
        int in = strmap_find(s->remove_aux, tag) != NULL;
        int remove = s->keep_aux_mode ? !in : in;
        if (remove) {
            memmove(p, next, end - next);
            b->l_data -= (int)(next - p);
            end = b->data + b->l_data;
        } else p = next;
    }
}

static int process_aln(sam_hdr_t *h, bam1_t *b, view_settings_t *s) {
    if (s->remove_B) bam_remove_B(b);
    if (s->min_qlen > 0) {
        int qlen = 0; uint32_t *cigar = bam_get_cigar(b);
        for (uint32_t k = 0; k < b->core.n_cigar; k++)
            if ((bam_cigar_type(bam_cigar_op(cigar[k])) & 1) || bam_cigar_op(cigar[k]) == BAM_CHARD_CLIP) qlen += bam_cigar_oplen(cigar[k]);
        if (qlen < s->min_qlen) return 1;
    }
    if (b->core.qual < s->min_mapQ || ((b->core.flag & s->flag_on) != s->flag_on) || (b->core.flag & s->flag_off)) return 1;
    if (s->flag_alloff && ((b->core.flag & s->flag_alloff) == s->flag_alloff)) return 1;
    if (s->flag_anyon && ((b->core.flag & s->flag_anyon) == 0)) return 1;
    if (s->bed && (b->core.tid < 0 || !bed_overlap(s->bed, sam_hdr_tid2name(h, b->core.tid), b->core.pos, bam_endpos(b)))) return 1;
    if (s->subsam_frac > 0.) {
        uint32_t k = Wang_hash(X31_hash_string(bam_get_qname(b)) ^ s->subsam_seed);
        if ((double)(k & 0xffffff) / 0x1000000 >= s->subsam_frac) return 1;
    }
    if (s->rghash) {
        uint8_t *rg = bam_aux_get(b, "RG");
        if (rg) { if (!strmap_find(s->rghash, (char*)rg + 1)) return 1; }
        else if (s->exclude_no_rg) return 1;
    } else if (s->exclude_no_rg) {
        if (!bam_aux_get(b, "RG")) return 1;
    }
    if (s->tag[0]) {
        uint8_t *t = bam_aux_get(b, s->tag);
        if (t) {
            if (s->tvhash) {
                char buf[32]; const char *val;
                if (bam_aux_is_int(t)) { snprintf(buf, sizeof buf, "%lld", (long long)bam_aux2i(t)); val = buf; }
                else if (*t == 'A') { buf[0] = (char)t[1]; buf[1] = 0; val = buf; }
                else if (*t == 'f' || *t == 'd') { snprintf(buf, sizeof buf, "%g", bam_aux2f(t)); val = buf; }
                else val = (char*)t + 1;
                if (!strmap_find(s->tvhash, val)) return 1;
            }
        } else return 1;
    }
    if (s->rnhash) {
        int in = strmap_find(s->rnhash, bam_get_qname(b)) != NULL;
        if (s->rn_negate ? in : !in) return 1;
    }
    if (s->library) {
        char buf[1024];
        const char *lib = bam_get_library(h, b, buf, sizeof buf);
        if (!lib || strcmp(lib, s->library) != 0) return 1;
    }
    if (s->filter) {
        int r = hts_filter_eval_bam(s->filter, h, b);
        if (r < 0) return -1;
        if (r == 0) return 1;
    }
    return 0;
}

static void change_flag(bam1_t *b, view_settings_t *s) {
    if (s->add_flags) b->core.flag |= s->add_flags;
    if (s->remove_flags) b->core.flag &= ~s->remove_flags;
}

static int add_read_group_single(const char *subcmd, view_settings_t *s, const char *name) {
    if (!s->rghash) s->rghash = strmap_new();
    strmap_set(s->rghash, name, 1);
    (void)subcmd;
    return 0;
}

static int add_read_groups_file(const char *subcmd, view_settings_t *s, const char *fn) {
    int negate = 0;
    if (fn[0] == '^') { negate = 1; fn++; }
    textfile_t *t = text_open(fn);
    if (!t) { print_error_errno(subcmd, "failed to open \"%s\" for reading", fn); return -1; }
    strmap_t *m = strmap_new();
    while (text_getline(t) >= 0) {
        char *line = t->line; char *e = line; while (*e && *e != '\t' && *e != ' ' && *e != '\r') e++; *e = 0;
        if (*line) strmap_set(m, line, 1);
    }
    text_close(t);
    (void)negate;
    if (!s->rghash) s->rghash = strmap_new();
    for (size_t i = 0; i < m->cap; i++) if (m->e[i].used) strmap_set(s->rghash, m->e[i].key, 1);
    strmap_free(m);
    return 0;
}

static strmap_t *load_names_file(const char *subcmd, const char *fn, int *negate) {
    *negate = 0;
    if (fn[0] == '^') { *negate = 1; fn++; }
    textfile_t *t = text_open(fn);
    if (!t) { print_error_errno(subcmd, "failed to open \"%s\" for reading", fn); return NULL; }
    strmap_t *m = strmap_new();
    while (text_getline(t) >= 0) {
        char *line = t->line; char *e = line; while (*e && *e != '\t' && *e != '\r') e++; *e = 0;
        if (*line) strmap_set(m, line, 1);
    }
    text_close(t);
    return m;
}

static int parse_aux_list(view_settings_t *s, const char *optarg, int keep) {
    const char *p = optarg;
    if (*p == '^') { keep = !keep; p++; }
    if (!s->remove_aux) s->remove_aux = strmap_new();
    if (keep) s->keep_aux_mode = 1;
    while (*p) {
        if (strlen(p) < 2 || (p[2] != ',' && p[2] != 0)) { print_error("view", "Expected a two character tag name in -x option '%s'", optarg); return -1; }
        char tag[3] = { p[0], p[1], 0 };
        strmap_set(s->remove_aux, tag, 1);
        s->n_remove_aux++;
        p += 2;
        if (*p == ',') p++;
    }
    return 0;
}

static int write_counts(const char *fn, int64_t processed, int64_t accepted, int64_t rejected) {
    FILE *fp = fopen(fn, "w");
    if (!fp) { print_error_errno("view", "failed to open \"%s\" for writing", fn); return -1; }
    fprintf(fp, "{\n    \"records_processed\" : %lld,\n    \"records_filter_accepted\" : %lld,\n    \"records_filter_rejected\" : %lld\n}\n", (long long)processed, (long long)accepted, (long long)rejected);
    fclose(fp);
    return 0;
}

int main_samview(int argc, char **argv) {
    view_settings_t s; memset(&s, 0, sizeof s);
    sam_global_args ga = SAM_GLOBAL_ARGS_INIT;
    int c, is_header = 0, is_header_only = 0, ret = 0, compress_level = -1, is_count = 0;
    int is_long_help = 0, has_index_file = 0, multi_region = 0, fetch_pairs = 0;
    int out_fmt_set = 0, out_bam = 0, out_cram = 0;
    char *fn_in = NULL, *fn_out = NULL, *fn_list = NULL, *fn_un_out = NULL, *fn_counts = NULL, *fn_region_file = NULL, *fn_bed = NULL;
    char *fn_idx_in = NULL;
    int64_t count = 0, count_filtered = 0, count_processed = 0;
    int no_pg = 0;
    const char *out_mode_fmt = NULL;

    enum { OPT_RF = 1000, OPT_NO_HEADER = 1010, OPT_SAVE_COUNTS, OPT_SUBSAMPLE, OPT_SUBSAMPLE_SEED, OPT_ADD_FLAGS, OPT_REMOVE_FLAGS, OPT_KEEP_TAG, OPT_NO_PG, OPT_REGION_FILE,
           OPT_INPUT_FMT = 1001, OPT_INPUT_FMT_OPTION = 1002, OPT_OUTPUT_FMT = 1003, OPT_OUTPUT_FMT_OPTION = 1004, OPT_REFERENCE = 1005, OPT_THREADS = 1006, OPT_WRITE_INDEX = 1007, OPT_VERBOSITY = 1008 };
    static const struct option lopts[] = {
        { "bam", no_argument, NULL, 'b' }, { "cram", no_argument, NULL, 'C' }, { "fast", no_argument, NULL, '1' },
        { "uncompressed", no_argument, NULL, 'u' }, { "with-header", no_argument, NULL, 'h' }, { "header-only", no_argument, NULL, 'H' },
        { "no-header", no_argument, NULL, OPT_NO_HEADER }, { "count", no_argument, NULL, 'c' }, { "save-counts", required_argument, NULL, OPT_SAVE_COUNTS },
        { "output", required_argument, NULL, 'o' }, { "unoutput", required_argument, NULL, 'U' }, { "output-unselected", required_argument, NULL, 'U' },
        { "unmap", no_argument, NULL, 'p' }, { "fetch-pairs", no_argument, NULL, 'P' },
        { "fai-reference", required_argument, NULL, 't' }, { "use-index", no_argument, NULL, 'M' },
        { "region-file", required_argument, NULL, OPT_REGION_FILE }, { "regions-file", required_argument, NULL, OPT_REGION_FILE },
        { "customized-index", no_argument, NULL, 'X' },
        { "target-file", required_argument, NULL, 'L' }, { "targets-file", required_argument, NULL, 'L' },
        { "qname-file", required_argument, NULL, 'N' }, { "read-group", required_argument, NULL, 'r' }, { "read-group-file", required_argument, NULL, 'R' },
        { "exclude-no-read_group", no_argument, NULL, 'n' }, { "exclude-no-read-group", no_argument, NULL, 'n' },
        { "tag", required_argument, NULL, 'd' }, { "tag-file", required_argument, NULL, 'D' },
        { "min-MQ", required_argument, NULL, 'q' }, { "min-mq", required_argument, NULL, 'q' }, { "library", required_argument, NULL, 'l' }, { "min-qlen", required_argument, NULL, 'm' },
        { "expr", required_argument, NULL, 'e' }, { "require-flags", required_argument, NULL, 'f' }, { "excl-flags", required_argument, NULL, 'F' }, { "exclude-flags", required_argument, NULL, 'F' },
        { "rf", required_argument, NULL, OPT_RF }, { "incl-flags", required_argument, NULL, OPT_RF }, { "include-flags", required_argument, NULL, OPT_RF },
        { "subsample", required_argument, NULL, OPT_SUBSAMPLE }, { "subsample-seed", required_argument, NULL, OPT_SUBSAMPLE_SEED },
        { "add-flags", required_argument, NULL, OPT_ADD_FLAGS }, { "remove-flags", required_argument, NULL, OPT_REMOVE_FLAGS },
        { "remove-tag", required_argument, NULL, 'x' }, { "keep-tag", required_argument, NULL, OPT_KEEP_TAG }, { "remove-B", no_argument, NULL, 'B' },
        { "sanitize", required_argument, NULL, 'z' }, { "help", no_argument, NULL, '?' }, { "no-PG", no_argument, NULL, OPT_NO_PG },
        { "input-fmt", required_argument, NULL, OPT_INPUT_FMT }, { "input-fmt-option", required_argument, NULL, OPT_INPUT_FMT_OPTION },
        { "output-fmt", required_argument, NULL, OPT_OUTPUT_FMT }, { "output-fmt-option", required_argument, NULL, OPT_OUTPUT_FMT_OPTION },
        { "reference", required_argument, NULL, OPT_REFERENCE }, { "threads", required_argument, NULL, OPT_THREADS },
        { "write-index", no_argument, NULL, OPT_WRITE_INDEX }, { "verbosity", required_argument, NULL, OPT_VERBOSITY },
        { NULL, 0, NULL, 0 }
    };

    char *tag_file = NULL;
    double subsam_frac_opt = -1; long subsam_seed_opt = 0; int seed_set = 0;
    char *fn_rn = NULL;
    opterr = 0;
    while ((c = getopt_long(argc, argv, "SbBcCt:h1Ho:O:q:f:F:G:ul:r:?T:R:d:D:L:s:@:m:x:U:MXe:pPnz:N:", lopts, NULL)) >= 0) {
        switch (c) {
        case 's': {
            char *q;
            s.subsam_seed = (uint32_t)strtol(optarg, &q, 10);
            if (s.subsam_seed != 0) { srand(s.subsam_seed); s.subsam_seed = (uint32_t)rand(); }
            if (q && *q == '.') s.subsam_frac = strtod(q, &q);
            else if (q && *q) { print_error("view", "Incorrect sampling argument \"%s\"", optarg); ret = 1; goto view_end; }
            break;
        }
        case OPT_SUBSAMPLE: subsam_frac_opt = strtod(optarg, NULL); break;
        case OPT_SUBSAMPLE_SEED: subsam_seed_opt = strtol(optarg, NULL, 10); seed_set = 1; break;
        case 'm': s.min_qlen = atoi(optarg); break;
        case 'c': is_count = 1; break;
        case 'S': break;
        case 'b': out_bam = 1; out_fmt_set = 1; break;
        case 'C': out_cram = 1; out_fmt_set = 1; break;
        case 't': fn_list = strdup(optarg); break;
        case 'h': is_header = 1; break;
        case 'H': is_header_only = 1; break;
        case OPT_NO_HEADER: is_header = is_header_only = 0; break;
        case 'o': fn_out = strdup(optarg); break;
        case 'U': fn_un_out = strdup(optarg); break;
        case 'X': has_index_file = 1; break;
        case 'f': { int f = bam_str2flag(optarg); if (f < 0) { print_error("view", "Unknown flag '%s'", optarg); ret = 1; goto view_end; } s.flag_on |= f; break; }
        case 'F': { int f = bam_str2flag(optarg); if (f < 0) { print_error("view", "Unknown flag '%s'", optarg); ret = 1; goto view_end; } s.flag_off |= f; break; }
        case 'G': { int f = bam_str2flag(optarg); if (f < 0) { print_error("view", "Unknown flag '%s'", optarg); ret = 1; goto view_end; } s.flag_alloff |= f; break; }
        case OPT_RF: { int f = bam_str2flag(optarg); if (f < 0) { print_error("view", "Unknown flag '%s'", optarg); ret = 1; goto view_end; } s.flag_anyon |= f; break; }
        case 'q': s.min_mapQ = atoi(optarg); break;
        case 'u': compress_level = 0; out_bam = out_cram ? out_bam : 1; if (!out_fmt_set) { out_bam = 1; } break;
        case '1': compress_level = 1; if (!out_fmt_set) out_bam = 1; break;
        case 'l': s.library = strdup(optarg); break;
        case 'p': s.unmap = 1; break;
        case 'P': fetch_pairs = 1; break;
        case 'L': fn_bed = strdup(optarg); break;
        case 'N': fn_rn = strdup(optarg); break;
        case 'r': if (add_read_group_single("view", &s, optarg) != 0) { ret = 1; goto view_end; } break;
        case 'R': if (add_read_groups_file("view", &s, optarg) != 0) { ret = 1; goto view_end; } break;
        case 'n': s.exclude_no_rg = 1; break;
        case 'd': {
            if (strlen(optarg) < 2 || (strlen(optarg) > 2 && optarg[2] != ':')) { print_error("view", "Invalid \"tag:value\" option: \"%s\"", optarg); ret = 1; goto view_end; }
            if (s.tag[0] && (s.tag[0] != optarg[0] || s.tag[1] != optarg[1])) { print_error("view", "Different tag \"%s\" was specified", optarg); ret = 1; goto view_end; }
            s.tag[0] = optarg[0]; s.tag[1] = optarg[1]; s.tag[2] = 0;
            if (strlen(optarg) > 3) { if (!s.tvhash) s.tvhash = strmap_new(); strmap_set(s.tvhash, optarg + 3, 1); }
            break;
        }
        case 'D': {
            if (strlen(optarg) < 4 || optarg[2] != ':') { print_error("view", "Invalid \"tag:file\" option: \"%s\"", optarg); ret = 1; goto view_end; }
            if (s.tag[0] && (s.tag[0] != optarg[0] || s.tag[1] != optarg[1])) { print_error("view", "Different tag \"%s\" was specified", optarg); ret = 1; goto view_end; }
            s.tag[0] = optarg[0]; s.tag[1] = optarg[1]; s.tag[2] = 0;
            tag_file = strdup(optarg + 3);
            break;
        }
        case 'x': if (parse_aux_list(&s, optarg, 0) < 0) { ret = 1; goto view_end; } break;
        case OPT_KEEP_TAG: if (parse_aux_list(&s, optarg, 1) < 0) { ret = 1; goto view_end; } break;
        case 'B': s.remove_B = 1; break;
        case 'z': s.sanitize = bam_sanitize_options(optarg); if (s.sanitize < 0) { ret = 1; goto view_end; } break;
        case 'M': multi_region = 1; break;
        case OPT_REGION_FILE: fn_region_file = strdup(optarg); multi_region = 1; break;
        case OPT_SAVE_COUNTS: fn_counts = strdup(optarg); break;
        case OPT_ADD_FLAGS: { int f = bam_str2flag(optarg); if (f < 0) { print_error("view", "Unknown flag '%s'", optarg); ret = 1; goto view_end; } s.add_flags |= f; break; }
        case OPT_REMOVE_FLAGS: { int f = bam_str2flag(optarg); if (f < 0) { print_error("view", "Unknown flag '%s'", optarg); ret = 1; goto view_end; } s.remove_flags |= f; break; }
        case 'e': s.filter = hts_filter_init(optarg); if (!s.filter) { print_error("view", "Couldn't initialise filter"); ret = 1; goto view_end; } break;
        case OPT_NO_PG: no_pg = 1; break;
        case 'T': free(ga.reference); ga.reference = strdup(optarg); break;
        case '@': ga.nthreads = atoi(optarg); break;
        case 'O': {
            int fmt = 0, comp = 0, level = ga.out_level;
            if (parse_format_string(optarg, &fmt, &comp, &level, 1) < 0 || fmt == 0) { return usage(stderr, 1, 0); }
            ga.out_fmt = fmt; ga.out_comp = comp; ga.out_level = level; out_fmt_set = 1;
            break;
        }
        case OPT_OUTPUT_FMT: {
            int fmt = 0, comp = 0, level = ga.out_level;
            if (parse_format_string(optarg, &fmt, &comp, &level, 1) < 0 || fmt == 0) { return usage(stderr, 1, 0); }
            ga.out_fmt = fmt; ga.out_comp = comp; ga.out_level = level; out_fmt_set = 1;
            break;
        }
        case OPT_INPUT_FMT: case OPT_INPUT_FMT_OPTION: break;
        case OPT_OUTPUT_FMT_OPTION: { int level = ga.out_level, fmt = ga.out_fmt; parse_format_option(optarg, &level, &fmt); ga.out_level = level; break; }
        case OPT_REFERENCE: free(ga.reference); ga.reference = strdup(optarg); break;
        case OPT_THREADS: ga.nthreads = atoi(optarg); break;
        case OPT_WRITE_INDEX: ga.write_index = 1; break;
        case OPT_VERBOSITY: hts_verbose = atoi(optarg); break;
        case '?':
            if (optopt == '?' || (optind > 0 && strcmp(argv[optind-1], "-?") == 0) || strcmp(argv[optind-1], "--help") == 0) { is_long_help = 1; return usage(stdout, 0, is_long_help); }
            if (optopt) { fprintf(stderr, "samtools view: invalid option -- '%c'\n", optopt); }
            else fprintf(stderr, "samtools view: unrecognized option '%s'\n", argv[optind-1]);
            return usage(stderr, 1, 0);
        default:
            return usage(stderr, 1, 0);
        }
    }
    if (subsam_frac_opt >= 0) {
        s.subsam_frac = subsam_frac_opt;
        if (seed_set) { s.subsam_seed = (uint32_t)subsam_seed_opt; if (s.subsam_seed != 0) { srand(s.subsam_seed); s.subsam_seed = (uint32_t)rand(); } }
    }
    if (compress_level >= 0 && ga.out_level < 0) ga.out_level = compress_level;
    if (out_cram) ga.out_fmt = FMT_CRAM;
    else if (out_bam && (ga.out_fmt == 0 || ga.out_fmt == FMT_SAM)) { if (ga.out_fmt == 0) ga.out_fmt = FMT_BAM; }
    (void)out_mode_fmt;

    if (fn_un_out && fn_out == NULL && !is_count) { /* fine: un_out separate */ }

    if (is_header_only) is_header = 1;
    if (argc == optind && isatty(STDIN_FILENO)) return usage(stderr, 1, is_long_help);

    fn_in = (optind < argc) ? argv[optind] : "-";
    if (has_index_file) {
        if (optind + 1 < argc) fn_idx_in = argv[optind + 1];
        else { print_error("view", "Incorrect number of arguments for -X option. Aborting."); ret = 1; goto view_end; }
    }
    int region_start = optind + 1 + (has_index_file ? 1 : 0);

    if (fn_rn) {
        s.rnhash = load_names_file("view", fn_rn, &s.rn_negate);
        if (!s.rnhash) { ret = 1; goto view_end; }
    }
    if (tag_file) {
        int neg;
        s.tvhash = load_names_file("view", tag_file, &neg);
        if (!s.tvhash) { ret = 1; goto view_end; }
    }
    if (fn_bed) {
        s.bed = bed_read(fn_bed);
        if (!s.bed) { print_error_errno("view", "Could not read file \"%s\"", fn_bed); ret = 1; goto view_end; }
    }
    if (fn_region_file) {
        if (fn_bed) { /* --regions-file equivalent to -M -L: later one ignored */ }
        else {
            s.bed = NULL;
            bed_t *rb = bed_read(fn_region_file);
            if (!rb) { print_error_errno("view", "Could not read file \"%s\"", fn_region_file); ret = 1; goto view_end; }
            s.bed = rb;
        }
    }

    samfile_t *in = sam_open_read_nohdr(fn_in);
    if (!in) {
        log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn_in, strerror(errno));
        print_error_errno("view", "failed to open \"%s\" for reading", fn_in);
        ret = 1; goto view_end;
    }
    if (in->fmt == FMT_CRAM) { print_error("view", "CRAM format is not supported by this build"); ret = 1; sam_close(in); goto view_end; }
    if (fn_list) sam_set_fai_filename(in, fn_list);
    if (sam_read_header(in) < 0) {
        fprintf(stderr, "[main_samview] fail to read the header from \"%s\".\n", fn_in);
        ret = 1; sam_close(in); goto view_end;
    }
    sam_hdr_t *header = in->hdr;
    if (fn_list && header->n_targets == 0) sam_hdr_add_fai_refs(header, fn_list);

    char *arg_list = NULL;
    if (!no_pg) {
        arg_list = stringify_argv(argc + 1, argv - 1);
        if (sam_hdr_add_pg(header, "samtools", samtools_version(), arg_list, NULL) != 0) { print_error("view", "failed to add PG line to the header"); ret = 1; sam_close(in); free(arg_list); goto view_end; }
    }

    samfile_t *out = NULL, *un_out = NULL;
    if (!is_count) {
        const char *fo = fn_out ? fn_out : "-";
        if (ga.out_fmt == FMT_CRAM) { print_error("view", "CRAM output is not supported by this build"); ret = 1; sam_close(in); free(arg_list); goto view_end; }
        out = sam_open_output(fo, "w", &ga, 0);
        if (!out) { print_error_errno("view", "failed to open \"%s\" for writing", fo); ret = 1; sam_close(in); free(arg_list); goto view_end; }
        if (fn_un_out) {
            un_out = sam_open_output(fn_un_out, "w", &ga, 0);
            if (!un_out) { print_error_errno("view", "failed to open \"%s\" for writing", fn_un_out); ret = 1; sam_close(in); sam_close(out); free(arg_list); goto view_end; }
        }
        if (out->fmt != FMT_SAM || is_header) {
            if (sam_write_hdr(out, header) != 0) { print_error_errno("view", "failed to write the SAM header"); ret = 1; goto done_files; }
        }
        if (un_out && (un_out->fmt != FMT_SAM || is_header)) {
            if (sam_write_hdr(un_out, header) != 0) { print_error_errno("view", "failed to write the SAM header"); ret = 1; goto done_files; }
        }
        if (is_header_only) goto done_files;
    }

    {
        bam1_t *b = bam_init1();
        int r;
        if (region_start >= argc && !(fn_region_file && multi_region)) {
            while ((r = sam_read1(in, header, b)) >= 0) {
                count_processed++;
                if (s.sanitize) bam_sanitize(header, b, s.sanitize);
                int pr = process_aln(header, b, &s);
                if (pr < 0) { ret = 1; break; }
                if (pr == 0) {
                    if (!is_count) {
                        change_flag(b, &s);
                        if (s.remove_aux) remove_aux_tags(b, &s);
                        if (sam_write1(out, header, b) < 0) { print_error_errno("view", "writing to \"%s\" failed", fn_out ? fn_out : "standard output"); ret = 1; break; }
                    }
                    count++;
                } else {
                    count_filtered++;
                    if (!is_count) {
                        if (s.unmap) {
                            b->core.flag |= BAM_FUNMAP;
                            change_flag(b, &s);
                            if (s.remove_aux) remove_aux_tags(b, &s);
                            if (sam_write1(out, header, b) < 0) { print_error_errno("view", "writing to \"%s\" failed", fn_out ? fn_out : "standard output"); ret = 1; break; }
                        } else if (un_out) {
                            if (sam_write1(un_out, header, b) < 0) { print_error_errno("view", "writing to \"%s\" failed", fn_un_out); ret = 1; break; }
                        }
                    }
                }
            }
            if (r < -1) { print_error("view", "error reading file \"%s\"", fn_in); ret = 1; }
        } else {
            /* region-based */
            if (in->fmt != FMT_BAM || !bgzf_is_bgzf(in->bg)) {
                if (!fn_idx_in) log_error("idx_find_and_load", "Could not retrieve index file for '%s'", fn_in);
                print_error("view", "Random alignment retrieval only works for indexed SAM.gz, BAM or CRAM files.");
                ret = 1; bam_destroy1(b); goto done_files;
            }
            hts_idx_t *idx = sam_index_load2(fn_in, fn_idx_in);
            if (!idx) {
                if (!fn_idx_in) log_error("idx_find_and_load", "Could not retrieve index file for '%s'", fn_in);
                print_error("view", "Random alignment retrieval only works for indexed SAM.gz, BAM or CRAM files.");
                ret = 1; bam_destroy1(b); goto done_files;
            }
            if (multi_region) {
                hts_reglist_t rl = { 0, 0, NULL };
                int nocoor = 0;
                if (fn_region_file && s.bed) {
                    for (int i = 0; i < bed_nchr(s.bed); i++) {
                        int tid = sam_hdr_name2tid(header, bed_chr_name(s.bed, i));
                        if (tid < 0) continue;
                        for (int j = 0; j < bed_chr_nintv(s.bed, i); j++) { int64_t bb, ee; bed_chr_intv(s.bed, i, j, &bb, &ee); reglist_add(&rl, tid, bb, ee); }
                    }
                    if (fn_region_file) { bed_destroy(s.bed); s.bed = NULL; }
                }
                for (int i = region_start; i < argc; i++) {
                    int tid; int64_t bb, ee;
                    if (hts_parse_region(argv[i], header, &tid, &bb, &ee) < 0) {
                        fprintf(stderr, "[main_samview] region \"%s\" specifies an invalid region or unknown reference. Continue anyway.\n", argv[i]);
                        continue;
                    }
                    if (tid == HTS_IDX_NOCOOR) { nocoor = 1; continue; }
                    reglist_add(&rl, tid, bb, ee);
                }
                reglist_sort_merge(&rl);
                int i = 0;
                while (i < rl.n && ret == 0) {
                    int tid = rl.a[i].tid; int j = i;
                    while (j < rl.n && rl.a[j].tid == tid) j++;
                    int64_t *bb = malloc((j - i) * sizeof(int64_t)), *ee = malloc((j - i) * sizeof(int64_t));
                    for (int k = i; k < j; k++) { bb[k-i] = rl.a[k].beg; ee[k-i] = rl.a[k].end; }
                    hts_itr_t *itr = sam_itr_query_multi(idx, tid, j - i, bb, ee);
                    free(bb); free(ee);
                    while ((r = sam_itr_next(in, itr, b)) >= 0) {
                        count_processed++;
                        if (s.sanitize) bam_sanitize(header, b, s.sanitize);
                        int pr = process_aln(header, b, &s);
                        if (pr < 0) { ret = 1; break; }
                        if (pr == 0) {
                            if (!is_count) { change_flag(b, &s); if (s.remove_aux) remove_aux_tags(b, &s); if (sam_write1(out, header, b) < 0) { ret = 1; break; } }
                            count++;
                        } else {
                            count_filtered++;
                            if (!is_count) {
                                if (s.unmap) { b->core.flag |= BAM_FUNMAP; change_flag(b, &s); if (s.remove_aux) remove_aux_tags(b, &s); if (sam_write1(out, header, b) < 0) { ret = 1; break; } }
                                else if (un_out) { if (sam_write1(un_out, header, b) < 0) { ret = 1; break; } }
                            }
                        }
                    }
                    if (r < -1) { print_error("view", "retrieval of region failed due to truncated file or corrupt BAM index file"); ret = 1; }
                    hts_itr_destroy(itr);
                    i = j;
                }
                if (nocoor && ret == 0) {
                    hts_itr_t *itr = sam_itr_queryi(idx, HTS_IDX_NOCOOR, 0, 0);
                    while ((r = sam_itr_next(in, itr, b)) >= 0) {
                        count_processed++;
                        int pr = process_aln(header, b, &s);
                        if (pr == 0) { if (!is_count) { change_flag(b, &s); if (s.remove_aux) remove_aux_tags(b, &s); sam_write1(out, header, b); } count++; }
                        else { count_filtered++; if (!is_count && un_out) sam_write1(un_out, header, b); }
                    }
                    hts_itr_destroy(itr);
                }
                free(rl.a);
            } else {
                for (int i = region_start; i < argc; ++i) {
                    hts_itr_t *iter = sam_itr_querys(idx, header, argv[i]);
                    if (iter == NULL) {
                        fprintf(stderr, "[main_samview] region \"%s\" specifies an invalid region or unknown reference. Continue anyway.\n", argv[i]);
                        continue;
                    }
                    while ((r = sam_itr_next(in, iter, b)) >= 0) {
                        count_processed++;
                        if (s.sanitize) bam_sanitize(header, b, s.sanitize);
                        int pr = process_aln(header, b, &s);
                        if (pr < 0) { ret = 1; break; }
                        if (pr == 0) {
                            if (!is_count) { change_flag(b, &s); if (s.remove_aux) remove_aux_tags(b, &s); if (sam_write1(out, header, b) < 0) { print_error_errno("view", "writing to \"%s\" failed", fn_out ? fn_out : "standard output"); ret = 1; break; } }
                            count++;
                        } else {
                            count_filtered++;
                            if (!is_count) {
                                if (s.unmap) { b->core.flag |= BAM_FUNMAP; change_flag(b, &s); if (s.remove_aux) remove_aux_tags(b, &s); if (sam_write1(out, header, b) < 0) { ret = 1; break; } }
                                else if (un_out) { if (sam_write1(un_out, header, b) < 0) { ret = 1; break; } }
                            }
                        }
                    }
                    hts_itr_destroy(iter);
                    if (r < -1) { print_error("view", "retrieval of region \"%s\" failed due to truncated file or corrupt BAM index file", argv[i]); ret = 1; break; }
                }
            }
            hts_idx_destroy(idx);
            (void)fetch_pairs;
        }
        bam_destroy1(b);
    }

done_files:
    if (out) {
        if (sam_close(out) < 0) { print_error_errno("view", "error closing \"%s\"", fn_out ? fn_out : "standard output"); ret = 1; }
    }
    if (un_out) { if (sam_close(un_out) < 0) { print_error_errno("view", "error closing \"%s\"", fn_un_out); ret = 1; } }
    sam_close(in);
    free(arg_list);
    if (is_count && ret == 0) {
        if (fn_out) { FILE *fp = fopen(fn_out, "w"); if (fp) { fprintf(fp, "%lld\n", (long long)count); fclose(fp); } else { print_error_errno("view", "failed to open \"%s\" for writing", fn_out); ret = 1; } }
        else printf("%lld\n", (long long)count);
    }
    if (fn_counts && ret == 0) write_counts(fn_counts, count_processed, count, count_filtered);
view_end:
    free(fn_out); free(fn_list); free(fn_un_out); free(fn_counts); free(fn_region_file); free(fn_bed); free(fn_rn); free(tag_file);
    free(s.library); if (s.bed) bed_destroy(s.bed);
    strmap_free(s.rghash); strmap_free(s.rnhash); strmap_free(s.tvhash); strmap_free(s.remove_aux);
    if (s.filter) hts_filter_free(s.filter);
    sam_global_args_free(&ga);
    return ret;
}

static int usage(FILE *fp, int exit_status, int is_long_help) {
    fprintf(fp,
"\n"
"Usage: samtools view [options] <in.bam>|<in.sam>|<in.cram> [region ...]\n"
"\n"
"Output options:\n"
"  -b, --bam                  Output BAM\n"
"  -C, --cram                 Output CRAM (requires -T)\n"
"  -1, --fast                 Use fast BAM compression (and default to --bam)\n"
"  -u, --uncompressed         Uncompressed BAM output (and default to --bam)\n"
"  -h, --with-header          Include header in SAM output\n"
"  -H, --header-only          Print SAM header only (no alignments)\n"
"      --no-header            Print SAM alignment records only [default]\n"
"  -c, --count                Print only the count of matching records\n"
"      --save-counts FILE     Write counts of passed/failed records to FILE\n"
"  -o, --output FILE          Write output to FILE [standard output]\n"
"  -U, --unoutput FILE, --output-unselected FILE\n"
"                             Output reads not selected by filters to FILE\n"
"  -p, --unmap                Set flag to UNMAP on reads not selected\n"
"                             then write to output file.\n"
"  -P, --fetch-pairs          Retrieve complete pairs even when outside of region\n"
"\n"
"Input options:\n"
"  -t, --fai-reference FILE   FILE listing reference names and lengths\n"
"  -M, --use-index            Use index and multi-region iterator for regions\n"
"      --region[s]-file FILE  Use index to include only reads overlapping FILE\n"
"  -X, --customized-index     Expect extra index file argument after <in.bam>\n"
"\n"
"Filtering options (Only include in output reads that...):\n"
"  -L, --target[s]-file FILE  ...overlap (BED) regions in FILE\n"
"  -N, --qname-file [^]FILE   ...whose read name is listed in FILE (\"^\" negates)\n"
"  -r, --read-group STR       ...are in read group STR or in no read group\n"
"  -R, --read-group-file [^]FILE\n"
"                             ...are in a read group listed in FILE or in none\n"
"  -n, --exclude-no-read_group\n"
"                             ...have a read group, exclude those that have not\n"
"  -d, --tag STR1[:STR2]      ...have a tag STR1 (with associated value STR2)\n"
"  -D, --tag-file STR:FILE    ...have a tag STR whose value is listed in FILE\n"
"  -q, --min-MQ INT           ...have mapping quality >= INT\n"
"  -l, --library STR          ...are in library STR\n"
"  -m, --min-qlen INT         ...cover >= INT query bases (as measured via CIGAR)\n"
"  -e, --expr STR             ...match the filter expression STR\n"
"  -f, --require-flags FLAG   ...have all of the FLAGs present\n"
"  -F, --excl[ude]-flags FLAG ...have none of the FLAGs present\n"
"      --rf, --incl-flags, --include-flags FLAG\n"
"                             ...have some of the FLAGs present\n"
"  -G FLAG                    EXCLUDE reads with all of the FLAGs present\n"
"      --subsample FLOAT      Keep only FLOAT fraction of templates/read pairs\n"
"      --subsample-seed INT   Influence WHICH reads are kept in subsampling [0]\n"
"  -s INT.FRAC                Same as --subsample 0.FRAC --subsample-seed INT\n"
"\n"
"Processing options:\n"
"      --add-flags FLAG       Add FLAGs to reads\n"
"      --remove-flags FLAG    Remove FLAGs from reads\n"
"  -x, --remove-tag STR\n"
"               Comma-separated read tags to strip (repeatable) [null]\n"
"      --keep-tag STR\n"
"               Comma-separated read tags to preserve (repeatable) [null].\n"
"               Equivalent to \"-x ^STR\"\n"
"  -B, --remove-B             Collapse the backward CIGAR operation\n"
"  -z, --sanitize FLAGS       Perform sanitity checking and fixing on records.\n"
"                             FLAGS is comma separated (see manual). [off]\n"
"\n"
"General options:\n"
"  -?, --help   Print long help, including note about region specification\n"
"  -S           Ignored (input format is auto-detected)\n"
"      --no-PG  Do not add a PG line\n");
    sam_global_opt_help(fp, "-.O.T@..");
    fprintf(fp, "\n");
    if (is_long_help)
        fprintf(fp,
"Notes:\n"
"\n"
"1. This command now auto-detects the input format (BAM/CRAM/SAM).\n"
"   Further control over the CRAM format can be specified by using the\n"
"   --output-fmt-option, e.g. to specify the number of sequences per slice\n"
"   and to use avoid reference based compression:\n"
"\n"
"\tsamtools view -C --output-fmt-option seqs_per_slice=5000 \\\n"
"\t   --output-fmt-option no_ref -o out.cram in.bam\n"
"\n"
"   Options can also be specified as a comma separated list within the\n"
"   --output-fmt value too.  For example this is equivalent to the above\n"
"\n"
"\tsamtools view --output-fmt cram,seqs_per_slice=5000,no_ref \\\n"
"\t   -o out.cram in.bam\n"
"\n"
"2. The file supplied with `-t' is SPACE/TAB delimited with the first\n"
"   two fields of each line consisting of the reference name and the\n"
"   corresponding sequence length. The `.fai' file generated by \n"
"   `samtools faidx' is suitable for use as this file. This may be an\n"
"   empty file if reads are unaligned.\n"
"\n"
"3. SAM->BAM conversion:  samtools view -bT ref.fa in.sam.gz\n"
"\n"
"4. BAM->SAM conversion:  samtools view -h in.bam\n"
"\n"
"5. A region should be presented in one of the following formats:\n"
"   `chr1', `chr2:1,000' and `chr3:1000-2,000'. When a region is\n"
"   specified, the input alignment file must be a sorted and indexed\n"
"   alignment (BAM/CRAM) file.\n"
"\n"
"6. Option `-u' is preferred over `-b' when the output is piped to\n"
"   another samtools command.\n"
"\n"
"7. Option `-M`/`--use-index` causes overlaps with `-L` BED file regions and\n"
"   command-line region arguments to be computed using the multi-region iterator\n"
"   and an index. This increases speed, omits duplicates, and outputs the reads\n"
"   as they are ordered in the input SAM/BAM/CRAM file.\n"
"\n"
"8. Options `-L`/`--target[s]-file` and `--region[s]-file` may not be used\n"
"   together. `--region[s]-file FILE` is simply equivalent to `-M -L FILE`,\n"
"   so using both causes one of the specified BED files to be ignored.\n"
"\n");
    return exit_status;
}
