#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <errno.h>
#include <unistd.h>
#include "samtools.h"
#include "index.h"
#include "log.h"

/* build an index for a BAM file; returns 0 ok, -1 failure (message printed), -2 unsorted etc */
int sam_index_build3(const char *fn, const char *fnidx, int min_shift, int nthreads) {
    (void)nthreads;
    samfile_t *fp = sam_open_read_nohdr(fn);
    if (!fp) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn, strerror(errno)); return -1; }
    if (fp->fmt == FMT_SAM && !bgzf_is_bgzf(fp->bg)) {
        log_error("sam_index_build3", "SAM file \"%s\" not BGZF compressed", fn);
        sam_close(fp); errno = ENOENT; return -2;
    }
    if (fp->fmt == FMT_CRAM) { sam_close(fp); errno = ENOENT; return -2; }
    if (fp->fmt != FMT_BAM && fp->fmt != FMT_SAM) {
        sam_close(fp); errno = ENOENT; return -3;
    }
    if (sam_read_header(fp) < 0) { sam_close(fp); errno = ENOENT; return -2; }
    sam_hdr_t *h = fp->hdr;
    int fmt = min_shift > 0 ? HTS_FMT_CSI : HTS_FMT_BAI;
