#include "sanitize.h"
#include "samtools.h"
#include <string.h>
#include <strings.h>

int bam_sanitize_options(const char *str) {
    int opt = 0;
    const char *p = str;
    while (*p) {
        const char *e = strchr(p, ','); size_t l = e ? (size_t)(e - p) : strlen(p);
        if (l == 3 && strncasecmp(p, "all", 3) == 0) opt |= FIX_ALL;
        else if (l == 4 && strncasecmp(p, "none", 4) == 0) opt = 0;
        else if (l == 3 && strncasecmp(p, "off", 3) == 0) opt = 0;
        else if (l == 3 && strncasecmp(p, "pos", 3) == 0) opt |= FIX_POS;
        else if (l == 5 && strncasecmp(p, "mqual", 5) == 0) opt |= FIX_MQUAL;
        else if (l == 5 && strncasecmp(p, "unmap", 5) == 0) opt |= FIX_UNMAP;
        else if (l == 5 && strncasecmp(p, "cigar", 5) == 0) opt |= FIX_CIGAR;
        else if (l == 3 && strncasecmp(p, "aux", 3) == 0) opt |= FIX_AUX;
        else if (l == 6 && strncasecmp(p, "cigdup", 6) == 0) opt |= FIX_CIGDUP;
        else if (l == 6 && strncasecmp(p, "cigarx", 6) == 0) opt |= FIX_CIGARX;
        else { print_error("sanitize", "Unrecognised keyword %.*s", (int)l, p); return -1; }
        if (!e) break;
        p = e + 1;
    }
    return opt;
}

int bam_sanitize(sam_hdr_t *h, bam1_t *b, int flags) {
    (void)h;
    if ((flags & FIX_POS) && b->core.tid < 0 && b->core.pos >= 0) { b->core.pos = -1; b->core.flag |= BAM_FUNMAP; }
    if ((flags & FIX_UNMAP) && (b->core.flag & BAM_FUNMAP)) {
        if (flags & FIX_MQUAL) b->core.qual = 0;
        if (flags & FIX_CIGAR) { if (b->core.n_cigar) bam_set_cigar(b, NULL, 0); }
    }
    if ((flags & FIX_UNMAP) && (b->core.flag & BAM_FMUNMAP) && (flags & FIX_POS)) { if (b->core.mtid >= 0 && 0) {} }
    if ((flags & FIX_CIGDUP) && b->core.n_cigar > 1) {
        uint32_t *c = bam_get_cigar(b); uint32_t n = b->core.n_cigar, j = 0;
        uint32_t *nc = malloc(n * 4);
        for (uint32_t i = 0; i < n; i++) {
            if (j > 0 && bam_cigar_op(nc[j-1]) == bam_cigar_op(c[i])) nc[j-1] = bam_cigar_gen(bam_cigar_oplen(nc[j-1]) + bam_cigar_oplen(c[i]), bam_cigar_op(c[i]));
            else nc[j++] = c[i];
        }
        if (j != n) bam_set_cigar(b, nc, j);
        free(nc);
    }
    if ((flags & FIX_CIGARX) && b->core.n_cigar) {
        uint32_t *c = bam_get_cigar(b);
        for (uint32_t i = 0; i < b->core.n_cigar; i++) if (bam_cigar_op(c[i]) == BAM_CEQUAL || bam_cigar_op(c[i]) == BAM_CDIFF) c[i] = bam_cigar_gen(bam_cigar_oplen(c[i]), BAM_CMATCH);
        /* merge adjacent */
        uint32_t n = b->core.n_cigar, j = 0; uint32_t *nc = malloc(n * 4);
        for (uint32_t i = 0; i < n; i++) {
            if (j > 0 && bam_cigar_op(nc[j-1]) == bam_cigar_op(c[i])) nc[j-1] = bam_cigar_gen(bam_cigar_oplen(nc[j-1]) + bam_cigar_oplen(c[i]), bam_cigar_op(c[i]));
            else nc[j++] = c[i];
        }
        if (j != n) bam_set_cigar(b, nc, j);
        free(nc);
    }
    return 0;
}
