        for (int i = 0; i < h->n_targets; i++) printf("%s\t%lld\t%llu\t%llu\n", h->targets[i].name, (long long)h->targets[i].len, (unsigned long long)mapped[i], (unsigned long long)unmapped[i]);
        printf("*\t0\t0\t%llu\n", (unsigned long long)nocoor);
        free(mapped); free(unmapped);
    }
    sam_close(fp);
    return 0;
}

/* ---------------- flagstat ---------------- */
typedef struct {
    long long n_reads[2], n_mapped[2], n_pair_all[2], n_pair_map[2], n_pair_good[2];
    long long n_sgltn[2], n_read1[2], n_read2[2], n_dup[2];
    long long n_diffchr[2], n_diffhigh[2], n_secondary[2], n_supp[2], n_primary[2], n_pmapped[2], n_pdup[2];
} bam_flagstat_t;

static void flagstat_loop(bam_flagstat_t *s, bam1_core_t *c) {
    int w = (c->flag & BAM_FQCFAIL) ? 1 : 0;
    ++s->n_reads[w];
    if (c->flag & BAM_FSECONDARY) ++s->n_secondary[w];
    else if (c->flag & BAM_FSUPPLEMENTARY) ++s->n_supp[w];
    else {
        ++s->n_primary[w];
        if (c->flag & BAM_FPAIRED) {
            ++s->n_pair_all[w];
            if ((c->flag & BAM_FPROPER_PAIR) && !(c->flag & BAM_FUNMAP)) ++s->n_pair_good[w];
            if (c->flag & BAM_FREAD1) ++s->n_read1[w];
            if (c->flag & BAM_FREAD2) ++s->n_read2[w];
            if ((c->flag & BAM_FMUNMAP) && !(c->flag & BAM_FUNMAP)) ++s->n_sgltn[w];
            if (!(c->flag & BAM_FUNMAP) && !(c->flag & BAM_FMUNMAP)) {
                ++s->n_pair_map[w];
                if (c->mtid != c->tid) { ++s->n_diffchr[w]; if (c->qual >= 5) ++s->n_diffhigh[w]; }
            }
        }
        if (!(c->flag & BAM_FUNMAP)) ++s->n_pmapped[w];
        if (c->flag & BAM_FDUP) ++s->n_pdup[w];
    }
    if (!(c->flag & BAM_FUNMAP)) ++s->n_mapped[w];
    if (c->flag & BAM_FDUP) ++s->n_dup[w];
}

static void percent(char *buf, long long n, long long total) {
    if (total != 0) sprintf(buf, "%.2f%%", (float)n / total * 100.0);
    else strcpy(buf, "N/A");
}

static void flagstat_usage(FILE *fp) {
    fprintf(fp, "Usage: samtools flagstat [options] <in.bam>\n");
    sam_global_opt_help(fp, ".-..-@-.");
    fprintf(fp, "  -O, --output-fmt FORMAT[,OPT[=VAL]]...\n               Specify output format (json, tsv)\n");
}

static void out_fmt_json(bam_flagstat_t *s) {
    char b1[32], b2[32], b3[32], b4[32];
    printf("{\n");
    for (int w = 0; w < 2; w++) {
        printf(" \"QC-%s reads\": { \n", w ? "failed" : "passed");
        printf("  \"total\": %lld, \n", s->n_reads[w]);
        printf("  \"primary\": %lld, \n", s->n_primary[w]);
        printf("  \"secondary\": %lld, \n", s->n_secondary[w]);
        printf("  \"supplementary\": %lld, \n", s->n_supp[w]);
        printf("  \"duplicates\": %lld, \n", s->n_dup[w]);
        printf("  \"primary duplicates\": %lld, \n", s->n_pdup[w]);
        printf("  \"mapped\": %lld, \n", s->n_mapped[w]);
        if (s->n_reads[w]) printf("  \"mapped %%\": %.2f, \n", (float)s->n_mapped[w] / s->n_reads[w] * 100.0); else printf("  \"mapped %%\": null, \n");
        printf("  \"primary mapped\": %lld, \n", s->n_pmapped[w]);
        if (s->n_primary[w]) printf("  \"primary mapped %%\": %.2f, \n", (float)s->n_pmapped[w] / s->n_primary[w] * 100.0); else printf("  \"primary mapped %%\": null, \n");
        printf("  \"paired in sequencing\": %lld, \n", s->n_pair_all[w]);
        printf("  \"read1\": %lld, \n", s->n_read1[w]);
        printf("  \"read2\": %lld, \n", s->n_read2[w]);
        printf("  \"properly paired\": %lld, \n", s->n_pair_good[w]);
        if (s->n_pair_all[w]) printf("  \"properly paired %%\": %.2f, \n", (float)s->n_pair_good[w] / s->n_pair_all[w] * 100.0); else printf("  \"properly paired %%\": null, \n");
        printf("  \"with itself and mate mapped\": %lld, \n", s->n_pair_map[w]);
        printf("  \"singletons\": %lld, \n", s->n_sgltn[w]);
        if (s->n_pair_all[w]) printf("  \"singletons %%\": %.2f, \n", (float)s->n_sgltn[w] / s->n_pair_all[w] * 100.0); else printf("  \"singletons %%\": null, \n");
        printf("  \"with mate mapped to a different chr\": %lld, \n", s->n_diffchr[w]);
        printf("  \"with mate mapped to a different chr (mapQ >= 5)\": %lld \n", s->n_diffhigh[w]);
        printf(w ? " }\n" : " },\n");
    }
    printf("}\n");
    (void)b1; (void)b2; (void)b3; (void)b4;
}

static void out_fmt_tsv(bam_flagstat_t *s) {
    char b1[32], b2[32];
    printf("%lld\t%lld\ttotal (QC-passed reads + QC-failed reads)\n", s->n_reads[0], s->n_reads[1]);
    printf("%lld\t%lld\tprimary\n", s->n_primary[0], s->n_primary[1]);
    printf("%lld\t%lld\tsecondary\n", s->n_secondary[0], s->n_secondary[1]);
    printf("%lld\t%lld\tsupplementary\n", s->n_supp[0], s->n_supp[1]);
    printf("%lld\t%lld\tduplicates\n", s->n_dup[0], s->n_dup[1]);
    printf("%lld\t%lld\tprimary duplicates\n", s->n_pdup[0], s->n_pdup[1]);
    printf("%lld\t%lld\tmapped\n", s->n_mapped[0], s->n_mapped[1]);
    percent(b1, s->n_mapped[0], s->n_reads[0]); percent(b2, s->n_mapped[1], s->n_reads[1]);
    printf("%s\t%s\tmapped %%\n", b1, b2);
    printf("%lld\t%lld\tprimary mapped\n", s->n_pmapped[0], s->n_pmapped[1]);
    percent(b1, s->n_pmapped[0], s->n_primary[0]); percent(b2, s->n_pmapped[1], s->n_primary[1]);
    printf("%s\t%s\tprimary mapped %%\n", b1, b2);
    printf("%lld\t%lld\tpaired in sequencing\n", s->n_pair_all[0], s->n_pair_all[1]);
    printf("%lld\t%lld\tread1\n", s->n_read1[0], s->n_read1[1]);
    printf("%lld\t%lld\tread2\n", s->n_read2[0], s->n_read2[1]);
    printf("%lld\t%lld\tproperly paired\n", s->n_pair_good[0], s->n_pair_good[1]);
    percent(b1, s->n_pair_good[0], s->n_pair_all[0]); percent(b2, s->n_pair_good[1], s->n_pair_all[1]);
    printf("%s\t%s\tproperly paired %%\n", b1, b2);
    printf("%lld\t%lld\twith itself and mate mapped\n", s->n_pair_map[0], s->n_pair_map[1]);
    printf("%lld\t%lld\tsingletons\n", s->n_sgltn[0], s->n_sgltn[1]);
    percent(b1, s->n_sgltn[0], s->n_pair_all[0]); percent(b2, s->n_sgltn[1], s->n_pair_all[1]);
    printf("%s\t%s\tsingletons %%\n", b1, b2);
    printf("%lld\t%lld\twith mate mapped to a different chr\n", s->n_diffchr[0], s->n_diffchr[1]);
    printf("%lld\t%lld\twith mate mapped to a different chr (mapQ>=5)\n", s->n_diffhigh[0], s->n_diffhigh[1]);
}

static void out_fmt_default(bam_flagstat_t *s) {
    char b1[32], b2[32];
    printf("%lld + %lld in total (QC-passed reads + QC-failed reads)\n", s->n_reads[0], s->n_reads[1]);
    printf("%lld + %lld primary\n", s->n_primary[0], s->n_primary[1]);
    printf("%lld + %lld secondary\n", s->n_secondary[0], s->n_secondary[1]);
    printf("%lld + %lld supplementary\n", s->n_supp[0], s->n_supp[1]);
    printf("%lld + %lld duplicates\n", s->n_dup[0], s->n_dup[1]);
    printf("%lld + %lld primary duplicates\n", s->n_pdup[0], s->n_pdup[1]);
    percent(b1, s->n_mapped[0], s->n_reads[0]); percent(b2, s->n_mapped[1], s->n_reads[1]);
    printf("%lld + %lld mapped (%s : %s)\n", s->n_mapped[0], s->n_mapped[1], b1, b2);
    percent(b1, s->n_pmapped[0], s->n_primary[0]); percent(b2, s->n_pmapped[1], s->n_primary[1]);
    printf("%lld + %lld primary mapped (%s : %s)\n", s->n_pmapped[0], s->n_pmapped[1], b1, b2);
    printf("%lld + %lld paired in sequencing\n", s->n_pair_all[0], s->n_pair_all[1]);
    printf("%lld + %lld read1\n", s->n_read1[0], s->n_read1[1]);
    printf("%lld + %lld read2\n", s->n_read2[0], s->n_read2[1]);
    percent(b1, s->n_pair_good[0], s->n_pair_all[0]); percent(b2, s->n_pair_good[1], s->n_pair_all[1]);
    printf("%lld + %lld properly paired (%s : %s)\n", s->n_pair_good[0], s->n_pair_good[1], b1, b2);
    printf("%lld + %lld with itself and mate mapped\n", s->n_pair_map[0], s->n_pair_map[1]);
    percent(b1, s->n_sgltn[0], s->n_pair_all[0]); percent(b2, s->n_sgltn[1], s->n_pair_all[1]);
    printf("%lld + %lld singletons (%s : %s)\n", s->n_sgltn[0], s->n_sgltn[1], b1, b2);
    printf("%lld + %lld with mate mapped to a different chr\n", s->n_diffchr[0], s->n_diffchr[1]);
    printf("%lld + %lld with mate mapped to a different chr (mapQ>=5)\n", s->n_diffhigh[0], s->n_diffhigh[1]);
}

int bam_flagstat(int argc, char **argv) {
    int c; const char *out_fmt = "default";
    static const struct option lopts[] = {
        { "input-fmt-option", required_argument, NULL, 1002 }, { "threads", required_argument, NULL, '@' }, { "verbosity", required_argument, NULL, 1008 },
        { "output-fmt", required_argument, NULL, 'O' }, { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "@:O:", lopts, NULL)) >= 0) {
        switch (c) {
        case '@': break;
        case 'O': out_fmt = optarg; break;
        case 1002: break;
        case 1008: hts_verbose = atoi(optarg); break;
        default:
            if (optopt) fprintf(stderr, "flagstat: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "flagstat: unrecognized option '%s'\n", argv[optind-1]);
            flagstat_usage(stderr); return 1;
        }
    }
    if (argc == optind) { flagstat_usage(stdout); return 1; }
    if (argc != optind + 1) { flagstat_usage(stderr); return 1; }
    const char *fn = argv[optind];
    samfile_t *fp = sam_open_read_nohdr(fn);
    if (!fp) {
        log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn, strerror(errno));
        print_error_errno("flagstat", "Cannot open input file \"%s\"", fn); return 1;
    }
    if (sam_read_header(fp) < 0) { print_error("flagstat", "Failed to read header for \"%s\"", fn); sam_close(fp); return 1; }
    bam_flagstat_t s; memset(&s, 0, sizeof s);
    bam1_t *b = bam_init1(); int r;
    while ((r = sam_read1(fp, fp->hdr, b)) >= 0) flagstat_loop(&s, &b->core);
    bam_destroy1(b);
    if (r < -1) { print_error("flagstat", "error reading from \"%s\"", fn); sam_close(fp); return 1; }
    if (strcmp(out_fmt, "json") == 0) out_fmt_json(&s);
    else if (strcmp(out_fmt, "tsv") == 0) out_fmt_tsv(&s);
    else out_fmt_default(&s);
    sam_close(fp);
    return 0;
}

/* ---------------- flags ---------------- */
static void flags_usage(FILE *fp) {
    fprintf(fp,
"About: Convert between textual and numeric flag representation\n"
"Usage: samtools flags FLAGS...\n"
"\n"
"Each FLAGS argument is either an INT (in decimal/hexadecimal/octal) representing\n"
"a combination of the following numeric flag values, or a comma-separated string\n"
"NAME,...,NAME representing a combination of the following flag names:\n"
"\n"
"   0x1     1  PAIRED         paired-end / multiple-segment sequencing technology\n"
"   0x2     2  PROPER_PAIR    each segment properly aligned according to aligner\n"
"   0x4     4  UNMAP          segment unmapped\n"
"   0x8     8  MUNMAP         next segment in the template unmapped\n"
"  0x10    16  REVERSE        SEQ is reverse complemented\n"
"  0x20    32  MREVERSE       SEQ of next segment in template is rev.complemented\n"
"  0x40    64  READ1          the first segment in the template\n"
"  0x80   128  READ2          the last segment in the template\n"
" 0x100   256  SECONDARY      secondary alignment\n"
" 0x200   512  QCFAIL         not passing quality controls or other filters\n"
" 0x400  1024  DUP            PCR or optical duplicate\n"
" 0x800  2048  SUPPLEMENTARY  supplementary alignment\n");
}

int main_flags(int argc, char **argv) {
    if (argc == 1) { flags_usage(stdout); return 0; }
    for (int i = 1; i < argc; i++) {
        int mask = bam_str2flag(argv[i]);
        if (mask < 0) { print_error("flags", "Could not parse \"%s\"", argv[i]); flags_usage(stderr); return 1; }
        char *str = bam_flag2str(mask);
        printf("0x%x\t%d\t%s\n", mask, mask, str);
        free(str);
    }
    return 0;
}

/* ---------------- head ---------------- */
static void head_usage(FILE *fp) {
    fprintf(fp, "Usage: samtools head [OPTION]... [FILE]\nOptions:\n  -h, --headers INT   Display INT header lines [all]\n  -n, --records INT   Display INT alignment record lines [none]\n");
    sam_global_opt_help(fp, ".-..T@-.");
}

int main_head(int argc, char **argv) {
    int c; long nheaders = -1, nrecords = 0;
    static const struct option lopts[] = {
        { "headers", required_argument, NULL, 'h' }, { "records", required_argument, NULL, 'n' },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "reference", required_argument, NULL, 'T' }, { "threads", required_argument, NULL, '@' }, { "verbosity", required_argument, NULL, 1008 }, { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "h:n:T:@:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'h': nheaders = atol(optarg); break;
        case 'n': nrecords = atol(optarg); break;
        case 'T': case '@': case 1002: break;
        case 1008: hts_verbose = atoi(optarg); break;
        default:
            if (optopt) fprintf(stderr, "head: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "head: unrecognized option '%s'\n", argv[optind-1]);
            head_usage(stderr); return 1;
        }
    }
    const char *fn;
    if (optind == argc) fn = "-";
    else if (optind + 1 == argc) fn = argv[optind];
    else { head_usage(stderr); return 1; }
    samfile_t *fp = sam_open_read_nohdr(fn);
    if (!fp) {
        log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn, strerror(errno));
        print_error_errno("head", "failed to open \"%s\" for reading", fn); return 1;
    }
    if (sam_read_header(fp) < 0) { print_error("head", "failed to read the header"); sam_close(fp); return 1; }
    sam_hdr_t *h = fp->hdr;
    const char *text = sam_hdr_str(h); size_t l = sam_hdr_length(h);
    if (nheaders < 0) fwrite(text, 1, l, stdout);
    else {
        long n = 0; const char *p = text;
        while (n < nheaders && p < text + l) {
            const char *nl = memchr(p, '\n', text + l - p);
            size_t len = nl ? (size_t)(nl - p + 1) : (size_t)(text + l - p);
            fwrite(p, 1, len, stdout); p += len; n++;
        }
    }
    int ret = 0;
    if (nrecords != 0) {
        bam1_t *b = bam_init1(); kstring_t ks = KS_INITIALIZE; long n = 0; int r;
        while ((nrecords < 0 || n < nrecords) && (r = sam_read1(fp, h, b)) >= 0) {
            if (sam_format1(h, b, &ks) < 0) { ret = 1; break; }
            kputc('\n', &ks);
            fwrite(ks.s, 1, ks.l, stdout);
            n++;
        }
        if ((nrecords < 0 || n < nrecords) && r < -1) { print_error("head", "\"%s\" is truncated", fn); ret = 1; }
        free(ks.s); bam_destroy1(b);
    }
    sam_close(fp);
    return ret;
}
