{"command":"cd /workspace && cat > src/sort.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <errno.h>
#include <ctype.h>
#include <unistd.h>
#include "samtools.h"
#include "log.h"
#include "index.h"

enum { ORD_COORD = 0, ORD_QNAME, ORD_QNAME_ASCII, ORD_TAG_COORD, ORD_TAG_QNAME, ORD_TAG_QNAME_ASCII, ORD_TEMPLATE, ORD_MINHASH };

int strnum_cmp(const char *_a, const char *_b) {
    const unsigned char *a = (const unsigned char*)_a, *b = (const unsigned char*)_b;
    while (*a && *b) {
        if (isdigit(*a) && isdigit(*b)) {
            const unsigned char *pa = a, *pb = b;
            while (*pa == '0') pa++;
            while (*pb == '0') pb++;
            int la = 0, lb = 0;
            while (isdigit(pa[la])) la++;
            while (isdigit(pb[lb])) lb++;
            if (la != lb) return la < lb ? -1 : 1;
            for (int i = 0; i < la; i++) if (pa[i] != pb[i]) return (int)pa[i] - (int)pb[i];
            a = pa + la; b = pb + lb;
        } else {
            if (*a != *b) return (int)*a - (int)*b;
            a++; b++;
        }
    }
    return *a ? 1 : *b ? -1 : 0;
}

static int g_order = ORD_COORD;
static char g_tag[2];

static inline uint64_t pos_key(const bam1_t *b) {
    uint64_t tid = b->core.tid < 0 ? 0xffffffffu : (uint32_t)b->core.tid;
    return (tid << 32) | ((uint64_t)(uint32_t)(b->core.pos + 1) << 1) | (bam_is_rev(b) ? 1 : 0);
}

static int cmp_core(const bam1_t *a, const bam1_t *b, int order) {
    if (order == ORD_QNAME || order == ORD_QNAME_ASCII) {
        int t = order == ORD_QNAME ? strnum_cmp(bam_get_qname(a), bam_get_qname(b)) : strcmp(bam_get_qname(a), bam_get_qname(b));
        if (t) return t;
        int fa = a->core.flag & 0xc0, fb = b->core.flag & 0xc0;
        if (fa != fb) return fa < fb ? -1 : 1;
        return 0;
    }
    uint64_t pa = pos_key(a), pb = pos_key(b);
    if (pa != pb) return pa < pb ? -1 : 1;
    return 0;
}

static int cmp_tag(const bam1_t *a, const bam1_t *b) {
    uint8_t *ta = bam_aux_get(a, g_tag), *tb = bam_aux_get(b, g_tag);
    if (!ta && tb) return -1;
    if (ta && !tb) return 1;
    if (ta && tb) {
        int sa = (*ta == 'Z' || *ta == 'H'), sb = (*tb == 'Z' || *tb == 'H');
        if (sa && sb) { int t = strcmp((char*)ta + 1, (char*)tb + 1); if (t) return t; }
        else if (sa) return -1;
        else if (sb) return 1;
        else if (*ta == 'A' && *tb == 'A') { if (ta[1] != tb[1]) return ta[1] < tb[1] ? -1 : 1; }
        else {
            double va = (*ta == 'f' || *ta == 'd') ? bam_aux2f(ta) : (*ta == 'A' ? ta[1] : (double)bam_aux2i(ta));
            double vb = (*tb == 'f' || *tb == 'd') ? bam_aux2f(tb) : (*tb == 'A' ? tb[1] : (double)bam_aux2i(tb));
            if (va != vb) return va < vb ? -1 : 1;
        }
    }
    int o = g_order == ORD_TAG_COORD ? ORD_COORD : g_order == ORD_TAG_QNAME ? ORD_QNAME : ORD_QNAME_ASCII;
    return cmp_core(a, b, o);
}

/* template coordinate */
static int64_t unclipped_start(const bam1_t *b) {
    int64_t p = b->core.pos; uint32_t *c = bam_get_cigar(b);
    for (uint32_t i = 0; i < b->core.n_cigar; i++) { int op = bam_cigar_op(c[i]); if (op == BAM_CSOFT_CLIP || op == BAM_CHARD_CLIP) p -= bam_cigar_oplen(c[i]); else break; }
    return p;
}
static int64_t unclipped_end(const bam1_t *b) {
    int64_t p = bam_endpos(b); uint32_t *c = bam_get_cigar(b);
    for (int i = (int)b->core.n_cigar - 1; i >= 0; i--) { int op = bam_cigar_op(c[i]); if (op == BAM_CSOFT_CLIP || op == BAM_CHARD_CLIP) p += bam_cigar_oplen(c[i]); else break; }
    return p;
}
static int64_t unclipped_other_start(int64_t mpos, const char *cig) {
    int64_t p = mpos;
    while (*cig) { char *e; long n = strtol(cig, &e, 10); if (e == cig) break; if (*e == 'S' || *e == 'H') p -= n; else break; cig = e + 1; }
    return p;
}
static int64_t unclipped_other_end(int64_t mpos, const char *cig) {
    int64_t p = mpos; const char *q = cig; int64_t rlen = 0, trail = 0;
    /* compute reference length and trailing clips */
    while (*q) { char *e; long n = strtol(q, &e, 10); if (e == q) break; char op = *e; if (op == 'M' || op == 'D' || op == 'N' || op == '=' || op == 'X') rlen += n; q = e + 1; }
    /* trailing clips */
    q = cig; const char *last = NULL; (void)last;
    /* parse into array */
    int n_ops = 0; long lens[1024]; char ops[1024];
    q = cig;
    while (*q && n_ops < 1024) { char *e; long n = strtol(q, &e, 10); if (e == q) break; lens[n_ops] = n; ops[n_ops] = *e; n_ops++; q = e + 1; }
    for (int i = n_ops - 1; i >= 0; i--) { if (ops[i] == 'S' || ops[i] == 'H') trail += lens[i]; else break; }
    return p + rlen + trail;
}

typedef struct { int64_t tid1, pos1, tid2, pos2; int neg1, neg2; int is_upper; char *lib; char *mi; } tc_key_t;

static sam_hdr_t *g_hdr;

static void tc_key(const bam1_t *b, tc_key_t *k) {
    memset(k, 0, sizeof *k);
    int rev = bam_is_rev(b);
    int64_t s = rev ? unclipped_end(b) : unclipped_start(b);
    k->tid1 = b->core.tid < 0 ? INT32_MAX : b->core.tid; k->pos1 = s; k->neg1 = rev;
    if ((b->core.flag & BAM_FPAIRED) && !(b->core.flag & BAM_FMUNMAP)) {
        uint8_t *mc = bam_aux_get(b, "MC");
        const char *cig = mc ? (char*)mc + 1 : "";
        int mrev = bam_is_mrev(b);
        int64_t ms = mrev ? unclipped_other_end(b->core.mpos, cig) : unclipped_other_start(b->core.mpos, cig);
        k->tid2 = b->core.mtid < 0 ? INT32_MAX : b->core.mtid; k->pos2 = ms; k->neg2 = mrev;
        /* order so that 1 is the lower */
        if (k->tid2 < k->tid1 || (k->tid2 == k->tid1 && (k->pos2 < k->pos1 || (k->pos2 == k->pos1 && k->neg2 < k->neg1)))) {
            int64_t t; int n;
            t = k->tid1; k->tid1 = k->tid2; k->tid2 = t; t = k->pos1; k->pos1 = k->pos2; k->pos2 = t; n = k->neg1; k->neg1 = k->neg2; k->neg2 = n;
            k->is_upper = 1;
        }
    } else { k->tid2 = INT32_MAX; k->pos2 = INT64_MAX; k->neg2 = 0; }
    uint8_t *rg = bam_aux_get(b, "RG");
    if (rg) { char *lb = sam_hdr_find_tag_id(g_hdr, "RG", "ID", (char*)rg + 1, "LB"); k->lib = lb; }
    uint8_t *mi = bam_aux_get(b, "MI");
    if (mi && *mi == 'Z') k->mi = strdup((char*)mi + 1);
}

static int cmp_template(const bam1_t *a, const bam1_t *b) {
    tc_key_t ka, kb; tc_key(a, &ka); tc_key(b, &kb);
    int r = 0;
    if (ka.tid1 != kb.tid1) r = ka.tid1 < kb.tid1 ? -1 : 1;
    else if (ka.pos1 != kb.pos1) r = ka.pos1 < kb.pos1 ? -1 : 1;
    else if (ka.neg1 != kb.neg1) r = ka.neg1 < kb.neg1 ? -1 : 1;
    else if (ka.tid2 != kb.tid2) r = ka.tid2 < kb.tid2 ? -1 : 1;
    else if (ka.pos2 != kb.pos2) r = ka.pos2 < kb.pos2 ? -1 : 1;
    else if (ka.neg2 != kb.neg2) r = ka.neg2 < kb.neg2 ? -1 : 1;
    else {
        const char *la = ka.lib ? ka.lib : "", *lb = kb.lib ? kb.lib : "";
        int t = strcmp(la, lb);
        if (t) r = t;
        else {
            const char *ma = ka.mi ? ka.mi : "", *mb = kb.mi ? kb.mi : "";
            t = strcmp(ma, mb);
            if (t) r = t;
            else {
                t = strcmp(bam_get_qname(a), bam_get_qname(b));
                if (t) r = t;
                else if (ka.is_upper != kb.is_upper) r = ka.is_upper < kb.is_upper ? -1 : 1;
            }
        }
    }
    free(ka.lib); free(ka.mi); free(kb.lib); free(kb.mi);
    return r;
}

static int cmp_records(const void *pa, const void *pb) {
    const bam1_t *a = *(bam1_t* const*)pa, *b = *(bam1_t* const*)pb;
    int r;
    switch (g_order) {
    case ORD_TAG_COORD: case ORD_TAG_QNAME: case ORD_TAG_QNAME_ASCII: r = cmp_tag(a, b); break;
    case ORD_TEMPLATE: r = cmp_template(a, b); break;
    case ORD_QNAME: case ORD_QNAME_ASCII: r = cmp_core(a, b, g_order); break;
    default: r = cmp_core(a, b, ORD_COORD); break;
    }
    if (r) return r;
    return a->id < b->id ? -1 : a->id > b->id ? 1 : 0;
}

static void sort_usage(FILE *fp) {
    fprintf(fp,
"Usage: samtools sort [options...] [in.bam]\n"
"Options:\n"
"  -l INT     Set compression level, from 0 (uncompressed) to 9 (best)\n"
"  -u         Output uncompressed data (equivalent to -l 0)\n"
"  -m INT     Set maximum memory per thread; suffix K/M/G recognized [768M]\n"
"  -M         Use minimiser for clustering unaligned/unplaced reads\n"
"  -R         Do not use reverse strand (only compatible with -M)\n"
"  -K INT     Kmer size to use for minimiser [20]\n"
"  -I FILE    Order minimisers by their position in FILE FASTA\n"
"  -w INT     Window size for minimiser indexing via -I ref.fa [100]\n"
"  -H         Squash homopolymers when computing minimiser\n"
"  -n         Sort by read name (natural): cannot be used with samtools index\n"
"  -N         Sort by read name (ASCII): cannot be used with samtools index\n"
"  -t TAG     Sort by value of TAG. Uses position as secondary index (or read name if -n is set)\n"
"  -o FILE    Write final output to FILE rather than standard output\n"
"  -T PREFIX  Write temporary files to PREFIX.nnnn.bam\n"
"      --no-PG\n"
"               Do not add a PG line\n"
"      --template-coordinate\n"
"               Sort by template-coordinate\n");
    sam_global_opt_help(fp, ".-O-.@--");
}

int bam_sort(int argc, char **argv) {
    int c, ret = 0, by_qname = 0, ascii = 0, by_tag = 0, template = 0, minhash = 0, no_pg = 0, level = -1;
    char *fnout = NULL, *tmpprefix = NULL; const char *tag = NULL;
    size_t max_mem = 768 << 20;
    sam_global_args ga = SAM_GLOBAL_ARGS_INIT;
    static const struct option lopts[] = {
        { "no-PG", no_argument, NULL, 1 }, { "template-coordinate", no_argument, NULL, 2 },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "output-fmt", required_argument, NULL, 1003 }, { "output-fmt-option", required_argument, NULL, 1004 },
        { "reference", required_argument, NULL, 1005 }, { "threads", required_argument, NULL, '@' }, { "write-index", no_argument, NULL, 1007 }, { "verbosity", required_argument, NULL, 1008 },
        { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "l:m:no:O:T:@:t:MNuK:I:w:HR", lopts, NULL)) >= 0) {
        switch (c) {
        case 'o': fnout = optarg; break;
        case 'n': by_qname = 1; ascii = 0; break;
        case 'N': by_qname = 1; ascii = 1; break;
        case 't': by_tag = 1; tag = optarg; break;
        case 'M': minhash = 1; break;
        case 'K': case 'I': case 'w': case 'H': case 'R': break;
        case 'm': {
            char *q; double m = strtod(optarg, &q);
            if (*q == 'k' || *q == 'K') m *= 1024; else if (*q == 'm' || *q == 'M') m *= 1024 * 1024; else if (*q == 'g' || *q == 'G') m *= 1024 * 1024 * 1024;
            max_mem = (size_t)m;
            break;
        }
        case 'T': tmpprefix = optarg; break;
        case 'u': level = 0; break;
        case 'l': level = atoi(optarg); break;
        case '@': ga.nthreads = atoi(optarg); break;
        case 1: no_pg = 1; break;
        case 2: template = 1; break;
        case 1003: case 1004: case 1005: case 1008: case 1002: {
            int r = parse_sam_global_opt(c, optarg, NULL, &ga);
            if (r < 0) { sort_usage(stderr); return 1; }
            break;
        }
        case 1007: ga.write_index = 1; break;
        default:
            if (optopt) fprintf(stderr, "sort: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "sort: unrecognized option '%s'\n", argv[optind-1]);
            sort_usage(stderr); return 1;
        }
    }
    if (argc - optind > 1) { fprintf(stderr, "[bam_sort] Use -T PREFIX / -o FILE to specify temporary and final output files\n"); sort_usage(stderr); return 1; }
    if (max_mem < (1 << 20)) {
        fprintf(stderr, "[bam_sort] -m setting (%zu bytes) is less than the minimum required (1M).\n\n"
"Trying to run with -m too small can lead to the creation of a very large number\n"
"of temporary files.  This may make sort fail due to it exceeding limits on the\n"
"number of files it can have open at the same time.\n\n"
"Please check your -m parameter.  It should be an integer followed by one of the\n"
"letters K (for kilobytes), M (megabytes) or G (gigabytes).  You should ensure it\n"
"is at least the minimum above, and much higher if you are sorting a large file.\n", max_mem);
        return 1;
    }
    if (by_tag) { if (strlen(tag) != 2) { print_error("sort", "tag name must be 2 characters"); return 1; } g_tag[0] = tag[0]; g_tag[1] = tag[1]; }
    if (template) g_order = ORD_TEMPLATE;
    else if (by_tag) g_order = by_qname ? (ascii ? ORD_TAG_QNAME_ASCII : ORD_TAG_QNAME) : ORD_TAG_COORD;
    else if (by_qname) g_order = ascii ? ORD_QNAME_ASCII : ORD_QNAME;
    else g_order = ORD_COORD;
    if (level >= 0 && ga.out_level < 0) ga.out_level = level;
    (void)tmpprefix; (void)minhash;

    const char *fn = optind < argc ? argv[optind] : "-";
    samfile_t *in = sam_open_read_nohdr(fn);
    if (!in) {
        log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn, strerror(errno));
        print_error_errno("sort", "can't open \"%s\"", fn); return 1;
    }
    if (in->fmt == FMT_CRAM) { print_error("sort", "CRAM not supported"); sam_close(in); return 1; }
    if (sam_read_header(in) < 0) { print_error("sort", "failed to read header from \"%s\"", fn); sam_close(in); return 1; }
    sam_hdr_t *h = in->hdr; g_hdr = h;

    /* read all */
    size_t n = 0, m = 0; bam1_t **recs = NULL;
    bam1_t *b = bam_init1(); int r;
    while ((r = sam_read1(in, h, b)) >= 0) {
        if (template && (b->core.flag & BAM_FPAIRED) && !(b->core.flag & BAM_FMUNMAP) && !bam_aux_get(b, "MC") && !(b->core.flag & BAM_FUNMAP)) {
            fprintf(stderr, "[bam_sort] error: no MC tag. Please run samtools fixmate on file first.\n");
            ret = 1; break;
        }
        if (n == m) { m = m ? m * 2 : 1024; recs = realloc(recs, m * sizeof(bam1_t*)); }
        recs[n] = bam_dup1(b); recs[n]->id = n; n++;
    }
    bam_destroy1(b);
    if (r < -1) { print_error("sort", "truncated file. Aborting"); ret = 1; }
    if (ret) { for (size_t i = 0; i < n; i++) bam_destroy1(recs[i]); free(recs); sam_close(in); return ret; }

    qsort(recs, n, sizeof(bam1_t*), cmp_records);

    /* header updates */
    {
        const char *so = "coordinate"; char ss[64] = "";
        if (template) { so = "unsorted"; strcpy(ss, "unsorted:template-coordinate"); }
        else if (by_tag) { so = "unsorted"; snprintf(ss, sizeof ss, "unsorted:%s:%s", tag, by_qname ? (ascii ? "queryname:lexicographical" : "queryname:natural") : "coordinate"); }
        else if (by_qname) { so = "queryname"; strcpy(ss, ascii ? "queryname:lexicographical" : "queryname:natural"); }
        else if (minhash) { strcpy(ss, "coordinate:minhash"); }
        int hd = sam_hdr_find_line_id(h, "HD", NULL, NULL);
        if (hd >= 0) {
            sam_hdr_update_line_idx(h, hd, "GO", NULL);
            sam_hdr_update_line_idx(h, hd, "SS", NULL);
            sam_hdr_update_line_idx(h, hd, "SO", so);
            if (ss[0]) sam_hdr_update_line_idx(h, hd, "SS", ss);
        } else {
            char line[256]; snprintf(line, sizeof line, "@HD\tVN:1.6\tSO:%s%s%s", so, ss[0] ? "\tSS:" : "", ss);
            if (h->n_lines == h->m_lines) { h->m_lines = h->m_lines ? h->m_lines * 2 : 32; h->lines = realloc(h->lines, h->m_lines * sizeof(char*)); }
            memmove(h->lines + 1, h->lines, h->n_lines * sizeof(char*));
            h->lines[0] = strdup(line); h->n_lines++; h->dirty = 1;
        }
        if (!no_pg) {
            char *arg_list = stringify_argv(argc + 1, argv - 1);
            sam_hdr_add_pg(h, "samtools", samtools_version(), arg_list, NULL);
            free(arg_list);
        }
    }

    const char *fo = fnout ? fnout : "-";
    char mode[8] = "w";
    if (ga.out_fmt == 0 && !fnout) ga.out_fmt = FMT_BAM;
    samfile_t *out = sam_open_output(fo, mode, &ga, 0);
    if (!out) {
        log_error("hts_open_format", "Failed to open file \"%s\" : %s", fo, strerror(errno));
        print_error_errno("sort", "failed to create \"%s\"", fo);
        for (size_t i = 0; i < n; i++) bam_destroy1(recs[i]); free(recs); sam_close(in); return 1;
    }
    if (ga.out_fmt == 0 && out->fmt == FMT_SAM && !fnout) { /* stdout default: bam handled above */ }
    if (sam_write_hdr(out, h) < 0) { print_error_errno("sort", "failed to write header to \"%s\"", fo); ret = 1; }
    hts_idx_t *idx = NULL;
    if (ga.write_index && out->fmt == FMT_BAM && !ret) {
        idx = hts_idx_init(h->n_targets, HTS_FMT_BAI, bgzf_tell(out->bg), 14, 5);
    }
    for (size_t i = 0; i < n && !ret; i++) {
        if (sam_write1(out, h, recs[i]) < 0) { print_error_errno("sort", "failed writing to \"%s\"", fo); ret = 1; break; }
        if (idx) hts_idx_push(idx, recs[i]->core.tid, recs[i]->core.pos, bam_endpos(recs[i]), bgzf_tell(out->bg), !(recs[i]->core.flag & BAM_FUNMAP));
    }
    if (idx) {
        if (!ret) { bgzf_flush(out->bg); hts_idx_finish(idx, bgzf_tell(out->bg)); char *fni = malloc(strlen(fo) + 5); sprintf(fni, "%s.bai", fo); hts_idx_save_as(idx, fo, fni, HTS_FMT_BAI); free(fni); }
        hts_idx_destroy(idx);
    }
    if (sam_close(out) < 0 && !ret) { print_error_errno("sort", "error closing output file \"%s\"", fo); ret = 1; }
    for (size_t i = 0; i < n; i++) bam_destroy1(recs[i]);
    free(recs);
    sam_close(in);
    sam_global_args_free(&ga);
    return ret;
}
EOF
sed -i '/STUB(bam_sort, "sort")/d' src/stubs.c && make -j8 build/samtools 2>&1 | grep -E "error|warning"; cd /tmp/w; C=./cmp.sh; $C sort /tmp/w/toy.sam; $C sort -n /tmp/w/srt2.sam; $C sort -N /tmp/w/srt2.sam; $C sort /tmp/w/srt.sam; $C sort -t XF /tmp/w/srt2.sam; $C sort -t XS /tmp/w/srt3.sam; $C sort -t XF -n /tmp/w/srt2.sam; $C sort /tmp/w/hd.sam; $C sort -n /tmp/w/hd.sam; $C sort /tmp/w/hd2.sam; $C sort -O sam /tmp/w/ex1.bam; $C sort -n -O sam /tmp/w/ex1.bam; $C sort -l 0 /tmp/w/ex1.bam; $C sort -l 9 /tmp/w/ex1.sam.gz; $C sort nonexist.bam; $C sort /tmp/w/toy.sam extra; $C sort -m 1K /tmp/w/toy.sam; $C sort -o /nonexist/x.bam /tmp/w/toy.sam; $C sort --template-coordinate /tmp/w/toy.sam; $C sort -M /tmp/w/toy.sam"}

actions.command:
cd /workspace && cat > src/sort.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <errno.h>
#include <ctype.h>
#include <unistd.h>
#include "samtools.h"
#include "log.h"
#include "index.h"

enum { ORD_COORD = 0, ORD_QNAME, ORD_QNAME_ASCII, ORD_TAG_COORD, ORD_TAG_QNAME, ORD_TAG_QNAME_ASCII, ORD_TEMPLATE, ORD_MINHASH };

int strnum_cmp(const char *_a, const char *_b) {
    const unsigned char *a = (const unsigned char*)_a, *b = (const unsigned char*)_b;
    while (*a && *b) {
        if (isdigit(*a) && isdigit(*b)) {
            const unsigned char *pa = a, *pb = b;
            while (*pa == '0') pa++;
            while (*pb == '0') pb++;
            int la = 0, lb = 0;
            while (isdigit(pa[la])) la++;
            while (isdigit(pb[lb])) lb++;
            if (la != lb) return la < lb ? -1 : 1;
            for (int i = 0; i < la; i++) if (pa[i] != pb[i]) return (int)pa[i] - (int)pb[i];
            a = pa + la; b = pb + lb;
        } else {
            if (*a != *b) return (int)*a - (int)*b;
            a++; b++;
        }
    }
    return *a ? 1 : *b ? -1 : 0;
}

static int g_order = ORD_COORD;
static char g_tag[2];

static inline uint64_t pos_key(const bam1_t *b) {
    uint64_t tid = b->core.tid < 0 ? 0xffffffffu : (uint32_t)b->core.tid;
    return (tid << 32) | ((uint64_t)(uint32_t)(b->core.pos + 1) << 1) | (bam_is_rev(b) ? 1 : 0);
}

static int cmp_core(const bam1_t *a, const bam1_t *b, int order) {
    if (order == ORD_QNAME || order == ORD_QNAME_ASCII) {
        int t = order == ORD_QNAME ? strnum_cmp(bam_get_qname(a), bam_get_qname(b)) : strcmp(bam_get_qname(a), bam_get_qname(b));
        if (t) return t;
        int fa = a->core.flag & 0xc0, fb = b->core.flag & 0xc0;
        if (fa != fb) return fa < fb ? -1 : 1;
        return 0;
    }
    uint64_t pa = pos_key(a), pb = pos_key(b);
    if (pa != pb) return pa < pb ? -1 : 1;
    return 0;
}

static int cmp_tag(const bam1_t *a, const bam1_t *b) {
    uint8_t *ta = bam_aux_get(a, g_tag), *tb = bam_aux_get(b, g_tag);
    if (!ta && tb) return -1;
    if (ta && !tb) return 1;
    if (ta && tb) {
        int sa = (*ta == 'Z' || *ta == 'H'), sb = (*tb == 'Z' || *tb == 'H');
        if (sa && sb) { int t = strcmp((char*)ta + 1, (char*)tb + 1); if (t) return t; }
        else if (sa) return -1;
        else if (sb) return 1;
        else if (*ta == 'A' && *tb == 'A') { if (ta[1] != tb[1]) return ta[1] < tb[1] ? -1 : 1; }
        else {
            double va = (*ta == 'f' || *ta == 'd') ? bam_aux2f(ta) : (*ta == 'A' ? ta[1] : (double)bam_aux2i(ta));
            double vb = (*tb == 'f' || *tb == 'd') ? bam_aux2f(tb) : (*tb == 'A' ? tb[1] : (double)bam_aux2i(tb));
            if (va != vb) return va < vb ? -1 : 1;
        }
    }
    int o = g_order == ORD_TAG_COORD ? ORD_COORD : g_order == ORD_TAG_QNAME ? ORD_QNAME : ORD_QNAME_ASCII;
    return cmp_core(a, b, o);
}

/* template coordinate */
static int64_t unclipped_start(const bam1_t *b) {
    int64_t p = b->core.pos; uint32_t *c = bam_get_cigar(b);
    for (uint32_t i = 0; i < b->core.n_cigar; i++) { int op = bam_cigar_op(c[i]); if (op == BAM_CSOFT_CLIP || op == BAM_CHARD_CLIP) p -= bam_cigar_oplen(c[i]); else break; }
    return p;
}
static int64_t unclipped_end(const bam1_t *b) {
    int64_t p = bam_endpos(b); uint32_t *c = bam_get_cigar(b);
    for (int i = (int)b->core.n_cigar - 1; i >= 0; i--) { int op = bam_cigar_op(c[i]); if (op == BAM_CSOFT_CLIP || op == BAM_CHARD_CLIP) p += bam_cigar_oplen(c[i]); else break; }
    return p;
}
static int64_t unclipped_other_start(int64_t mpos, const char *cig) {
    int64_t p = mpos;
    while (*cig) { char *e; long n = strtol(cig, &e, 10); if (e == cig) break; if (*e == 'S' || *e == 'H') p -= n; else break; cig = e + 1; }
    return p;
}
static int64_t unclipped_other_end(int64_t mpos, const char *cig) {
    int64_t p = mpos; const char *q = cig; int64_t rlen = 0, trail = 0;
    /* compute reference length and trailing clips */
    while (*q) { char *e; long n = strtol(q, &e, 10); if (e == q) break; char op = *e; if (op == 'M' || op == 'D' || op == 'N' || op == '=' || op == 'X') rlen += n; q = e + 1; }
    /* trailing clips */
    q = cig; const char *last = NULL; (void)last;
    /* parse into array */
    int n_ops = 0; long lens[1024]; char ops[1024];
    q = cig;
    while (*q && n_ops < 1024) { char *e; long n = strtol(q, &e, 10); if (e == q) break; lens[n_ops] = n; ops[n_ops] = *e; n_ops++; q = e + 1; }
    for (int i = n_ops - 1; i >= 0; i--) { if (ops[i] == 'S' || ops[i] == 'H') trail += lens[i]; else break; }
    return p + rlen + trail;
}

typedef struct { int64_t tid1, pos1, tid2, pos2; int neg1, neg2; int is_upper; char *lib; char *mi; } tc_key_t;

static sam_hdr_t *g_hdr;

static void tc_key(const bam1_t *b, tc_key_t *k) {
    memset(k, 0, sizeof *k);
    int rev = bam_is_rev(b);
    int64_t s = rev ? unclipped_end(b) : unclipped_start(b);
    k->tid1 = b->core.tid < 0 ? INT32_MAX : b->core.tid; k->pos1 = s; k->neg1 = rev;
    if ((b->core.flag & BAM_FPAIRED) && !(b->core.flag & BAM_FMUNMAP)) {
        uint8_t *mc = bam_aux_get(b, "MC");
        const char *cig = mc ? (char*)mc + 1 : "";
        int mrev = bam_is_mrev(b);
        int64_t ms = mrev ? unclipped_other_end(b->core.mpos, cig) : unclipped_other_start(b->core.mpos, cig);
        k->tid2 = b->core.mtid < 0 ? INT32_MAX : b->core.mtid; k->pos2 = ms; k->neg2 = mrev;
        /* order so that 1 is the lower */
        if (k->tid2 < k->tid1 || (k->tid2 == k->tid1 && (k->pos2 < k->pos1 || (k->pos2 == k->pos1 && k->neg2 < k->neg1)))) {
            int64_t t; int n;
            t = k->tid1; k->tid1 = k->tid2; k->tid2 = t; t = k->pos1; k->pos1 = k->pos2; k->pos2 = t; n = k->neg1; k->neg1 = k->neg2; k->neg2 = n;
            k->is_upper = 1;
        }
    } else { k->tid2 = INT32_MAX; k->pos2 = INT64_MAX; k->neg2 = 0; }
    uint8_t *rg = bam_aux_get(b, "RG");
    if (rg) { char *lb = sam_hdr_find_tag_id(g_hdr, "RG", "ID", (char*)rg + 1, "LB"); k->lib = lb; }
    uint8_t *mi = bam_aux_get(b, "MI");
    if (mi && *mi == 'Z') k->mi = strdup((char*)mi + 1);
}

static int cmp_template(const bam1_t *a, const bam1_t *b) {
    tc_key_t ka, kb; tc_key(a, &ka); tc_key(b, &kb);
    int r = 0;
    if (ka.tid1 != kb.tid1) r = ka.tid1 < kb.tid1 ? -1 : 1;
    else if (ka.pos1 != kb.pos1) r = ka.pos1 < kb.pos1 ? -1 : 1;
    else if (ka.neg1 != kb.neg1) r = ka.neg1 < kb.neg1 ? -1 : 1;
    else if (ka.tid2 != kb.tid2) r = ka.tid2 < kb.tid2 ? -1 : 1;
    else if (ka.pos2 != kb.pos2) r = ka.pos2 < kb.pos2 ? -1 : 1;
    else if (ka.neg2 != kb.neg2) r = ka.neg2 < kb.neg2 ? -1 : 1;
    else {
        const char *la = ka.lib ? ka.lib : "", *lb = kb.lib ? kb.lib : "";
        int t = strcmp(la, lb);
        if (t) r = t;
        else {
            const char *ma = ka.mi ? ka.mi : "", *mb = kb.mi ? kb.mi : "";
            t = strcmp(ma, mb);
            if (t) r = t;
            else {
                t = strcmp(bam_get_qname(a), bam_get_qname(b));
                if (t) r = t;
                else if (ka.is_upper != kb.is_upper) r = ka.is_upper < kb.is_upper ? -1 : 1;
            }
        }
    }
    free(ka.lib); free(ka.mi); free(kb.lib); free(kb.mi);
    return r;
}

static int cmp_records(const void *pa, const void *pb) {
    const bam1_t *a = *(bam1_t* const*)pa, *b = *(bam1_t* const*)pb;
    int r;
    switch (g_order) {
    case ORD_TAG_COORD: case ORD_TAG_QNAME: case ORD_TAG_QNAME_ASCII: r = cmp_tag(a, b); break;
    case ORD_TEMPLATE: r = cmp_template(a, b); break;
    case ORD_QNAME: case ORD_QNAME_ASCII: r = cmp_core(a, b, g_order); break;
    default: r = cmp_core(a, b, ORD_COORD); break;
    }
    if (r) return r;
    return a->id < b->id ? -1 : a->id > b->id ? 1 : 0;
}

static void sort_usage(FILE *fp) {
    fprintf(fp,
"Usage: samtools sort [options...] [in.bam]\n"
"Options:\n"
"  -l INT     Set compression level, from 0 (uncompressed) to 9 (best)\n"
"  -u         Output uncompressed data (equivalent to -l 0)\n"
"  -m INT     Set maximum memory per thread; suffix K/M/G recognized [768M]\n"
"  -M         Use minimiser for clustering unaligned/unplaced reads\n"
"  -R         Do not use reverse strand (only compatible with -M)\n"
"  -K INT     Kmer size to use for minimiser [20]\n"
"  -I FILE    Order minimisers by their position in FILE FASTA\n"
"  -w INT     Window size for minimiser indexing via -I ref.fa [100]\n"
"  -H         Squash homopolymers when computing minimiser\n"
"  -n         Sort by read name (natural): cannot be used with samtools index\n"
"  -N         Sort by read name (ASCII): cannot be used with samtools index\n"
"  -t TAG     Sort by value of TAG. Uses position as secondary index (or read name if -n is set)\n"
"  -o FILE    Write final output to FILE rather than standard output\n"
"  -T PREFIX  Write temporary files to PREFIX.nnnn.bam\n"
"      --no-PG\n"
"               Do not add a PG line\n"
"      --template-coordinate\n"
"               Sort by template-coordinate\n");
    sam_global_opt_help(fp, ".-O-.@--");
}

int bam_sort(int argc, char **argv) {
    int c, ret = 0, by_qname = 0, ascii = 0, by_tag = 0, template = 0, minhash = 0, no_pg = 0, level = -1;
    char *fnout = NULL, *tmpprefix = NULL; const char *tag = NULL;
    size_t max_mem = 768 << 20;
    sam_global_args ga = SAM_GLOBAL_ARGS_INIT;
    static const struct option lopts[] = {
        { "no-PG", no_argument, NULL, 1 }, { "template-coordinate", no_argument, NULL, 2 },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "output-fmt", required_argument, NULL, 1003 }, { "output-fmt-option", required_argument, NULL, 1004 },
        { "reference", required_argument, NULL, 1005 }, { "threads", required_argument, NULL, '@' }, { "write-index", no_argument, NULL, 1007 }, { "verbosity", required_argument, NULL, 1008 },
        { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "l:m:no:O:T:@:t:MNuK:I:w:HR", lopts, NULL)) >= 0) {
        switch (c) {
        case 'o': fnout = optarg; break;
        case 'n': by_qname = 1; ascii = 0; break;
        case 'N': by_qname = 1; ascii = 1; break;
        case 't': by_tag = 1; tag = optarg; break;
        case 'M': minhash = 1; break;
        case 'K': case 'I': case 'w': case 'H': case 'R': break;
        case 'm': {
            char *q; double m = strtod(optarg, &q);
            if (*q == 'k' || *q == 'K') m *= 1024; else if (*q == 'm' || *q == 'M') m *= 1024 * 1024; else if (*q == 'g' || *q == 'G') m *= 1024 * 1024 * 1024;
            max_mem = (size_t)m;
            break;
        }
        case 'T': tmpprefix = optarg; break;
        case 'u': level = 0; break;
        case 'l': level = atoi(optarg); break;
        case '@': ga.nthreads = atoi(optarg); break;
        case 1: no_pg = 1; break;
        case 2: template = 1; break;
        case 1003: case 1004: case 1005: case 1008: case 1002: {
            int r = parse_sam_global_opt(c, optarg, NULL, &ga);
            if (r < 0) { sort_usage(stderr); return 1; }
            break;
        }
        case 1007: ga.write_index = 1; break;
        default:
            if (optopt) fprintf(stderr, "sort: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "sort: unrecognized option '%s'\n", argv[optind-1]);
            sort_usage(stderr); return 1;
        }
    }
    if (argc - optind > 1) { fprintf(stderr, "[bam_sort] Use -T PREFIX / -o FILE to specify temporary and final output files\n"); sort_usage(stderr); return 1; }
    if (max_mem < (1 << 20)) {
        fprintf(stderr, "[bam_sort] -m setting (%zu bytes) is less than the minimum required (1M).\n\n"
"Trying to run with -m too small can lead to the creation of a very large number\n"
"of temporary files.  This may make sort fail due to it exceeding limits on the\n"
"number of files it can have open at the same time.\n\n"
"Please check your -m parameter.  It should be an integer followed by one of the\n"
"letters K (for kilobytes), M (megabytes) or G (gigabytes).  You should ensure it\n"
"is at least the minimum above, and much higher if you are sorting a large file.\n", max_mem);
        return 1;
    }
    if (by_tag) { if (strlen(tag) != 2) { print_error("sort", "tag name must be 2 characters"); return 1; } g_tag[0] = tag[0]; g_tag[1] = tag[1]; }
    if (template) g_order = ORD_TEMPLATE;
    else if (by_tag) g_order = by_qname ? (ascii ? ORD_TAG_QNAME_ASCII : ORD_TAG_QNAME) : ORD_TAG_COORD;
    else if (by_qname) g_order = ascii ? ORD_QNAME_ASCII : ORD_QNAME;
    else g_order = ORD_COORD;
    if (level >= 0 && ga.out_level < 0) ga.out_level = level;
    (void)tmpprefix; (void)minhash;

    const char *fn = optind < argc ? argv[optind] : "-";
    samfile_t *in = sam_open_read_nohdr(fn);
    if (!in) {
        log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn, strerror(errno));
        print_error_errno("sort", "can't open \"%s\"", fn); return 1;
    }
    if (in->fmt == FMT_CRAM) { print_error("sort", "CRAM not supported"); sam_close(in); return 1; }
    if (sam_read_header(in) < 0) { print_error("sort", "failed to read header from \"%s\"", fn); sam_close(in); return 1; }
    sam_hdr_t *h = in->hdr; g_hdr = h;

    /* read all */
    size_t n = 0, m = 0; bam1_t **recs = NULL;
    bam1_t *b = bam_init1(); int r;
    while ((r = sam_read1(in, h, b)) >= 0) {
        if (template && (b->core.flag & BAM_FPAIRED) && !(b->core.flag & BAM_FMUNMAP) && !bam_aux_get(b, "MC") && !(b->core.flag & BAM_FUNMAP)) {
            fprintf(stderr, "[bam_sort] error: no MC tag. Please run samtools fixmate on file first.\n");
            ret = 1; break;
        }
        if (n == m) { m = m ? m * 2 : 1024; recs = realloc(recs, m * sizeof(bam1_t*)); }
        recs[n] = bam_dup1(b); recs[n]->id = n; n++;
    }
    bam_destroy1(b);
    if (r < -1) { print_error("sort", "truncated file. Aborting"); ret = 1; }
    if (ret) { for (size_t i = 0; i < n; i++) bam_destroy1(recs[i]); free(recs); sam_close(in); return ret; }

    qsort(recs, n, sizeof(bam1_t*), cmp_records);

    /* header updates */
    {
        const char *so = "coordinate"; char ss[64] = "";
        if (template) { so = "unsorted"; strcpy(ss, "unsorted:template-coordinate"); }
        else if (by_tag) { so = "unsorted"; snprintf(ss, sizeof ss, "unsorted:%s:%s", tag, by_qname ? (ascii ? "queryname:lexicographical" : "queryname:natural") : "coordinate"); }
        else if (by_qname) { so = "queryname"; strcpy(ss, ascii ? "queryname:lexicographical" : "queryname:natural"); }
        else if (minhash) { strcpy(ss, "coordinate:minhash"); }
        int hd = sam_hdr_find_line_id(h, "HD", NULL, NULL);
        if (hd >= 0) {
            sam_hdr_update_line_idx(h, hd, "GO", NULL);
            sam_hdr_update_line_idx(h, hd, "SS", NULL);
            sam_hdr_update_line_idx(h, hd, "SO", so);
            if (ss[0]) sam_hdr_update_line_idx(h, hd, "SS", ss);
        } else {
            char line[256]; snprintf(line, sizeof line, "@HD\tVN:1.6\tSO:%s%s%s", so, ss[0] ? "\tSS:" : "", ss);
            if (h->n_lines == h->m_lines) { h->m_lines = h->m_lines ? h->m_lines * 2 : 32; h->lines = realloc(h->lines, h->m_lines * sizeof(char*)); }
            memmove(h->lines + 1, h->lines, h->n_lines * sizeof(char*));
            h->lines[0] = strdup(line); h->n_lines++; h->dirty = 1;
        }
        if (!no_pg) {
            char *arg_list = stringify_argv(argc + 1, argv - 1);
            sam_hdr_add_pg(h, "samtools", samtools_version(), arg_list, NULL);
            free(arg_list);
        }
    }

    const char *fo = fnout ? fnout : "-";
    char mode[8] = "w";
    if (ga.out_fmt == 0 && !fnout) ga.out_fmt = FMT_BAM;
    samfile_t *out = sam_open_output(fo, mode, &ga, 0);
    if (!out) {
        log_error("hts_open_format", "Failed to open file \"%s\" : %s", fo, strerror(errno));
        print_error_errno("sort", "failed to create \"%s\"", fo);
        for (size_t i = 0; i < n; i++) bam_destroy1(recs[i]); free(recs); sam_close(in); return 1;
    }
    if (ga.out_fmt == 0 && out->fmt == FMT_SAM && !fnout) { /* stdout default: bam handled above */ }
    if (sam_write_hdr(out, h) < 0) { print_error_errno("sort", "failed to write header to \"%s\"", fo); ret = 1; }
    hts_idx_t *idx = NULL;
    if (ga.write_index && out->fmt == FMT_BAM && !ret) {
        idx = hts_idx_init(h->n_targets, HTS_FMT_BAI, bgzf_tell(out->bg), 14, 5);
    }
    for (size_t i = 0; i < n && !ret; i++) {
        if (sam_write1(out, h, recs[i]) < 0) { print_error_errno("sort", "failed writing to \"%s\"", fo); ret = 1; break; }
        if (idx) hts_idx_push(idx, recs[i]->core.tid, recs[i]->core.pos, bam_endpos(recs[i]), bgzf_tell(out->bg), !(recs[i]->core.flag & BAM_FUNMAP));
    }
    if (idx) {
        if (!ret) { bgzf_flush(out->bg); hts_idx_finish(idx, bgzf_tell(out->bg)); char *fni = malloc(strlen(fo) + 5); sprintf(fni, "%s.bai", fo); hts_idx_save_as(idx, fo, fni, HTS_FMT_BAI); free(fni); }
        hts_idx_destroy(idx);
    }
    if (sam_close(out) < 0 && !ret) { print_error_errno("sort", "error closing output file \"%s\"", fo); ret = 1; }
    for (size_t i = 0; i < n; i++) bam_destroy1(recs[i]);
    free(recs);
    sam_close(in);
    sam_global_args_free(&ga);
    return ret;
}
EOF
