cat >> src/bgzf.c <<'EOF'

/* ---- gzi ---- */
int bgzf_build_gzi(bgzf_t *fp, bgzf_gzi_t *gzi) {
    gzi->n = gzi->m = 0; gzi->a = NULL;
    if (!fp->is_compressed || fp->is_gzip) return -1;
    if (lseek(fp->fd, 0, SEEK_SET) < 0) return -1;
    fp->rpos = 0; fp->rbuf_len = fp->rbuf_off = 0; fp->ublock_len = fp->ublock_off = 0; fp->block_address = 0; fp->eof_seen = 0;
    int64_t uaddr = 0;
    for (;;) {
        int64_t caddr = raw_offset(fp);
        int r = read_block_bgzf(fp);
        if (r < 0) return -1;
        if (r == 1 && fp->ublock_len == 0 && raw_offset(fp) == caddr) break; /* true EOF */
        if (gzi->n == gzi->m) { gzi->m = gzi->m ? gzi->m * 2 : 64; gzi->a = realloc(gzi->a, gzi->m * sizeof(bgzf_idx_pair_t)); }
        gzi->a[gzi->n].caddr = caddr; gzi->a[gzi->n].uaddr = uaddr; gzi->n++;
        uaddr += fp->ublock_len;
        fp->ublock_off = fp->ublock_len;
        if (r == 1) { /* empty block: EOF marker or embedded; continue if more data */
            uint8_t tmp[1]; if (raw_peek(fp, 1) <= 0) break;
            (void)tmp;
        }
    }
    /* reset */
    lseek(fp->fd, 0, SEEK_SET);
    fp->rpos = 0; fp->rbuf_len = fp->rbuf_off = 0; fp->ublock_len = fp->ublock_off = 0; fp->block_address = 0; fp->eof_seen = 0;
    return 0;
}

int bgzf_gzi_save(const bgzf_gzi_t *gzi, const char *fn) {
    int fd = open(fn, O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (fd < 0) return -1;
    /* skip trailing empty (EOF) block entries */
    int n = gzi->n;
    uint64_t cnt = n > 0 ? n - 1 : 0;
    write(fd, &cnt, 8);
    for (int i = 1; i < n; i++) { uint64_t c = gzi->a[i].caddr, u = gzi->a[i].uaddr; write(fd, &c, 8); write(fd, &u, 8); }
    close(fd);
    return 0;
}

int bgzf_gzi_load(bgzf_gzi_t *gzi, const char *fn) {
    int fd = open(fn, O_RDONLY);
    if (fd < 0) return -1;
    uint64_t cnt;
    if (read(fd, &cnt, 8) != 8) { close(fd); return -1; }
    gzi->n = 0; gzi->m = (int)cnt + 1; gzi->a = malloc(gzi->m * sizeof(bgzf_idx_pair_t));
    gzi->a[0].caddr = 0; gzi->a[0].uaddr = 0; gzi->n = 1;
    for (uint64_t i = 0; i < cnt; i++) {
        uint64_t c, u;
        if (read(fd, &c, 8) != 8 || read(fd, &u, 8) != 8) { close(fd); return -1; }
        gzi->a[gzi->n].caddr = c; gzi->a[gzi->n].uaddr = u; gzi->n++;
    }
    close(fd);
    return 0;
}

int bgzf_useek(bgzf_t *fp, const bgzf_gzi_t *gzi, int64_t uoffset) {
    if (!fp->is_compressed) return bgzf_seek(fp, uoffset);
    if (fp->is_gzip || !gzi || gzi->n == 0) return -1;
    /* binary search */
    int lo = 0, hi = gzi->n - 1;
    while (lo < hi) { int mid = (lo + hi + 1) / 2; if (gzi->a[mid].uaddr <= uoffset) lo = mid; else hi = mid - 1; }
    if (bgzf_seek(fp, gzi->a[lo].caddr << 16) < 0) return -1;
    int64_t skip = uoffset - gzi->a[lo].uaddr;
    while (skip > 0) {
        if (fp->ublock_off >= fp->ublock_len) { int r = read_block(fp); if (r != 0) return -1; }
        int avail = fp->ublock_len - fp->ublock_off;
        int take = skip < avail ? (int)skip : avail;
        fp->ublock_off += take; skip -= take;
    }
    return 0;
}

int64_t bgzf_utell(bgzf_t *fp, const bgzf_gzi_t *gzi) {
    if (!fp->is_compressed) return fp->block_address + fp->ublock_off;
    if (!gzi) return -1;
    for (int i = 0; i < gzi->n; i++) if (gzi->a[i].caddr == fp->block_address) return gzi->a[i].uaddr + fp->ublock_off;
    return -1;
}
