#include "faidx.h"
#include "strmap.h"
#include "log.h"
#include "index.h"
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>

static faidx_t *fai_new(void) { faidx_t *f = calloc(1, sizeof *f); f->map = strmap_new(); return f; }

void fai_destroy(faidx_t *fai) {
    if (!fai) return;
    for (int i = 0; i < fai->n; i++) free(fai->a[i].name);
    free(fai->a); strmap_free((strmap_t*)fai->map);
    if (fai->bg) bgzf_close(fai->bg);
    free(fai->gzi.a); free(fai->fn); free(fai);
