static int fai_insert_index(faidx_t *fai, const char *name, uint64_t len, uint32_t line_len, uint32_t line_blen, uint64_t seq_offset, uint64_t qual_offset) {
    int is_new; strmap_entry_t *e = strmap_put((strmap_t*)fai->map, name, &is_new);
    if (!is_new) {
        log_warning("fai_insert_index", "Ignoring duplicate sequence \"%s\" at byte offset %llu", name, (unsigned long long)seq_offset);
        return 0;
    }
    if (fai->n == fai->m) { fai->m = fai->m ? fai->m * 2 : 16; fai->a = realloc(fai->a, fai->m * sizeof(faidx1_t)); }
    faidx1_t *x = &fai->a[fai->n];
    x->name = strdup(name); x->len = len; x->line_len = line_len; x->line_blen = line_blen; x->seq_offset = seq_offset; x->qual_offset = qual_offset;
    e->val = fai->n++;
    return 0;
}

/* build core: reads through bg */
static faidx_t *fai_build_from_bgzf(bgzf_t *bg, int format, const char *fn) {
    faidx_t *fai = fai_new();
    fai->is_fastq = (format == FAI_FASTQ);
    kstring_t name = KS_INITIALIZE;
    int c, lineno = 1;
    int64_t offset = 0; /* uncompressed offset of next char */
    enum { S_HDR = 0, S_SEQ, S_QUAL_PLUS, S_QUAL } state = S_HDR;
    int first = 1;
    uint64_t len = 0, seq_offset = 0, qual_offset = 0, qual_len = 0;
    uint32_t line_len = 0, line_blen = 0;
    int short_line_seen = 0;
    int c_prev = -1;
    int read_fmt = -1; /* detected from first char */
    #define GETC() (c = bgzf_getc(bg), (c >= 0 ? (offset++, c) : c))
    for (;;) {
        GETC();
        if (c < 0) break;
        if (first) {
            first = 0;
            if (c == '>') read_fmt = FAI_FASTA; else if (c == '@') read_fmt = FAI_FASTQ;
            else { log_error("fai_build_core", "Format error, unexpected \"%c\" at line %d", c, lineno); goto fail; }
            if (format == FAI_FASTQ && read_fmt == FAI_FASTA) { /* still proceed: treated as fasta */ }
        }
        if (c == '\n') { lineno++; continue; }
        if (c == '>' || (c == '@' && read_fmt == FAI_FASTQ && state == S_HDR)) {
            if (state != S_HDR) {
                /* unexpected header during seq? in FASTQ, seq may legitimately start with '@'? no: in FASTQ state SEQ, '@' handled as seq char */
            }
            if (name.l || len) { }
            /* record previous */
            if (name.s && name.l) {
                /* handled at end of sequence below */
            }
            /* read name */
            name.l = 0;
            for (;;) { GETC(); if (c < 0 || c == '\n' || isspace(c)) break; kputc(c, &name); }
            if (!name.s) kputsn("", 0, &name);
            while (c >= 0 && c != '\n') { GETC(); }
            if (c == '\n') lineno++;
            seq_offset = offset; len = 0; line_len = line_blen = 0; short_line_seen = 0; qual_len = 0; qual_offset = 0;
            state = S_SEQ;
            /* read sequence lines */
            for (;;) {
                /* peek first char of line */
                uint8_t pc; int n = bgzf_peek(bg, &pc, 1);
                if (n <= 0) { c = -1; break; }
                if (pc == '>' && read_fmt == FAI_FASTA) break;
                if (pc == '+' && read_fmt == FAI_FASTQ) break;
                if (pc == '@' && read_fmt == FAI_FASTQ && len > 0 && 0) break;
                /* read line */
                uint32_t ll = 0, lb = 0;
                for (;;) { GETC(); if (c < 0) break; lb++; if (c == '\n') break; if (isgraph(c)) ll++; }
                if (c < 0 && lb == 0) break;
                if (ll == 0 && (c == '\n' || c < 0)) {
                    /* empty line: ends the sequence */
                    if (c == '\n') lineno++;
                    if (read_fmt == FAI_FASTQ) { /* in fastq an empty line would be odd; treat as end */ }
                    break;
                }
                if (short_line_seen) {
                    log_error("fai_build_core", "Format error, unexpected \"%c\" at line %d", bg->ubuf[bg->ublock_off - lb >= 0 ? bg->ublock_off - lb : 0], lineno);
                    goto fail;
                }
                if (line_len == 0) { line_len = lb; line_blen = ll; }
                else if (ll != line_blen || lb != line_len) {
                    if (ll > line_blen || (ll == line_blen && lb != line_len)) {
                        log_error("fai_build_core", "Different line length in sequence '%s' at line %d", name.s, lineno);
                        goto fail;
                    }
                    short_line_seen = 1;
                }
                len += ll;
                if (c == '\n') lineno++;
                if (c < 0) break;
            }
            if (read_fmt == FAI_FASTQ) {
                uint8_t pc; int n = bgzf_peek(bg, &pc, 1);
                if (n > 0 && pc == '+') {
                    /* skip + line */
                    for (;;) { GETC(); if (c < 0 || c == '\n') break; }
                    if (c == '\n') lineno++;
                    qual_offset = offset;
                    /* read qual: same number of bases */
                    while (qual_len < len) {
                        GETC(); if (c < 0) break;
                        if (c == '\n') { lineno++; continue; }
                        if (isgraph(c)) qual_len++;
                    }
                    /* consume rest of line */
                    if (c >= 0 && c != '\n') { for (;;) { GETC(); if (c < 0 || c == '\n') break; } if (c == '\n') lineno++; }
                    if (qual_len < len) { log_error("fai_build_core", "Quality string length too short for sequence '%s' at line %d", name.s, lineno); goto fail; }
                } else if (n > 0) {
                    log_error("fai_build_core", "Format error, unexpected \"%c\" at line %d", pc, lineno);
                    goto fail;
                } else {
                    log_error("fai_build_core", "File truncated at line %d", lineno); goto fail;
                }
            }
            fai_insert_index(fai, name.s ? name.s : "", len, line_len, line_blen, seq_offset, qual_offset);
            state = S_HDR;
            if (c < 0) break;
            continue;
        }
        if (state == S_HDR) {
            log_error("fai_build_core", "Format error, unexpected \"%c\" at line %d", c, lineno);
            goto fail;
        }
    }
    (void)c_prev;
    if (fai->n == 0 && first) { log_error("fai_build_core", "File truncated at line %d", lineno); goto fail; }
    free(name.s);
    return fai;
fail:
    free(name.s);
    fai_destroy(fai);
    return NULL;
}

faidx_t *fai_build_core(const char *fn, int format) {
    bgzf_t *bg = bgzf_open_read(fn);
    if (!bg) { log_error("fai_build3_core", "Failed to open the file %s : %s", fn, strerror(errno)); return NULL; }
    if (bg->is_compressed && bg->is_gzip) {
        log_error("fai_build3_core", "Cannot index files compressed with gzip, please use bgzip");
        bgzf_close(bg); return NULL;
    }
    faidx_t *fai = fai_build_from_bgzf(bg, format, fn);
    if (!fai) { bgzf_close(bg); return NULL; }
    fai->fn = strdup(fn);
    if (bg->is_compressed) {
        if (bgzf_build_gzi(bg, &fai->gzi) == 0) fai->has_gzi = 1;
    }
    fai->bg = bg;
    return fai;
}

int fai_save(const faidx_t *fai, const char *fnfai) {
    FILE *fp = fopen(fnfai, "wb");
    if (!fp) return -1;
    for (int i = 0; i < fai->n; i++) {
        const faidx1_t *x = &fai->a[i];
        if (fai->is_fastq) fprintf(fp, "%s\t%llu\t%llu\t%u\t%u\t%llu\n", x->name, (unsigned long long)x->len, (unsigned long long)x->seq_offset, x->line_blen, x->line_len, (unsigned long long)x->qual_offset);
        else fprintf(fp, "%s\t%llu\t%llu\t%u\t%u\n", x->name, (unsigned long long)x->len, (unsigned long long)x->seq_offset, x->line_blen, x->line_len);
    }
    return fclose(fp) == 0 ? 0 : -1;
}

static char *default_fai(const char *fn) { char *s = malloc(strlen(fn) + 5); sprintf(s, "%s.fai", fn); return s; }
static char *default_gzi(const char *fn) { char *s = malloc(strlen(fn) + 5); sprintf(s, "%s.gzi", fn); return s; }

int fai_build3(const char *fn, const char *fnfai, const char *fngzi, int format) {
    char *dfai = fnfai ? NULL : default_fai(fn), *dgzi = fngzi ? NULL : default_gzi(fn);
    if (!fnfai) fnfai = dfai;
    if (!fngzi) fngzi = dgzi;
    faidx_t *fai = fai_build_core(fn, format);
    int ret = 0;
    if (!fai) ret = -1;
    else {
        if (fai_save(fai, fnfai) < 0) { log_error("fai_build3_core", "Failed to write FASTA index %s : %s", fnfai, strerror(errno)); ret = -1; }
        else if (fai->has_gzi) { if (bgzf_gzi_save(&fai->gzi, fngzi) < 0) { log_error("fai_build3_core", "Failed to write index %s", fngzi); ret = -1; } }
        fai_destroy(fai);
    }
    free(dfai); free(dgzi);
    return ret;
}

static int fai_read(faidx_t *fai, const char *fnfai, int format) {
    textfile_t *t = text_open(fnfai);
    if (!t) return -1;
    int lineno = 0;
    while (text_getline(t) >= 0) {
        lineno++;
        if (t->len == 0) continue;
        char *f[7] = {0}; int nf = 0; char *p = t->line;
        f[nf++] = p;
        while (nf < 7 && (p = strchr(p, '\t'))) { *p++ = 0; f[nf++] = p; }
        int need = format == FAI_FASTQ ? 6 : 5;
        if (nf < need) {
            if (format == FAI_FASTQ && nf == 5) log_error("fai_read", "Possibly this is a FASTA index, try using faidx.  Problem in %s line %d", fnfai, lineno);
            else log_error("fai_read", "Could not understand FASTA index %s line %d", fnfai, lineno);
            text_close(t); return -1;
        }
        if (format == FAI_FASTA && nf >= 6) {
            log_error("fai_read", "Possibly this is a FASTQ index, try using fqidx.  Problem in %s line %d", fnfai, lineno);
            text_close(t); return -1;
        }
        char *e;
        uint64_t len = strtoull(f[1], &e, 10);
        uint64_t off = strtoull(f[2], &e, 10);
        uint32_t blen = (uint32_t)strtoul(f[3], &e, 10);
        uint32_t llen = (uint32_t)strtoul(f[4], &e, 10);
        uint64_t qoff = nf >= 6 ? strtoull(f[5], &e, 10) : 0;
        fai_insert_index(fai, f[0], len, llen, blen, off, qoff);
    }
    text_close(t);
    fai->is_fastq = (format == FAI_FASTQ);
    return 0;
}

faidx_t *fai_load3(const char *fn, const char *fnfai, const char *fngzi, int create, int format) {
    char *dfai = fnfai ? NULL : default_fai(fn), *dgzi = fngzi ? NULL : default_gzi(fn);
    if (!fnfai) fnfai = dfai;
    if (!fngzi) fngzi = dgzi;
    struct stat st;
    faidx_t *fai = NULL;
    bgzf_t *bg = bgzf_open_read(fn);
    if (!bg) { log_error("fai_load3_core", "Failed to open FASTA file %s", fn); free(dfai); free(dgzi); return NULL; }
    int is_bgzf = bg->is_compressed && !bg->is_gzip;
    if (stat(fnfai, &st) != 0 || (is_bgzf && stat(fngzi, &st) != 0)) {
        if (!create) { log_error("fai_load3_core", "Failed to open FASTA index %s", fnfai); bgzf_close(bg); free(dfai); free(dgzi); return NULL; }
        log_info("fai_load3_core", "build FASTA index");
        if (fai_build3(fn, fnfai, fngzi, format) < 0) { bgzf_close(bg); free(dfai); free(dgzi); return NULL; }
    }
    fai = fai_new();
    fai->fn = strdup(fn);
    if (fai_read(fai, fnfai, format) < 0) {
        log_error("fai_load3_core", "Failed to read %s index %s", format == FAI_FASTQ ? "FASTQ" : "FASTA", fnfai);
        fai_destroy(fai); bgzf_close(bg); free(dfai); free(dgzi); return NULL;
    }
    if (is_bgzf) {
        if (bgzf_gzi_load(&fai->gzi, fngzi) < 0) { log_error("fai_load3_core", "Failed to load .gzi index %s", fngzi); fai_destroy(fai); bgzf_close(bg); free(dfai); free(dgzi); return NULL; }
        fai->has_gzi = 1;
    }
    fai->bg = bg;
    free(dfai); free(dgzi);
    return fai;
}

int fai_nseq(const faidx_t *fai) { return fai->n; }
const char *fai_iseq(const faidx_t *fai, int i) { return (i >= 0 && i < fai->n) ? fai->a[i].name : NULL; }
int fai_has_seq(const faidx_t *fai, const char *name) { return strmap_find((strmap_t*)fai->map, name) != NULL; }
int64_t fai_seq_len(const faidx_t *fai, const char *name) { int64_t v; if (strmap_get((strmap_t*)fai->map, name, &v) < 0) return -1; return (int64_t)fai->a[v].len; }
int fai_line_length(const faidx_t *fai, const char *name) { int64_t v; if (strmap_get((strmap_t*)fai->map, name, &v) < 0) return -1; return (int)fai->a[v].line_blen; }

static int fai_name2id(const faidx_t *fai, const char *name) { int64_t v; if (strmap_get((strmap_t*)fai->map, name, &v) < 0) return -1; return (int)v; }

/* htslib-style region parse */
int fai_parse_region(const faidx_t *fai, const char *s, int *tid, int64_t *beg, int64_t *end) {
    size_t s_len = strlen(s);
    const char *colon = NULL; int quoted = 0;
    if (*s == '{') {
        const char *close = memchr(s, '}', s_len);
        if (!close) { log_error("hts_parse_region", "Mismatching braces in \"%s\"", s); *tid = -1; return -1; }
        s++; s_len--;
        if (close[1] == ':') colon = close + 1;
        quoted = 1;
    } else {
        for (size_t i = s_len; i > 0; i--) if (s[i-1] == ':') { colon = s + i - 1; break; }
    }
    char *ks;
    if (colon == NULL) {
        *beg = 0; *end = HTS_POS_MAX;
        ks = strndup(s, s_len - quoted);
        *tid = fai_name2id(fai, ks); free(ks);
        return *tid >= 0 ? 0 : -1;
    }
    if (!quoted) {
        *beg = 0; *end = HTS_POS_MAX;
        ks = strndup(s, s_len);
        if ((*tid = fai_name2id(fai, ks)) >= 0) {
            free(ks);
            ks = strndup(s, colon - s);
            if (fai_name2id(fai, ks) >= 0) log_warning("hts_parse_region", "Range is ambiguous. Use {%s} or {%.*s}%s instead", s, (int)(colon - s), s, colon);
            free(ks);
            return 0;
        }
        free(ks);
    }
    ks = strndup(s, colon - s - quoted);
    *tid = fai_name2id(fai, ks); free(ks);
    if (*tid < 0) return -1;
    char *hyphen;
    *beg = hts_parse_decimal(colon + 1, &hyphen, 0) - 1;
    if (*beg < 0) {
        if (*beg != -1 && *hyphen == '-' && colon[1] != '\0') { log_error("hts_parse_region", "Coordinates must be > 0"); return -1; }
        if (isdigit((unsigned char)*hyphen) || *hyphen == '\0' || *hyphen == ',') {
            *end = *beg == -1 ? HTS_POS_MAX : -(*beg + 1);
            *beg = 0;
            return 0;
        } else if (*beg < -1) { log_error("hts_parse_region", "Unexpected string \"%s\" after region", hyphen); return -1; }
    }
    if (*hyphen == '\0') *end = HTS_POS_MAX;
    else if (*hyphen == '-') {
        *end = hts_parse_decimal(hyphen + 1, &hyphen, 0);
        if (*hyphen != '\0') { log_error("hts_parse_region", "Unexpected string \"%s\" after region", hyphen); return -1; }
    } else { log_error("hts_parse_region", "Unexpected string \"%s\" after region", hyphen); return -1; }
    if (*end == 0) *end = HTS_POS_MAX;
    if (*beg >= *end) return -1;
    return 0;
}

static char *fai_retrieve(const faidx_t *fai, const faidx1_t *val, uint64_t offset, int64_t beg, int64_t end, int64_t *len) {
    if (val->line_blen <= 0) { log_error("fai_retrieve", "Invalid line length in index: %u", val->line_blen); *len = -1; return NULL; }
    int64_t want = end - beg;
    if (want <= 0) { *len = 0; char *s = malloc(1); s[0] = 0; return s; }
    int64_t uoff = (int64_t)offset + beg / val->line_blen * val->line_len + beg % val->line_blen;
    if (bgzf_useek(fai->bg, fai->has_gzi ? &fai->gzi : NULL, uoff) < 0) { log_error("fai_retrieve", "Failed to retrieve block. (Seeking in a compressed, .gzi unindexed, file?)"); *len = -1; return NULL; }
    char *s = malloc(want + 2);
    int64_t l = 0;
    int64_t pos_in_line = beg % val->line_blen;
    while (l < want) {
        int64_t to_read = val->line_blen - pos_in_line;
        if (to_read > want - l) to_read = want - l;
        ssize_t r = bgzf_read(fai->bg, s + l, to_read);
        if (r < 0) { log_error("fai_retrieve", "Failed to retrieve block: %s", strerror(errno)); free(s); *len = -1; return NULL; }
        if (r == 0) break;
        l += r;
        if (r < to_read) break;
        pos_in_line += r;
        if (pos_in_line >= val->line_blen) {
            /* skip to next line */
            int64_t skip = val->line_len - val->line_blen;
            char junk[256];
            while (skip > 0) { ssize_t k = bgzf_read(fai->bg, junk, skip < (int64_t)sizeof junk ? skip : (int64_t)sizeof junk); if (k <= 0) break; skip -= k; }
            pos_in_line = 0;
        }
    }
    s[l] = 0;
    *len = l;
    return s;
}

static int fai_get_val(const faidx_t *fai, const char *str, int64_t *len, const faidx1_t **val, int64_t *fbeg, int64_t *fend) {
    int tid; int64_t beg, end;
    if (fai_parse_region(fai, str, &tid, &beg, &end) < 0) {
        log_warning("fai_get_val", "Reference %s not found in FASTA file, returning empty sequence", str);
        *len = -2; return 1;
    }
    *val = &fai->a[tid];
    uint64_t L = (*val)->len;
    if ((uint64_t)beg >= L) beg = (int64_t)L;
    if ((uint64_t)end >= L) end = (int64_t)L;
    *fbeg = beg; *fend = end;
    return 0;
}

char *fai_fetch64(const faidx_t *fai, const char *str, int64_t *len) {
    const faidx1_t *val; int64_t beg, end;
    if (fai_get_val(fai, str, len, &val, &beg, &end)) return NULL;
    return fai_retrieve(fai, val, val->seq_offset, beg, end, len);
}

char *fai_fetchqual64(const faidx_t *fai, const char *str, int64_t *len) {
    const faidx1_t *val; int64_t beg, end;
    if (fai_get_val(fai, str, len, &val, &beg, &end)) return NULL;
    return fai_retrieve(fai, val, val->qual_offset, beg, end, len);
}

char *faidx_fetch_seq64(const faidx_t *fai, const char *name, int64_t beg, int64_t end, int64_t *len) {
    int64_t v;
    if (strmap_get((strmap_t*)fai->map, name, &v) < 0) { *len = -2; return NULL; }
    const faidx1_t *val = &fai->a[v];
    if (beg < 0) beg = 0;
    if ((uint64_t)end >= val->len) end = (int64_t)val->len;
    if ((uint64_t)beg >= val->len) beg = (int64_t)val->len;
    return fai_retrieve(fai, val, val->seq_offset, beg, end, len);
}

char *faidx_fetch_qual64(const faidx_t *fai, const char *name, int64_t beg, int64_t end, int64_t *len) {
    int64_t v;
    if (strmap_get((strmap_t*)fai->map, name, &v) < 0) { *len = -2; return NULL; }
    const faidx1_t *val = &fai->a[v];
    if (beg < 0) beg = 0;
    if ((uint64_t)end >= val->len) end = (int64_t)val->len;
    if ((uint64_t)beg >= val->len) beg = (int64_t)val->len;
    return fai_retrieve(fai, val, val->qual_offset, beg, end, len);
}
EOF
echo ok"}

