static void reverse_complement(char *s, int64_t len) {
    for (int64_t i = 0, j = len - 1; i < j; i++, j--) { char t = comp_tab[(unsigned char)s[i]]; s[i] = comp_tab[(unsigned char)s[j]]; s[j] = t; }
    if (len & 1) s[len/2] = comp_tab[(unsigned char)s[len/2]];
}
static void reverse_str(char *s, int64_t len) {
    for (int64_t i = 0, j = len - 1; i < j; i++, j--) { char t = s[i]; s[i] = s[j]; s[j] = t; }
}

static void write_wrapped(FILE *fp, const char *s, int64_t len, int line_len) {
    if (line_len <= 0) { fwrite(s, 1, len, fp); fputc('\n', fp); return; }
    for (int64_t i = 0; i < len; i += line_len) {
        int64_t l = len - i < line_len ? len - i : line_len;
        fwrite(s + i, 1, l, fp); fputc('\n', fp);
    }
}

enum { MARK_RC, MARK_NO, MARK_SIGN, MARK_CUSTOM };

typedef struct { int fastq; int rc; int mark; char *pos_mark, *neg_mark; int line_len; int line_len_set; FILE *out; int cont; } faidx_opts;

static int write_output(faidx_t *fai, faidx_opts *o, const char *reg) {
    const char *suffix = "";
    if (o->mark == MARK_RC) suffix = o->rc ? "/rc" : "";
    else if (o->mark == MARK_SIGN) suffix = o->rc ? "(-)" : "(+)";
    else if (o->mark == MARK_CUSTOM) suffix = o->rc ? o->neg_mark : o->pos_mark;
    else suffix = "";
    fprintf(o->out, "%c%s%s\n", o->fastq ? '@' : '>', reg, suffix);
    int64_t len;
    char *seq = fai_fetch64(fai, reg, &len);
    if (len < 0) {
        fprintf(stderr, "[faidx] Failed to fetch sequence in %s\n", reg);
        free(seq);
        return 1;
    }
    int tid; int64_t beg, end;
    if (len == 0) fprintf(stderr, "[faidx] Zero length sequence: %s\n", reg);
    else if (fai_parse_region(fai, reg, &tid, &beg, &end) == 0 && end < HTS_POS_MAX && end - beg > len) fprintf(stderr, "[faidx] Truncated sequence: %s\n", reg);
    int ll = o->line_len;
    if (!o->line_len_set) {
        int t; int64_t b, e;
        if (fai_parse_region(fai, reg, &t, &b, &e) == 0) ll = fai_line_length(fai, fai_iseq(fai, t)); else ll = 60;
        if (ll <= 0) ll = 60;
    }
    if (o->rc) reverse_complement(seq, len);
    write_wrapped(o->out, seq, len, ll);
    free(seq);
    if (o->fastq) {
        char *qual = fai_fetchqual64(fai, reg, &len);
        if (len < 0) { fprintf(stderr, "[faidx] Failed to fetch quality in %s\n", reg); free(qual); return 1; }
        fprintf(o->out, "+\n");
        if (o->rc) reverse_str(qual, len);
        write_wrapped(o->out, qual, len, ll);
        free(qual);
    }
    return 0;
}

static void usage_fai(FILE *fp, int fastq) {
    const char *fq = fastq ? "fq" : "fa";
    fprintf(fp, "Usage: samtools %s <file.%s|file.%s.gz> [<reg> [...]]\n", fastq ? "fqidx" : "faidx", fq, fq);
    fprintf(fp, "Option: \n");
    fprintf(fp, "  -o, --output FILE        Write %s to file.\n", fastq ? "FASTQ" : "FASTA");
    fprintf(fp, "  -n, --length INT         Length of %s sequence line. [60]\n", fastq ? "FASTQ" : "FASTA");
    fprintf(fp, "  -c, --continue           Continue after trying to retrieve missing region.\n");
    fprintf(fp, "  -r, --region-file FILE   File of regions.  Format is chr:from-to. One per line.\n");
    fprintf(fp, "  -i, --reverse-complement Reverse complement sequences.\n");
    fprintf(fp, "      --mark-strand TYPE   Add strand indicator to sequence name\n");
    fprintf(fp, "                           TYPE = rc   for /rc on negative strand (default)\n");
    fprintf(fp, "                                  no   for no strand indicator\n");
    fprintf(fp, "                                  sign for (+) / (-)\n");
    fprintf(fp, "                                  custom,<pos>,<neg> for custom indicator\n");
    fprintf(fp, "      --fai-idx      FILE  name of the index file (default file.%s.fai).\n", fq);
    fprintf(fp, "      --gzi-idx      FILE  name of compressed file index (default file.%s.gz.gzi).\n", fq);
    if (!fastq) fprintf(fp, "  -f, --fastq              File and index in FASTQ format.\n");
    fprintf(fp, "  -h, --help               This message.\n");
    sam_global_opt_help(fp, "...-..@-.");
}

static int faidx_core(int argc, char **argv, int fastq) {
    faidx_opts o; memset(&o, 0, sizeof o);
    o.fastq = fastq; o.line_len = 60; o.mark = MARK_RC; o.out = stdout;
    const char *fn_out = NULL, *fn_fai = NULL, *fn_gzi = NULL, *fn_regs = NULL;
    const char *cmd = fastq ? "fqidx" : "faidx";
    int c;
    static const struct option lopts[] = {
        { "output", required_argument, NULL, 'o' }, { "length", required_argument, NULL, 'n' }, { "continue", no_argument, NULL, 'c' },
        { "region-file", required_argument, NULL, 'r' }, { "reverse-complement", no_argument, NULL, 'i' }, { "mark-strand", required_argument, NULL, 1 },
        { "fai-idx", required_argument, NULL, 2 }, { "gzi-idx", required_argument, NULL, 3 }, { "fastq", no_argument, NULL, 'f' }, { "help", no_argument, NULL, 'h' },
        { "output-fmt-option", required_argument, NULL, 1004 }, { "threads", required_argument, NULL, '@' }, { "write-index", no_argument, NULL, 1007 },
        { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, fastq ? "o:n:cr:ih@:" : "o:n:cr:ifh@:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'o': fn_out = optarg; break;
        case 'n': {
            char *e; long v = strtol(optarg, &e, 10);
            if (*e || v < 0) { fprintf(stderr, "[%s] bad line length '%s', using default:60\n", "faidx", optarg); o.line_len = 60; o.line_len_set = 1; }
            else { o.line_len = (int)v; o.line_len_set = 1; }
            break;
        }
        case 'c': o.cont = 1; break;
        case 'r': fn_regs = optarg; break;
        case 'i': o.rc = 1; break;
        case 'f': o.fastq = 1; cmd = "fqidx"; break;
        case 1:
            if (strcmp(optarg, "rc") == 0) o.mark = MARK_RC;
            else if (strcmp(optarg, "no") == 0) o.mark = MARK_NO;
            else if (strcmp(optarg, "sign") == 0) o.mark = MARK_SIGN;
            else if (strncmp(optarg, "custom,", 7) == 0) {
                o.mark = MARK_CUSTOM;
                char *dup = strdup(optarg + 7); char *comma = strchr(dup, ',');
                if (comma) { *comma = 0; o.pos_mark = strdup(dup); o.neg_mark = strdup(comma + 1); }
                else { o.pos_mark = strdup(dup); o.neg_mark = strdup(""); }
                free(dup);
            } else { fprintf(stderr, "[faidx] Bad mark-strand option '%s'\n", optarg); usage_fai(stderr, fastq); return 1; }
            break;
        case 2: fn_fai = optarg; break;
        case 3: fn_gzi = optarg; break;
        case 'h': usage_fai(stdout, fastq); return 0;
        case '@': case 1004: case 1007: break;
        default:
            if (optopt) fprintf(stderr, "%s: invalid option -- '%c'\n", cmd, optopt);
            else fprintf(stderr, "%s: unrecognized option '%s'\n", cmd, argv[optind-1]);
            usage_fai(stderr, fastq); return 1;
        }
    }
    if (argc == optind) { usage_fai(stdout, fastq); return 0; }
    const char *fn = argv[optind];
    int format = o.fastq ? FAI_FASTQ : FAI_FASTA;
    int exit_status = 0;
    if (argc - optind == 1 && !fn_regs) {
        if (fai_build3(fn, fn_fai, fn_gzi, format) != 0) {
            char *dfai = NULL; if (!fn_fai) { dfai = malloc(strlen(fn) + 5); sprintf(dfai, "%s.fai", fn); }
            fprintf(stderr, "[faidx] Could not build fai index %s\n", fn_fai ? fn_fai : dfai);
            free(dfai); free(o.pos_mark); free(o.neg_mark);
            return 1;
        }
        free(o.pos_mark); free(o.neg_mark);
        return 0;
    }
    faidx_t *fai = fai_load3(fn, fn_fai, fn_gzi, 1, format);
    if (!fai) {
        char *dfai = NULL; if (!fn_fai) { dfai = malloc(strlen(fn) + 5); sprintf(dfai, "%s.fai", fn); }
        fprintf(stderr, "[faidx] Could not load fai index %s\n", fn_fai ? fn_fai : dfai);
        free(dfai); free(o.pos_mark); free(o.neg_mark);
        return 1;
    }
    if (fn_out) {
        o.out = fopen(fn_out, "w");
        if (!o.out) { print_error_errno("faidx", "Cannot open \"%s\" for writing", fn_out); fai_destroy(fai); return 1; }
    }
    if (fn_regs) {
        textfile_t *t = text_open(fn_regs);
        if (!t) { print_error_errno("faidx", "Failed to open \"%s\"", fn_regs); fai_destroy(fai); return 1; }
        while (text_getline(t) >= 0) {
            if (write_output(fai, &o, t->line) != 0) { exit_status = 1; if (!o.cont) break; }
        }
        text_close(t);
    }
    if (exit_status == 0 || o.cont) {
        for (int i = optind + 1; i < argc; i++) {
            if (write_output(fai, &o, argv[i]) != 0) { exit_status = 1; if (!o.cont) break; }
        }
    }
    if (o.cont) exit_status = 0;
    if (fn_out) fclose(o.out);
    fai_destroy(fai);
    free(o.pos_mark); free(o.neg_mark);
    return exit_status;
}

int faidx_main(int argc, char **argv) { return faidx_core(argc, argv, 0); }
int fqidx_main(int argc, char **argv) { return faidx_core(argc, argv, 1); }
