#ifndef SAMX_KSEQ_H
#define SAMX_KSEQ_H
#include "bgzf.h"
#include "kstring.h"
/* simple FASTA/FASTQ reader over bgzf */
typedef struct { kstring_t name, comment, seq, qual; int last_char; bgzf_t *bg; int is_fastq; } kseq_t;
static inline kseq_t *kseq_init(bgzf_t *bg) { kseq_t *k = calloc(1, sizeof *k); k->bg = bg; return k; }
static inline void kseq_destroy(kseq_t *k) { if (!k) return; free(k->name.s); free(k->comment.s); free(k->seq.s); free(k->qual.s); free(k); }
/* returns seq length >=0, -1 EOF, -2 truncated quality */
static inline int kseq_read(kseq_t *k) {
    int c;
    k->name.l = k->comment.l = k->seq.l = k->qual.l = 0;
    if (k->last_char == 0) {
        while ((c = bgzf_getc(k->bg)) >= 0 && c != '>' && c != '@');
        if (c < 0) return -1;
        k->last_char = c;
    }
    k->is_fastq = (k->last_char == '@');
    /* name */
    while ((c = bgzf_getc(k->bg)) >= 0 && c != '\n' && c != ' ' && c != '\t' && c != '\r') kputc(c, &k->name);
    if (!k->name.s) kputsn("", 0, &k->name);
    if (c == ' ' || c == '\t') {
        while ((c = bgzf_getc(k->bg)) >= 0 && (c == ' ' || c == '\t'));
        if (c >= 0 && c != '\n') { kputc(c, &k->comment); while ((c = bgzf_getc(k->bg)) >= 0 && c != '\n') kputc(c, &k->comment); }
        if (k->comment.l && k->comment.s[k->comment.l-1] == '\r') k->comment.s[--k->comment.l] = 0;
    } else if (c == '\r') { while ((c = bgzf_getc(k->bg)) >= 0 && c != '\n'); }
    if (!k->comment.s) kputsn("", 0, &k->comment);
    while ((c = bgzf_getc(k->bg)) >= 0 && c != '>' && c != '+' && c != '@') {
        if (c == '\n') continue;
        kputc(c, &k->seq);
        while ((c = bgzf_getc(k->bg)) >= 0 && c != '\n') kputc(c, &k->seq);
        if (c < 0) break;
    }
    /* strip whitespace within seq */
    { size_t j = 0; for (size_t i = 0; i < k->seq.l; i++) { unsigned char ch = k->seq.s[i]; if (ch > ' ') k->seq.s[j++] = ch; } k->seq.l = j; if (k->seq.s) k->seq.s[j] = 0; }
    if (!k->seq.s) kputsn("", 0, &k->seq);
    if (c == '>' || c == '@') k->last_char = c; else k->last_char = 0;
    if (c != '+') return (int)k->seq.l;
    while ((c = bgzf_getc(k->bg)) >= 0 && c != '\n');
    if (c < 0) return -2;
    while ((c = bgzf_getc(k->bg)) >= 0 && k->qual.l < k->seq.l) { if (c >= 33 && c <= 127) kputc(c, &k->qual); }
    if (!k->qual.s) kputsn("", 0, &k->qual);
    k->last_char = 0;
    if (k->seq.l != k->qual.l) return -2;
    return (int)k->seq.l;
}
