cat > src/dict.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include "samtools.h"
#include "kseq.h"
#include "md5.h"
#include "strmap.h"

static void dict_usage(FILE *fp) {
    fprintf(fp, "\nAbout:   Create a sequence dictionary file from a fasta file\n"
"Usage:   samtools dict [options] <file.fa|file.fa.gz>\n\n"
"Options: -a, --assembly STR    assembly\n"
"         -A, --alias, --alternative-name\n"
"                               add AN tag by adding/removing 'chr'\n"
"         -H, --no-header       do not print @HD line\n"
"         -l, --alt FILE        add AH:* tag to alternate locus sequences\n"
"         -o, --output FILE     file to write out dict file [stdout]\n"
"         -s, --species STR     species\n"
"         -u, --uri STR         URI [file:///abs/path/to/file.fa]\n\n");
}

int dict_main(int argc, char **argv) {
    const char *assembly = NULL, *species = NULL, *uri = NULL, *output = NULL, *alt_fn = NULL;
    int alias = 0, header = 1, c;
    static const struct option lopts[] = {
        { "assembly", required_argument, NULL, 'a' }, { "alias", no_argument, NULL, 'A' }, { "alternative-name", no_argument, NULL, 'A' },
        { "no-header", no_argument, NULL, 'H' }, { "alt", required_argument, NULL, 'l' }, { "output", required_argument, NULL, 'o' },
        { "species", required_argument, NULL, 's' }, { "uri", required_argument, NULL, 'u' }, { "help", no_argument, NULL, 'h' }, { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "AHa:l:o:s:u:h", lopts, NULL)) >= 0) {
        switch (c) {
        case 'a': assembly = optarg; break;
        case 'A': alias = 1; break;
        case 'H': header = 0; break;
        case 'l': alt_fn = optarg; break;
        case 'o': output = optarg; break;
        case 's': species = optarg; break;
        case 'u': uri = optarg; break;
        case 'h': dict_usage(stdout); return 0;
        default: dict_usage(stderr); return 1;
        }
    }
    const char *fn = optind < argc ? argv[optind] : "-";
    if (optind + 1 < argc) { dict_usage(stderr); return 1; }
    strmap_t *alt = NULL;
    if (alt_fn) {
        textfile_t *t = text_open(alt_fn);
        if (!t) { print_error_errno("dict", "Cannot open alt file %s", alt_fn); return 1; }
        alt = strmap_new();
        while (text_getline(t) >= 0) {
            char *line = t->line; if (line[0] == '#' || line[0] == 0) continue;
            char *tab = strchr(line, '\t'); if (tab) *tab = 0;
            strmap_set(alt, line, 1);
        }
        text_close(t);
    }
    bgzf_t *bg = bgzf_open_read(fn);
    if (!bg) { print_error_errno("dict", "Cannot open %s", fn); strmap_free(alt); return 1; }
    FILE *out = stdout;
    if (output) { out = fopen(output, "w"); if (!out) { print_error_errno("dict", "Cannot open %s for writing", output); bgzf_close(bg); return 1; } }
    char real[PATH_MAX]; char *uristr = NULL;
    if (!uri && strcmp(fn, "-") != 0) {
        if (realpath(fn, real)) { uristr = malloc(strlen(real) + 8); sprintf(uristr, "file://%s", real); }
    }
    if (header) fprintf(out, "@HD\tVN:1.0\tSO:unsorted\n");
    kseq_t *ks = kseq_init(bg);
    int l;
    while ((l = kseq_read(ks)) >= 0) {
        md5_ctx_t ctx; md5_init(&ctx);
        for (size_t i = 0; i < ks->seq.l; i++) ks->seq.s[i] = (char)toupper((unsigned char)ks->seq.s[i]);
        md5_update(&ctx, ks->seq.s, ks->seq.l);
        uint8_t d[16]; char hex[33]; md5_final(&ctx, d); md5_hex(d, hex);
        fprintf(out, "@SQ\tSN:%s\tLN:%zu\tM5:%s", ks->name.s, ks->seq.l, hex);
        if (alt && strmap_find(alt, ks->name.s)) fprintf(out, "\tAH:*");
        if (alias) {
            const char *name = ks->name.s;
            int has_chr = strncmp(name, "chr", 3) == 0;
            const char *base = has_chr ? name + 3 : name;
            fprintf(out, "\tAN:");
            if (has_chr) fprintf(out, "%s", base); else fprintf(out, "chr%s", base);
            if (strcmp(base, "M") == 0) fprintf(out, ",chrMT,MT");
            else if (strcmp(base, "MT") == 0) fprintf(out, ",chrM,M");
        }
        if (uri) fprintf(out, "\tUR:%s", uri); else if (uristr) fprintf(out, "\tUR:%s", uristr);
        if (assembly) fprintf(out, "\tAS:%s", assembly);
        if (species) fprintf(out, "\tSP:%s", species);
        fprintf(out, "\n");
    }
    kseq_destroy(ks); bgzf_close(bg); free(uristr); strmap_free(alt);
    if (output) fclose(out);
    return 0;
}
