        case 'N': o.has12 = 1; o.has12_set = 1; o.no12 = 0; break;
        case 'O': o.use_oq = 1; break;
        case 's': o.fnse = optarg; break;
        case 't': o.copy_tags = 1; break;
        case 'T': o.taglist = optarg; break;
        case 'i': o.casava = 1; break;
        case 'c': o.level = atoi(optarg); break;
        case 'v': def_qual = atoi(optarg); if (def_qual < 0 || def_qual > 93) { fprintf(stderr, "Invalid -v default quality %d, allowed range 0 to 93\n", def_qual); bam2fq_usage(stderr, o.fasta); return 1; } break;
        case 'U': o.umi = 1; break;
        case 5: o.umi_tags = optarg; break;
        case 2: o.no_sc = 1; break;
        case 3: if (strlen(optarg) != 2) { print_error("bam2fq", "--sc-aux tag must be 2 characters"); return 1; } o.sc_aux[0] = optarg[0]; o.sc_aux[1] = optarg[1]; break;
        case 4: o.sc_bkp = 0; break;
        case 6: o.fn_idx[0] = optarg; break;
        case 7: o.fn_idx[1] = optarg; break;
        case 8: o.barcode_tag = optarg; break;
        case 9: o.quality_tag = optarg; break;
        case 10: o.index_format = optarg; break;
        case 'd': {
            if (strlen(optarg) < 2 || (strlen(optarg) > 2 && optarg[2] != ':')) { print_error("bam2fq", "Invalid \"tag:value\" option: \"%s\"", optarg); return 1; }
            o.tag[0] = optarg[0]; o.tag[1] = optarg[1]; o.has_tag = 1;
            if (strlen(optarg) > 3) { if (!o.tvhash) o.tvhash = strmap_new(); strmap_set(o.tvhash, optarg + 3, 1); }
            break;
        }
        case 'D': {
            if (strlen(optarg) < 4 || optarg[2] != ':') { print_error("bam2fq", "Invalid \"tag:file\" option: \"%s\"", optarg); return 1; }
            o.tag[0] = optarg[0]; o.tag[1] = optarg[1]; o.has_tag = 1;
            textfile_t *t = text_open(optarg + 3);
            if (!t) { print_error_errno("bam2fq", "failed to open \"%s\" for reading", optarg + 3); return 1; }
            if (!o.tvhash) o.tvhash = strmap_new();
            while (text_getline(t) >= 0) { char *e = t->line; while (*e && *e != '\t') e++; *e = 0; if (*t->line) strmap_set(o.tvhash, t->line, 1); }
            text_close(t);
            break;
        }
        case '@': case 1002: case 1005: break;
        case 1008: hts_verbose = atoi(optarg); break;
        case 'h': bam2fq_usage(stdout, o.fasta); return 0;
        default:
            if (optopt) fprintf(stderr, "%s: invalid option -- '%c'\n", o.fasta ? "fasta" : "fastq", optopt);
            else fprintf(stderr, "%s: unrecognized option '%s'\n", o.fasta ? "fasta" : "fastq", argv[optind-1]);
            bam2fq_usage(stderr, o.fasta); return 1;
        }
    }
    if (o.casava && !o.index_format) { fprintf(stderr, "You must specify an index format (--index-format) with the Illumina Casava (-i) option\n"); bam2fq_usage(stderr, o.fasta); return 1; }
    if (argc - optind > 1) { fprintf(stderr, "Too many arguments.\n"); bam2fq_usage(stderr, o.fasta); return 1; }
    o.fn_in = optind < argc ? argv[optind] : "-";
    if (!o.has12_set) o.has12 = !(o.fnr[1] || o.fnr[2] || o.fn_output);
    else o.has12 = !o.no12;
    if (o.copy_tags || o.taglist) {
        o.tags = strmap_new();
        if (o.copy_tags) { strmap_set(o.tags, "RG", 1); strmap_set(o.tags, "BC", 1); strmap_set(o.tags, "QT", 1); }
        if (o.taglist) {
            if (strcmp(o.taglist, "*") == 0) o.all_tags = 1;
            else {
                char *dup = strdup(o.taglist), *p = dup;
                while (*p) { char *e = strchr(p, ','); if (e) *e = 0; if (strlen(p) == 2) strmap_set(o.tags, p, 1); if (!e) break; p = e + 1; }
                free(dup);
            }
        }
    }
    (void)def_qual;

    samfile_t *fp = sam_open_read_nohdr(o.fn_in);
    if (!fp) {
        log_error("hts_open_format", "Failed to open file \"%s\" : %s", o.fn_in, strerror(errno));
        print_error_errno("bam2fq", "Cannot read file \"%s\"", o.fn_in); return 1;
    }
    if (sam_read_header(fp) < 0) { fprintf(stderr, "Failed to read header for \"%s\"\n", o.fn_in); sam_close(fp); return 1; }
    sam_hdr_t *h = fp->hdr;

    /* open outputs */
    outf_t *fpr[3] = { NULL, NULL, NULL }, *fpse = NULL, *fidx[2] = { NULL, NULL };
    outf_t *stdout_f = calloc(1, sizeof(outf_t)); stdout_f->bg = bgzf_open_write("-", 0); bgzf_set_uncompressed(stdout_f->bg);
    outf_t *fout = NULL;
    int ret = 0;
    if (o.fn_output) { fout = open_out(o.fn_output, o.level); if (!fout) { print_error_errno("bam2fq", "Cannot write to %s file \"%s\"", "output", o.fn_output); ret = 1; goto done; } }
    for (int i = 0; i < 3; i++) {
        if (o.fnr[i]) { fpr[i] = open_out(o.fnr[i], o.level); if (!fpr[i]) { print_error_errno("bam2fq", "Cannot write to r%d file \"%s\"", i, o.fnr[i]); ret = 1; goto done; } }
        else if (i > 0 && fout) fpr[i] = fout;
        else fpr[i] = stdout_f;
    }
    if (o.fnse) { fpse = open_out(o.fnse, o.level); if (!fpse) { print_error_errno("bam2fq", "Cannot write to singleton file \"%s\"", o.fnse); ret = 1; goto done; } }
    for (int i = 0; i < 2; i++) if (o.fn_idx[i]) { fidx[i] = open_out(o.fn_idx[i], o.level); if (!fidx[i]) { print_error_errno("bam2fq", "Cannot write to i%d file \"%s\"", i + 1, o.fn_idx[i]); ret = 1; goto done; } }

    {
        bam1_t *b = bam_init1();
        kstring_t lb[3] = { KS_INITIALIZE, KS_INITIALIZE, KS_INITIALIZE };
        int have[3] = { 0, 0, 0 };
        bam1_t *keep[3] = { NULL, NULL, NULL };
        char *cur = NULL;
        long long n_reads = 0, n_singletons = 0;
        int at_eof = 0;
        while (!at_eof) {
            int r = sam_read1(fp, h, b);
            if (r < -1) { print_error("bam2fq", "Error reading from input file"); ret = 1; break; }
            at_eof = r < 0;
            if (!at_eof && filter_it_out(b, &o)) continue;
            if (!at_eof) n_reads++;
            if (at_eof || !cur || strcmp(cur, bam_get_qname(b)) != 0) {
                if (cur) {
                    if (have[1] && have[2]) {
                        write_out(fpr[1], &lb[1]); write_out(fpr[2], &lb[2]);
                        if (keep[1]) write_index_reads(fidx, keep[1], &o);
                    } else if (have[1] || have[2]) {
                        int rp = have[1] ? 1 : 2;
                        if (fpse) { write_out(fpse, &lb[rp]); n_singletons++; }
                        else write_out(fpr[rp], &lb[rp]);
                        if (keep[rp]) write_index_reads(fidx, keep[rp], &o);
                    }
                    if (have[0]) { write_out(fpr[0], &lb[0]); if (keep[0]) write_index_reads(fidx, keep[0], &o); }
                }
                have[0] = have[1] = have[2] = 0;
                for (int i = 0; i < 3; i++) { if (keep[i]) { bam_destroy1(keep[i]); keep[i] = NULL; } }
                free(cur); cur = at_eof ? NULL : strdup(bam_get_qname(b));
            }
            if (at_eof) break;
            int rp = which_readpart(b);
            if (!have[rp]) {
                format_read(&lb[rp], b, &o);
                have[rp] = 1;
                if (fidx[0] || fidx[1]) keep[rp] = bam_dup1(b);
            }
        }
        free(cur);
        for (int i = 0; i < 3; i++) { free(lb[i].s); if (keep[i]) bam_destroy1(keep[i]); }
        bam_destroy1(b);
        if (!ret) {
            fprintf(stderr, "[M::bam2fq_mainloop] discarded %lld singletons\n", n_singletons);
            fprintf(stderr, "[M::bam2fq_mainloop] processed %lld reads\n", n_reads);
        }
    }
done:
    for (int i = 0; i < 3; i++) if (fpr[i] && fpr[i] != stdout_f && fpr[i] != fout) { bgzf_close(fpr[i]->bg); free(fpr[i]); }
    if (fout) { bgzf_close(fout->bg); free(fout); }
    if (fpse) { bgzf_close(fpse->bg); free(fpse); }
    for (int i = 0; i < 2; i++) if (fidx[i]) { bgzf_close(fidx[i]->bg); free(fidx[i]); }
    bgzf_close(stdout_f->bg); free(stdout_f);
    sam_close(fp);
    strmap_free(o.tags); strmap_free(o.tvhash);
    return ret;
}
EOF
sed -i '/STUB(main_bam2fq, "fastq")/d' src/stubs.c && make -j8 build/samtools 2>&1 | grep -E "error" | head; cd /tmp/w; C=./cmp.sh; $C fastq /tmp/w/toy.sam; $C fasta /tmp/w/toy.sam; $C fastq /tmp/w/ex1n.bam; $C fastq -1 /tmp/w/r1.fq -2 /tmp/w/r2.fq -s /tmp/w/s.fq -0 /tmp/w/o.fq /tmp/w/ex1n.bam; md5sum r1.fq r2.fq s.fq o.fq | cut -c1-8 | tr '\n' ' '; echo; $C fastq -N /tmp/w/toy.sam; $C fastq -n /tmp/w/ex1n.bam; $C fastq -t /tmp/w/ex1n.bam; $C fastq -T MF,Aq /tmp/w/ex1n.bam; $C fastq -T '*' /tmp/w/ex1n.bam; $C fastq -F 0 /tmp/w/toy.sam; $C fastq -v 5 /tmp/w/toy.sam; $C fastq /tmp/w/rev.sam; $C fasta /tmp/w/rev.sam; $C fastq -s /tmp/w/s2.fq /tmp/w/toy.sam; $C fastq /tmp/w/fq1.sam; $C fastq -O /tmp/w/fq1.sam; $C fastq -t /tmp/w/fq1.sam; $C fastq -U /tmp/w/fq1.sam; $C fastq -1 /tmp/w/r1b.fq /tmp/w/fq1.sam; $C fastq -o /tmp/w/ob.fq /tmp/w/fq1.sam; $C fastq -0 /tmp/w/o0.fq /tmp/w/fq1.sam; $C fastq /tmp/w/fq2.sam; $C fastq -N /tmp/w/fq2.sam; $C fastq -F 0 /tmp/w/fq2.sam; $C fastq -s /tmp/w/sg.fq -1 /tmp/w/p1.fq -2 /tmp/w/p2.fq /tmp/w/fq2.sam;  $C fastq -F 0 /tmp/w/fq3.sam; $C fastq /tmp/w/fq4.sam; $C fastq -s /tmp/w/sg.fq -0 /tmp/w/p0.fq /tmp/w/fq4.sam; $C fastq --no-sc /tmp/w/sc.sam; $C fastq --no-sc -T '*' /tmp/w/sc.sam; $C fastq --no-sc --no-sc-bkp -T '*' /tmp/w/sc.sam; $C fastq --no-sc --sc-aux XS -T XS /tmp/w/sc.sam; $C fastq -d XX /tmp/w/toy.sam; $C fastq -d XX:1 /tmp/w/toy.sam; $C fastq -f 1 -F 0 /tmp/w/toy.sam; $C fastq --rf 16 /tmp/w/toy.sam; $C fastq -G 0x53 /tmp/w/toy.sam; $C fastq nonexist.bam; $C fastq; $C fastq /tmp/w/toy.sam extra; $C fastq -v 94 /tmp/w/nq.sam; $C fastq -i /tmp/w/fq1.sam; $C fasta -h; $C fastq -c 9 -1 /tmp/w/r1c.fq.gz /tmp/w/fq1.sam; $C fastq --i1 /tmp/w/i1.fq --index-format i2i2 /tmp/w/fq1.sam; cat i1.fq"}

actions.command:
cd /workspace && cat > src/bam2fq.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <errno.h>
#include <ctype.h>
#include "samtools.h"
#include "strmap.h"
#include "log.h"

typedef struct {
    bgzf_t *bg; int compressed;
} outf_t;

typedef struct {
    int fasta;
    int flag_on, flag_off, flag_alloff, flag_anyon;
    int has12, has12_set, no12;
    int use_oq, copy_tags; char *taglist; int all_tags;
    strmap_t *tags;
    int casava; int umi; char *umi_tags;
    int no_sc, sc_bkp; char sc_aux[3];
    char *fnr[3], *fnse, *fn_output;
    char *barcode_tag, *quality_tag, *index_format, *fn_idx[2];
    int level;
    char tag[3]; strmap_t *tvhash; char *tagval; int has_tag;
    char *fn_in;
} bam2fq_opts_t;

static void bam2fq_usage(FILE *fp, int fasta) {
    fprintf(fp, "Usage: samtools %s [options...] <in.bam>\n", fasta ? "fasta" : "fastq");
    fprintf(fp, "\nDescription:\nConverts a SAM, BAM or CRAM to %s format.\n\n", fasta ? "FASTA" : "FASTQ");
    fprintf(fp,
"Options:\n"
"  -0 FILE      write reads designated READ_OTHER to FILE\n"
"  -1 FILE      write reads designated READ1 to FILE\n"
"  -2 FILE      write reads designated READ2 to FILE\n"
"  -o FILE      write reads designated READ1 or READ2 to FILE\n"
"               note: if a singleton file is specified with -s, only\n"
"               paired reads will be written to the -1 and -2 files.\n"
"  -d, --tag TAG[:VAL]\n"
"               only include reads containing TAG, optionally with value VAL\n"
"  -D, --tag-file STR:FILE\n"
"               only include reads containing TAG, with a value listed in FILE\n"
"  -f, --require-flags INT\n"
"               only include reads with all  of the FLAGs in INT present [0]\n"
"  -F, --excl[ude]-flags INT\n"
"               only include reads with none of the FLAGs in INT present [0x900]\n"
"      --rf, --incl[ude]-flags INT\n"
"               only include reads with any  of the FLAGs in INT present [0]\n"
"  -G INT       only EXCLUDE reads with all  of the FLAGs in INT present [0]\n"
"  -n           don't append /1 and /2 to the read name\n"
"  -N           always append /1 and /2 to the read name\n"
"  --no-sc      Remove soft-clips from output\n"
"  --sc-aux TAG Tag with which to backup the removed soft-clip data [s0]\n"
"  --no-sc-bkp  Do not backup removed soft-clips as aux tags\n");
    if (!fasta) fprintf(fp, "  -O           output quality in the OQ tag if present\n");
    fprintf(fp,
"  -s FILE      write singleton reads designated READ1 or READ2 to FILE\n"
"  -t           copy RG, BC and QT tags to the %s header line\n"
"  -T TAGLIST   copy arbitrary tags to the %s header line, '*' for all\n", fasta ? "FASTA" : "FASTQ", fasta ? "FASTA" : "FASTQ");
    if (!fasta) fprintf(fp, "  -v INT       default quality score if not given in file [1]\n");
    fprintf(fp,
"  -i           add Illumina Casava 1.8 format entry to header (eg 1:N:0:ATCACG)\n"
"  -U, --UMI     add UMI to read name\n"
"  --UMI-tag TAG-LIST\n"
"               the list of aux tags to search for UMI barcode [RX,OX]\n"
"  -c INT       compression level [0..9] to use when writing bgzf files [1]\n"
"  --i1 FILE    write first index reads to FILE\n"
"  --i2 FILE    write second index reads to FILE\n"
"  --barcode-tag TAG\n"
"               Barcode tag [BC]\n"
"  --quality-tag TAG\n"
"               Quality tag [QT]\n"
"  --index-format STR\n"
"               How to parse barcode and quality tags\n\n");
    sam_global_opt_help(fp, ".-..-@.-");
    fprintf(fp,
"\n"
"The files will be automatically compressed if the file names have a .gz\n"
"or .bgzf extension.  The input to this program must be collated by name.\n"
"Run 'samtools collate' or 'samtools sort -n' to achieve this.\n"
"\n"
"Reads are designated READ1 if FLAG READ1 is set and READ2 is not set.\n"
"Reads are designated READ2 if FLAG READ1 is not set and READ2 is set.\n"
"Otherwise reads are designated READ_OTHER (both flags set or both flags unset).\n"
"Run 'samtools flags' for more information on flag codes and meanings.\n"
"\n"
"The index-format string describes how to parse the barcode and quality tags.\n"
"It is made up of 'i' or 'n' followed by a length or '*'.  For example:\n"
"   i14i8       The first 14 characters are index 1, the next 8 are index 2\n"
"   n8i14       Ignore the first 8 characters, and use the next 14 for index 1\n"
"\n"
"If the tag contains a separator, then the numeric part can be replaced with\n"
"'*' to mean 'read until the separator or end of tag', for example:\n"
"   i*i*        Break the tag at the separator into index 1 and index 2\n"
"   n*i*        Ignore the left part of the tag until the separator,\n"
"               then use the second part of the tag as index 1\n"
"\n"
"Examples:\n"
"To get just the paired reads in separate files, use:\n"
"   samtools %s -1 pair1.%s -2 pair2.%s -0 /dev/null -s /dev/null -n in.bam\n"
"\n"
"To get all non-supplementary/secondary reads in a single file, redirect\n"
"the output:\n"
"   samtools %s in.bam > all_reads.%s\n", fasta ? "fasta" : "fastq", fasta ? "fa" : "fq", fasta ? "fa" : "fq", fasta ? "fasta" : "fastq", fasta ? "fa" : "fq");
}

static int which_readpart(const bam1_t *b) {
    if ((b->core.flag & BAM_FREAD1) && !(b->core.flag & BAM_FREAD2)) return 1;
    if ((b->core.flag & BAM_FREAD2) && !(b->core.flag & BAM_FREAD1)) return 2;
    return 0;
}

static const char comp_base[16] = { 0, 8, 4, 12, 2, 10, 6, 14, 1, 9, 5, 13, 3, 11, 7, 15 };

/* format a record into FASTQ/FASTA text */
static int format_read(kstring_t *ks, const bam1_t *b, bam2fq_opts_t *o) {
    ks->l = 0;
    const char *qname = bam_get_qname(b);
    kputc(o->fasta ? '>' : '@', ks);
    kputs(qname, ks);
    if (o->umi) {
        /* search UMI tags */
        char *list = strdup(o->umi_tags ? o->umi_tags : "RX,OX");
        char *p = list; int found = 0;
        while (*p && !found) {
            char *e = strchr(p, ','); if (e) *e = 0;
            if (strlen(p) == 2) { uint8_t *t = bam_aux_get(b, p); if (t && *t == 'Z') { kputc(':', ks); kputs((char*)t + 1, ks); found = 1; } }
            if (!e) break; p = e + 1;
        }
        free(list);
    }
    if (o->has12 && (b->core.flag & BAM_FPAIRED)) {
        int rp = which_readpart(b);
        if (rp == 1) kputs("/1", ks); else if (rp == 2) kputs("/2", ks);
    }
    if (o->casava) {
        int rp = which_readpart(b);
        ksprintf(ks, " %d:%c:0:", rp == 2 ? 2 : (rp == 1 ? 1 : 0), (b->core.flag & BAM_FQCFAIL) ? 'Y' : 'N');
        uint8_t *bc = bam_aux_get(b, o->barcode_tag ? o->barcode_tag : "BC");
        if (bc && *bc == 'Z') { const char *s = (char*)bc + 1; while (*s) { if (*s != '-' && *s != '+') kputc(*s, ks); s++; } }
    }
    /* soft clip info */
    int lead = 0, trail = 0;
    if (o->no_sc && b->core.n_cigar) {
        uint32_t *c = bam_get_cigar(b);
        for (uint32_t i = 0; i < b->core.n_cigar; i++) { int op = bam_cigar_op(c[i]); if (op == BAM_CSOFT_CLIP) lead += bam_cigar_oplen(c[i]); else if (op != BAM_CHARD_CLIP) break; }
        for (int i = (int)b->core.n_cigar - 1; i >= 0; i--) { int op = bam_cigar_op(c[i]); if (op == BAM_CSOFT_CLIP) trail += bam_cigar_oplen(c[i]); else if (op != BAM_CHARD_CLIP) break; }
        if (lead + trail >= b->core.l_qseq) lead = trail = 0;
    }
    int rev = bam_is_rev(b);
    int len = b->core.l_qseq;
    uint8_t *seq = bam_get_seq(b), *qual = bam_get_qual(b);
    /* build oriented seq/qual */
    char *S = malloc(len + 1), *Q = malloc(len + 1);
    for (int i = 0; i < len; i++) {
        int j = rev ? len - 1 - i : i;
        int base = bam_seqi(seq, j);
        if (rev) base = comp_base[base];
        S[i] = seq_nt16_str[base];
    }
    S[len] = 0;
    int noqual = (len == 0 || qual[0] == 0xff);
    uint8_t *oq = NULL;
    if (o->use_oq) { uint8_t *t = bam_aux_get(b, "OQ"); if (t && *t == 'Z' && (int)strlen((char*)t + 1) == len) oq = t + 1; }
    for (int i = 0; i < len; i++) {
        int j = rev ? len - 1 - i : i;
        if (oq) Q[i] = (char)oq[j];
        else if (noqual) Q[i] = 'B';
        else Q[i] = (char)(qual[j] + 33);
    }
    Q[len] = 0;
    /* clipping: in oriented coordinates, leading clip of reverse read is the trailing clip in original */
    int clip_l = rev ? trail : lead, clip_r = rev ? lead : trail;
    /* aux tags */
    if (o->tags || o->all_tags || (o->no_sc && o->sc_bkp && (lead || trail))) {
        kstring_t aux = KS_INITIALIZE;
        uint8_t *s = bam_get_aux(b), *end = b->data + b->l_data;
        while (s + 3 <= end) {
            char tag[3] = { (char)s[0], (char)s[1], 0 };
            uint8_t *n = bam_aux_skip(s + 2, end); if (!n) break;
            if (o->all_tags || (o->tags && strmap_find(o->tags, tag))) sam_format_aux1(s, s[2], s + 3, end, &aux);
            s = n;
        }
        if (o->no_sc && o->sc_bkp && (lead || trail) && (o->all_tags || (o->tags && strmap_find(o->tags, o->sc_aux)))) {
            /* s0:Z:CIGAR:clippedbases:clippedquals in oriented form */
            kputc('\t', &aux); kputsn(o->sc_aux, 2, &aux); kputs(":Z:", &aux);
            uint32_t *c = bam_get_cigar(b);
            if (rev) for (int i = (int)b->core.n_cigar - 1; i >= 0; i--) { kputuw(bam_cigar_oplen(c[i]), &aux); kputc(bam_cigar_opchr(c[i]), &aux); }
            else for (uint32_t i = 0; i < b->core.n_cigar; i++) { kputuw(bam_cigar_oplen(c[i]), &aux); kputc(bam_cigar_opchr(c[i]), &aux); }
            kputc(':', &aux); kputsn(S, clip_l, &aux); kputsn(S + len - clip_r, clip_r, &aux);
            kputc(':', &aux); kputsn(Q, clip_l, &aux); kputsn(Q + len - clip_r, clip_r, &aux);
        }
        if (aux.l) kputsn(aux.s, aux.l, ks);
        free(aux.s);
    }
    kputc('\n', ks);
    kputsn(S + clip_l, len - clip_l - clip_r, ks); kputc('\n', ks);
    if (!o->fasta) { kputs("+\n", ks); kputsn(Q + clip_l, len - clip_l - clip_r, ks); kputc('\n', ks); }
    free(S); free(Q);
    return 0;
}

static int write_out(outf_t *f, kstring_t *ks) {
    if (!f || !f->bg) return 0;
    return bgzf_write(f->bg, ks->s, ks->l) < 0 ? -1 : 0;
}

static outf_t *open_out(const char *fn, int level) {
    outf_t *f = calloc(1, sizeof *f);
    size_t l = strlen(fn);
    int gz = (l > 3 && strcmp(fn + l - 3, ".gz") == 0) || (l > 5 && strcmp(fn + l - 5, ".bgzf") == 0);
    f->bg = bgzf_open_write(fn, gz ? level : 0);
    if (!f->bg) { free(f); return NULL; }
    if (!gz) bgzf_set_uncompressed(f->bg);
    f->compressed = gz;
    return f;
}

static int filter_it_out(const bam1_t *b, bam2fq_opts_t *o) {
    int flag = b->core.flag;
    if ((flag & o->flag_off) || (flag & o->flag_on) != o->flag_on) return 1;
    if (o->flag_alloff && (flag & o->flag_alloff) == o->flag_alloff) return 1;
    if (o->flag_anyon && !(flag & o->flag_anyon)) return 1;
    if (o->has_tag) {
        uint8_t *t = bam_aux_get(b, o->tag);
        if (!t) return 1;
        if (o->tvhash) {
            char buf[32]; const char *val;
            if (bam_aux_is_int(t)) { snprintf(buf, sizeof buf, "%lld", (long long)bam_aux2i(t)); val = buf; }
            else if (*t == 'A') { buf[0] = (char)t[1]; buf[1] = 0; val = buf; }
            else if (*t == 'f' || *t == 'd') { snprintf(buf, sizeof buf, "%g", bam_aux2f(t)); val = buf; }
            else val = (char*)t + 1;
            if (!strmap_find(o->tvhash, val)) return 1;
        }
    }
    return 0;
}

static void write_index_reads(outf_t **fidx, const bam1_t *b, bam2fq_opts_t *o) {
    if (!o->index_format || (!fidx[0] && !fidx[1])) return;
    uint8_t *bc = bam_aux_get(b, o->barcode_tag ? o->barcode_tag : "BC");
    uint8_t *qt = bam_aux_get(b, o->quality_tag ? o->quality_tag : "QT");
    if (!bc || *bc != 'Z') return;
    const char *bs = (char*)bc + 1, *qs = (qt && *qt == 'Z') ? (char*)qt + 1 : NULL;
    const char *p = o->index_format; int idx = 0; size_t pos = 0, blen = strlen(bs);
    while (*p && idx < 2) {
        char type = *p++;
        size_t n;
        if (*p == '*') { p++; size_t e = pos; while (e < blen && bs[e] != '-' && bs[e] != '+') e++; n = e - pos; }
        else { n = strtoul(p, (char**)&p, 10); }
        if (pos + n > blen) n = blen - pos;
        if (type == 'i') {
            if (fidx[idx] && fidx[idx]->bg) {
                kstring_t ks = KS_INITIALIZE;
                kputc('@', &ks); kputs(bam_get_qname(b), &ks); kputc('\n', &ks); kputsn(bs + pos, n, &ks); kputs("\n+\n", &ks);
                if (qs && strlen(qs) >= pos + n) kputsn(qs + pos, n, &ks); else for (size_t i = 0; i < n; i++) kputc('B', &ks);
                kputc('\n', &ks);
                write_out(fidx[idx], &ks); free(ks.s);
            }
            idx++;
        }
        pos += n;
        if (pos < blen && (bs[pos] == '-' || bs[pos] == '+')) pos++;
    }
}

int main_bam2fq(int argc, char **argv) {
    bam2fq_opts_t o; memset(&o, 0, sizeof o);
    o.fasta = (strcmp(argv[0], "fasta") == 0);
    o.flag_off = 0x900; o.has12 = 1; o.level = 1; o.sc_bkp = 1; strcpy(o.sc_aux, "s0");
    int c, def_qual = 1;
    static const struct option lopts[] = {
        { "tag", required_argument, NULL, 'd' }, { "tag-file", required_argument, NULL, 'D' }, { "require-flags", required_argument, NULL, 'f' },
        { "excl-flags", required_argument, NULL, 'F' }, { "exclude-flags", required_argument, NULL, 'F' }, { "rf", required_argument, NULL, 1 }, { "incl-flags", required_argument, NULL, 1 }, { "include-flags", required_argument, NULL, 1 },
        { "no-sc", no_argument, NULL, 2 }, { "sc-aux", required_argument, NULL, 3 }, { "no-sc-bkp", no_argument, NULL, 4 },
        { "UMI", no_argument, NULL, 'U' }, { "UMI-tag", required_argument, NULL, 5 }, { "i1", required_argument, NULL, 6 }, { "i2", required_argument, NULL, 7 },
        { "barcode-tag", required_argument, NULL, 8 }, { "quality-tag", required_argument, NULL, 9 }, { "index-format", required_argument, NULL, 10 },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "reference", required_argument, NULL, 1005 }, { "threads", required_argument, NULL, '@' }, { "verbosity", required_argument, NULL, 1008 },
        { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "0:1:2:o:f:F:G:niNOs:c:tT:v:@:d:D:Uh", lopts, NULL)) >= 0) {
        switch (c) {
        case '0': o.fnr[0] = optarg; break;
        case '1': o.fnr[1] = optarg; break;
        case '2': o.fnr[2] = optarg; break;
        case 'o': o.fn_output = optarg; break;
        case 'f': { int f = bam_str2flag(optarg); if (f < 0) { print_error("bam2fq", "Unknown flag value: %s", optarg); return 1; } o.flag_on |= f; break; }
        case 'F': { int f = bam_str2flag(optarg); if (f < 0) { print_error("bam2fq", "Unknown flag value: %s", optarg); return 1; } o.flag_off |= f; break; }
        case 'G': { int f = bam_str2flag(optarg); if (f < 0) { print_error("bam2fq", "Unknown flag value: %s", optarg); return 1; } o.flag_alloff |= f; break; }
        case 1: { int f = bam_str2flag(optarg); if (f < 0) { print_error("bam2fq", "Unknown flag value: %s", optarg); return 1; } o.flag_anyon |= f; break; }
        case 'n': o.no12 = 1; o.has12_set = 1; break;
        case 'N': o.has12 = 1; o.has12_set = 1; o.no12 = 0; break;
        case 'O': o.use_oq = 1; break;
        case 's': o.fnse = optarg; break;
        case 't': o.copy_tags = 1; break;
        case 'T': o.taglist = optarg; break;
        case 'i': o.casava = 1; break;
        case 'c': o.level = atoi(optarg); break;
        case 'v': def_qual = atoi(optarg); if (def_qual < 0 || def_qual > 93) { fprintf(stderr, "Invalid -v default quality %d, allowed range 0 to 93\n", def_qual); bam2fq_usage(stderr, o.fasta); return 1; } break;
        case 'U': o.umi = 1; break;
        case 5: o.umi_tags = optarg; break;
        case 2: o.no_sc = 1; break;
        case 3: if (strlen(optarg) != 2) { print_error("bam2fq", "--sc-aux tag must be 2 characters"); return 1; } o.sc_aux[0] = optarg[0]; o.sc_aux[1] = optarg[1]; break;
        case 4: o.sc_bkp = 0; break;
        case 6: o.fn_idx[0] = optarg; break;
        case 7: o.fn_idx[1] = optarg; break;
        case 8: o.barcode_tag = optarg; break;
        case 9: o.quality_tag = optarg; break;
        case 10: o.index_format = optarg; break;
        case 'd': {
            if (strlen(optarg) < 2 || (strlen(optarg) > 2 && optarg[2] != ':')) { print_error("bam2fq", "Invalid \"tag:value\" option: \"%s\"", optarg); return 1; }
            o.tag[0] = optarg[0]; o.tag[1] = optarg[1]; o.has_tag = 1;
            if (strlen(optarg) > 3) { if (!o.tvhash) o.tvhash = strmap_new(); strmap_set(o.tvhash, optarg + 3, 1); }
            break;
        }
        case 'D': {
            if (strlen(optarg) < 4 || optarg[2] != ':') { print_error("bam2fq", "Invalid \"tag:file\" option: \"%s\"", optarg); return 1; }
            o.tag[0] = optarg[0]; o.tag[1] = optarg[1]; o.has_tag = 1;
            textfile_t *t = text_open(optarg + 3);
            if (!t) { print_error_errno("bam2fq", "failed to open \"%s\" for reading", optarg + 3); return 1; }
            if (!o.tvhash) o.tvhash = strmap_new();
            while (text_getline(t) >= 0) { char *e = t->line; while (*e && *e != '\t') e++; *e = 0; if (*t->line) strmap_set(o.tvhash, t->line, 1); }
            text_close(t);
            break;
        }
        case '@': case 1002: case 1005: break;
        case 1008: hts_verbose = atoi(optarg); break;
        case 'h': bam2fq_usage(stdout, o.fasta); return 0;
        default:
            if (optopt) fprintf(stderr, "%s: invalid option -- '%c'\n", o.fasta ? "fasta" : "fastq", optopt);
            else fprintf(stderr, "%s: unrecognized option '%s'\n", o.fasta ? "fasta" : "fastq", argv[optind-1]);
