        if (o.copy_tags) { strmap_set(o.tags, "RG", 1); strmap_set(o.tags, "BC", 1); strmap_set(o.tags, "QT", 1); }
        if (o.taglist) {
            if (strcmp(o.taglist, "*") == 0) o.all_tags = 1;
            else {
                char *dup = strdup(o.taglist), *p = dup;
                while (*p) { char *e = strchr(p, ','); if (e) *e = 0; if (strlen(p) == 2) strmap_set(o.tags, p, 1); if (!e) break; p = e + 1; }
                free(dup);
            }
        }
    }
    (void)def_qual;

    samfile_t *fp = sam_open_read_nohdr(o.fn_in);
    if (!fp) {
        log_error("hts_open_format", "Failed to open file \"%s\" : %s", o.fn_in, strerror(errno));
        print_error_errno("bam2fq", "Cannot read file \"%s\"", o.fn_in); return 1;
    }
    if (sam_read_header(fp) < 0) { fprintf(stderr, "Failed to read header for \"%s\"\n", o.fn_in); sam_close(fp); return 1; }
    sam_hdr_t *h = fp->hdr;

    /* open outputs */
    outf_t *fpr[3] = { NULL, NULL, NULL }, *fpse = NULL, *fidx[2] = { NULL, NULL };
    outf_t *stdout_f = calloc(1, sizeof(outf_t)); stdout_f->bg = bgzf_open_write("-", 0); bgzf_set_uncompressed(stdout_f->bg);
    outf_t *fout = NULL;
    int ret = 0;
    if (o.fn_output) { fout = open_out(o.fn_output, o.level); if (!fout) { print_error_errno("bam2fq", "Cannot write to %s file \"%s\"", "output", o.fn_output); ret = 1; goto done; } }
    for (int i = 0; i < 3; i++) {
        if (o.fnr[i]) { fpr[i] = open_out(o.fnr[i], o.level); if (!fpr[i]) { print_error_errno("bam2fq", "Cannot write to r%d file \"%s\"", i, o.fnr[i]); ret = 1; goto done; } }
        else if (i > 0 && fout) fpr[i] = fout;
        else fpr[i] = stdout_f;
    }
    if (o.fnse) { fpse = open_out(o.fnse, o.level); if (!fpse) { print_error_errno("bam2fq", "Cannot write to singleton file \"%s\"", o.fnse); ret = 1; goto done; } }
    for (int i = 0; i < 2; i++) if (o.fn_idx[i]) { fidx[i] = open_out(o.fn_idx[i], o.level); if (!fidx[i]) { print_error_errno("bam2fq", "Cannot write to i%d file \"%s\"", i + 1, o.fn_idx[i]); ret = 1; goto done; } }

    {
        bam1_t *b = bam_init1();
        kstring_t lb[3] = { KS_INITIALIZE, KS_INITIALIZE, KS_INITIALIZE };
        int have[3] = { 0, 0, 0 };
        bam1_t *keep[3] = { NULL, NULL, NULL };
