            if (!at_eof && filter_it_out(b, &o)) continue;
            if (!at_eof) n_reads++;
            if (at_eof || !cur || strcmp(cur, bam_get_qname(b)) != 0) {
                if (cur) {
                    if (have[1] && have[2]) {
                        write_out(fpr[1], &lb[1]); write_out(fpr[2], &lb[2]);
                        if (keep[1]) write_index_reads(fidx, keep[1], &o);
                    } else if (have[1] || have[2]) {
                        int rp = have[1] ? 1 : 2;
                        if (fpse) { write_out(fpse, &lb[rp]); n_singletons++; }
                        else write_out(fpr[rp], &lb[rp]);
                        if (keep[rp]) write_index_reads(fidx, keep[rp], &o);
                    }
                    if (have[0]) { write_out(fpr[0], &lb[0]); if (keep[0]) write_index_reads(fidx, keep[0], &o); }
                }
                have[0] = have[1] = have[2] = 0;
                for (int i = 0; i < 3; i++) { if (keep[i]) { bam_destroy1(keep[i]); keep[i] = NULL; } }
                free(cur); cur = at_eof ? NULL : strdup(bam_get_qname(b));
            }
            if (at_eof) break;
            int rp = which_readpart(b);
            if (!have[rp]) {
                format_read(&lb[rp], b, &o);
                have[rp] = 1;
                if (fidx[0] || fidx[1]) keep[rp] = bam_dup1(b);
            }
        }
        free(cur);
        for (int i = 0; i < 3; i++) { free(lb[i].s); if (keep[i]) bam_destroy1(keep[i]); }
        bam_destroy1(b);
        if (!ret) {
            fprintf(stderr, "[M::bam2fq_mainloop] discarded %lld singletons\n", n_singletons);
            fprintf(stderr, "[M::bam2fq_mainloop] processed %lld reads\n", n_reads);
        }
    }
done:
    for (int i = 0; i < 3; i++) if (fpr[i] && fpr[i] != stdout_f && fpr[i] != fout) { bgzf_close(fpr[i]->bg); free(fpr[i]); }
    if (fout) { bgzf_close(fout->bg); free(fout); }
    if (fpse) { bgzf_close(fpse->bg); free(fpse); }
    for (int i = 0; i < 2; i++) if (fidx[i]) { bgzf_close(fidx[i]->bg); free(fidx[i]); }
    bgzf_close(stdout_f->bg); free(stdout_f);
    sam_close(fp);
    strmap_free(o.tags); strmap_free(o.tvhash);
    return ret;
}
