#include <string.h>
#include <stdlib.h>

uint32_t hts_str_hash_X31(const char *s) { uint32_t h = (uint32_t)*s; if (h) for (++s; *s; ++s) h = (h << 5) - h + (uint32_t)*s; return h; }
uint32_t hts_hash_Wang(uint32_t key) { key += ~(key << 15); key ^= (key >> 10); key += (key << 3); key ^= (key >> 6); key += ~(key << 11); key ^= (key >> 16); return key; }

static lbnode_t *node_alloc(void) { lbnode_t *n = calloc(1, sizeof(lbnode_t)); return n; }
static void node_free(lbnode_t *n) { free(n->b.data); free(n); }

bam_plp_t bam_plp_init(bam_plp_auto_f func, void *data) {
    bam_plp_t iter = calloc(1, sizeof(struct bam_plp_s));
    iter->func = func; iter->data = data;
    iter->head = iter->tail = node_alloc();
    iter->max_tid = iter->max_pos = -1;
    iter->maxcnt = 8000;
    if (func) iter->tmp = bam_init1();
    return iter;
}

void bam_plp_init_overlaps(bam_plp_t iter) { if (!iter->overlaps) iter->overlaps = strmap_new(); }
void bam_plp_constructor(bam_plp_t plp, bam_plp_callback_f func) { plp->plp_construct = func; }
void bam_plp_destructor(bam_plp_t plp, bam_plp_callback_f func) { plp->plp_destruct = func; }
void bam_plp_set_maxcnt(bam_plp_t iter, int maxcnt) { iter->maxcnt = maxcnt; }

void bam_plp_destroy(bam_plp_t iter) {
    if (!iter) return;
    lbnode_t *p = iter->head;
    while (p) { lbnode_t *n = p->next; if (iter->plp_destruct && p != iter->tail) iter->plp_destruct(iter->data, &p->b, &p->cd); node_free(p); p = n; }
    strmap_free((strmap_t*)iter->overlaps);
    free(iter->plp);
    if (iter->tmp) bam_destroy1(iter->tmp);
    free(iter);
}

void bam_plp_reset(bam_plp_t iter) {
    lbnode_t *p = iter->head;
    while (p != iter->tail) { lbnode_t *n = p->next; node_free(p); p = n; }
    iter->head = iter->tail;
    iter->tid = iter->pos = 0; iter->is_eof = 0; iter->max_tid = iter->max_pos = -1;
    if (iter->overlaps) { strmap_free((strmap_t*)iter->overlaps); iter->overlaps = strmap_new(); }
}

/* ---- overlap removal ---- */
static inline int cigar_iref2iseq_set(const uint32_t **cigar, const uint32_t *cigar_max, int64_t *icig, int64_t *iseq, int64_t *iref) {
    int64_t pos = *iref;
    if (pos < 0) return -1;
    *icig = 0; *iseq = 0; *iref = 0;
    while (*cigar < cigar_max) {
        int cig = (**cigar) & BAM_CIGAR_MASK; int ncig = (**cigar) >> BAM_CIGAR_SHIFT;
        if (cig == BAM_CSOFT_CLIP) { (*cigar)++; *iseq += ncig; *icig = 0; continue; }
        if (cig == BAM_CHARD_CLIP || cig == BAM_CPAD) { (*cigar)++; *icig = 0; continue; }
        if (cig == BAM_CMATCH || cig == BAM_CEQUAL || cig == BAM_CDIFF) {
            pos -= ncig;
            if (pos < 0) { *icig = ncig + pos; *iseq += *icig; *iref += *icig; return BAM_CMATCH; }
            (*cigar)++; *iseq += ncig; *icig = 0; *iref += ncig;
            continue;
        }
        if (cig == BAM_CINS) { (*cigar)++; *iseq += ncig; *icig = 0; continue; }
        if (cig == BAM_CDEL || cig == BAM_CREF_SKIP) {
            pos -= ncig;
            if (pos < 0) pos = 0;
            (*cigar)++; *icig = 0; *iref += ncig;
            continue;
        }
        log_error("cigar_iref2iseq_set", "Unexpected cigar %d", cig);
        return -2;
    }
    *iseq = -1;
    return -1;
}

static inline int cigar_iref2iseq_next(const uint32_t **cigar, const uint32_t *cigar_max, int64_t *icig, int64_t *iseq, int64_t *iref) {
    while (*cigar < cigar_max) {
        int cig = (**cigar) & BAM_CIGAR_MASK; int ncig = (**cigar) >> BAM_CIGAR_SHIFT;
        if (cig == BAM_CMATCH || cig == BAM_CEQUAL || cig == BAM_CDIFF) {
            if (*icig >= ncig - 1) { *icig = -1; (*cigar)++; continue; }
            (*iseq)++; (*icig)++; (*iref)++;
            return BAM_CMATCH;
        }
        if (cig == BAM_CDEL || cig == BAM_CREF_SKIP) { (*cigar)++; (*iref) += ncig; *icig = -1; continue; }
        if (cig == BAM_CINS) { (*cigar)++; *iseq += ncig; *icig = -1; continue; }
        if (cig == BAM_CSOFT_CLIP) { (*cigar)++; *iseq += ncig; *icig = -1; continue; }
        if (cig == BAM_CHARD_CLIP || cig == BAM_CPAD) { (*cigar)++; *icig = -1; continue; }
        log_error("cigar_iref2iseq_next", "Unexpected cigar %d", cig);
        return -2;
    }
    *iseq = -1; *iref = -1;
    return -1;
}

int tweak_overlap_quality(bam1_t *a, bam1_t *b) {
    const uint32_t *a_cigar = bam_get_cigar(a), *a_cigar_max = a_cigar + a->core.n_cigar;
    const uint32_t *b_cigar = bam_get_cigar(b), *b_cigar_max = b_cigar + b->core.n_cigar;
    int64_t a_icig = 0, a_iseq = 0, b_icig = 0, b_iseq = 0;
    uint8_t *a_qual = bam_get_qual(a), *b_qual = bam_get_qual(b);
    uint8_t *a_seq = bam_get_seq(a), *b_seq = bam_get_seq(b);
    int64_t iref = b->core.pos;
    int64_t a_iref = iref - a->core.pos, b_iref = iref - b->core.pos;
    int a_ret = cigar_iref2iseq_set(&a_cigar, a_cigar_max, &a_icig, &a_iseq, &a_iref);
    if (a_ret < 0) return a_ret + 1;
    int b_ret = cigar_iref2iseq_set(&b_cigar, b_cigar_max, &b_icig, &b_iseq, &b_iref);
    if (b_ret < 0) return b_ret + 1;
    uint8_t amul, bmul;
    if (hts_hash_Wang(hts_str_hash_X31(bam_get_qname(a))) & 1) { amul = 1; bmul = 0; } else { amul = 0; bmul = 1; }
    int err = 0;
    while (1) {
        while (a_ret >= 0 && a_iref >= 0 && a_iref < iref - a->core.pos) a_ret = cigar_iref2iseq_next(&a_cigar, a_cigar_max, &a_icig, &a_iseq, &a_iref);
        if (a_ret < 0) { err = a_ret < -1 ? -1 : 0; break; }
        if (iref < a_iref + a->core.pos) iref = a_iref + a->core.pos;
        while (b_ret >= 0 && b_iref >= 0 && b_iref < iref - b->core.pos) b_ret = cigar_iref2iseq_next(&b_cigar, b_cigar_max, &b_icig, &b_iseq, &b_iref);
        if (b_ret < 0) { err = b_ret < -1 ? -1 : 0; break; }
        if (iref < b_iref + b->core.pos) iref = b_iref + b->core.pos;
        iref++;
        if (a_iref + a->core.pos != b_iref + b->core.pos) continue;
        if (a_iseq > a->core.l_qseq || b_iseq > b->core.l_qseq) return -1;
        if (bam_seqi(a_seq, a_iseq) == bam_seqi(b_seq, b_iseq)) {
            int qual = a_qual[a_iseq] + b_qual[b_iseq];
            a_qual[a_iseq] = amul * (qual > 200 ? 200 : qual);
            b_qual[b_iseq] = bmul * (qual > 200 ? 200 : qual);
        } else {
            if (a_qual[a_iseq] > b_qual[b_iseq]) { a_qual[a_iseq] = (uint8_t)(0.8 * a_qual[a_iseq]); b_qual[b_iseq] = 0; }
            else if (a_qual[a_iseq] < b_qual[b_iseq]) { b_qual[b_iseq] = (uint8_t)(0.8 * b_qual[b_iseq]); a_qual[a_iseq] = 0; }
            else { a_qual[a_iseq] = (uint8_t)(amul * 0.8 * a_qual[a_iseq]); b_qual[b_iseq] = (uint8_t)(bmul * 0.8 * b_qual[b_iseq]); }
        }
    }
    return err;
}

static int overlap_push(bam_plp_t iter, lbnode_t *node) {
    if (!iter->overlaps) return 0;
    if ((node->b.core.flag & BAM_FMUNMAP) || !(node->b.core.flag & BAM_FPROPER_PAIR)) return 0;
    if ((node->b.core.tid != node->b.core.mtid) || (llabs((long long)node->b.core.isize) >= 2 * node->b.core.l_qseq && node->b.core.mpos >= node->end)) return 0;
    strmap_t *m = (strmap_t*)iter->overlaps;
    strmap_entry_t *e = strmap_find(m, bam_get_qname(&node->b));
    if (!e) {
        if (node->b.core.mpos >= node->b.core.pos || ((node->b.core.flag & BAM_FPAIRED) && node->b.core.mpos == -1)) {
            strmap_entry_t *x = strmap_put(m, bam_get_qname(&node->b), NULL);
            x->ptr = node;
        }
    } else {
        lbnode_t *a = (lbnode_t*)e->ptr;
        int err = tweak_overlap_quality(&a->b, &node->b);
        strmap_del(m, bam_get_qname(&node->b));
        return err;
    }
    return 0;
}

static void overlap_remove(bam_plp_t iter, const bam1_t *b) {
    if (!iter->overlaps) return;
    strmap_t *m = (strmap_t*)iter->overlaps;
    strmap_entry_t *e = strmap_find(m, bam_get_qname(b));
    if (e && e->ptr && &((lbnode_t*)e->ptr)->b == b) strmap_del(m, bam_get_qname(b));
}

/* ---- cigar resolution ---- */
#define _cop(c) ((c)&BAM_CIGAR_MASK)
#define _cln(c) ((c)>>BAM_CIGAR_SHIFT)

static inline int resolve_cigar2(bam_pileup1_t *p, int64_t pos, cstate_t *s) {
    bam1_t *b = p->b; bam1_core_t *c = &b->core;
    uint32_t *cigar = bam_get_cigar(b);
    int k;
    if (s->k == -1) {
        p->qpos = 0;
        if (c->n_cigar == 1) {
            if (_cop(cigar[0]) == BAM_CMATCH || _cop(cigar[0]) == BAM_CEQUAL || _cop(cigar[0]) == BAM_CDIFF) s->k = 0, s->x = c->pos, s->y = 0;
        } else {
            for (k = 0, s->x = c->pos, s->y = 0; k < (int)c->n_cigar; ++k) {
                int op = _cop(cigar[k]); int l = _cln(cigar[k]);
                if (op == BAM_CMATCH || op == BAM_CDEL || op == BAM_CEQUAL || op == BAM_CDIFF || op == BAM_CREF_SKIP) break;
                else if (op == BAM_CINS || op == BAM_CSOFT_CLIP) s->y += l;
            }
            s->k = k;
        }
        if (s->k < 0 || s->k >= (int)c->n_cigar) return 0;
    } else {
        int op, l = _cln(cigar[s->k]);
        if (pos - s->x >= l) {
            if (s->k + 1 >= (int)c->n_cigar) return 0;
            op = _cop(cigar[s->k+1]);
            if (op == BAM_CMATCH || op == BAM_CDEL || op == BAM_CEQUAL || op == BAM_CDIFF || op == BAM_CREF_SKIP) {
                if (_cop(cigar[s->k]) == BAM_CMATCH || _cop(cigar[s->k]) == BAM_CEQUAL || _cop(cigar[s->k]) == BAM_CDIFF) s->y += l;
                s->x += l; ++s->k;
            } else {
                if (_cop(cigar[s->k]) == BAM_CMATCH || _cop(cigar[s->k]) == BAM_CEQUAL || _cop(cigar[s->k]) == BAM_CDIFF) s->y += l;
                s->x += l;
                for (k = s->k + 1; k < (int)c->n_cigar; ++k) {
                    op = _cop(cigar[k]), l = _cln(cigar[k]);
                    if (op == BAM_CMATCH || op == BAM_CDEL || op == BAM_CEQUAL || op == BAM_CDIFF || op == BAM_CREF_SKIP) break;
                    else if (op == BAM_CINS || op == BAM_CSOFT_CLIP) s->y += l;
                }
                s->k = k;
            }
            if (s->k >= (int)c->n_cigar) return 0;
        }
    }
    {
        int op, l;
        op = _cop(cigar[s->k]); l = _cln(cigar[s->k]);
        p->is_del = p->indel = p->is_refskip = 0;
        if (s->x + l - 1 == pos && s->k + 1 < (int)c->n_cigar) {
            int op2 = _cop(cigar[s->k+1]); int l2 = _cln(cigar[s->k+1]);
            if (op2 == BAM_CDEL && op != BAM_CDEL) {
                p->indel = -(int)l2;
                for (k = s->k + 2; k < (int)c->n_cigar; ++k) {
                    op2 = _cop(cigar[k]); l2 = _cln(cigar[k]);
                    if (op2 == BAM_CDEL) p->indel -= l2; else break;
                }
            } else if (op2 == BAM_CINS) {
                p->indel = l2;
                for (k = s->k + 2; k < (int)c->n_cigar; ++k) {
                    op2 = _cop(cigar[k]); l2 = _cln(cigar[k]);
                    if (op2 == BAM_CINS) p->indel += l2; else if (op2 != BAM_CPAD) break;
                }
            } else if (op2 == BAM_CPAD && s->k + 2 < (int)c->n_cigar) {
                int l3 = 0;
                for (k = s->k + 2; k < (int)c->n_cigar; ++k) {
                    op2 = _cop(cigar[k]); l2 = _cln(cigar[k]);
                    if (op2 == BAM_CINS) l3 += l2;
                    else if (op2 == BAM_CDEL || op2 == BAM_CMATCH || op2 == BAM_CREF_SKIP || op2 == BAM_CEQUAL || op2 == BAM_CDIFF) break;
                }
                if (l3 > 0) p->indel = l3;
            }
        }
        if (op == BAM_CMATCH || op == BAM_CEQUAL || op == BAM_CDIFF) p->qpos = (int32_t)(s->y + (pos - s->x));
        else if (op == BAM_CDEL || op == BAM_CREF_SKIP) { p->qpos = (int32_t)s->y; p->is_del = 1; p->is_refskip = (op == BAM_CREF_SKIP); }
        p->is_head = (pos == c->pos); p->is_tail = (pos == s->end);
    }
    p->cigar_ind = s->k;
    return 1;
}

int bam_plp_push(bam_plp_t iter, const bam1_t *b) {
    if (iter->error) return -1;
    if (b) {
        if (b->core.tid < 0) { overlap_remove(iter, b); return 0; }
        if (b->core.flag & BAM_FUNMAP) { overlap_remove(iter, b); return 0; }
        if (iter->plp_construct) { if (iter->plp_construct(iter->data, b, &iter->tail->cd) < 0) { overlap_remove(iter, b); return 0; } }
        if (iter->tid == b->core.tid && iter->pos == b->core.pos && iter->cnt > iter->maxcnt) { overlap_remove(iter, b); if (iter->plp_destruct) iter->plp_destruct(iter->data, b, &iter->tail->cd); return 0; }
        if (bam_copy1(&iter->tail->b, b) == NULL) return -1;
        iter->tail->b.id = iter->id++;
        iter->tail->beg = b->core.pos;
        iter->tail->end = b->core.pos + bam_cigar2rlen(b->core.n_cigar, bam_get_cigar(b));
        iter->tail->s.k = -1; iter->tail->s.x = iter->tail->s.y = 0; iter->tail->s.end = iter->tail->end - 1;
        if (b->core.tid < iter->max_tid) { log_error("bam_plp_push", "The input is not sorted (chromosomes out of order)"); iter->error = 1; return -1; }
        if ((b->core.tid == iter->max_tid) && (iter->tail->beg < iter->max_pos)) { log_error("bam_plp_push", "The input is not sorted (reads out of order)"); iter->error = 1; return -1; }
        iter->max_tid = b->core.tid; iter->max_pos = iter->tail->beg;
        if (iter->tail->end > iter->pos || iter->tail->b.core.tid > iter->tid) {
            lbnode_t *next = node_alloc();
            if (overlap_push(iter, iter->tail) < 0) { iter->error = 1; node_free(next); return -1; }
            iter->tail->next = next; iter->tail = next;
            iter->cnt++;
        } else {
            /* read entirely before current position: dropped */
            if (iter->plp_destruct) iter->plp_destruct(iter->data, &iter->tail->b, &iter->tail->cd);
        }
    } else iter->is_eof = 1;
    return 0;
}

const bam_pileup1_t *bam_plp_next(bam_plp_t iter, int *_tid, int64_t *_pos, int *_n_plp) {
    if (iter->error) { *_n_plp = -1; return NULL; }
    *_n_plp = 0;
    if (iter->is_eof && iter->head == iter->tail) return NULL;
    while (iter->is_eof || iter->max_tid > iter->tid || (iter->max_tid == iter->tid && iter->max_pos > iter->pos)) {
        int n_plp = 0;
        lbnode_t **pptr = &iter->head;
        while (*pptr != iter->tail) {
            lbnode_t *p = *pptr;
            if (p->b.core.tid < iter->tid || (p->b.core.tid == iter->tid && p->end <= iter->pos)) {
                overlap_remove(iter, &p->b);
                if (iter->plp_destruct) iter->plp_destruct(iter->data, &p->b, &p->cd);
                *pptr = p->next; node_free(p); iter->cnt--;
            } else {
                if (p->b.core.tid == iter->tid && p->beg <= iter->pos) {
                    if (n_plp == iter->max_plp) {
                        iter->max_plp = iter->max_plp ? iter->max_plp << 1 : 256;
                        iter->plp = realloc(iter->plp, sizeof(bam_pileup1_t) * iter->max_plp);
                    }
                    iter->plp[n_plp].b = &p->b;
                    iter->plp[n_plp].cd = p->cd;
                    if (resolve_cigar2(iter->plp + n_plp, iter->pos, &p->s)) ++n_plp;
                }
                pptr = &(*pptr)->next;
            }
        }
        *_n_plp = n_plp; *_tid = iter->tid; *_pos = iter->pos;
        if (iter->head != iter->tail) {
            if (iter->tid > iter->head->b.core.tid) { log_error("bam_plp_next", "Unsorted input. Pileup aborts."); iter->error = 1; *_n_plp = -1; return NULL; }
            if (iter->tid < iter->head->b.core.tid) { iter->tid = iter->head->b.core.tid; iter->pos = iter->head->beg; }
            else if (iter->pos < iter->head->beg) iter->pos = iter->head->beg;
            else ++iter->pos;
        }
        if (n_plp) return iter->plp;
        if (iter->is_eof && iter->head == iter->tail) break;
    }
    return NULL;
}

const bam_pileup1_t *bam_plp_auto(bam_plp_t iter, int *_tid, int64_t *_pos, int *_n_plp) {
    const bam_pileup1_t *plp;
    if (iter->func == 0 || iter->error) { *_n_plp = -1; return 0; }
    if ((plp = bam_plp_next(iter, _tid, _pos, _n_plp)) != 0) return plp;
    else {
        *_n_plp = 0;
        if (iter->is_eof) return 0;
        int ret;
        while ((ret = iter->func(iter->data, iter->tmp)) >= 0) {
            if (bam_plp_push(iter, iter->tmp) < 0) { *_n_plp = -1; return 0; }
            if ((plp = bam_plp_next(iter, _tid, _pos, _n_plp)) != 0) return plp;
            if (iter->is_eof) return 0;
        }
        if (ret < -1) { iter->error = ret; *_n_plp = -1; return 0; }
        if (!iter->is_eof) { bam_plp_push(iter, 0); }
        if ((plp = bam_plp_next(iter, _tid, _pos, _n_plp)) != 0) return plp;
        return 0;
    }
}

int bam_plp_insertion(const bam_pileup1_t *p, kstring_t *ins, int *del_len) {
    int j, k, indel = p->indel;
    uint32_t *cigar;
    if (p->indel <= 0) { if (del_len) *del_len = 0; ins->l = 0; if (ins->s) ins->s[0] = 0; return 0; }
    if (del_len) *del_len = 0;
    ins->l = 0;
    cigar = bam_get_cigar(p->b);
    for (k = p->cigar_ind + 1; k < (int)p->b->core.n_cigar && indel > 0; k++) {
        int op = bam_cigar_op(cigar[k]); int len = bam_cigar_oplen(cigar[k]);
        if (op == BAM_CINS) {
            uint8_t *seq = bam_get_seq(p->b);
            int qpos = p->qpos + 1 + (int)ins->l; /* approximate: track consumed */
            (void)qpos;
            for (j = 0; j < len; j++) kputc(seq_nt16_str[bam_seqi(seq, p->qpos + 1 + j + (int)(ins->l - ins->l))], ins);
            indel -= len;
        } else if (op == BAM_CPAD) {
            for (j = 0; j < len; j++) kputc('*', ins);
            indel -= len;
        } else if (op == BAM_CDEL) {
            if (del_len) *del_len = len;
            break;
        } else break;
    }
    return (int)ins->l;
}

/* ---- multi ---- */
bam_mplp_t bam_mplp_init(int n, bam_plp_auto_f func, void **data) {
    bam_mplp_t iter = calloc(1, sizeof(struct bam_mplp_s));
    iter->pos = calloc(n, sizeof(int64_t)); iter->tid = calloc(n, sizeof(int32_t));
    iter->n_plp = calloc(n, sizeof(int)); iter->plp = calloc(n, sizeof(bam_pileup1_t*));
    iter->iter = calloc(n, sizeof(bam_plp_t));
    iter->n = n; iter->min_pos = (int64_t)1 << 62; iter->min_tid = (1 << 30);
    for (int i = 0; i < n; i++) { iter->iter[i] = bam_plp_init(func, data[i]); iter->pos[i] = iter->min_pos; iter->tid[i] = iter->min_tid; }
    return iter;
}
void bam_mplp_init_overlaps(bam_mplp_t iter) { for (int i = 0; i < iter->n; i++) bam_plp_init_overlaps(iter->iter[i]); }
void bam_mplp_set_maxcnt(bam_mplp_t iter, int maxcnt) { for (int i = 0; i < iter->n; i++) iter->iter[i]->maxcnt = maxcnt; }
void bam_mplp_constructor(bam_mplp_t iter, bam_plp_callback_f func) { for (int i = 0; i < iter->n; i++) bam_plp_constructor(iter->iter[i], func); }
void bam_mplp_destructor(bam_mplp_t iter, bam_plp_callback_f func) { for (int i = 0; i < iter->n; i++) bam_plp_destructor(iter->iter[i], func); }
void bam_mplp_destroy(bam_mplp_t iter) {
    if (!iter) return;
    for (int i = 0; i < iter->n; i++) bam_plp_destroy(iter->iter[i]);
    free(iter->iter); free(iter->pos); free(iter->tid); free(iter->n_plp); free(iter->plp); free(iter);
}

int bam_mplp_auto(bam_mplp_t iter, int *_tid, int64_t *_pos, int *n_plp, const bam_pileup1_t **plp) {
    int i, ret = 0;
    int64_t new_min_pos = (int64_t)1 << 62; int32_t new_min_tid = (1 << 30);
