#include "baq.h"
#include "log.h"
#include <math.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>

const probaln_par_t probaln_par_def = { 0.001, 0.1, 7 };

#define EI .25
#define EM .33333333333
