    for (i = 1; i <= l_query; ++i) {
        double sum = 0., *fi = f[i], *bi = b[i], max = 0.;
        int beg = 1, end = l_ref, x, max_k = -1;
        x = i - bw; beg = beg > x ? beg : x;
        x = i + bw; end = end < x ? end : x;
        for (k = beg; k <= end; ++k) {
            int u;
            double z;
            set_u(u, bw, i, k);
            z = fi[u+0] * bi[u+0]; if (z > max) max = z, max_k = (k-1) << 2 | 0; sum += z;
