                int op = cigar[k] & 0xf, l = cigar[k] >> 4;
                if (op == BAM_CMATCH || op == BAM_CEQUAL || op == BAM_CDIFF) {
                    for (i = y; i < y + l; ++i) {
                        if ((state[i] & 3) != 0 || state[i] >> 2 != x - xb + (i - y)) bqa[i] = 0;
                        else bqa[i] = qual[i] < q[i] ? qual[i] : q[i];
                    }
                    x += l; y += l;
                } else if (op == BAM_CSOFT_CLIP || op == BAM_CINS) y += l;
                else if (op == BAM_CDEL) x += l;
            }
            for (i = 0; i < c->l_qseq; ++i) bqa[i] = qual[i] - bqa[i] + 64;
        } else {
            uint8_t *left, *rght;
            left = calloc(c->l_qseq, 1); rght = calloc(c->l_qseq, 1);
            for (k = 0, x = c->pos, y = 0; k < (int)c->n_cigar; ++k) {
                int op = cigar[k] & 0xf, l = cigar[k] >> 4;
                if (op == BAM_CMATCH || op == BAM_CEQUAL || op == BAM_CDIFF) {
                    for (i = y; i < y + l; ++i) bqa[i] = ((state[i] & 3) != 0 || state[i] >> 2 != x - xb + (i - y)) ? 0 : q[i];
                    for (left[y] = bqa[y], i = y + 1; i < y + l; ++i) left[i] = bqa[i] > left[i-1] ? bqa[i] : left[i-1];
                    for (rght[y+l-1] = bqa[y+l-1], i = y + l - 2; i >= y; --i) rght[i] = bqa[i] > rght[i+1] ? bqa[i] : rght[i+1];
                    for (i = y; i < y + l; ++i) bqa[i] = left[i] < rght[i] ? left[i] : rght[i];
                    x += l; y += l;
                } else if (op == BAM_CSOFT_CLIP || op == BAM_CINS) y += l;
                else if (op == BAM_CDEL) x += l;
            }
            for (i = 0; i < c->l_qseq; ++i) bqa[i] = 64 + (qual[i] <= bqa[i] ? 0 : qual[i] - bqa[i]);
            free(left); free(rght);
        }
        if (apply_baq) {
            for (i = 0; i < c->l_qseq; ++i) qual[i] -= bqa[i] - 64;
            bam_aux_append(b, "ZQ", 'Z', c->l_qseq + 1, bqa);
        } else bam_aux_append(b, "BQ", 'Z', c->l_qseq + 1, bqa);
        free(bqa); free(s); free(r); free(q); free(state);
    }
    return 0;
}

int sam_cap_mapq(bam1_t *b, const char *ref, int64_t ref_len, int thres) {
    uint8_t *seq = bam_get_seq(b), *qual = bam_get_qual(b);
    uint32_t *cigar = bam_get_cigar(b);
    bam1_core_t *c = &b->core;
    int k, y, mm, q, len, clip_l, clip_q;
    int64_t i, x;
    double t;
    if (thres < 0) thres = 40;
    mm = q = len = clip_l = clip_q = 0;
    for (k = 0, x = c->pos, y = 0; k < (int)c->n_cigar; ++k) {
        int op = cigar[k] & 0xf, l = cigar[k] >> 4;
        if (op == BAM_CMATCH || op == BAM_CEQUAL || op == BAM_CDIFF) {
            for (i = 0; i < l; ++i) {
                int c1, c2, z = (int)(y + i);
                if (x + i >= ref_len || ref[x+i] == '\0') break;
                c1 = bam_seqi(seq, z), c2 = seq_nt16_table[(int)ref[x+i]];
                if (c2 != 15 && c1 != 15) {
                    ++len;
                    if (c1 && c1 != c2 && qual[z] >= 13) { ++mm; q += qual[z] > 33 ? 33 : qual[z]; }
                }
            }
            if (i < l) break;
            x += l; y += l; len += l;
        } else if (op == BAM_CDEL) {
            for (i = 0; i < l; ++i) if (x + i >= ref_len || ref[x+i] == '\0') break;
            if (i < l) break;
            x += l;
        } else if (op == BAM_CSOFT_CLIP) {
            clip_l += l;
            for (i = 0; i < l; ++i) clip_q += qual[y+i];
            y += l;
        } else if (op == BAM_CHARD_CLIP) {
            clip_l += l;
            for (i = 0; i < l; ++i) clip_q += 13;
        } else if (op == BAM_CINS) y += l;
        else if (op == BAM_CREF_SKIP) x += l;
    }
    (void)clip_l; (void)clip_q;
    /* heuristic from htslib */
    t = 0; for (i = 0, t = 1; i < mm; ++i) t *= (double)len / (i + 1);
    t = (double)q - 4.343 * log(t) - thres;
    if (t > 0) { (void)0; }
    return (int)(q - 4.343 * log(t > 0 ? 1 : 1)) >= 0 ? (int)(t > 0 ? (int)(c->qual < t ? c->qual : t) : c->qual) : -1;
}
