    bed_t *bed;
    strmap_t *rghash;
    int print_cols; char **tags; int n_tags;
    char sep, empty;
    FILE *out;
} mplp_conf_t;

typedef struct {
    samfile_t *fp;
    hts_itr_t *iter;
    sam_hdr_t *h;
    mplp_conf_t *conf;
    char *ref; int ref_id; int64_t ref_len;
    hts_idx_t *idx;
} mplp_aux_t;

static int mplp_get_ref(mplp_aux_t *ma, int tid, char **ref, int64_t *ref_len) {
    mplp_conf_t *conf = ma->conf;
    if (!conf->fai) { *ref = NULL; return 0; }
    if (ma->ref_id == tid) { *ref = ma->ref; *ref_len = ma->ref_len; return 1; }
    free(ma->ref); ma->ref = NULL; ma->ref_id = tid;
    int64_t len;
    ma->ref = faidx_fetch_seq64(conf->fai, sam_hdr_tid2name(ma->h, tid), 0, INT32_MAX, &len);
    if (!ma->ref) { ma->ref_len = 0; *ref = NULL; *ref_len = 0; return 0; }
    ma->ref_len = len;
    *ref = ma->ref; *ref_len = len;
    return 1;
}

static int mplp_func(void *data, bam1_t *b) {
    mplp_aux_t *ma = data;
    int ret, skip = 0;
    char *ref; int64_t ref_len;
    do {
        int has_ref;
        ret = ma->iter ? sam_itr_next(ma->fp, ma->iter, b) : sam_read1(ma->fp, ma->h, b);
        if (ret < 0) break;
        if (b->core.tid < 0 || (b->core.flag & BAM_FUNMAP)) { skip = 1; continue; }
        if (ma->conf->rflag_require && !(ma->conf->rflag_require & b->core.flag)) { skip = 1; continue; }
        if (ma->conf->rflag_filter && (ma->conf->rflag_filter & b->core.flag)) { skip = 1; continue; }
        if (ma->conf->bed && ma->conf->all == 0) {
            skip = !bed_overlap(ma->conf->bed, sam_hdr_tid2name(ma->h, b->core.tid), b->core.pos, bam_endpos(b));
            if (skip) continue;
        }
        if (ma->conf->rghash) {
            uint8_t *rg = bam_aux_get(b, "RG");
            skip = (rg && strmap_find(ma->conf->rghash, (char*)rg + 1) != NULL);
            if (skip) continue;
        }
        if (ma->conf->flag & MPLP_ILLUMINA13) {
            uint8_t *qual = bam_get_qual(b);
            for (int i = 0; i < b->core.l_qseq; ++i) qual[i] = qual[i] > 31 ? qual[i] - 31 : 0;
        }
        if (ma->conf->fai && b->core.tid >= 0) {
            has_ref = mplp_get_ref(ma, b->core.tid, &ref, &ref_len);
            if (has_ref && ref_len <= b->core.pos) {
                fprintf(stderr, "[%s] Skipping because %lld is outside of %lld [ref:%d]\n", "mplp_func", (long long)b->core.pos, (long long)ref_len, b->core.tid);
                skip = 1; continue;
            }
        } else has_ref = 0;
        skip = 0;
        if (has_ref && (ma->conf->flag & MPLP_REALN)) sam_prob_realn(b, ref, ref_len, (ma->conf->flag & MPLP_REDO_BAQ) ? 7 : 3);
        if (has_ref && ma->conf->capQ_thres > 10) {
            int q = sam_cap_mapq(b, ref, ref_len, ma->conf->capQ_thres);
            if (q < 0) skip = 1;
            else if (b->core.qual > q) b->core.qual = q;
        }
        if (b->core.qual < ma->conf->min_mq) skip = 1;
        else if ((ma->conf->flag & MPLP_NO_ORPHAN) && (b->core.flag & BAM_FPAIRED) && !(b->core.flag & BAM_FPROPER_PAIR)) skip = 1;
    } while (skip);
    return ret;
}

static void printw(int c, FILE *fp) { char buf[16]; int l, x; if (c == 0) { fputc('0', fp); return; } for (l = 0, x = c < 0 ? -c : c; x > 0; x /= 10) buf[l++] = (char)(x % 10 + '0'); if (c < 0) buf[l++] = '-'; buf[l] = 0; for (x = 0; x < l / 2; ++x) { int y = buf[x]; buf[x] = buf[l-1-x]; buf[l-1-x] = (char)y; } fputs(buf, fp); }

static int pileup_seq(FILE *fp, const bam_pileup1_t *p, int64_t pos, int64_t ref_len, const char *ref, kstring_t *ks, mplp_conf_t *conf) {
    int j;
    if (!conf->no_ends && p->is_head) { putc('^', fp); putc(p->b->core.qual > 93 ? 126 : p->b->core.qual + 33, fp); }
    if (!p->is_del) {
        int c = p->qpos < p->b->core.l_qseq ? seq_nt16_str[bam_seqi(bam_get_seq(p->b), p->qpos)] : 'N';
        if (ref) {
            int rb = pos < ref_len ? ref[pos] : 'N';
            if (c == '=' || seq_nt16_table[c] == seq_nt16_table[rb]) c = bam_is_rev(p->b) ? ',' : '.';
            else c = bam_is_rev(p->b) ? tolower(c) : toupper(c);
        } else {
            if (c == '=') c = bam_is_rev(p->b) ? ',' : '.';
            else c = bam_is_rev(p->b) ? tolower(c) : toupper(c);
        }
        putc(c, fp);
    } else putc(p->is_refskip ? (bam_is_rev(p->b) ? '<' : '>') : (conf->rev_del && bam_is_rev(p->b) ? '#' : '*'), fp);
    int del_len = -p->indel;
    if (p->indel > 0) {
        int len = bam_plp_insertion(p, ks, &del_len);
        if (len < 0) return -1;
        if (conf->no_ins < 2) { putc('+', fp); printw(len, fp); }
        if (conf->no_ins == 0) for (j = 0; j < (int)ks->l; j++) putc(bam_is_rev(p->b) ? tolower(ks->s[j]) : toupper(ks->s[j]), fp);
    }
    if (del_len > 0) {
        if (conf->no_del < 2) printw(-del_len, fp);
        if (conf->no_del == 0) for (j = 1; j <= del_len; ++j) { int c = (ref && pos + j < ref_len) ? ref[pos+j] : 'N'; putc(bam_is_rev(p->b) ? tolower(c) : toupper(c), fp); }
    }
    if (!conf->no_ends && p->is_tail) putc('$', fp);
