static int read_file_list(const char *fn, int *n, char ***files) {
    textfile_t *t = text_open(fn);
    if (!t) return -1;
    int m = 0; *n = 0; *files = NULL;
    while (text_getline(t) >= 0) {
        char *s = t->line; while (*s == ' ' || *s == '\t') s++;
        char *e = s + strlen(s); while (e > s && (e[-1] == ' ' || e[-1] == '\t' || e[-1] == '\r')) *--e = 0;
        if (!*s || *s == '#') continue;
        if (*n == m) { m = m ? m * 2 : 8; *files = realloc(*files, m * sizeof(char*)); }
        (*files)[(*n)++] = strdup(s);
    }
    text_close(t);
    return 0;
}

static int mpileup(mplp_conf_t *conf, int n, char **fn, char **fn_idx) {
    mplp_aux_t **data = calloc(n, sizeof(mplp_aux_t*));
    sam_hdr_t *h = NULL;
    int tid0 = 0; int64_t beg0 = 0, end0 = INT64_MAX;
    int ret = 0;
    strmap_t *samples = strmap_new();
    int nsamp = 0;
    for (int i = 0; i < n; i++) {
        data[i] = calloc(1, sizeof(mplp_aux_t));
        data[i]->fp = sam_open_read_nohdr(fn[i]);
        if (!data[i]->fp) {
            log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn[i], strerror(errno));
            fprintf(stderr, "[%s] failed to open %s: %s\n", "mpileup", fn[i], strerror(errno));
            ret = 1; goto fail;
        }
        if (sam_read_header(data[i]->fp) < 0) { fprintf(stderr, "[%s] fail to read the header of %s\n", "mpileup", fn[i]); ret = 1; goto fail; }
        data[i]->conf = conf; data[i]->ref_id = -1;
        sam_hdr_t *hh = data[i]->fp->hdr;
        data[i]->h = hh;
        /* samples */
        if (conf->flag & MPLP_IGNORE_RG) { nsamp++; }
        else {
            int nrg = 0;
            for (int j = 0; j < hh->n_lines; j++) if (sam_hdr_line_type_is(hh->lines[j], "RG")) {
                char *sm = hdr_line_tag(hh->lines[j], "SM"); char *id = hdr_line_tag(hh->lines[j], "ID");
                const char *name = sm ? sm : id;
                if (name) { int is_new; strmap_put(samples, name, &is_new); if (is_new) nsamp++; }
                free(sm); free(id); nrg++;
            }
            if (nrg == 0) { int is_new; strmap_put(samples, fn[i], &is_new); if (is_new) nsamp++; }
        }
        if (conf->reg) {
            hts_idx_t *idx = NULL;
            if (data[i]->fp->fmt == FMT_BAM && bgzf_is_bgzf(data[i]->fp->bg)) idx = sam_index_load2(fn[i], fn_idx ? fn_idx[i] : NULL);
            if (!idx) {
                if (!fn_idx) log_error("idx_find_and_load", "Could not retrieve index file for '%s'", fn[i]);
                fprintf(stderr, "[%s] fail to load index for %s\n", "mpileup", fn[i]); ret = 1; goto fail;
            }
            int tid; int64_t beg, end;
            if (hts_parse_region(conf->reg, hh, &tid, &beg, &end) < 0 || tid < 0) {
                fprintf(stderr, "[%s] malformatted region or wrong seqname for %s\n", "mpileup", fn[i]); hts_idx_destroy(idx); ret = 1; goto fail;
            }
            if (i == 0) { tid0 = tid; beg0 = beg; end0 = end; }
            data[i]->iter = sam_itr_queryi(idx, tid, beg, end);
            data[i]->idx = idx;
        }
        if (i == 0) h = hh;
    }
    fprintf(stderr, "[%s] %d samples in %d input files\n", "mpileup", nsamp, n);
    FILE *out = conf->out;
    bam_mplp_t iter = bam_mplp_init(n, mplp_func, (void**)data);
    if (conf->flag & MPLP_SMART_OVERLAPS) bam_mplp_init_overlaps(iter);
    bam_mplp_set_maxcnt(iter, conf->max_depth);
    int *n_plp = calloc(n, sizeof(int));
    const bam_pileup1_t **plp = calloc(n, sizeof(bam_pileup1_t*));
    int tid, last_tid = -1; int64_t pos, last_pos = -1;
    char *ref = NULL; int64_t ref_len = 0;
    kstring_t ks = KS_INITIALIZE;
    int r;
    while ((r = bam_mplp_auto(iter, &tid, &pos, n_plp, plp)) > 0) {
        if (conf->reg && (pos < beg0 || pos >= end0)) continue;
        if (conf->bed && tid >= 0 && !bed_overlap(conf->bed, sam_hdr_tid2name(h, tid), pos, pos + 1)) continue;
        mplp_get_ref(data[0], tid, &ref, &ref_len);
        if (conf->all) {
            while (tid > last_tid) {
                if (last_tid >= 0 && !conf->reg) {
                    char *r2 = NULL; int64_t rl2 = 0; mplp_get_ref(data[0], last_tid, &r2, &rl2);
                    while (++last_pos < sam_hdr_tid2len(h, last_tid)) {
                        if (conf->bed && bed_overlap(conf->bed, sam_hdr_tid2name(h, last_tid), last_pos, last_pos + 1) == 0) continue;
                        print_empty_pileup(out, conf, sam_hdr_tid2name(h, last_tid), last_pos, n, r2, rl2);
                    }
                    mplp_get_ref(data[0], tid, &ref, &ref_len);
                }
                last_tid++; last_pos = -1;
                if (conf->all < 2) break;
            }
            while (++last_pos < pos) {
                if (conf->reg && last_pos < beg0) continue;
                if (conf->bed && bed_overlap(conf->bed, sam_hdr_tid2name(h, tid), last_pos, last_pos + 1) == 0) continue;
                print_empty_pileup(out, conf, sam_hdr_tid2name(h, tid), last_pos, n, ref, ref_len);
            }
            last_tid = tid; last_pos = pos;
        }
        fputs(sam_hdr_tid2name(h, tid), out); putc('\t', out); fprintf(out, "%lld", (long long)pos + 1); putc('\t', out);
        putc((ref && pos < ref_len) ? ref[pos] : 'N', out);
        for (int i = 0; i < n; ++i) {
            int j, cnt;
            for (j = cnt = 0; j < n_plp[i]; ++j) {
                const bam_pileup1_t *p = plp[i] + j;
                int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                if (c >= conf->min_baseQ) ++cnt;
            }
            fprintf(out, "\t%d\t", cnt);
            if (n_plp[i] == 0) {
                fputs("*\t*", out);
                int ne = n_extra_cols(conf);
                for (j = 0; j < ne; j++) fputs("\t*", out);
            } else {
                int nn = 0;
                for (j = 0; j < n_plp[i]; ++j) {
                    const bam_pileup1_t *p = plp[i] + j;
                    int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                    if (c >= conf->min_baseQ) { nn++; pileup_seq(out, p, pos, ref_len, ref, &ks, conf); }
                }
                if (!nn) putc('*', out);
                putc('\t', out);
                nn = 0;
                for (j = 0; j < n_plp[i]; ++j) {
                    const bam_pileup1_t *p = plp[i] + j;
                    int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                    if (c >= conf->min_baseQ) { nn++; c = c + 33 < 126 ? c + 33 : 126; putc(c, out); }
                }
                if (!nn) putc('*', out);
                if (conf->flag & MPLP_PRINT_MAPQ) {
                    putc('\t', out); nn = 0;
                    for (j = 0; j < n_plp[i]; ++j) {
                        const bam_pileup1_t *p = plp[i] + j;
                        int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                        if (c < conf->min_baseQ) continue;
                        nn++; c = p->b->core.qual + 33; if (c > 126) c = 126; putc(c, out);
                    }
                    if (!nn) putc('*', out);
                }
                if (conf->flag & (MPLP_PRINT_QPOS | MPLP_PRINT_QPOS5)) {
                    putc('\t', out); nn = 0;
                    for (j = 0; j < n_plp[i]; ++j) {
                        const bam_pileup1_t *p = plp[i] + j;
                        int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                        if (c < conf->min_baseQ) continue;
                        if (nn > 0) putc(conf->sep, out);
                        nn++;
                        int qp;
                        if (conf->flag & MPLP_PRINT_QPOS5) qp = bam_is_rev(p->b) ? p->b->core.l_qseq - p->qpos : p->qpos + 1;
                        else qp = p->qpos + 1;
                        fprintf(out, "%d", qp);
                    }
                    if (!nn) putc('*', out);
                }
                if (conf->flag & MPLP_PRINT_QNAME) {
                    putc('\t', out); nn = 0;
                    for (j = 0; j < n_plp[i]; ++j) {
                        const bam_pileup1_t *p = plp[i] + j;
                        int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                        if (c < conf->min_baseQ) continue;
                        if (nn > 0) putc(conf->sep, out);
                        nn++; fputs(bam_get_qname(p->b), out);
                    }
                    if (!nn) putc('*', out);
                }
                for (int col = 0; col < 7; col++) {
                    if (!(conf->print_cols & (1 << col))) continue;
                    putc('\t', out); nn = 0;
                    for (j = 0; j < n_plp[i]; ++j) {
                        const bam_pileup1_t *p = plp[i] + j;
                        int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                        if (c < conf->min_baseQ) continue;
                        if (nn > 0) putc(conf->sep, out);
                        nn++;
                        switch (1 << col) {
                        case COL_QNAME: fputs(bam_get_qname(p->b), out); break;
                        case COL_FLAG: fprintf(out, "%d", p->b->core.flag); break;
                        case COL_RNAME: fputs(sam_hdr_tid2name(h, p->b->core.tid), out); break;
                        case COL_POS: fprintf(out, "%lld", (long long)p->b->core.pos + 1); break;
                        case COL_MAPQ: fprintf(out, "%d", p->b->core.qual); break;
                        case COL_RNEXT: fputs(p->b->core.mtid >= 0 ? sam_hdr_tid2name(h, p->b->core.mtid) : "*", out); break;
                        case COL_PNEXT: fprintf(out, "%lld", (long long)p->b->core.mpos + 1); break;
                        }
                    }
                    if (!nn) putc('*', out);
                }
                for (int t = 0; t < conf->n_tags; t++) {
                    putc('\t', out); nn = 0;
                    for (j = 0; j < n_plp[i]; ++j) {
                        const bam_pileup1_t *p = plp[i] + j;
                        int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                        if (c < conf->min_baseQ) continue;
                        if (nn > 0) putc(conf->sep, out);
                        nn++; print_aux_col(out, p->b, conf->tags[t], conf);
                    }
                    if (!nn) putc('*', out);
                }
            }
        }
        putc('\n', out);
    }
    if (r < 0) { fprintf(stderr, "[%s] error reading from input file\n", "mpileup"); ret = 1; }
    if (conf->all && ret == 0) {
        if (last_tid < 0 && conf->reg && conf->all > 1) { last_tid = tid0; last_pos = beg0 - 1; mplp_get_ref(data[0], tid0, &ref, &ref_len); }
        while (last_tid >= 0 && last_tid < h->n_targets) {
            mplp_get_ref(data[0], last_tid, &ref, &ref_len);
            while (++last_pos < sam_hdr_tid2len(h, last_tid)) {
                if (last_pos >= end0) break;
                if (conf->bed && bed_overlap(conf->bed, sam_hdr_tid2name(h, last_tid), last_pos, last_pos + 1) == 0) continue;
                print_empty_pileup(out, conf, sam_hdr_tid2name(h, last_tid), last_pos, n, ref, ref_len);
            }
            last_tid++; last_pos = -1;
            if (conf->all < 2 || conf->reg) break;
        }
    }
    free(ks.s);
    bam_mplp_destroy(iter);
    free(n_plp); free(plp);
fail:
    for (int i = 0; i < n; i++) {
        if (!data[i]) continue;
        if (data[i]->iter) hts_itr_destroy(data[i]->iter);
        if (data[i]->idx) hts_idx_destroy(data[i]->idx);
        if (data[i]->fp) sam_close(data[i]->fp);
        free(data[i]->ref); free(data[i]);
    }
    free(data); strmap_free(samples);
    return ret;
}

int bam_mpileup(int argc, char **argv) {
    mplp_conf_t mplp; memset(&mplp, 0, sizeof mplp);
    mplp.min_baseQ = 13; mplp.capQ_thres = 0; mplp.max_depth = 8000;
    mplp.flag = MPLP_NO_ORPHAN | MPLP_REALN | MPLP_SMART_OVERLAPS;
    mplp.rflag_filter = BAM_FUNMAP | BAM_FSECONDARY | BAM_FQCFAIL | BAM_FDUP;
    mplp.sep = ','; mplp.empty = '*';
    char *file_list = NULL; int has_index_file = 0; int c;
    static const struct option lopts[] = {
        { "rf", required_argument, NULL, 1 }, { "incl-flags", required_argument, NULL, 1 },
        { "ff", required_argument, NULL, 2 }, { "excl-flags", required_argument, NULL, 2 },
        { "output", required_argument, NULL, 3 }, { "illumina1.3+", no_argument, NULL, '6' }, { "count-orphans", no_argument, NULL, 'A' },
        { "bam-list", required_argument, NULL, 'b' }, { "no-BAQ", no_argument, NULL, 'B' }, { "no-baq", no_argument, NULL, 'B' },
        { "adjust-MQ", required_argument, NULL, 'C' }, { "adjust-mq", required_argument, NULL, 'C' }, { "max-depth", required_argument, NULL, 'd' },
        { "redo-BAQ", no_argument, NULL, 'E' }, { "redo-baq", no_argument, NULL, 'E' }, { "fasta-ref", required_argument, NULL, 'f' },
        { "exclude-RG", required_argument, NULL, 'G' }, { "exclude-rg", required_argument, NULL, 'G' }, { "positions", required_argument, NULL, 'l' },
        { "region", required_argument, NULL, 'r' }, { "ignore-RG", no_argument, NULL, 'R' }, { "ignore-rg", no_argument, NULL, 'R' },
        { "min-MQ", required_argument, NULL, 'q' }, { "min-mq", required_argument, NULL, 'q' }, { "min-BQ", required_argument, NULL, 'Q' }, { "min-bq", required_argument, NULL, 'Q' },
        { "ignore-overlaps", no_argument, NULL, 'x' }, { "ignore-overlaps-removal", no_argument, NULL, 'x' }, { "disable-overlap-removal", no_argument, NULL, 'x' },
        { "output-BP", no_argument, NULL, 'O' }, { "output-bp", no_argument, NULL, 'O' }, { "output-BP-5", no_argument, NULL, 4 }, { "output-bp-5", no_argument, NULL, 4 },
        { "output-mods", no_argument, NULL, 'M' }, { "output-MQ", no_argument, NULL, 's' }, { "output-mq", no_argument, NULL, 's' },
        { "output-QNAME", no_argument, NULL, 5 }, { "output-qname", no_argument, NULL, 5 }, { "output-extra", required_argument, NULL, 6 },
        { "output-sep", required_argument, NULL, 7 }, { "output-empty", required_argument, NULL, 8 },
        { "no-output-ins", no_argument, NULL, 9 }, { "no-output-ins-mods", no_argument, NULL, 10 }, { "no-output-del", no_argument, NULL, 11 }, { "no-output-ends", no_argument, NULL, 12 },
        { "reverse-del", no_argument, NULL, 13 }, { "customized-index", no_argument, NULL, 'X' },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "reference", required_argument, NULL, 1005 }, { "verbosity", required_argument, NULL, 1008 },
        { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "Agf:r:l:q:Q:uRC:BDSd:L:b:P:po:e:h:Im:F:EG:6OsVvxXt:aM", lopts, NULL)) >= 0) {
        switch (c) {
        case 'x': mplp.flag &= ~MPLP_SMART_OVERLAPS; break;
        case 1: mplp.rflag_require = bam_str2flag(optarg); if (mplp.rflag_require < 0) { fprintf(stderr, "Could not parse --rf %s\n", optarg); return 1; } break;
        case 2: mplp.rflag_filter = bam_str2flag(optarg); if (mplp.rflag_filter < 0) { fprintf(stderr, "Could not parse --ff %s\n", optarg); return 1; } break;
        case 3: mplp.output_fname = optarg; break;
        case 'f': mplp.fai_fname = optarg; break;
        case 'd': mplp.max_depth = atoi(optarg); break;
        case 'r': mplp.reg = strdup(optarg); break;
        case 'l': mplp.pl_list = optarg; break;
        case 'G': {
            textfile_t *t = text_open(optarg);
            if (!t) { fprintf(stderr, "[%s] Could not open read group list %s\n", "mpileup", optarg); return 1; }
            mplp.rghash = strmap_new();
            while (text_getline(t) >= 0) { char *e = t->line; while (*e && *e != '\t' && *e != ' ') e++; *e = 0; if (*t->line) strmap_set(mplp.rghash, t->line, 1); }
            text_close(t);
            break;
        }
        case 'q': mplp.min_mq = atoi(optarg); break;
        case 'Q': mplp.min_baseQ = atoi(optarg); break;
        case 'b': file_list = optarg; break;
        case 'o': mplp.output_fname = optarg; break;
        case 'B': mplp.flag &= ~MPLP_REALN; break;
        case 'E': mplp.flag |= MPLP_REDO_BAQ; break;
        case '6': mplp.flag |= MPLP_ILLUMINA13; break;
        case 'R': mplp.flag |= MPLP_IGNORE_RG; break;
        case 's': mplp.flag |= MPLP_PRINT_MAPQ; break;
        case 'O': mplp.flag |= MPLP_PRINT_QPOS; break;
        case 4: mplp.flag |= MPLP_PRINT_QPOS5; break;
        case 5: mplp.flag |= MPLP_PRINT_QNAME; break;
        case 'M': break;
        case 'C': mplp.capQ_thres = atoi(optarg); break;
        case 'A': mplp.flag &= ~MPLP_NO_ORPHAN; break;
        case 'a': mplp.all++; break;
        case 'X': has_index_file = 1; break;
        case 6: {
            char *dup = strdup(optarg), *p = dup;
            while (*p) {
                char *e = strchr(p, ','); if (e) *e = 0;
                if (strcmp(p, "QNAME") == 0) mplp.print_cols |= COL_QNAME;
                else if (strcmp(p, "FLAG") == 0) mplp.print_cols |= COL_FLAG;
                else if (strcmp(p, "RNAME") == 0) mplp.print_cols |= COL_RNAME;
                else if (strcmp(p, "POS") == 0) mplp.print_cols |= COL_POS;
                else if (strcmp(p, "MAPQ") == 0) mplp.print_cols |= COL_MAPQ;
                else if (strcmp(p, "RNEXT") == 0) mplp.print_cols |= COL_RNEXT;
                else if (strcmp(p, "PNEXT") == 0) mplp.print_cols |= COL_PNEXT;
                else if (strlen(p) == 2) { mplp.tags = realloc(mplp.tags, (mplp.n_tags + 1) * sizeof(char*)); mplp.tags[mplp.n_tags++] = strdup(p); }
                else { fprintf(stderr, "Could not parse --output-extra value %s\n", p); free(dup); return 1; }
                if (!e) break; p = e + 1;
            }
            free(dup);
            break;
        }
        case 7: mplp.sep = optarg[0]; break;
        case 8: mplp.empty = optarg[0]; break;
        case 9: mplp.no_ins++; break;
        case 10: mplp.no_ins_mods = 1; break;
        case 11: mplp.no_del++; break;
        case 12: mplp.no_ends = 1; break;
        case 13: mplp.rev_del = 1; break;
        case 1002: case 1005: break;
        case 1008: hts_verbose = atoi(optarg); break;
        case 'g': case 'u': case 'v': case 'V': case 'D': case 'S': case 'I': case 't': case 'e': case 'h': case 'm': case 'F': case 'P': case 'p': case 'L':
            fprintf(stderr, "[%s] options for generating BCF/VCF output have been removed. Please use \"bcftools mpileup\" instead.\n", "mpileup"); return 1;
        default:
            if (optopt) fprintf(stderr, "mpileup: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "mpileup: unrecognized option '%s'\n", argv[optind-1]);
            mpileup_usage(stderr); return 1;
        }
    }
    if (mplp.fai_fname) {
        mplp.fai = fai_load3(mplp.fai_fname, NULL, NULL, 1, FAI_FASTA);
        if (!mplp.fai) { fprintf(stderr, "[%s] failed to process %s\n", "mpileup", mplp.fai_fname); return 1; }
    }
    if (mplp.pl_list) {
        mplp.bed = bed_read(mplp.pl_list);
        if (!mplp.bed) { fprintf(stderr, "[%s] Could not read file \"%s\"\n", "mpileup", mplp.pl_list); return 1; }
    }
    int n = 0; char **fn = NULL, **fn_idx = NULL;
    if (file_list) {
        if (read_file_list(file_list, &n, &fn) < 0) { fprintf(stderr, "[%s] Could not read file list \"%s\"\n", "mpileup", file_list); return 1; }
    } else {
        if (argc == optind) { mpileup_usage(stderr); return 1; }
        if (has_index_file) {
            int nf = argc - optind; if (nf % 2) { fprintf(stderr, "Odd number of filenames detected! Each BAM file should have an index file\n"); return 1; }
            n = nf / 2; fn = calloc(n, sizeof(char*)); fn_idx = calloc(n, sizeof(char*));
            for (int i = 0; i < n; i++) { fn[i] = strdup(argv[optind + i]); fn_idx[i] = strdup(argv[optind + n + i]); }
        } else {
            n = argc - optind; fn = calloc(n, sizeof(char*));
            for (int i = 0; i < n; i++) fn[i] = strdup(argv[optind + i]);
        }
    }
    mplp.out = stdout;
    if (mplp.output_fname) {
        mplp.out = fopen(mplp.output_fname, "w");
        if (!mplp.out) { fprintf(stderr, "[%s] failed to write to %s: %s\n", "mpileup", mplp.output_fname, strerror(errno)); return 1; }
    }
    int ret = mpileup(&mplp, n, fn, fn_idx);
    if (mplp.output_fname) fclose(mplp.out);
    for (int i = 0; i < n; i++) { free(fn[i]); if (fn_idx) free(fn_idx[i]); }
    free(fn); free(fn_idx);
    if (mplp.fai) fai_destroy(mplp.fai);
    if (mplp.bed) bed_destroy(mplp.bed);
    strmap_free(mplp.rghash);
    for (int i = 0; i < mplp.n_tags; i++) free(mplp.tags[i]); free(mplp.tags);
    free(mplp.reg);
    return ret;
}
EOF
sed -i '/STUB(bam_mpileup, "mpileup")/d' src/stubs.c && make -j8 build/samtools 2>&1 | grep -E "error" | head; cd /tmp/w; C=./cmp.sh; $C mpileup /tmp/w/toy.sam; $C mpileup -B -f /tmp/w/toy.fa /tmp/w/toy.sam; $C mpileup -f /tmp/w/toy.fa /tmp/w/toy.sam; $C mpileup -Q 0 -f /tmp/w/toy.fa /tmp/w/toy.sam; $C mpileup -s -O --output-QNAME -B -f /tmp/w/toy.fa /tmp/w/toy.sam; $C mpileup -a -B /tmp/w/toy.sam; $C mpileup -aa -B -r ref2:38-40 /tmp/w/toy.bam; $C mpileup --output-extra FLAG,POS,MAPQ,XX,RNAME,QNAME -B /tmp/w/toy.sam; $C mpileup -s --output-BP-5 --output-sep ';' --output-empty '-' --output-extra NM,XX -B /tmp/w/toy.sam; $C mpileup --no-output-ins -B /tmp/w/toy.sam; $C mpileup --no-output-ins --no-output-ins -B /tmp/w/toy.sam; $C mpileup --no-output-del --no-output-ends -B /tmp/w/toy.sam; $C mpileup --reverse-del -B /tmp/w/toy.sam; $C mpileup /tmp/w/toy.sam /tmp/w/toy.sam; $C mpileup -A -B /tmp/w/rg.sam; $C mpileup -l /tmp/w/r.bed -B /tmp/w/toy.sam; $C mpileup -l /tmp/w/r2.bed -B /tmp/w/toy.sam; $C mpileup -l /tmp/w/pos.txt -B /tmp/w/toy.sam; $C mpileup -l /tmp/w/r12.bed -a -B /tmp/w/toy.sam; $C mpileup -r ref:10-12 -a -B /tmp/w/toy.bam; $C mpileup -r ref2:38-40 -a -B /tmp/w/toy.bam; $C mpileup -r ref:30-45 -a -B /tmp/w/toy.bam; $C mpileup -aa -B /tmp/w/toyu.sam; $C mpileup -a -B -r ref2 /tmp/w/toy.bam; $C mpileup nonexist; $C mpileup -r ref /tmp/w/toy.sam; $C mpileup -Q 0 /tmp/w/ov2.sam; $C mpileup -Q 0 /tmp/w/ov3.sam; $C mpileup -x -Q 0 /tmp/w/ov3.sam; $C mpileup -B /tmp/w/ex1.bam; $C mpileup -B -f /tmp/w/ex1.fa /tmp/w/ex1.bam; $C mpileup -f /tmp/w/ex1.fa /tmp/w/ex1.bam; $C mpileup -E -f /tmp/w/ex1.fa /tmp/w/ex1.bam; $C mpileup -C 50 -f /tmp/w/ex1.fa /tmp/w/ex1.bam"}

actions.command:
cd /workspace && cat > src/mpileup.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <errno.h>
#include <ctype.h>
#include "samtools.h"
#include "pileup.h"
#include "index.h"
#include "faidx.h"
#include "bedidx.h"
#include "baq.h"
#include "strmap.h"
#include "log.h"

#define MPLP_NO_ORPHAN 0x40
#define MPLP_REALN 0x80
#define MPLP_REDO_BAQ 0x400
#define MPLP_ILLUMINA13 0x800
#define MPLP_IGNORE_RG 0x1000
#define MPLP_PRINT_QPOS 0x2000
#define MPLP_PRINT_MAPQ 0x4000
#define MPLP_SMART_OVERLAPS 0x10000
#define MPLP_PRINT_QNAME 0x20000
#define MPLP_PRINT_QPOS5 0x40000

enum { COL_QNAME = 1, COL_FLAG = 2, COL_RNAME = 4, COL_POS = 8, COL_MAPQ = 16, COL_RNEXT = 32, COL_PNEXT = 64 };

typedef struct {
    int min_mq, flag, min_baseQ, capQ_thres, max_depth, all, rev_del, no_ins, no_ins_mods, no_del, no_ends;
    int rflag_require, rflag_filter;
    char *reg, *pl_list, *fai_fname, *output_fname;
    faidx_t *fai;
    bed_t *bed;
    strmap_t *rghash;
    int print_cols; char **tags; int n_tags;
    char sep, empty;
    FILE *out;
} mplp_conf_t;

typedef struct {
    samfile_t *fp;
    hts_itr_t *iter;
    sam_hdr_t *h;
    mplp_conf_t *conf;
    char *ref; int ref_id; int64_t ref_len;
    hts_idx_t *idx;
} mplp_aux_t;

static int mplp_get_ref(mplp_aux_t *ma, int tid, char **ref, int64_t *ref_len) {
    mplp_conf_t *conf = ma->conf;
    if (!conf->fai) { *ref = NULL; return 0; }
    if (ma->ref_id == tid) { *ref = ma->ref; *ref_len = ma->ref_len; return 1; }
    free(ma->ref); ma->ref = NULL; ma->ref_id = tid;
    int64_t len;
    ma->ref = faidx_fetch_seq64(conf->fai, sam_hdr_tid2name(ma->h, tid), 0, INT32_MAX, &len);
    if (!ma->ref) { ma->ref_len = 0; *ref = NULL; *ref_len = 0; return 0; }
    ma->ref_len = len;
    *ref = ma->ref; *ref_len = len;
    return 1;
}

static int mplp_func(void *data, bam1_t *b) {
    mplp_aux_t *ma = data;
    int ret, skip = 0;
    char *ref; int64_t ref_len;
    do {
        int has_ref;
        ret = ma->iter ? sam_itr_next(ma->fp, ma->iter, b) : sam_read1(ma->fp, ma->h, b);
        if (ret < 0) break;
        if (b->core.tid < 0 || (b->core.flag & BAM_FUNMAP)) { skip = 1; continue; }
        if (ma->conf->rflag_require && !(ma->conf->rflag_require & b->core.flag)) { skip = 1; continue; }
        if (ma->conf->rflag_filter && (ma->conf->rflag_filter & b->core.flag)) { skip = 1; continue; }
        if (ma->conf->bed && ma->conf->all == 0) {
            skip = !bed_overlap(ma->conf->bed, sam_hdr_tid2name(ma->h, b->core.tid), b->core.pos, bam_endpos(b));
            if (skip) continue;
        }
        if (ma->conf->rghash) {
            uint8_t *rg = bam_aux_get(b, "RG");
            skip = (rg && strmap_find(ma->conf->rghash, (char*)rg + 1) != NULL);
            if (skip) continue;
        }
        if (ma->conf->flag & MPLP_ILLUMINA13) {
            uint8_t *qual = bam_get_qual(b);
            for (int i = 0; i < b->core.l_qseq; ++i) qual[i] = qual[i] > 31 ? qual[i] - 31 : 0;
        }
        if (ma->conf->fai && b->core.tid >= 0) {
            has_ref = mplp_get_ref(ma, b->core.tid, &ref, &ref_len);
            if (has_ref && ref_len <= b->core.pos) {
                fprintf(stderr, "[%s] Skipping because %lld is outside of %lld [ref:%d]\n", "mplp_func", (long long)b->core.pos, (long long)ref_len, b->core.tid);
                skip = 1; continue;
            }
        } else has_ref = 0;
        skip = 0;
        if (has_ref && (ma->conf->flag & MPLP_REALN)) sam_prob_realn(b, ref, ref_len, (ma->conf->flag & MPLP_REDO_BAQ) ? 7 : 3);
        if (has_ref && ma->conf->capQ_thres > 10) {
            int q = sam_cap_mapq(b, ref, ref_len, ma->conf->capQ_thres);
            if (q < 0) skip = 1;
            else if (b->core.qual > q) b->core.qual = q;
        }
        if (b->core.qual < ma->conf->min_mq) skip = 1;
        else if ((ma->conf->flag & MPLP_NO_ORPHAN) && (b->core.flag & BAM_FPAIRED) && !(b->core.flag & BAM_FPROPER_PAIR)) skip = 1;
    } while (skip);
    return ret;
}

static void printw(int c, FILE *fp) { char buf[16]; int l, x; if (c == 0) { fputc('0', fp); return; } for (l = 0, x = c < 0 ? -c : c; x > 0; x /= 10) buf[l++] = (char)(x % 10 + '0'); if (c < 0) buf[l++] = '-'; buf[l] = 0; for (x = 0; x < l / 2; ++x) { int y = buf[x]; buf[x] = buf[l-1-x]; buf[l-1-x] = (char)y; } fputs(buf, fp); }

static int pileup_seq(FILE *fp, const bam_pileup1_t *p, int64_t pos, int64_t ref_len, const char *ref, kstring_t *ks, mplp_conf_t *conf) {
    int j;
    if (!conf->no_ends && p->is_head) { putc('^', fp); putc(p->b->core.qual > 93 ? 126 : p->b->core.qual + 33, fp); }
    if (!p->is_del) {
        int c = p->qpos < p->b->core.l_qseq ? seq_nt16_str[bam_seqi(bam_get_seq(p->b), p->qpos)] : 'N';
        if (ref) {
            int rb = pos < ref_len ? ref[pos] : 'N';
            if (c == '=' || seq_nt16_table[c] == seq_nt16_table[rb]) c = bam_is_rev(p->b) ? ',' : '.';
            else c = bam_is_rev(p->b) ? tolower(c) : toupper(c);
        } else {
            if (c == '=') c = bam_is_rev(p->b) ? ',' : '.';
            else c = bam_is_rev(p->b) ? tolower(c) : toupper(c);
        }
        putc(c, fp);
    } else putc(p->is_refskip ? (bam_is_rev(p->b) ? '<' : '>') : (conf->rev_del && bam_is_rev(p->b) ? '#' : '*'), fp);
    int del_len = -p->indel;
    if (p->indel > 0) {
        int len = bam_plp_insertion(p, ks, &del_len);
        if (len < 0) return -1;
        if (conf->no_ins < 2) { putc('+', fp); printw(len, fp); }
        if (conf->no_ins == 0) for (j = 0; j < (int)ks->l; j++) putc(bam_is_rev(p->b) ? tolower(ks->s[j]) : toupper(ks->s[j]), fp);
    }
    if (del_len > 0) {
        if (conf->no_del < 2) printw(-del_len, fp);
        if (conf->no_del == 0) for (j = 1; j <= del_len; ++j) { int c = (ref && pos + j < ref_len) ? ref[pos+j] : 'N'; putc(bam_is_rev(p->b) ? tolower(c) : toupper(c), fp); }
    }
    if (!conf->no_ends && p->is_tail) putc('$', fp);
    return 0;
}

static int n_extra_cols(mplp_conf_t *conf) {
    int n = 0;
    if (conf->flag & MPLP_PRINT_MAPQ) n++;
    if (conf->flag & (MPLP_PRINT_QPOS | MPLP_PRINT_QPOS5)) n++;
    if (conf->flag & MPLP_PRINT_QNAME) n++;
    for (int i = 0; i < 7; i++) if (conf->print_cols & (1 << i)) n++;
    n += conf->n_tags;
    return n;
}

static void print_empty_pileup(FILE *fp, mplp_conf_t *conf, const char *tname, int64_t pos, int n, const char *ref, int64_t ref_len) {
    fprintf(fp, "%s\t%lld\t%c", tname, (long long)pos + 1, (ref && pos < ref_len) ? ref[pos] : 'N');
    int ne = n_extra_cols(conf);
    for (int i = 0; i < n; i++) { fputs("\t0\t*\t*", fp); for (int j = 0; j < ne; j++) fputs("\t*", fp); }
    putc('\n', fp);
}

static void print_aux_col(FILE *fp, const bam1_t *b, const char *tag, mplp_conf_t *conf) {
    uint8_t *s = bam_aux_get(b, tag);
    if (!s) { putc(conf->empty, fp); return; }
    switch (*s) {
    case 'A': putc(s[1], fp); break;
    case 'c': case 'C': case 's': case 'S': case 'i': case 'I': fprintf(fp, "%lld", (long long)bam_aux2i(s)); break;
    case 'f': case 'd': fprintf(fp, "%g", bam_aux2f(s)); break;
    case 'Z': case 'H': fputs((char*)s + 1, fp); break;
    default: putc('*', fp); break;
    }
}

static void mpileup_usage(FILE *fp) {
    fprintf(fp,
"\n"
"Usage: samtools mpileup [options] in1.bam [in2.bam [...]]\n"
"\n"
"Input options:\n"
"  -6, --illumina1.3+      quality is in the Illumina-1.3+ encoding\n"
"  -A, --count-orphans     do not discard anomalous read pairs\n"
"  -b, --bam-list FILE     list of input BAM filenames, one per line\n"
"  -B, --no-BAQ            disable BAQ (per-Base Alignment Quality)\n"
"  -C, --adjust-MQ INT     adjust mapping quality; recommended:50, disable:0 [0]\n"
"  -d, --max-depth INT     max per-file depth; avoids excessive memory usage [8000]\n"
"  -E, --redo-BAQ          recalculate BAQ on the fly, ignore existing BQs\n"
"  -f, --fasta-ref FILE    faidx indexed reference sequence file\n"
"  -G, --exclude-RG FILE   exclude read groups listed in FILE\n"
"  -l, --positions FILE    skip unlisted positions (chr pos) or regions (BED)\n"
"  -q, --min-MQ INT        skip alignments with mapQ smaller than INT [0]\n"
"  -Q, --min-BQ INT        skip bases with baseQ/BAQ smaller than INT [13]\n"
"  -r, --region REG        region in which pileup is generated\n"
"  -R, --ignore-RG         ignore RG tags (one BAM = one sample)\n"
"  --rf, --incl-flags STR|INT\n"
"                          required flags: only include reads with any of\n"
"                          the mask bits set []\n"
"  --ff, --excl-flags STR|INT\n"
"                          filter flags: skip reads with any of the mask bits set\n"
"                                            [UNMAP,SECONDARY,QCFAIL,DUP]\n"
"  -x, --ignore-overlaps-removal, --disable-overlap-removal\n"
"                          disable read-pair overlap detection and removal\n"
"  -X, --customized-index  use customized index files\n"
"\n"
"Output options:\n"
"  -o, --output FILE        write output to FILE [standard output]\n"
"  -O, --output-BP          output base positions on reads, current orientation\n"
"      --output-BP-5        output base positions on reads, 5' to 3' orientation\n"
"  -M, --output-mods        output base modifications\n"
"  -s, --output-MQ          output mapping quality\n"
"      --output-QNAME       output read names\n"
"      --output-extra STR   output extra read fields and read tag values\n"
"      --output-sep CHAR    set the separator character for tag lists [,]\n"
"      --output-empty CHAR  set the no value character for tag lists [*]\n"
"      --no-output-ins      skip insertion sequence after +NUM\n"
"                           Use twice for complete insertion removal\n"
"      --no-output-ins-mods don't display base modifications within insertions\n"
"      --no-output-del      skip deletion sequence after -NUM\n"
"                           Use twice for complete deletion removal\n"
"      --no-output-ends     remove ^MQUAL and $ markup in sequence column\n"
"      --reverse-del        use '#' character for deletions on the reverse strand\n"
"  -a                       output all positions (including zero depth)\n"
"  -a -a (or -aa)           output absolutely all positions, including unused ref. sequences\n"
"\n"
"Generic options:\n");
    sam_global_opt_help(fp, ".-..-..-");
    fprintf(fp,
"\n"
"Note that using \"samtools mpileup\" to generate BCF or VCF files has been\n"
"removed.  To output these formats, please use \"bcftools mpileup\" instead.\n\n");
}

static int read_file_list(const char *fn, int *n, char ***files) {
    textfile_t *t = text_open(fn);
    if (!t) return -1;
    int m = 0; *n = 0; *files = NULL;
    while (text_getline(t) >= 0) {
        char *s = t->line; while (*s == ' ' || *s == '\t') s++;
        char *e = s + strlen(s); while (e > s && (e[-1] == ' ' || e[-1] == '\t' || e[-1] == '\r')) *--e = 0;
        if (!*s || *s == '#') continue;
        if (*n == m) { m = m ? m * 2 : 8; *files = realloc(*files, m * sizeof(char*)); }
        (*files)[(*n)++] = strdup(s);
    }
    text_close(t);
    return 0;
}

static int mpileup(mplp_conf_t *conf, int n, char **fn, char **fn_idx) {
    mplp_aux_t **data = calloc(n, sizeof(mplp_aux_t*));
    sam_hdr_t *h = NULL;
    int tid0 = 0; int64_t beg0 = 0, end0 = INT64_MAX;
    int ret = 0;
    strmap_t *samples = strmap_new();
    int nsamp = 0;
    for (int i = 0; i < n; i++) {
        data[i] = calloc(1, sizeof(mplp_aux_t));
        data[i]->fp = sam_open_read_nohdr(fn[i]);
        if (!data[i]->fp) {
            log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn[i], strerror(errno));
            fprintf(stderr, "[%s] failed to open %s: %s\n", "mpileup", fn[i], strerror(errno));
            ret = 1; goto fail;
        }
        if (sam_read_header(data[i]->fp) < 0) { fprintf(stderr, "[%s] fail to read the header of %s\n", "mpileup", fn[i]); ret = 1; goto fail; }
        data[i]->conf = conf; data[i]->ref_id = -1;
        sam_hdr_t *hh = data[i]->fp->hdr;
        data[i]->h = hh;
        /* samples */
        if (conf->flag & MPLP_IGNORE_RG) { nsamp++; }
        else {
            int nrg = 0;
            for (int j = 0; j < hh->n_lines; j++) if (sam_hdr_line_type_is(hh->lines[j], "RG")) {
                char *sm = hdr_line_tag(hh->lines[j], "SM"); char *id = hdr_line_tag(hh->lines[j], "ID");
                const char *name = sm ? sm : id;
                if (name) { int is_new; strmap_put(samples, name, &is_new); if (is_new) nsamp++; }
                free(sm); free(id); nrg++;
            }
            if (nrg == 0) { int is_new; strmap_put(samples, fn[i], &is_new); if (is_new) nsamp++; }
        }
        if (conf->reg) {
            hts_idx_t *idx = NULL;
            if (data[i]->fp->fmt == FMT_BAM && bgzf_is_bgzf(data[i]->fp->bg)) idx = sam_index_load2(fn[i], fn_idx ? fn_idx[i] : NULL);
            if (!idx) {
                if (!fn_idx) log_error("idx_find_and_load", "Could not retrieve index file for '%s'", fn[i]);
                fprintf(stderr, "[%s] fail to load index for %s\n", "mpileup", fn[i]); ret = 1; goto fail;
            }
            int tid; int64_t beg, end;
            if (hts_parse_region(conf->reg, hh, &tid, &beg, &end) < 0 || tid < 0) {
                fprintf(stderr, "[%s] malformatted region or wrong seqname for %s\n", "mpileup", fn[i]); hts_idx_destroy(idx); ret = 1; goto fail;
            }
            if (i == 0) { tid0 = tid; beg0 = beg; end0 = end; }
            data[i]->iter = sam_itr_queryi(idx, tid, beg, end);
            data[i]->idx = idx;
        }
        if (i == 0) h = hh;
    }
    fprintf(stderr, "[%s] %d samples in %d input files\n", "mpileup", nsamp, n);
    FILE *out = conf->out;
    bam_mplp_t iter = bam_mplp_init(n, mplp_func, (void**)data);
    if (conf->flag & MPLP_SMART_OVERLAPS) bam_mplp_init_overlaps(iter);
    bam_mplp_set_maxcnt(iter, conf->max_depth);
    int *n_plp = calloc(n, sizeof(int));
    const bam_pileup1_t **plp = calloc(n, sizeof(bam_pileup1_t*));
    int tid, last_tid = -1; int64_t pos, last_pos = -1;
    char *ref = NULL; int64_t ref_len = 0;
    kstring_t ks = KS_INITIALIZE;
    int r;
    while ((r = bam_mplp_auto(iter, &tid, &pos, n_plp, plp)) > 0) {
        if (conf->reg && (pos < beg0 || pos >= end0)) continue;
        if (conf->bed && tid >= 0 && !bed_overlap(conf->bed, sam_hdr_tid2name(h, tid), pos, pos + 1)) continue;
        mplp_get_ref(data[0], tid, &ref, &ref_len);
        if (conf->all) {
            while (tid > last_tid) {
                if (last_tid >= 0 && !conf->reg) {
                    char *r2 = NULL; int64_t rl2 = 0; mplp_get_ref(data[0], last_tid, &r2, &rl2);
                    while (++last_pos < sam_hdr_tid2len(h, last_tid)) {
                        if (conf->bed && bed_overlap(conf->bed, sam_hdr_tid2name(h, last_tid), last_pos, last_pos + 1) == 0) continue;
                        print_empty_pileup(out, conf, sam_hdr_tid2name(h, last_tid), last_pos, n, r2, rl2);
                    }
                    mplp_get_ref(data[0], tid, &ref, &ref_len);
                }
                last_tid++; last_pos = -1;
                if (conf->all < 2) break;
            }
            while (++last_pos < pos) {
                if (conf->reg && last_pos < beg0) continue;
                if (conf->bed && bed_overlap(conf->bed, sam_hdr_tid2name(h, tid), last_pos, last_pos + 1) == 0) continue;
                print_empty_pileup(out, conf, sam_hdr_tid2name(h, tid), last_pos, n, ref, ref_len);
            }
            last_tid = tid; last_pos = pos;
        }
        fputs(sam_hdr_tid2name(h, tid), out); putc('\t', out); fprintf(out, "%lld", (long long)pos + 1); putc('\t', out);
        putc((ref && pos < ref_len) ? ref[pos] : 'N', out);
        for (int i = 0; i < n; ++i) {
            int j, cnt;
            for (j = cnt = 0; j < n_plp[i]; ++j) {
                const bam_pileup1_t *p = plp[i] + j;
                int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                if (c >= conf->min_baseQ) ++cnt;
            }
            fprintf(out, "\t%d\t", cnt);
            if (n_plp[i] == 0) {
                fputs("*\t*", out);
                int ne = n_extra_cols(conf);
                for (j = 0; j < ne; j++) fputs("\t*", out);
            } else {
                int nn = 0;
                for (j = 0; j < n_plp[i]; ++j) {
                    const bam_pileup1_t *p = plp[i] + j;
                    int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                    if (c >= conf->min_baseQ) { nn++; pileup_seq(out, p, pos, ref_len, ref, &ks, conf); }
                }
                if (!nn) putc('*', out);
                putc('\t', out);
                nn = 0;
                for (j = 0; j < n_plp[i]; ++j) {
                    const bam_pileup1_t *p = plp[i] + j;
                    int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                    if (c >= conf->min_baseQ) { nn++; c = c + 33 < 126 ? c + 33 : 126; putc(c, out); }
                }
                if (!nn) putc('*', out);
                if (conf->flag & MPLP_PRINT_MAPQ) {
                    putc('\t', out); nn = 0;
                    for (j = 0; j < n_plp[i]; ++j) {
                        const bam_pileup1_t *p = plp[i] + j;
                        int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                        if (c < conf->min_baseQ) continue;
                        nn++; c = p->b->core.qual + 33; if (c > 126) c = 126; putc(c, out);
                    }
                    if (!nn) putc('*', out);
                }
                if (conf->flag & (MPLP_PRINT_QPOS | MPLP_PRINT_QPOS5)) {
                    putc('\t', out); nn = 0;
                    for (j = 0; j < n_plp[i]; ++j) {
                        const bam_pileup1_t *p = plp[i] + j;
                        int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                        if (c < conf->min_baseQ) continue;
                        if (nn > 0) putc(conf->sep, out);
                        nn++;
                        int qp;
                        if (conf->flag & MPLP_PRINT_QPOS5) qp = bam_is_rev(p->b) ? p->b->core.l_qseq - p->qpos : p->qpos + 1;
                        else qp = p->qpos + 1;
                        fprintf(out, "%d", qp);
                    }
                    if (!nn) putc('*', out);
                }
                if (conf->flag & MPLP_PRINT_QNAME) {
                    putc('\t', out); nn = 0;
                    for (j = 0; j < n_plp[i]; ++j) {
                        const bam_pileup1_t *p = plp[i] + j;
                        int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                        if (c < conf->min_baseQ) continue;
                        if (nn > 0) putc(conf->sep, out);
                        nn++; fputs(bam_get_qname(p->b), out);
                    }
                    if (!nn) putc('*', out);
                }
                for (int col = 0; col < 7; col++) {
                    if (!(conf->print_cols & (1 << col))) continue;
                    putc('\t', out); nn = 0;
                    for (j = 0; j < n_plp[i]; ++j) {
                        const bam_pileup1_t *p = plp[i] + j;
                        int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                        if (c < conf->min_baseQ) continue;
                        if (nn > 0) putc(conf->sep, out);
                        nn++;
                        switch (1 << col) {
                        case COL_QNAME: fputs(bam_get_qname(p->b), out); break;
                        case COL_FLAG: fprintf(out, "%d", p->b->core.flag); break;
                        case COL_RNAME: fputs(sam_hdr_tid2name(h, p->b->core.tid), out); break;
                        case COL_POS: fprintf(out, "%lld", (long long)p->b->core.pos + 1); break;
                        case COL_MAPQ: fprintf(out, "%d", p->b->core.qual); break;
                        case COL_RNEXT: fputs(p->b->core.mtid >= 0 ? sam_hdr_tid2name(h, p->b->core.mtid) : "*", out); break;
                        case COL_PNEXT: fprintf(out, "%lld", (long long)p->b->core.mpos + 1); break;
                        }
                    }
                    if (!nn) putc('*', out);
                }
                for (int t = 0; t < conf->n_tags; t++) {
                    putc('\t', out); nn = 0;
                    for (j = 0; j < n_plp[i]; ++j) {
                        const bam_pileup1_t *p = plp[i] + j;
                        int c = p->qpos < p->b->core.l_qseq ? bam_get_qual(p->b)[p->qpos] : 0;
                        if (c < conf->min_baseQ) continue;
                        if (nn > 0) putc(conf->sep, out);
                        nn++; print_aux_col(out, p->b, conf->tags[t], conf);
                    }
                    if (!nn) putc('*', out);
                }
            }
        }
        putc('\n', out);
    }
    if (r < 0) { fprintf(stderr, "[%s] error reading from input file\n", "mpileup"); ret = 1; }
    if (conf->all && ret == 0) {
        if (last_tid < 0 && conf->reg && conf->all > 1) { last_tid = tid0; last_pos = beg0 - 1; mplp_get_ref(data[0], tid0, &ref, &ref_len); }
        while (last_tid >= 0 && last_tid < h->n_targets) {
            mplp_get_ref(data[0], last_tid, &ref, &ref_len);
            while (++last_pos < sam_hdr_tid2len(h, last_tid)) {
                if (last_pos >= end0) break;
                if (conf->bed && bed_overlap(conf->bed, sam_hdr_tid2name(h, last_tid), last_pos, last_pos + 1) == 0) continue;
                print_empty_pileup(out, conf, sam_hdr_tid2name(h, last_tid), last_pos, n, ref, ref_len);
            }
            last_tid++; last_pos = -1;
            if (conf->all < 2 || conf->reg) break;
        }
    }
    free(ks.s);
    bam_mplp_destroy(iter);
    free(n_plp); free(plp);
fail:
    for (int i = 0; i < n; i++) {
        if (!data[i]) continue;
        if (data[i]->iter) hts_itr_destroy(data[i]->iter);
        if (data[i]->idx) hts_idx_destroy(data[i]->idx);
        if (data[i]->fp) sam_close(data[i]->fp);
        free(data[i]->ref); free(data[i]);
    }
    free(data); strmap_free(samples);
    return ret;
}

int bam_mpileup(int argc, char **argv) {
    mplp_conf_t mplp; memset(&mplp, 0, sizeof mplp);
    mplp.min_baseQ = 13; mplp.capQ_thres = 0; mplp.max_depth = 8000;
    mplp.flag = MPLP_NO_ORPHAN | MPLP_REALN | MPLP_SMART_OVERLAPS;
    mplp.rflag_filter = BAM_FUNMAP | BAM_FSECONDARY | BAM_FQCFAIL | BAM_FDUP;
    mplp.sep = ','; mplp.empty = '*';
    char *file_list = NULL; int has_index_file = 0; int c;
    static const struct option lopts[] = {
        { "rf", required_argument, NULL, 1 }, { "incl-flags", required_argument, NULL, 1 },
        { "ff", required_argument, NULL, 2 }, { "excl-flags", required_argument, NULL, 2 },
        { "output", required_argument, NULL, 3 }, { "illumina1.3+", no_argument, NULL, '6' }, { "count-orphans", no_argument, NULL, 'A' },
        { "bam-list", required_argument, NULL, 'b' }, { "no-BAQ", no_argument, NULL, 'B' }, { "no-baq", no_argument, NULL, 'B' },
        { "adjust-MQ", required_argument, NULL, 'C' }, { "adjust-mq", required_argument, NULL, 'C' }, { "max-depth", required_argument, NULL, 'd' },
        { "redo-BAQ", no_argument, NULL, 'E' }, { "redo-baq", no_argument, NULL, 'E' }, { "fasta-ref", required_argument, NULL, 'f' },
        { "exclude-RG", required_argument, NULL, 'G' }, { "exclude-rg", required_argument, NULL, 'G' }, { "positions", required_argument, NULL, 'l' },
        { "region", required_argument, NULL, 'r' }, { "ignore-RG", no_argument, NULL, 'R' }, { "ignore-rg", no_argument, NULL, 'R' },
        { "min-MQ", required_argument, NULL, 'q' }, { "min-mq", required_argument, NULL, 'q' }, { "min-BQ", required_argument, NULL, 'Q' }, { "min-bq", required_argument, NULL, 'Q' },
        { "ignore-overlaps", no_argument, NULL, 'x' }, { "ignore-overlaps-removal", no_argument, NULL, 'x' }, { "disable-overlap-removal", no_argument, NULL, 'x' },
        { "output-BP", no_argument, NULL, 'O' }, { "output-bp", no_argument, NULL, 'O' }, { "output-BP-5", no_argument, NULL, 4 }, { "output-bp-5", no_argument, NULL, 4 },
        { "output-mods", no_argument, NULL, 'M' }, { "output-MQ", no_argument, NULL, 's' }, { "output-mq", no_argument, NULL, 's' },
        { "output-QNAME", no_argument, NULL, 5 }, { "output-qname", no_argument, NULL, 5 }, { "output-extra", required_argument, NULL, 6 },
        { "output-sep", required_argument, NULL, 7 }, { "output-empty", required_argument, NULL, 8 },
        { "no-output-ins", no_argument, NULL, 9 }, { "no-output-ins-mods", no_argument, NULL, 10 }, { "no-output-del", no_argument, NULL, 11 }, { "no-output-ends", no_argument, NULL, 12 },
        { "reverse-del", no_argument, NULL, 13 }, { "customized-index", no_argument, NULL, 'X' },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "reference", required_argument, NULL, 1005 }, { "verbosity", required_argument, NULL, 1008 },
        { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "Agf:r:l:q:Q:uRC:BDSd:L:b:P:po:e:h:Im:F:EG:6OsVvxXt:aM", lopts, NULL)) >= 0) {
        switch (c) {
        case 'x': mplp.flag &= ~MPLP_SMART_OVERLAPS; break;
        case 1: mplp.rflag_require = bam_str2flag(optarg); if (mplp.rflag_require < 0) { fprintf(stderr, "Could not parse --rf %s\n", optarg); return 1; } break;
        case 2: mplp.rflag_filter = bam_str2flag(optarg); if (mplp.rflag_filter < 0) { fprintf(stderr, "Could not parse --ff %s\n", optarg); return 1; } break;
        case 3: mplp.output_fname = optarg; break;
        case 'f': mplp.fai_fname = optarg; break;
        case 'd': mplp.max_depth = atoi(optarg); break;
        case 'r': mplp.reg = strdup(optarg); break;
        case 'l': mplp.pl_list = optarg; break;
        case 'G': {
            textfile_t *t = text_open(optarg);
            if (!t) { fprintf(stderr, "[%s] Could not open read group list %s\n", "mpileup", optarg); return 1; }
            mplp.rghash = strmap_new();
            while (text_getline(t) >= 0) { char *e = t->line; while (*e && *e != '\t' && *e != ' ') e++; *e = 0; if (*t->line) strmap_set(mplp.rghash, t->line, 1); }
            text_close(t);
            break;
        }
        case 'q': mplp.min_mq = atoi(optarg); break;
        case 'Q': mplp.min_baseQ = atoi(optarg); break;
        case 'b': file_list = optarg; break;
        case 'o': mplp.output_fname = optarg; break;
        case 'B': mplp.flag &= ~MPLP_REALN; break;
        case 'E': mplp.flag |= MPLP_REDO_BAQ; break;
        case '6': mplp.flag |= MPLP_ILLUMINA13; break;
        case 'R': mplp.flag |= MPLP_IGNORE_RG; break;
        case 's': mplp.flag |= MPLP_PRINT_MAPQ; break;
        case 'O': mplp.flag |= MPLP_PRINT_QPOS; break;
        case 4: mplp.flag |= MPLP_PRINT_QPOS5; break;
        case 5: mplp.flag |= MPLP_PRINT_QNAME; break;
        case 'M': break;
        case 'C': mplp.capQ_thres = atoi(optarg); break;
        case 'A': mplp.flag &= ~MPLP_NO_ORPHAN; break;
        case 'a': mplp.all++; break;
        case 'X': has_index_file = 1; break;
        case 6: {
            char *dup = strdup(optarg), *p = dup;
            while (*p) {
                char *e = strchr(p, ','); if (e) *e = 0;
                if (strcmp(p, "QNAME") == 0) mplp.print_cols |= COL_QNAME;
                else if (strcmp(p, "FLAG") == 0) mplp.print_cols |= COL_FLAG;
                else if (strcmp(p, "RNAME") == 0) mplp.print_cols |= COL_RNAME;
                else if (strcmp(p, "POS") == 0) mplp.print_cols |= COL_POS;
                else if (strcmp(p, "MAPQ") == 0) mplp.print_cols |= COL_MAPQ;
                else if (strcmp(p, "RNEXT") == 0) mplp.print_cols |= COL_RNEXT;
                else if (strcmp(p, "PNEXT") == 0) mplp.print_cols |= COL_PNEXT;
                else if (strlen(p) == 2) { mplp.tags = realloc(mplp.tags, (mplp.n_tags + 1) * sizeof(char*)); mplp.tags[mplp.n_tags++] = strdup(p); }
                else { fprintf(stderr, "Could not parse --output-extra value %s\n", p); free(dup); return 1; }
                if (!e) break; p = e + 1;
            }
            free(dup);
            break;
        }
        case 7: mplp.sep = optarg[0]; break;
        case 8: mplp.empty = optarg[0]; break;
        case 9: mplp.no_ins++; break;
        case 10: mplp.no_ins_mods = 1; break;
        case 11: mplp.no_del++; break;
        case 12: mplp.no_ends = 1; break;
        case 13: mplp.rev_del = 1; break;
        case 1002: case 1005: break;
        case 1008: hts_verbose = atoi(optarg); break;
        case 'g': case 'u': case 'v': case 'V': case 'D': case 'S': case 'I': case 't': case 'e': case 'h': case 'm': case 'F': case 'P': case 'p': case 'L':
            fprintf(stderr, "[%s] options for generating BCF/VCF output have been removed. Please use \"bcftools mpileup\" instead.\n", "mpileup"); return 1;
        default:
            if (optopt) fprintf(stderr, "mpileup: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "mpileup: unrecognized option '%s'\n", argv[optind-1]);
            mpileup_usage(stderr); return 1;
        }
    }
    if (mplp.fai_fname) {
        mplp.fai = fai_load3(mplp.fai_fname, NULL, NULL, 1, FAI_FASTA);
        if (!mplp.fai) { fprintf(stderr, "[%s] failed to process %s\n", "mpileup", mplp.fai_fname); return 1; }
    }
    if (mplp.pl_list) {
        mplp.bed = bed_read(mplp.pl_list);
        if (!mplp.bed) { fprintf(stderr, "[%s] Could not read file \"%s\"\n", "mpileup", mplp.pl_list); return 1; }
    }
    int n = 0; char **fn = NULL, **fn_idx = NULL;
    if (file_list) {
        if (read_file_list(file_list, &n, &fn) < 0) { fprintf(stderr, "[%s] Could not read file list \"%s\"\n", "mpileup", file_list); return 1; }
    } else {
        if (argc == optind) { mpileup_usage(stderr); return 1; }
        if (has_index_file) {
            int nf = argc - optind; if (nf % 2) { fprintf(stderr, "Odd number of filenames detected! Each BAM file should have an index file\n"); return 1; }
            n = nf / 2; fn = calloc(n, sizeof(char*)); fn_idx = calloc(n, sizeof(char*));
            for (int i = 0; i < n; i++) { fn[i] = strdup(argv[optind + i]); fn_idx[i] = strdup(argv[optind + n + i]); }
        } else {
            n = argc - optind; fn = calloc(n, sizeof(char*));
            for (int i = 0; i < n; i++) fn[i] = strdup(argv[optind + i]);
        }
    }
    mplp.out = stdout;
    if (mplp.output_fname) {
        mplp.out = fopen(mplp.output_fname, "w");
        if (!mplp.out) { fprintf(stderr, "[%s] failed to write to %s: %s\n", "mpileup", mplp.output_fname, strerror(errno)); return 1; }
    }
    int ret = mpileup(&mplp, n, fn, fn_idx);
    if (mplp.output_fname) fclose(mplp.out);
    for (int i = 0; i < n; i++) { free(fn[i]); if (fn_idx) free(fn_idx[i]); }
    free(fn); free(fn_idx);
    if (mplp.fai) fai_destroy(mplp.fai);
    if (mplp.bed) bed_destroy(mplp.bed);
    strmap_free(mplp.rghash);
    for (int i = 0; i < mplp.n_tags; i++) free(mplp.tags[i]); free(mplp.tags);
    free(mplp.reg);
    return ret;
}
