actions.command:
cd /workspace && cat > src/depth.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <errno.h>
#include "samtools.h"
#include "index.h"
#include "bedidx.h"
#include "strmap.h"
#include "log.h"

typedef struct {
    samfile_t *fp; hts_itr_t *iter; hts_idx_t *idx; bam1_t *b; int eof;
    strmap_t *mates;   /* qname -> end position for -s */
} dfile_t;

typedef struct {
    int all, header, min_len, min_baseQ, min_mapQ, incl_del, no_overlap;
    int flag_filter, flag_incl, flag_req;
    char *reg, *bedfn, *fnlist, *outfn;
    bed_t *bed;
    FILE *out;
} depth_opts;

static void depth_usage(FILE *fp) {
    fprintf(fp,
"Usage: samtools depth [options] in.bam [in.bam ...]\n"
"\n"
"Options:\n"
"  -a           Output all positions (including zero depth)\n"
"  -a -a, -aa   Output absolutely all positions, including unused ref seqs\n"
"  -r REG       Specify a region in chr or chr:from-to syntax\n"
"  -b FILE      Use bed FILE for list of regions\n"
"  -f FILE      Specify list of input BAM/SAM/CRAM filenames\n"
"  -X           Use custom index files (in -X *.bam *.bam.bai order)\n"
"  -g INT       Remove specified flags from default filter-out flag list\n"
"  -G, --excl-flags FLAGS\n"
"               Add specified flags to the  default filter-out flag list\n"
"               [UNMAP,SECONDARY,QCFAIL,DUP]\n"
"      --incl-flags FLAGS\n"
"               Only include records with at least one the FLAGs present [0]\n"
"      --require-flags FLAGS\n"
"               Only include records with all of the FLAGs present [0]\n"
"  -H           Print a file header line\n"
"  -l INT       Minimum read length [0]\n"
"  -o FILE      Write output to FILE [stdout]\n"
"  -q, --min-BQ INT\n"
"               Filter bases with base quality smaller than INT [0]\n"
"  -Q, --min-MQ INT\n"
"               Filter alignments with mapping quality smaller than INT [0]\n"
"  -J           Include reads with deletions in depth computation\n"
"  -s           Do not count overlapping reads within a template\n");
    sam_global_opt_help(fp, ".-..-@.-");
}

/* window of counts */
typedef struct {
    int nf;
    int64_t base;          /* position of buf[0] */
    int64_t len;           /* allocated length */
    int64_t *cnt;          /* nf * len */
    uint8_t *span;         /* len */
    int64_t max_end;       /* highest position+1 touched */
} win_t;

static void win_ensure(win_t *w, int64_t end) {
    if (end - w->base <= w->len) return;
    int64_t nl = w->len ? w->len : 1024;
    while (end - w->base > nl) nl *= 2;
    int64_t *nc = calloc(w->nf * nl, sizeof(int64_t));
    uint8_t *ns = calloc(nl, 1);
    for (int f = 0; f < w->nf; f++) memcpy(nc + f * nl, w->cnt + f * w->len, w->len * sizeof(int64_t));
    memcpy(ns, w->span, w->len);
    free(w->cnt); free(w->span); w->cnt = nc; w->span = ns; w->len = nl;
}

static void print_pos(depth_opts *o, sam_hdr_t *h, int tid, int64_t pos, win_t *w, int in_win) {
    if (o->bed && !bed_overlap(o->bed, sam_hdr_tid2name(h, tid), pos, pos + 1)) return;
    fprintf(o->out, "%s\t%lld", sam_hdr_tid2name(h, tid), (long long)pos + 1);
    for (int f = 0; f < w->nf; f++) fprintf(o->out, "\t%lld", in_win ? (long long)w->cnt[f * w->len + (pos - w->base)] : 0LL);
    fputc('\n', o->out);
}

/* flush positions in [w->base, upto) */
static void win_flush(depth_opts *o, sam_hdr_t *h, int tid, win_t *w, int64_t upto, int64_t reg_beg, int64_t reg_end) {
    if (upto > w->max_end) upto = w->max_end;
    int64_t p;
    for (p = w->base; p < upto; p++) {
        int64_t i = p - w->base;
        if (p < reg_beg || p >= reg_end) continue;
        if (o->all || w->span[i]) print_pos(o, h, tid, p, w, 1);
    }
    if (upto > w->base) {
        int64_t shift = upto - w->base;
        if (shift >= w->len) { memset(w->cnt, 0, w->nf * w->len * sizeof(int64_t)); memset(w->span, 0, w->len); }
        else {
            for (int f = 0; f < w->nf; f++) { memmove(w->cnt + f * w->len, w->cnt + f * w->len + shift, (w->len - shift) * sizeof(int64_t)); memset(w->cnt + f * w->len + w->len - shift, 0, shift * sizeof(int64_t)); }
            memmove(w->span, w->span + shift, w->len - shift); memset(w->span + w->len - shift, 0, shift);
        }
        w->base = upto;
    }
}

static int read_next(dfile_t *d, sam_hdr_t *h, depth_opts *o) {
    while (!d->eof) {
        int r = d->iter ? sam_itr_next(d->fp, d->iter, d->b) : sam_read1(d->fp, h, d->b);
        if (r < -1) return -2;
        if (r < 0) { d->eof = 1; return -1; }
        bam1_t *b = d->b;
        if (b->core.tid < 0 || (b->core.flag & BAM_FUNMAP)) continue;
        if (b->core.flag & o->flag_filter) continue;
        if (o->flag_incl && !(b->core.flag & o->flag_incl)) continue;
        if (o->flag_req && (b->core.flag & o->flag_req) != o->flag_req) continue;
        if (b->core.qual < o->min_mapQ) continue;
        if (o->min_len > 0) {
            int len = b->core.l_qseq; uint32_t *c = bam_get_cigar(b);
            for (uint32_t i = 0; i < b->core.n_cigar; i++) if (bam_cigar_op(c[i]) == BAM_CSOFT_CLIP) len -= bam_cigar_oplen(c[i]);
            if (len < o->min_len) continue;
        }
        return 0;
    }
    return -1;
}

static void add_read(dfile_t *d, int f, bam1_t *b, win_t *w, depth_opts *o) {
    int64_t end = bam_endpos(b);
    int64_t skip_to = -1;
    if (o->no_overlap && (b->core.flag & BAM_FPAIRED) && !(b->core.flag & BAM_FMUNMAP) && b->core.mtid == b->core.tid) {
        strmap_entry_t *e = strmap_find(d->mates, bam_get_qname(b));
        if (e) { skip_to = e->val; strmap_del(d->mates, bam_get_qname(b)); }
        else if (b->core.mpos >= b->core.pos) { strmap_set(d->mates, bam_get_qname(b), end); }
    }
    win_ensure(w, end);
    if (end > w->max_end) w->max_end = end;
    for (int64_t p = b->core.pos; p < end; p++) w->span[p - w->base] = 1;
    uint32_t *cig = bam_get_cigar(b); uint8_t *qual = bam_get_qual(b);
    int64_t x = b->core.pos; int y = 0;
    int64_t *cnt = w->cnt + f * w->len;
    for (uint32_t k = 0; k < b->core.n_cigar; k++) {
        int op = bam_cigar_op(cig[k]), l = bam_cigar_oplen(cig[k]);
        if (op == BAM_CMATCH || op == BAM_CEQUAL || op == BAM_CDIFF) {
            for (int i = 0; i < l; i++) {
                int64_t p = x + i;
                if (p < skip_to) continue;
                int q = (qual[0] == 0xff) ? 255 : qual[y + i];
                if (q >= o->min_baseQ) cnt[p - w->base]++;
            }
            x += l; y += l;
        } else if (op == BAM_CDEL) {
            if (o->incl_del) for (int i = 0; i < l; i++) { int64_t p = x + i; if (p >= skip_to) cnt[p - w->base]++; }
            x += l;
        } else if (op == BAM_CREF_SKIP) x += l;
        else if (op == BAM_CINS || op == BAM_CSOFT_CLIP) y += l;
    }
}

int main_depth(int argc, char **argv) {
    depth_opts o; memset(&o, 0, sizeof o);
    o.flag_filter = BAM_FUNMAP | BAM_FSECONDARY | BAM_FQCFAIL | BAM_FDUP;
    int c, has_index_file = 0;
    static const struct option lopts[] = {
        { "excl-flags", required_argument, NULL, 'G' }, { "incl-flags", required_argument, NULL, 1 }, { "require-flags", required_argument, NULL, 2 },
        { "min-BQ", required_argument, NULL, 'q' }, { "min-bq", required_argument, NULL, 'q' }, { "min-MQ", required_argument, NULL, 'Q' }, { "min-mq", required_argument, NULL, 'Q' },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "reference", required_argument, NULL, 1005 }, { "threads", required_argument, NULL, '@' }, { "verbosity", required_argument, NULL, 1008 },
        { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "ar:b:f:Xg:G:Hl:o:q:Q:Js@:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'a': o.all++; break;
        case 'r': o.reg = optarg; break;
        case 'b': o.bedfn = optarg; break;
        case 'f': o.fnlist = optarg; break;
        case 'X': has_index_file = 1; break;
        case 'g': { int f = bam_str2flag(optarg); if (f < 0) { print_error("depth", "could not parse flag %s", optarg); return 1; } o.flag_filter &= ~f; break; }
        case 'G': { int f = bam_str2flag(optarg); if (f < 0) { print_error("depth", "could not parse flag %s", optarg); return 1; } o.flag_filter |= f; break; }
        case 1: { int f = bam_str2flag(optarg); if (f < 0) { print_error("depth", "could not parse flag %s", optarg); return 1; } o.flag_incl = f; break; }
        case 2: { int f = bam_str2flag(optarg); if (f < 0) { print_error("depth", "could not parse flag %s", optarg); return 1; } o.flag_req = f; break; }
        case 'H': o.header = 1; break;
        case 'l': o.min_len = atoi(optarg); break;
        case 'o': o.outfn = optarg; break;
        case 'q': o.min_baseQ = atoi(optarg); break;
        case 'Q': o.min_mapQ = atoi(optarg); break;
        case 'J': o.incl_del = 1; break;
        case 's': o.no_overlap = 1; break;
        case '@': case 1002: case 1005: break;
        case 1008: hts_verbose = atoi(optarg); break;
        default:
            if (optopt) fprintf(stderr, "depth: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "depth: unrecognized option '%s'\n", argv[optind-1]);
            depth_usage(stderr); return 1;
        }
    }
    int nf = 0; char **fn = NULL, **fnidx = NULL;
    if (o.fnlist) {
        textfile_t *t = text_open(o.fnlist);
        if (!t) { print_error_errno("depth", "Cannot open file list \"%s\"", o.fnlist); return 1; }
        int m = 0;
        while (text_getline(t) >= 0) { if (!t->line[0]) continue; if (nf == m) { m = m ? m * 2 : 8; fn = realloc(fn, m * sizeof(char*)); } fn[nf++] = strdup(t->line); }
        text_close(t);
    }
    if (argc - optind > 0) {
        int extra = argc - optind;
        if (has_index_file) {
            if (extra % 2) { print_error("depth", "Odd number of filenames detected! Each BAM file should have an index file"); return 1; }
            int half = extra / 2;
            fn = realloc(fn, (nf + half) * sizeof(char*)); fnidx = calloc(nf + half, sizeof(char*));
            for (int i = 0; i < half; i++) { fn[nf + i] = strdup(argv[optind + i]); fnidx[nf + i] = strdup(argv[optind + half + i]); }
            nf += half;
        } else {
            fn = realloc(fn, (nf + extra) * sizeof(char*));
            for (int i = 0; i < extra; i++) fn[nf + i] = strdup(argv[optind + i]);
            nf += extra;
        }
    }
    if (nf == 0) { depth_usage(stdout); return 0; }
    if (o.bedfn) { o.bed = bed_read(o.bedfn); if (!o.bed) { print_error_errno("depth", "Could not read file \"%s\"", o.bedfn); return 1; } }
    o.out = stdout;
    if (o.outfn) { o.out = fopen(o.outfn, "w"); if (!o.out) { print_error_errno("depth", "Cannot open \"%s\" for writing", o.outfn); return 1; } }
    dfile_t *d = calloc(nf, sizeof(dfile_t));
    sam_hdr_t *h = NULL;
    int ret = 0;
    int reg_tid = -1; int64_t reg_beg = 0, reg_end = INT64_MAX;
    for (int i = 0; i < nf; i++) {
        d[i].fp = sam_open_read_nohdr(fn[i]);
        if (!d[i].fp) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn[i], strerror(errno)); print_error_errno("depth", "Cannot open input file \"%s\"", fn[i]); ret = 1; goto end; }
        if (sam_read_header(d[i].fp) < 0) { print_error("depth", "Cannot read header for \"%s\"", fn[i]); ret = 1; goto end; }
        if (!h) h = d[i].fp->hdr;
        d[i].b = bam_init1();
        d[i].mates = strmap_new();
        if (o.reg) {
            if (d[i].fp->fmt == FMT_BAM && bgzf_is_bgzf(d[i].fp->bg)) d[i].idx = sam_index_load2(fn[i], fnidx ? fnidx[i] : NULL);
            if (!d[i].idx) { if (!fnidx) log_error("idx_find_and_load", "Could not retrieve index file for '%s'", fn[i]); print_error("depth", "cannot load index for \"%s\"", fn[i]); ret = 1; goto end; }
            int tid; int64_t beg, end;
            if (hts_parse_region(o.reg, d[i].fp->hdr, &tid, &beg, &end) < 0 || tid < 0) { print_error("depth", "cannot parse region \"%s\"", o.reg); ret = 1; goto end; }
            if (i == 0) { reg_tid = tid; reg_beg = beg; reg_end = end; }
            d[i].iter = sam_itr_queryi(d[i].idx, tid, beg, end);
        }
    }
    if (o.header) {
        fprintf(o.out, "#CHROM\tPOS");
        for (int i = 0; i < nf; i++) fprintf(o.out, "\t%s", fn[i]);
        fputc('\n', o.out);
    }
    /* prime */
    for (int i = 0; i < nf; i++) { int r = read_next(&d[i], d[i].fp->hdr, &o); if (r == -2) { print_error("depth", "error reading from \"%s\"", fn[i]); ret = 1; goto end; } }
    win_t w; memset(&w, 0, sizeof w); w.nf = nf;
    int cur_tid = -1;
    int last_tid_done = -1;  /* for -aa: tids fully printed so far */
    for (;;) {
        /* pick smallest */
        int bi = -1;
        for (int i = 0; i < nf; i++) {
            if (d[i].eof) continue;
            if (bi < 0 || d[i].b->core.tid < d[bi].b->core.tid || (d[i].b->core.tid == d[bi].b->core.tid && d[i].b->core.pos < d[bi].b->core.pos)) bi = i;
        }
        int new_tid = bi < 0 ? -1 : d[bi].b->core.tid;
        if (bi < 0 || new_tid != cur_tid) {
            /* finish current tid */
            if (cur_tid >= 0) {
                int64_t rb = cur_tid == reg_tid ? reg_beg : 0, re = cur_tid == reg_tid ? reg_end : INT64_MAX;
                int64_t tlen = sam_hdr_tid2len(h, cur_tid);
                int64_t upto = o.all ? (re < tlen ? re : tlen) : w.max_end;
                if (o.all) {
                    if (upto > w.max_end) { win_ensure(&w, upto); w.max_end = upto; }
                }
                win_flush(&o, h, cur_tid, &w, upto, rb, re);
                last_tid_done = cur_tid;
            }
            if (bi < 0) break;
            /* -aa: print skipped tids */
            if (o.all > 1 && !o.reg) {
                for (int t = last_tid_done + 1; t < new_tid; t++) {
                    int64_t tlen = sam_hdr_tid2len(h, t);
                    for (int64_t p = 0; p < tlen; p++) print_pos(&o, h, t, p, &w, 0);
                }
            }
            cur_tid = new_tid;
            w.base = (cur_tid == reg_tid) ? (reg_beg > 0 ? reg_beg : 0) : 0;
            if (o.all) {
                /* start from region start / 0 */
            } else w.base = d[bi].b->core.pos;
            w.max_end = w.base;
            memset(w.cnt, 0, w.nf * w.len * sizeof(int64_t)); memset(w.span, 0, w.len);
            last_tid_done = cur_tid;
        }
        bam1_t *b = d[bi].b;
        /* flush positions before this read */
        if (b->core.pos > w.base) {
            int64_t rb = cur_tid == reg_tid ? reg_beg : 0, re = cur_tid == reg_tid ? reg_end : INT64_MAX;
            int64_t upto = b->core.pos;
            if (o.all && upto > w.max_end) { win_ensure(&w, upto); w.max_end = upto; }
            win_flush(&o, h, cur_tid, &w, upto, rb, re);
        }
        if (b->core.pos < w.base) {
            /* read starts before window base (unsorted or region start): count only within window */
        }
        add_read(&d[bi], bi, b, &w, &o);
        int r = read_next(&d[bi], d[bi].fp->hdr, &o);
        if (r == -2) { print_error("depth", "error reading from \"%s\"", fn[bi]); ret = 1; goto end; }
    }
    if (o.all > 1 && !o.reg) {
        for (int t = last_tid_done + 1; t < h->n_targets; t++) {
            int64_t tlen = sam_hdr_tid2len(h, t);
            for (int64_t p = 0; p < tlen; p++) print_pos(&o, h, t, p, &w, 0);
        }
    }
    if (o.all > 1 && o.reg && cur_tid < 0) {
        int64_t tlen = sam_hdr_tid2len(h, reg_tid);
        for (int64_t p = reg_beg; p < reg_end && p < tlen; p++) print_pos(&o, h, reg_tid, p, &w, 0);
    }
    free(w.cnt); free(w.span);
end:
    for (int i = 0; i < nf; i++) {
        if (d[i].iter) hts_itr_destroy(d[i].iter);
        if (d[i].idx) hts_idx_destroy(d[i].idx);
        if (d[i].b) bam_destroy1(d[i].b);
        if (d[i].fp) sam_close(d[i].fp);
        strmap_free(d[i].mates);
        free(fn[i]); if (fnidx) free(fnidx[i]);
    }
    free(d); free(fn); free(fnidx);
    if (o.bed) bed_destroy(o.bed);
    if (o.outfn) fclose(o.out);
    return ret;
}
