#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include "samtools.h"
#include "pileup.h"
#include "index.h"
#include "log.h"

typedef struct {
    samfile_t *fp; hts_itr_t *iter; hts_idx_t *idx; sam_hdr_t *hdr;
    int min_mapQ, min_len, flags_excl, flags_req;
    struct stats_s *stats; int n_targets;
} cov_aux_t;

typedef struct stats_s {
    int64_t beg, end;
    uint64_t n_covered_bases, summed_coverage, summed_baseQ, summed_mapQ;
    uint32_t n_reads, n_selected_reads;
    int tid, bin_width;
} stats_aux_t;

static int readaln(void *data, bam1_t *b) {
    cov_aux_t *aux = data;
    int ret;
    while (1) {
        ret = aux->iter ? sam_itr_next(aux->fp, aux->iter, b) : sam_read1(aux->fp, aux->hdr, b);
        if (ret < 0) break;
        if (b->core.tid >= 0 && b->core.tid < aux->n_targets) aux->stats[b->core.tid].n_reads++;
        if (b->core.flag & aux->flags_excl) continue;
        if (aux->flags_req && !(b->core.flag & aux->flags_req)) continue;
        if (b->core.qual < aux->min_mapQ) continue;
        if (aux->min_len && bam_cigar2qlen(b->core.n_cigar, bam_get_cigar(b)) < aux->min_len) continue;
        if (b->core.tid >= 0 && b->core.tid < aux->n_targets) { aux->stats[b->core.tid].n_selected_reads++; aux->stats[b->core.tid].summed_mapQ += b->core.qual; }
        break;
    }
    return ret;
}

static char *readable_bps(double base_pairs, char *buf) {
    const char *suffix = "";
    if (base_pairs >= 1e9) { base_pairs /= 1e9; suffix = "G"; }
    else if (base_pairs >= 1e6) { base_pairs /= 1e6; suffix = "M"; }
    else if (base_pairs >= 1e3) { base_pairs /= 1e3; suffix = "K"; }
    if (suffix[0]) sprintf(buf, "%.1f%s", base_pairs, suffix); else sprintf(buf, "%.0f", base_pairs);
    return buf;
}

static void coverage_usage(FILE *fp) {
    fprintf(fp,
"Usage: samtools coverage [options] in1.bam [in2.bam [...]]\n"
"\n"
"Input options:\n"
"  -b, --bam-list FILE     list of input BAM filenames, one per line\n"
"  -l, --min-read-len INT  ignore reads shorter than INT bp [0]\n"
"  -q, --min-MQ INT        mapping quality threshold [0]\n"
"  -Q, --min-BQ INT        base quality threshold [0]\n"
"  --rf <int|str>          required flags: skip reads with mask bits unset []\n"
"  --ff <int|str>          filter flags: skip reads with mask bits set \n"
"                                      [UNMAP,SECONDARY,QCFAIL,DUP]\n"
"  -d, --depth INT         maximum allowed coverage depth [1000000].\n"
"                          If 0, depth is set to the maximum integer value,\n"
"                          effectively removing any depth limit.\n"
"      --min-depth INT     minimum coverage depth below which a position \n"
"                          to be ignored [1]\n"
"Output options:\n"
"  -m, --histogram         show histogram instead of tabular output\n"
"  -D, --plot-depth        plot depth instead of tabular output\n"
"  -A, --ascii             show only ASCII characters in histogram\n"
"  -o, --output FILE       write output to FILE [stdout]\n"
"  -H, --no-header         don't print a header in tabular mode\n"
"  -w, --n-bins INT        number of bins in histogram [terminal width - 40]\n"
"  -r, --region REG        show specified region. Format: chr:start-end. \n"
"  -h, --help              help (this page)\n"
"\n"
"Generic options:\n");
    sam_global_opt_help(fp, ".-..-..-");
    fprintf(fp,
"\n"
"See manpage for additional details.\n"
"  rname       Reference name / chromosome\n"
"  startpos    Start position\n"
"  endpos      End position (or sequence length)\n"
"  numreads    Number reads aligned to the region (after filtering)\n"
"  covbases    Number of covered bases with depth >= 1\n"
"  coverage    Percentage of covered bases [0..100]\n"
"  meandepth   Mean depth of coverage\n"
"  meanbaseq   Mean baseQ in covered region\n"
"  meanmapq    Mean mapQ of selected reads\n");
}

static void print_tabular_line(FILE *out, const sam_hdr_t *h, const stats_aux_t *s) {
    double len = (double)(s->end - s->beg);
    fprintf(out, "%s\t%lld\t%lld\t%u\t%llu\t%g\t%g\t%.3g\t%.3g\n", sam_hdr_tid2name(h, s->tid), (long long)s->beg + 1, (long long)s->end,
            s->n_selected_reads, (unsigned long long)s->n_covered_bases,
            100.0 * s->n_covered_bases / len, s->summed_coverage / len,
            s->summed_coverage > 0 ? s->summed_baseQ / (double)s->summed_coverage : 0,
            s->n_selected_reads > 0 ? s->summed_mapQ / (double)s->n_selected_reads : 0);
}

static void put_centered(char *line, int col, const char *lab) {
    int len = (int)strlen(lab);
    int start = col - (len - 1) / 2;
    memcpy(line + start, lab, len);
}

static void print_hist(FILE *out, const stats_aux_t *s, const sam_hdr_t *h, const uint32_t *hist, const double *dhist, int hist_size, int full_utf, int plot_depth) {
    static const char *BLOCK8[] = { "\u2581", "\u2582", "\u2583", "\u2584", "\u2585", "\u2586", "\u2587", "\u2588" };
    static const char *BLOCK2[] = { ".", ":" };
    const char * const *BLOCK = full_utf ? BLOCK8 : BLOCK2;
    const int blen = full_utf ? 8 : 2;
    const char *vline = full_utf ? "\u2502" : "|";
    const int n_rows = 10;
    double *data = malloc(hist_size * sizeof(double));
    double max_val = 0.0;
    for (int i = 0; i < hist_size; i++) {
        data[i] = plot_depth ? dhist[i] / (double)s->bin_width : 100 * hist[i] / (double)s->bin_width;
        if (data[i] > max_val) max_val = data[i];
    }
    char buf[64];
    fprintf(out, "%s (%sbp)\n", sam_hdr_tid2name(h, s->tid), readable_bps((double)sam_hdr_tid2len(h, s->tid), buf));
    double row_bin_size = max_val / (double)n_rows;
    for (int i = n_rows - 1; i >= 0; i--) {
        double current_bin = row_bin_size * i;
        if (plot_depth) fprintf(out, ">%8.1f ", current_bin); else fprintf(out, ">%7.2f%% ", current_bin);
        fputs(vline, out);
        for (int col = 0; col < hist_size; col++) {
            int cur = (int)round(blen * (data[col] - current_bin) / row_bin_size) - 1;
            if (cur < 0 || row_bin_size == 0) fputc(' ', out);
            else { if (cur >= blen) cur = blen - 1; fputs(BLOCK[cur], out); }
        }
        fputs(vline, out); fputc(' ', out);
        switch (i) {
        case 9: fprintf(out, "Number of reads: %u", s->n_selected_reads); break;
        case 8: if (s->n_reads - s->n_selected_reads > 0) fprintf(out, "    (%u filtered)", s->n_reads - s->n_selected_reads); break;
        case 7: fprintf(out, "Covered bases:   %sbp", readable_bps((double)s->n_covered_bases, buf)); break;
        case 6: fprintf(out, "Percent covered: %.4g%%", 100.0 * s->n_covered_bases / (double)(s->end - s->beg)); break;
        case 5: fprintf(out, "Mean coverage:   %.3gx", s->summed_coverage / (double)(s->end - s->beg)); break;
        case 4: fprintf(out, "Mean baseQ:      %.3g", s->summed_coverage ? s->summed_baseQ / (double)s->summed_coverage : 0.0); break;
        case 3: fprintf(out, "Mean mapQ:       %.3g", s->n_selected_reads ? s->summed_mapQ / (double)s->n_selected_reads : 0.0); break;
        case 1: fprintf(out, "Histo bin width: %sbp", readable_bps((double)s->bin_width, buf)); break;
        case 0: if (plot_depth) fprintf(out, "Histo max cov:   %.5g", max_val); else fprintf(out, "Histo max bin:   %.5g%%", max_val); break;
        }
        fputc('\n', out);
    }
    /* x axis */
    int bars = hist_size;
    int n = bars / 10;
    int nmax = n > 1 ? n : 1;
    int endcol = 10 + 10 * nmax + ((bars - 10 * n) > 1 ? (bars - 10 * n) : 1);
    int T = endcol + 5;
    char *line = malloc(T + 64); memset(line, ' ', T + 63); line[T] = 0;
    put_centered(line, 10, readable_bps((double)s->beg + 1, buf));
    for (int k = 1; k < n; k++) put_centered(line, 10 + 10 * k, readable_bps((double)(s->beg + 10.0 * k * s->bin_width), buf));
    put_centered(line, endcol, readable_bps((double)s->end, buf));
    line[T] = 0;
    fprintf(out, "%s\n", line);
    free(line); free(data);
}

int main_coverage(int argc, char **argv) {
    int c, min_mapQ = 0, min_baseQ = 0, min_len = 0, max_depth = 1000000, min_depth = 1;
    int flags_excl = BAM_FUNMAP | BAM_FSECONDARY | BAM_FQCFAIL | BAM_FDUP, flags_req = 0;
    int print_hist_mode = 0, plot_depth = 0, full_utf = 1, print_header = 1, n_bins = -1;
    const char *reg = NULL, *bamlist = NULL, *outfn = NULL;
    static const struct option lopts[] = {
        { "bam-list", required_argument, NULL, 'b' }, { "min-read-len", required_argument, NULL, 'l' }, { "min-MQ", required_argument, NULL, 'q' }, { "min-mq", required_argument, NULL, 'q' },
        { "min-BQ", required_argument, NULL, 'Q' }, { "min-bq", required_argument, NULL, 'Q' }, { "rf", required_argument, NULL, 1 }, { "incl-flags", required_argument, NULL, 1 },
        { "ff", required_argument, NULL, 2 }, { "excl-flags", required_argument, NULL, 2 }, { "depth", required_argument, NULL, 'd' }, { "min-depth", required_argument, NULL, 3 },
        { "histogram", no_argument, NULL, 'm' }, { "plot-depth", no_argument, NULL, 'D' }, { "ascii", no_argument, NULL, 'A' }, { "output", required_argument, NULL, 'o' },
        { "no-header", no_argument, NULL, 'H' }, { "n-bins", required_argument, NULL, 'w' }, { "region", required_argument, NULL, 'r' }, { "help", no_argument, NULL, 'h' },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "reference", required_argument, NULL, 1005 }, { "verbosity", required_argument, NULL, 1008 },
        { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "o:l:q:Q:hHw:r:b:mDAd:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'o': outfn = optarg; break;
        case 'l': min_len = atoi(optarg); break;
        case 'q': min_mapQ = atoi(optarg); break;
        case 'Q': min_baseQ = atoi(optarg); break;
        case 'd': max_depth = atoi(optarg); if (max_depth == 0) max_depth = INT32_MAX; break;
        case 3: min_depth = atoi(optarg); break;
        case 1: flags_req = bam_str2flag(optarg); if (flags_req < 0) { print_error("coverage", "Could not parse --rf %s", optarg); return 1; } break;
        case 2: flags_excl = bam_str2flag(optarg); if (flags_excl < 0) { print_error("coverage", "Could not parse --ff %s", optarg); return 1; } break;
        case 'm': print_hist_mode = 1; break;
        case 'D': print_hist_mode = 1; plot_depth = 1; break;
        case 'A': full_utf = 0; break;
        case 'H': print_header = 0; break;
        case 'w': n_bins = atoi(optarg); break;
        case 'r': reg = optarg; break;
        case 'b': bamlist = optarg; break;
        case 'h': coverage_usage(stdout); return 0;
        case 1002: case 1005: break;
        case 1008: hts_verbose = atoi(optarg); break;
        default:
            if (optopt) fprintf(stderr, "coverage: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "coverage: unrecognized option '%s'\n", argv[optind-1]);
            coverage_usage(stderr); return 1;
        }
    }
    int nf = 0; char **fn = NULL;
    if (bamlist) {
        textfile_t *t = text_open(bamlist);
        if (!t) { print_error_errno("coverage", "Cannot open file list \"%s\"", bamlist); return 1; }
        int m = 0;
        while (text_getline(t) >= 0) { if (!t->line[0]) continue; if (nf == m) { m = m ? m * 2 : 8; fn = realloc(fn, m * sizeof(char*)); } fn[nf++] = strdup(t->line); }
        text_close(t);
    }
    for (int i = optind; i < argc; i++) { fn = realloc(fn, (nf + 1) * sizeof(char*)); fn[nf++] = strdup(argv[i]); }
    if (nf == 0) { coverage_usage(stdout); return 0; }
    if (n_bins < 0) {
        n_bins = 40;
        if (isatty(STDOUT_FILENO)) {
            const char *cols = getenv("COLUMNS");
            int tw = cols ? atoi(cols) : 80;
            n_bins = tw - 40; if (n_bins < 1) n_bins = 1;
        }
    }
    FILE *out = stdout;
    if (outfn) { out = fopen(outfn, "w"); if (!out) { print_error_errno("coverage", "Cannot open \"%s\" for writing", outfn); return 1; } }
    cov_aux_t **data = calloc(nf, sizeof(cov_aux_t*));
    sam_hdr_t *h = NULL; int ret = 0;
    stats_aux_t *stats = NULL;
    int reg_tid = -1; int64_t reg_beg = 0, reg_end = INT64_MAX;
    for (int i = 0; i < nf; i++) {
        data[i] = calloc(1, sizeof(cov_aux_t));
        data[i]->fp = sam_open_read_nohdr(fn[i]);
        if (!data[i]->fp) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn[i], strerror(errno)); print_error_errno("coverage", "Could not open \"%s\"", fn[i]); ret = 1; goto end; }
        if (sam_read_header(data[i]->fp) < 0) { print_error("coverage", "Failed to read header for \"%s\"", fn[i]); ret = 1; goto end; }
        data[i]->hdr = data[i]->fp->hdr;
        data[i]->min_mapQ = min_mapQ; data[i]->min_len = min_len; data[i]->flags_excl = flags_excl; data[i]->flags_req = flags_req;
        if (i == 0) {
            h = data[i]->hdr;
            stats = calloc(h->n_targets, sizeof(stats_aux_t));
            for (int t = 0; t < h->n_targets; t++) { stats[t].tid = t; stats[t].beg = 0; stats[t].end = sam_hdr_tid2len(h, t); }
        }
        data[i]->stats = stats; data[i]->n_targets = h->n_targets;
        if (reg) {
            if (data[i]->fp->fmt == FMT_BAM && bgzf_is_bgzf(data[i]->fp->bg)) data[i]->idx = sam_index_load2(fn[i], NULL);
            if (!data[i]->idx) { log_error("idx_find_and_load", "Could not retrieve index file for '%s'", fn[i]); print_error("coverage", "Failed to load index for \"%s\"", fn[i]); ret = 1; goto end; }
            int tid; int64_t beg, end;
            if (hts_parse_region(reg, data[i]->hdr, &tid, &beg, &end) < 0 || tid < 0) { print_error("coverage", "Failed to parse region \"%s\"", reg); ret = 1; goto end; }
            data[i]->iter = sam_itr_queryi(data[i]->idx, tid, beg, end);
            if (i == 0) { reg_tid = tid; reg_beg = beg; reg_end = end; stats[tid].beg = beg; stats[tid].end = end == HTS_POS_MAX ? sam_hdr_tid2len(h, tid) : end; }
        }
    }
    if (print_header && !print_hist_mode) fprintf(out, "#rname\tstartpos\tendpos\tnumreads\tcovbases\tcoverage\tmeandepth\tmeanbaseq\tmeanmapq\n");
    {
        bam_mplp_t mplp = bam_mplp_init(nf, readaln, (void**)data);
        bam_mplp_set_maxcnt(mplp, max_depth);
        int *n_plp = calloc(nf, sizeof(int));
        const bam_pileup1_t **plp = calloc(nf, sizeof(bam_pileup1_t*));
        int tid, cur_tid = -1; int64_t pos;
        int *printed = calloc(h->n_targets, sizeof(int));
        uint32_t *hist = NULL; double *dhist = NULL; int hist_size = 0;
        int r;
        while ((r = bam_mplp_auto(mplp, &tid, &pos, n_plp, plp)) > 0) {
            if (tid < 0 || tid >= h->n_targets) break;
            if (reg && (tid != reg_tid || pos < reg_beg || pos >= reg_end)) continue;
            if (tid != cur_tid) {
                if (cur_tid >= 0) {
                    if (print_hist_mode) print_hist(out, &stats[cur_tid], h, hist, dhist, hist_size, full_utf, plot_depth);
                    else print_tabular_line(out, h, &stats[cur_tid]);
                    printed[cur_tid] = 1;
                }
                cur_tid = tid;
                if (print_hist_mode) {
                    int64_t len = stats[tid].end - stats[tid].beg;
                    hist_size = n_bins < len ? n_bins : (int)len;
                    if (hist_size < 1) hist_size = 1;
                    stats[tid].bin_width = (int)(len / hist_size);
                    if (stats[tid].bin_width < 1) stats[tid].bin_width = 1;
                    free(hist); free(dhist);
                    hist = calloc(hist_size, sizeof(uint32_t)); dhist = calloc(hist_size, sizeof(double));
                }
            }
            unsigned depth = 0;
            uint64_t sumq = 0;
            for (int i = 0; i < nf; i++) {
                for (int j = 0; j < n_plp[i]; j++) {
                    const bam_pileup1_t *p = plp[i] + j;
                    if (p->is_del || p->is_refskip) continue;
                    int q = bam_get_qual(p->b)[p->qpos];
                    if (q >= min_baseQ) { depth++; sumq += q; }
                }
            }
            if ((int)depth >= min_depth) {
                stats[tid].n_covered_bases++;
                stats[tid].summed_coverage += depth;
                stats[tid].summed_baseQ += sumq;
                if (print_hist_mode) {
                    int64_t bin = (pos - stats[tid].beg) / stats[tid].bin_width;
                    if (bin >= 0 && bin < hist_size) { hist[bin]++; dhist[bin] += depth; }
                }
            }
        }
        if (r < 0) { print_error("coverage", "error reading from input file"); ret = 1; }
        if (cur_tid >= 0) {
            if (print_hist_mode) print_hist(out, &stats[cur_tid], h, hist, dhist, hist_size, full_utf, plot_depth);
            else print_tabular_line(out, h, &stats[cur_tid]);
            printed[cur_tid] = 1;
        }
        if (!reg) {
            for (int t = 0; t < h->n_targets; t++) {
                if (printed[t]) continue;
                if (print_hist_mode) {
                    int64_t len = stats[t].end - stats[t].beg;
                    hist_size = n_bins < len ? n_bins : (int)len; if (hist_size < 1) hist_size = 1;
                    stats[t].bin_width = (int)(len / hist_size); if (stats[t].bin_width < 1) stats[t].bin_width = 1;
                    free(hist); free(dhist); hist = calloc(hist_size, sizeof(uint32_t)); dhist = calloc(hist_size, sizeof(double));
                    print_hist(out, &stats[t], h, hist, dhist, hist_size, full_utf, plot_depth);
                } else print_tabular_line(out, h, &stats[t]);
            }
        } else if (!printed[reg_tid]) {
            if (print_hist_mode) {
                int64_t len = stats[reg_tid].end - stats[reg_tid].beg;
                hist_size = n_bins < len ? n_bins : (int)len; if (hist_size < 1) hist_size = 1;
                stats[reg_tid].bin_width = (int)(len / hist_size); if (stats[reg_tid].bin_width < 1) stats[reg_tid].bin_width = 1;
                free(hist); free(dhist); hist = calloc(hist_size, sizeof(uint32_t)); dhist = calloc(hist_size, sizeof(double));
                print_hist(out, &stats[reg_tid], h, hist, dhist, hist_size, full_utf, plot_depth);
            } else print_tabular_line(out, h, &stats[reg_tid]);
        }
        free(hist); free(dhist); free(printed);
        bam_mplp_destroy(mplp); free(n_plp); free(plp);
    }
end:
    for (int i = 0; i < nf; i++) {
        if (!data[i]) continue;
        if (data[i]->iter) hts_itr_destroy(data[i]->iter);
        if (data[i]->idx) hts_idx_destroy(data[i]->idx);
        if (data[i]->fp) sam_close(data[i]->fp);
        free(data[i]); free(fn[i]);
    }
    free(data); free(fn); free(stats);
    if (outfn) fclose(out);
    return ret;
}
EOF
sed -i '/STUB(main_coverage, "coverage")/d' src/stubs.c && make -j8 build/samtools 2>&1 | grep -E "error" | head; cd /tmp/w; C=./cmp.sh; $C coverage /tmp/w/toy.sam; $C coverage /tmp/w/ex1.bam; $C coverage -r seq1:100-200 /tmp/w/ex1.bam; $C coverage -H /tmp/w/toy.sam; $C coverage -m -w 20 /tmp/w/toy.sam; $C coverage -m -A -w 20 /tmp/w/ex1.bam; $C coverage -D -w 20 -A /tmp/w/toy.sam; $C coverage /tmp/w/dd.sam; $C coverage /tmp/w/cv.sam; $C coverage -r ref2:3-8 /tmp/w/toy.bam; $C coverage -r ref2:30-100 /tmp/w/toy.bam; $C coverage -q 31 /tmp/w/toy.sam; $C coverage -Q 40 /tmp/w/toy.sam; $C coverage --min-depth 3 /tmp/w/toy.sam; $C coverage -l 25 /tmp/w/toy.sam; $C coverage /tmp/w/ov.sam; $C coverage /tmp/w/ov3.sam; $C coverage -H /tmp/w/ex1.bam /tmp/w/toy.bam; $C coverage -m -w 10 /tmp/w/cv.sam; $C coverage -m -w 10 -r ref2:3-8 /tmp/w/toy.bam; $C coverage -m /tmp/w/toy.sam; for w in 3 5 7 10 12 15 20 25 30 40 45 50; do $C coverage -m -A -w $w /tmp/w/toy.sam; $C coverage -m -w $w -r seq1 /tmp/w/ex1.bam; done 2>&1 | grep -v "^OK"; $C coverage -m -A -w 20 -r seq1:1000-1100 /tmp/w/ex1.bam; $C coverage -D -A -w 20 /tmp/w/ex1.bam; $C coverage -D -w 10 -A /tmp/w/cv.sam; $C coverage -h; $C coverage nonexist.bam; $C coverage; $C coverage -w 0 -m /tmp/w/toy.sam; $C coverage --rf 0x10 /tmp/w/toy.sam; $C coverage --ff 0 /tmp/w/toyu.sam; $C coverage -d 2 /tmp/w/toy.sam; $C coverage -o /tmp/w/cov.out /tmp/w/toy.sam; $C coverage -m -r ref3 /tmp/w/cv.sam; $C coverage -r ref3 /tmp/w/cv.sam; $C coverage -D /tmp/w/ex1.bam"}

actions.command:
cd /workspace && sed -i 's/if (iter->tid == b->core.tid \&\& iter->pos == b->core.pos \&\& iter->cnt > iter->maxcnt)/if (iter->tid == b->core.tid \&\& iter->pos == b->core.pos \&\& iter->cnt + 1 > iter->maxcnt)/' src/pileup.c && grep -c "iter->cnt + 1 > iter->maxcnt" src/pileup.c && cat > src/coverage.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include "samtools.h"
#include "pileup.h"
#include "index.h"
#include "log.h"

typedef struct {
    samfile_t *fp; hts_itr_t *iter; hts_idx_t *idx; sam_hdr_t *hdr;
    int min_mapQ, min_len, flags_excl, flags_req;
    struct stats_s *stats; int n_targets;
} cov_aux_t;

typedef struct stats_s {
    int64_t beg, end;
    uint64_t n_covered_bases, summed_coverage, summed_baseQ, summed_mapQ;
    uint32_t n_reads, n_selected_reads;
    int tid, bin_width;
} stats_aux_t;

static int readaln(void *data, bam1_t *b) {
    cov_aux_t *aux = data;
    int ret;
    while (1) {
        ret = aux->iter ? sam_itr_next(aux->fp, aux->iter, b) : sam_read1(aux->fp, aux->hdr, b);
        if (ret < 0) break;
        if (b->core.tid >= 0 && b->core.tid < aux->n_targets) aux->stats[b->core.tid].n_reads++;
        if (b->core.flag & aux->flags_excl) continue;
        if (aux->flags_req && !(b->core.flag & aux->flags_req)) continue;
        if (b->core.qual < aux->min_mapQ) continue;
        if (aux->min_len && bam_cigar2qlen(b->core.n_cigar, bam_get_cigar(b)) < aux->min_len) continue;
        if (b->core.tid >= 0 && b->core.tid < aux->n_targets) { aux->stats[b->core.tid].n_selected_reads++; aux->stats[b->core.tid].summed_mapQ += b->core.qual; }
        break;
    }
    return ret;
}

static char *readable_bps(double base_pairs, char *buf) {
    const char *suffix = "";
    if (base_pairs >= 1e9) { base_pairs /= 1e9; suffix = "G"; }
    else if (base_pairs >= 1e6) { base_pairs /= 1e6; suffix = "M"; }
    else if (base_pairs >= 1e3) { base_pairs /= 1e3; suffix = "K"; }
    if (suffix[0]) sprintf(buf, "%.1f%s", base_pairs, suffix); else sprintf(buf, "%.0f", base_pairs);
    return buf;
}

static void coverage_usage(FILE *fp) {
    fprintf(fp,
"Usage: samtools coverage [options] in1.bam [in2.bam [...]]\n"
"\n"
"Input options:\n"
"  -b, --bam-list FILE     list of input BAM filenames, one per line\n"
"  -l, --min-read-len INT  ignore reads shorter than INT bp [0]\n"
"  -q, --min-MQ INT        mapping quality threshold [0]\n"
"  -Q, --min-BQ INT        base quality threshold [0]\n"
"  --rf <int|str>          required flags: skip reads with mask bits unset []\n"
"  --ff <int|str>          filter flags: skip reads with mask bits set \n"
"                                      [UNMAP,SECONDARY,QCFAIL,DUP]\n"
"  -d, --depth INT         maximum allowed coverage depth [1000000].\n"
"                          If 0, depth is set to the maximum integer value,\n"
"                          effectively removing any depth limit.\n"
"      --min-depth INT     minimum coverage depth below which a position \n"
"                          to be ignored [1]\n"
"Output options:\n"
"  -m, --histogram         show histogram instead of tabular output\n"
"  -D, --plot-depth        plot depth instead of tabular output\n"
"  -A, --ascii             show only ASCII characters in histogram\n"
"  -o, --output FILE       write output to FILE [stdout]\n"
"  -H, --no-header         don't print a header in tabular mode\n"
"  -w, --n-bins INT        number of bins in histogram [terminal width - 40]\n"
"  -r, --region REG        show specified region. Format: chr:start-end. \n"
"  -h, --help              help (this page)\n"
"\n"
"Generic options:\n");
    sam_global_opt_help(fp, ".-..-..-");
    fprintf(fp,
"\n"
"See manpage for additional details.\n"
"  rname       Reference name / chromosome\n"
"  startpos    Start position\n"
"  endpos      End position (or sequence length)\n"
"  numreads    Number reads aligned to the region (after filtering)\n"
"  covbases    Number of covered bases with depth >= 1\n"
"  coverage    Percentage of covered bases [0..100]\n"
"  meandepth   Mean depth of coverage\n"
"  meanbaseq   Mean baseQ in covered region\n"
"  meanmapq    Mean mapQ of selected reads\n");
}

static void print_tabular_line(FILE *out, const sam_hdr_t *h, const stats_aux_t *s) {
    double len = (double)(s->end - s->beg);
    fprintf(out, "%s\t%lld\t%lld\t%u\t%llu\t%g\t%g\t%.3g\t%.3g\n", sam_hdr_tid2name(h, s->tid), (long long)s->beg + 1, (long long)s->end,
            s->n_selected_reads, (unsigned long long)s->n_covered_bases,
            100.0 * s->n_covered_bases / len, s->summed_coverage / len,
            s->summed_coverage > 0 ? s->summed_baseQ / (double)s->summed_coverage : 0,
            s->n_selected_reads > 0 ? s->summed_mapQ / (double)s->n_selected_reads : 0);
}

static void put_centered(char *line, int col, const char *lab) {
    int len = (int)strlen(lab);
    int start = col - (len - 1) / 2;
    memcpy(line + start, lab, len);
}

static void print_hist(FILE *out, const stats_aux_t *s, const sam_hdr_t *h, const uint32_t *hist, const double *dhist, int hist_size, int full_utf, int plot_depth) {
    static const char *BLOCK8[] = { "\u2581", "\u2582", "\u2583", "\u2584", "\u2585", "\u2586", "\u2587", "\u2588" };
    static const char *BLOCK2[] = { ".", ":" };
    const char * const *BLOCK = full_utf ? BLOCK8 : BLOCK2;
    const int blen = full_utf ? 8 : 2;
    const char *vline = full_utf ? "\u2502" : "|";
    const int n_rows = 10;
    double *data = malloc(hist_size * sizeof(double));
    double max_val = 0.0;
    for (int i = 0; i < hist_size; i++) {
        data[i] = plot_depth ? dhist[i] / (double)s->bin_width : 100 * hist[i] / (double)s->bin_width;
        if (data[i] > max_val) max_val = data[i];
    }
    char buf[64];
    fprintf(out, "%s (%sbp)\n", sam_hdr_tid2name(h, s->tid), readable_bps((double)sam_hdr_tid2len(h, s->tid), buf));
    double row_bin_size = max_val / (double)n_rows;
    for (int i = n_rows - 1; i >= 0; i--) {
        double current_bin = row_bin_size * i;
        if (plot_depth) fprintf(out, ">%8.1f ", current_bin); else fprintf(out, ">%7.2f%% ", current_bin);
        fputs(vline, out);
        for (int col = 0; col < hist_size; col++) {
            int cur = (int)round(blen * (data[col] - current_bin) / row_bin_size) - 1;
            if (cur < 0 || row_bin_size == 0) fputc(' ', out);
            else { if (cur >= blen) cur = blen - 1; fputs(BLOCK[cur], out); }
        }
        fputs(vline, out); fputc(' ', out);
        switch (i) {
        case 9: fprintf(out, "Number of reads: %u", s->n_selected_reads); break;
        case 8: if (s->n_reads - s->n_selected_reads > 0) fprintf(out, "    (%u filtered)", s->n_reads - s->n_selected_reads); break;
        case 7: fprintf(out, "Covered bases:   %sbp", readable_bps((double)s->n_covered_bases, buf)); break;
        case 6: fprintf(out, "Percent covered: %.4g%%", 100.0 * s->n_covered_bases / (double)(s->end - s->beg)); break;
        case 5: fprintf(out, "Mean coverage:   %.3gx", s->summed_coverage / (double)(s->end - s->beg)); break;
        case 4: fprintf(out, "Mean baseQ:      %.3g", s->summed_coverage ? s->summed_baseQ / (double)s->summed_coverage : 0.0); break;
        case 3: fprintf(out, "Mean mapQ:       %.3g", s->n_selected_reads ? s->summed_mapQ / (double)s->n_selected_reads : 0.0); break;
        case 1: fprintf(out, "Histo bin width: %sbp", readable_bps((double)s->bin_width, buf)); break;
        case 0: if (plot_depth) fprintf(out, "Histo max cov:   %.5g", max_val); else fprintf(out, "Histo max bin:   %.5g%%", max_val); break;
        }
        fputc('\n', out);
    }
    /* x axis */
    int bars = hist_size;
    int n = bars / 10;
    int nmax = n > 1 ? n : 1;
    int endcol = 10 + 10 * nmax + ((bars - 10 * n) > 1 ? (bars - 10 * n) : 1);
    int T = endcol + 5;
    char *line = malloc(T + 64); memset(line, ' ', T + 63); line[T] = 0;
    put_centered(line, 10, readable_bps((double)s->beg + 1, buf));
    for (int k = 1; k < n; k++) put_centered(line, 10 + 10 * k, readable_bps((double)(s->beg + 10.0 * k * s->bin_width), buf));
    put_centered(line, endcol, readable_bps((double)s->end, buf));
    line[T] = 0;
    fprintf(out, "%s\n", line);
    free(line); free(data);
}

int main_coverage(int argc, char **argv) {
    int c, min_mapQ = 0, min_baseQ = 0, min_len = 0, max_depth = 1000000, min_depth = 1;
    int flags_excl = BAM_FUNMAP | BAM_FSECONDARY | BAM_FQCFAIL | BAM_FDUP, flags_req = 0;
    int print_hist_mode = 0, plot_depth = 0, full_utf = 1, print_header = 1, n_bins = -1;
    const char *reg = NULL, *bamlist = NULL, *outfn = NULL;
    static const struct option lopts[] = {
