static void realloc_buffers(stats_t *s, int seq_len) {
    int n = 2 * seq_len; if (n < 2 * s->nbases) n = 2 * s->nbases;
    if (n <= s->nbases) return;
    int old = s->nbases;
#define GROW(arr, mult) do { arr = realloc(arr, (size_t)n * (mult) * sizeof(*arr)); memset(arr + (size_t)old * (mult), 0, ((size_t)(n - old)) * (mult) * sizeof(*arr)); } while (0)
    GROW(s->quals_1st, s->nquals); GROW(s->quals_2nd, s->nquals); GROW(s->mpc_buf, s->nquals);
    GROW(s->acgtno_cycles_1st, 1); GROW(s->acgtno_cycles_2nd, 1); GROW(s->acgtno_revcomp, 1);
    GROW(s->read_lengths, 1); GROW(s->read_lengths_1st, 1); GROW(s->read_lengths_2nd, 1);
    GROW(s->insertions, 1); GROW(s->deletions, 1);
    GROW(s->ins_cycles_1st, 1); GROW(s->ins_cycles_2nd, 1); GROW(s->del_cycles_1st, 1); GROW(s->del_cycles_2nd, 1);
#undef GROW
    s->nbases = n;
    s->nindels = n;
    /* coverage buffer must also be large enough */
    if (s->cov_rbuf.size < n) {
        int32_t *nb = calloc(n, sizeof(int32_t));
        /* re-linearize existing buffer */
        for (int i = 0; i < s->cov_rbuf.size; i++) nb[i] = s->cov_rbuf.buffer[(s->cov_rbuf.start + i) % s->cov_rbuf.size];
        free(s->cov_rbuf.buffer); s->cov_rbuf.buffer = nb; s->cov_rbuf.size = n; s->cov_rbuf.start = 0;
    }
}

static inline int coverage_idx(int min, int max, int n, int step, int depth) {
    if (depth < min) return 0;
    if (depth > max) return n - 1;
    return 1 + (depth - min) / step;
}

static void round_buffer_flush(stats_t *s, int64_t pos) {
    round_buffer_t *rb = &s->cov_rbuf;
    if (pos == rb->pos) return;
    int64_t new_pos = pos;
    if (pos == -1 || pos - rb->pos >= rb->size) pos = rb->pos + rb->size - 1;
    if (pos < rb->pos) return;
    int ifrom = rb->start;
    int64_t n = pos - rb->pos; if (n > rb->size) n = rb->size;
    for (int64_t k = 0; k < n; k++) {
        int ibuf = (int)((ifrom + k) % rb->size);
        if (rb->buffer[ibuf] == 0) continue;
        int icov = coverage_idx(s->info->cov_min, s->info->cov_max, s->ncov, s->info->cov_step, rb->buffer[ibuf]);
        s->cov[icov]++;
        rb->buffer[ibuf] = 0;
    }
    rb->start = (int)((rb->start + n) % rb->size);
    rb->pos = new_pos == -1 ? 0 : new_pos;
    if (new_pos == -1) { rb->start = 0; rb->pos = 0; }
}

static void round_buffer_insert_read(round_buffer_t *rb, int64_t from, int64_t to) {
    if (to - rb->pos >= rb->size) return;
    for (int64_t p = from; p <= to; p++) {
        if (p < rb->pos) continue;
        int ibuf = (int)((rb->start + (p - rb->pos)) % rb->size);
        rb->buffer[ibuf]++;
    }
}

static int bwa_trim_read(int trim_qual, uint8_t *quals, int len, int reverse) {
    if (len < BWA_MIN_RDLEN) return 0;
    int max_trimmed = len - BWA_MIN_RDLEN + 1;
    int l, sum = 0, max_sum = 0, max_l = 0;
    for (l = 0; l < max_trimmed; l++) {
        sum += trim_qual - quals[reverse ? l : len - 1 - l];
        if (sum < 0) break;
        if (sum > max_sum) { max_sum = sum; max_l = l + 1; }
    }
    return max_l;
}

static void count_indels(stats_t *s, bam1_t *b) {
    int is_fwd = (b->core.flag & BAM_FREVERSE) ? 0 : 1;
    int is_1st = (b->core.flag & BAM_FREAD2) ? 0 : 1;
    int icycle = 0, read_len = b->core.l_qseq;
    uint32_t *cig = bam_get_cigar(b);
    for (uint32_t k = 0; k < b->core.n_cigar; k++) {
        int op = bam_cigar_op(cig[k]), n = bam_cigar_oplen(cig[k]);
        if (!n) continue;
        if (op == BAM_CINS) {
            int idx = is_fwd ? icycle : read_len - icycle - n;
            if (idx >= 0 && idx < s->nbases) { if (is_1st) s->ins_cycles_1st[idx]++; else s->ins_cycles_2nd[idx]++; }
            icycle += n;
            if (n <= s->nindels) s->insertions[n-1]++;
            continue;
        }
        if (op == BAM_CDEL) {
            int idx = is_fwd ? icycle - 1 : read_len - icycle - 1;
            if (idx < 0) continue;
            if (idx < s->nbases) { if (is_1st) s->del_cycles_1st[idx]++; else s->del_cycles_2nd[idx]++; }
            if (n <= s->nindels) s->deletions[n-1]++;
            continue;
        }
        if (op != BAM_CREF_SKIP && op != BAM_CHARD_CLIP && op != BAM_CPAD) icycle += n;
    }
}

static void read_ref_seq(stats_t *s, int tid, int64_t pos) {
    if (!s->info->fai) return;
    free(s->rseq_buf); s->rseq_buf = NULL; s->nrseq_buf = 0;
    const char *name = sam_hdr_tid2name(s->hdr, tid);
    int64_t len;
    int64_t fetch_len = s->gcd_bin_size > 1000000 ? s->gcd_bin_size : 1000000;
    char *seq = name ? faidx_fetch_seq64(s->info->fai, name, pos, pos + fetch_len, &len) : NULL;
    if (!seq || len <= 0) { free(seq); s->rseq_pos = pos; s->rseq_tid = tid; return; }
    s->rseq_buf = malloc(len);
    for (int64_t i = 0; i < len; i++) s->rseq_buf[i] = (char)seq_nt16_table[(unsigned char)seq[i]];
    free(seq);
    s->nrseq_buf = len; s->rseq_pos = pos; s->rseq_tid = tid;
}

static float fai_gc_content(stats_t *s, int64_t pos, int len) {
    uint32_t gc = 0, count = 0;
    int64_t i = pos - s->rseq_pos, i_end = i + len;
    if (i_end > s->nrseq_buf) i_end = s->nrseq_buf;
    for (; i < i_end; i++) {
        unsigned char c = (unsigned char)s->rseq_buf[i];
        if (c == 2 || c == 4) gc++;
        if (c == 1 || c == 2 || c == 4 || c == 8) count++;
    }
    return count ? (float)gc / count : 0;
}

static void count_mismatches_per_cycle(stats_t *s, bam1_t *b) {
    int is_fwd = (b->core.flag & BAM_FREVERSE) ? 0 : 1;
    int iread = 0, icycle = 0;
    int64_t iref = b->core.pos - s->rseq_pos;
    int read_len = b->core.l_qseq;
    uint8_t *read = bam_get_seq(b), *quals = bam_get_qual(b);
    uint32_t *cig = bam_get_cigar(b);
    for (uint32_t k = 0; k < b->core.n_cigar; k++) {
        int op = bam_cigar_op(cig[k]), n = bam_cigar_oplen(cig[k]);
        if (op == BAM_CINS) { iread += n; icycle += n; continue; }
        if (op == BAM_CDEL) { iref += n; continue; }
        if (op == BAM_CSOFT_CLIP) { icycle += n; iread += n; continue; }
        if (op == BAM_CREF_SKIP || op == BAM_CHARD_CLIP || op == BAM_CPAD) { if (op == BAM_CREF_SKIP) iref += n; continue; }
        if (op != BAM_CMATCH && op != BAM_CEQUAL && op != BAM_CDIFF) continue;
        for (int im = 0; im < n; im++) {
            if (iref < 0 || iref >= s->nrseq_buf) { iref++; iread++; icycle++; continue; }
            uint8_t cread = iread < read_len ? bam_seqi(read, iread) : 15;
            uint8_t cref = (uint8_t)s->rseq_buf[iref];
            int idx = is_fwd ? icycle : read_len - icycle - 1;
            if (idx < 0 || idx > s->max_len || idx >= s->nbases) { iref++; iread++; icycle++; continue; }
            if (cread == 15) s->mpc_buf[(size_t)idx * s->nquals]++;
            else if (cref && cread && cref != cread) {
                int q = (iread < read_len ? quals[iread] : 0) + 1;
                if (q < s->nquals) s->mpc_buf[(size_t)idx * s->nquals + q]++;
            }
            iref++; iread++; icycle++;
        }
    }
}

static void collect_stats(bam1_t *b, stats_t *s) {
    stats_info_t *info = s->info;
    if (s->rg_hash) {
        uint8_t *rg = bam_aux_get(b, "RG");
        if (!rg || !strmap_find(s->rg_hash, (char*)rg + 1)) return;
    }
    int flag = b->core.flag;
    if (info->flag_require && (flag & info->flag_require) != info->flag_require) { s->nreads_filtered++; return; }
    if (info->flag_filter && (flag & info->flag_filter)) { s->nreads_filtered++; return; }
    if (s->targets) {
        if (b->core.tid < 0 || !bed_overlap(s->targets, sam_hdr_tid2name(s->hdr, b->core.tid), b->core.pos, bam_endpos(b))) return;
    }
    if (info->filter_readlen != -1 && b->core.l_qseq != info->filter_readlen) return;
    if (flag & BAM_FQCFAIL) s->nreads_qc_failed++;
    if (flag & BAM_FPAIRED) s->nreads_paired_tech++;
    if (flag & BAM_FSECONDARY) { s->nreads_secondary++; return; }
    if (flag & BAM_FSUPPLEMENTARY) { s->nreads_supplementary++; return; }
    /* checksums */
    s->chk_names += crc32(0, (uint8_t*)bam_get_qname(b), b->core.l_qname - 1 - b->core.l_extranul);
    s->chk_seqs += crc32(0, bam_get_seq(b), (b->core.l_qseq + 1) / 2);
    s->chk_quals += crc32(0, bam_get_qual(b), b->core.l_qseq);

    int seq_len = b->core.l_qseq;
    if (!seq_len) return;
    int read_len = seq_len;
    uint32_t *cig = bam_get_cigar(b);
    for (uint32_t k = 0; k < b->core.n_cigar; k++) if (bam_cigar_op(cig[k]) == BAM_CHARD_CLIP) read_len += bam_cigar_oplen(cig[k]);
    int need = read_len > seq_len ? read_len : seq_len;
    if (need >= s->nbases) realloc_buffers(s, need + 1);
    if (s->max_len < seq_len) s->max_len = seq_len;

    int is_1st = (flag & BAM_FREAD2) ? 0 : 1;
    uint64_t *quals; acgtno_count_t *acgtno; uint64_t *gc_arr;
    if (is_1st) { s->nreads_1st++; s->total_len_1st += seq_len; if (s->max_len_1st < seq_len) s->max_len_1st = seq_len; quals = s->quals_1st; acgtno = s->acgtno_cycles_1st; gc_arr = s->gc_1st; s->read_lengths_1st[read_len]++; }
    else { s->nreads_2nd++; s->total_len_2nd += seq_len; if (s->max_len_2nd < seq_len) s->max_len_2nd = seq_len; quals = s->quals_2nd; acgtno = s->acgtno_cycles_2nd; gc_arr = s->gc_2nd; s->read_lengths_2nd[read_len]++; }
    s->read_lengths[read_len]++;
    s->total_len += seq_len;
    if (flag & BAM_FDUP) { s->nreads_dup++; s->total_len_dup += seq_len; }

    int reverse = (flag & BAM_FREVERSE) ? 1 : 0;
    uint8_t *seq = bam_get_seq(b), *bq = bam_get_qual(b);
    int gc_count = 0;
    for (int i = 0; i < seq_len; i++) {
        int base = bam_seqi(seq, i);
        int cycle = reverse ? seq_len - i - 1 : i;
        acgtno_count_t *fwd = &acgtno[i];
        switch (base) {
        case 1: fwd->a++; break; case 2: fwd->c++; gc_count++; break; case 4: fwd->g++; gc_count++; break; case 8: fwd->t++; break;
        case 15: fwd->n++; break; default: fwd->other++; break;
        }
        /* read-oriented table: complement for reverse */
        acgtno_count_t *ro = &s->acgtno_revcomp[cycle];
        int rbase = reverse ? (base == 1 ? 8 : base == 2 ? 4 : base == 4 ? 2 : base == 8 ? 1 : base) : base;
        switch (rbase) {
        case 1: ro->a++; break; case 2: ro->c++; break; case 4: ro->g++; break; case 8: ro->t++; break;
        case 15: ro->n++; break; default: ro->other++; break;
        }
        int q = bq[i];
        if (q > s->max_qual) s->max_qual = q;
        quals[(size_t)cycle * s->nquals + q]++;
        s->sum_qual += q;
    }
    {
        int gc_idx_min = gc_count * (s->ngc - 1) / seq_len;
        int gc_idx_max = (gc_count + 1) * (s->ngc - 1) / seq_len;
        if (gc_idx_max >= s->ngc) gc_idx_max = s->ngc - 1;
        for (int i = gc_idx_min; i < gc_idx_max; i++) gc_arr[i]++;
    }
    if (info->trim_qual > 0) s->nbases_trimmed += bwa_trim_read(info->trim_qual, bq, seq_len, reverse);

    if (flag & BAM_FUNMAP) { s->nreads_unmapped++; return; }
    if (!b->core.qual) s->nreads_mq0++;
    if (!(flag & BAM_FQCFAIL) && !(flag & BAM_FDUP)) s->mapq[b->core.qual]++;
    count_indels(s, b);
    if (!(flag & BAM_FPAIRED) || (flag & BAM_FMUNMAP)) s->nreads_single_mapped++;
    else {
        s->nreads_paired_and_mapped++;
        if (b->core.tid != b->core.mtid) s->nreads_anomalous++;
        else {
            int64_t isize = b->core.isize; if (isize < 0) isize = -isize;
            if (isize > s->nisize) isize = s->nisize;
            if (isize > 0) {
                int64_t pos_fst = b->core.mpos - b->core.pos;
                int is_fst = (flag & BAM_FREAD1) ? 1 : -1;
                int is_fwd = (flag & BAM_FREVERSE) ? -1 : 1;
                int is_mfwd = (flag & BAM_FMREVERSE) ? -1 : 1;
                if (is_fwd * is_mfwd > 0) s->isize_other[isize]++;
                else if (is_fst * pos_fst > 0) { if (is_fst * is_fwd > 0) s->isize_inward[isize]++; else s->isize_outward[isize]++; }
                else if (is_fst * pos_fst < 0) { if (is_fst * is_fwd > 0) s->isize_outward[isize]++; else s->isize_inward[isize]++; }
            }
        }
    }
    if (flag & BAM_FPROPER_PAIR) s->nreads_properly_paired++;
    s->nreads_mapped++;
    s->nbases_mapped += seq_len;
    for (uint32_t k = 0; k < b->core.n_cigar; k++) { int op = bam_cigar_op(cig[k]); if (op == BAM_CMATCH || op == BAM_CINS || op == BAM_CEQUAL || op == BAM_CDIFF) s->nbases_mapped_cigar += bam_cigar_oplen(cig[k]); }
    uint8_t *nm = bam_aux_get(b, "NM");
    if (nm && bam_aux_is_int(nm)) s->nmismatches += bam_aux2i(nm);

    if (s->tid == b->core.tid && b->core.pos < s->pos) s->is_sorted = 0;
    s->pos = b->core.pos;
    if (s->is_sorted) {
        if (s->tid == -1 || s->tid != b->core.tid) round_buffer_flush(s, -1);
        if (info->fai) {
            int inc_ref = 0, inc_gcd = 0;
            if (s->rseq_pos == -1 || s->tid != b->core.tid) { inc_ref = 1; inc_gcd = 1; }
            else if (s->rseq_pos + s->nrseq_buf < b->core.pos + read_len) { inc_ref = 1; inc_gcd = 1; }
            else if (s->gcd_pos + (int64_t)s->gcd_bin_size < b->core.pos + read_len) {
                inc_gcd = 1;
                if (s->rseq_pos + s->nrseq_buf < b->core.pos + (int64_t)s->gcd_bin_size) inc_ref = 1;
            }
            if (inc_gcd) {
                s->igcd++;
                if (s->igcd >= s->ngcd) { uint32_t o = s->ngcd; s->ngcd = s->ngcd ? s->ngcd * 2 : 1024; s->gcd = realloc(s->gcd, s->ngcd * sizeof(gc_depth_t)); memset(s->gcd + o, 0, (s->ngcd - o) * sizeof(gc_depth_t)); }
                if (inc_ref) read_ref_seq(s, b->core.tid, b->core.pos);
                s->gcd_pos = b->core.pos;
                s->gcd[s->igcd].gc = fai_gc_content(s, s->gcd_pos, s->gcd_bin_size);
            }
            count_mismatches_per_cycle(s, b);
        } else if (s->gcd_pos == -1 || s->tid != b->core.tid || b->core.pos - s->gcd_pos > (int64_t)s->gcd_bin_size) {
            /* finalise previous bin */
            if (s->gcd_pos != -1 && s->gcd[s->igcd].depth) s->gcd[s->igcd].gc = s->gcd[s->igcd].gc / s->gcd[s->igcd].depth * 100;
            s->tid = b->core.tid;
            s->gcd_pos = b->core.pos;
            s->igcd++;
            if (s->igcd >= s->ngcd) { uint32_t o = s->ngcd; s->ngcd = s->ngcd ? s->ngcd * 2 : 1024; s->gcd = realloc(s->gcd, s->ngcd * sizeof(gc_depth_t)); memset(s->gcd + o, 0, (s->ngcd - o) * sizeof(gc_depth_t)); }
        }
        s->gcd[s->igcd].depth++;
        if (!info->fai) s->gcd[s->igcd].gc += (float)gc_count / seq_len;
        /* coverage */
        round_buffer_flush(s, b->core.pos);
        int64_t rpos = b->core.pos;
        for (uint32_t k = 0; k < b->core.n_cigar; k++) {
            int op = bam_cigar_op(cig[k]), n = bam_cigar_oplen(cig[k]);
            if (op == BAM_CMATCH || op == BAM_CEQUAL || op == BAM_CDIFF) { round_buffer_insert_read(&s->cov_rbuf, rpos, rpos + n - 1); rpos += n; }
            else if (op == BAM_CDEL || op == BAM_CREF_SKIP) rpos += n;
        }
    }
    s->tid = b->core.tid;
}

static float gcd_percentile(gc_depth_t *gcd, int N, int p) {
    float n = p * (N + 1) / 100.f;
    int k = (int)n;
    if (k <= 0) return gcd[0].depth;
    if (k >= N) return gcd[N-1].depth;
    float d = n - k;
    return gcd[k-1].depth + d * (gcd[k].depth - gcd[k-1].depth);
}
static int gcd_cmp(const void *a, const void *b) {
    const gc_depth_t *x = a, *y = b;
    if (x->gc < y->gc) return -1; if (x->gc > y->gc) return 1;
    if (x->depth < y->depth) return -1; if (x->depth > y->depth) return 1;
    return 0;
}

static void output_stats(stats_t *s, FILE *to) {
    stats_info_t *info = s->info;
    int i;
    fprintf(to, "# This file was produced by samtools stats (%s+htslib-%s) and can be plotted using plot-bamstats\n", SAMTOOLS_VERSION, HTSLIB_VERSION);
    if (info->rg_id) fprintf(to, "# This file contains statistics for reads with RG tag %s\n", info->rg_id);
    else fprintf(to, "# This file contains statistics for all reads.\n");
    fprintf(to, "# The command line was:  ");
    for (i = 0; i < info->argc; i++) fprintf(to, "%s%s", i ? " " : "", info->argv[i]);
    fprintf(to, "\n");
    fprintf(to, "# CHK, Checksum\t[2]Read Names\t[3]Sequences\t[4]Qualities\n");
    fprintf(to, "# CHK, CRC32 of reads which passed filtering followed by addition (32bit overflow)\n");
    fprintf(to, "CHK\t%08x\t%08x\t%08x\n", s->chk_names, s->chk_seqs, s->chk_quals);
    fprintf(to, "# Summary Numbers. Use `grep ^SN | cut -f 2-` to extract this part.\n");
    uint64_t nreads = s->nreads_1st + s->nreads_2nd;
    fprintf(to, "SN\traw total sequences:\t%llu\t# excluding supplementary and secondary reads\n", (unsigned long long)(s->nreads_filtered + nreads));
    fprintf(to, "SN\tfiltered sequences:\t%llu\n", (unsigned long long)s->nreads_filtered);
    fprintf(to, "SN\tsequences:\t%llu\n", (unsigned long long)nreads);
    fprintf(to, "SN\tis sorted:\t%d\t# sorted by coordinate\n", s->is_sorted ? 1 : 0);
    fprintf(to, "SN\t1st fragments:\t%llu\n", (unsigned long long)s->nreads_1st);
    fprintf(to, "SN\tlast fragments:\t%llu\n", (unsigned long long)s->nreads_2nd);
    fprintf(to, "SN\treads mapped:\t%llu\n", (unsigned long long)s->nreads_mapped);
    fprintf(to, "SN\treads mapped and paired:\t%llu\t# paired-end technology bit set + both mates mapped\n", (unsigned long long)s->nreads_paired_and_mapped);
    fprintf(to, "SN\treads unmapped:\t%llu\n", (unsigned long long)s->nreads_unmapped);
    fprintf(to, "SN\treads properly paired:\t%llu\t# proper-pair bit set\n", (unsigned long long)s->nreads_properly_paired);
    fprintf(to, "SN\treads paired:\t%llu\t# paired-end technology bit set\n", (unsigned long long)s->nreads_paired_tech);
    fprintf(to, "SN\treads duplicated:\t%llu\t# PCR or optical duplicate bit set\n", (unsigned long long)s->nreads_dup);
    fprintf(to, "SN\treads MQ0:\t%llu\t# mapped and MQ=0\n", (unsigned long long)s->nreads_mq0);
    fprintf(to, "SN\treads QC failed:\t%llu\n", (unsigned long long)s->nreads_qc_failed);
    fprintf(to, "SN\tnon-primary alignments:\t%llu\n", (unsigned long long)s->nreads_secondary);
    fprintf(to, "SN\tsupplementary alignments:\t%llu\n", (unsigned long long)s->nreads_supplementary);
    fprintf(to, "SN\ttotal length:\t%llu\t# ignores clipping\n", (unsigned long long)s->total_len);
    fprintf(to, "SN\ttotal first fragment length:\t%llu\t# ignores clipping\n", (unsigned long long)s->total_len_1st);
    fprintf(to, "SN\ttotal last fragment length:\t%llu\t# ignores clipping\n", (unsigned long long)s->total_len_2nd);
    fprintf(to, "SN\tbases mapped:\t%llu\t# ignores clipping\n", (unsigned long long)s->nbases_mapped);
    fprintf(to, "SN\tbases mapped (cigar):\t%llu\t# more accurate\n", (unsigned long long)s->nbases_mapped_cigar);
    fprintf(to, "SN\tbases trimmed:\t%llu\n", (unsigned long long)s->nbases_trimmed);
    fprintf(to, "SN\tbases duplicated:\t%llu\n", (unsigned long long)s->total_len_dup);
    fprintf(to, "SN\tmismatches:\t%llu\t# from NM fields\n", (unsigned long long)s->nmismatches);
    fprintf(to, "SN\terror rate:\t%e\t# mismatches / bases mapped (cigar)\n", s->nbases_mapped_cigar ? (double)s->nmismatches / s->nbases_mapped_cigar : 0.0);
    float avg_read_length = nreads ? (float)s->total_len / nreads : 0;
    float avg_read_length_1st = s->nreads_1st ? (float)s->total_len_1st / s->nreads_1st : 0;
    float avg_read_length_2nd = s->nreads_2nd ? (float)s->total_len_2nd / s->nreads_2nd : 0;
    fprintf(to, "SN\taverage length:\t%.0f\n", floorf(avg_read_length));
    fprintf(to, "SN\taverage first fragment length:\t%.0f\n", floorf(avg_read_length_1st));
    fprintf(to, "SN\taverage last fragment length:\t%.0f\n", floorf(avg_read_length_2nd));
    fprintf(to, "SN\tmaximum length:\t%d\n", s->max_len);
    fprintf(to, "SN\tmaximum first fragment length:\t%d\n", s->max_len_1st);
    fprintf(to, "SN\tmaximum last fragment length:\t%d\n", s->max_len_2nd);
    fprintf(to, "SN\taverage quality:\t%.1f\n", s->total_len ? s->sum_qual / s->total_len : 0);
    /* insert sizes */
    int nitems = s->nisize + 1;
    uint64_t nisize = 0, nisize_inward = 0, nisize_outward = 0, nisize_other = 0;
    for (i = 0; i < nitems; i++) {
        s->isize_inward[i] /= 2; s->isize_outward[i] /= 2; s->isize_other[i] /= 2;
        nisize_inward += s->isize_inward[i]; nisize_outward += s->isize_outward[i]; nisize_other += s->isize_other[i];
        nisize += s->isize_inward[i] + s->isize_outward[i] + s->isize_other[i];
    }
    double bulk = 0, avg_isize = 0, sd_isize = 0;
    int ibulk = 0;
    for (i = 0; i < nitems; i++) {
        uint64_t tot = s->isize_inward[i] + s->isize_outward[i] + s->isize_other[i];
        bulk += tot; avg_isize += (double)i * tot;
        if (nisize && bulk / nisize > info->isize_main_bulk) { ibulk = i + 1; nisize = (uint64_t)bulk; break; }
    }
    avg_isize /= nisize ? nisize : 1;
    for (i = 1; i < ibulk; i++) { uint64_t tot = s->isize_inward[i] + s->isize_outward[i] + s->isize_other[i]; sd_isize += tot * (i - avg_isize) * (i - avg_isize) / (nisize ? nisize : 1); }
    sd_isize = sqrt(sd_isize);
    fprintf(to, "SN\tinsert size average:\t%.1f\n", avg_isize);
    fprintf(to, "SN\tinsert size standard deviation:\t%.1f\n", sd_isize);
    fprintf(to, "SN\tinward oriented pairs:\t%llu\n", (unsigned long long)nisize_inward);
    fprintf(to, "SN\toutward oriented pairs:\t%llu\n", (unsigned long long)nisize_outward);
    fprintf(to, "SN\tpairs with other orientation:\t%llu\n", (unsigned long long)nisize_other);
    fprintf(to, "SN\tpairs on different chromosomes:\t%llu\n", (unsigned long long)(s->nreads_anomalous / 2));
    fprintf(to, "SN\tpercentage of properly paired reads (%%):\t%.1f\n", nreads ? (float)(100.0 * s->nreads_properly_paired / nreads) : 0);
    if (s->targets) {
        fprintf(to, "SN\tbases inside the target:\t%llu\n", (unsigned long long)s->nbases_target);
        fprintf(to, "SN\tpercentage of target genome with coverage > %d (%%):\t%.2f\n", info->cov_threshold, s->nbases_target ? 100.0 * s->ntarget_cov_above / s->nbases_target : 0.0);
    }
    int ibase, iqual;
    fprintf(to, "# First Fragment Qualities. Use `grep ^FFQ | cut -f 2-` to extract this part.\n# Columns correspond to qualities and rows to cycles. First column is the cycle number.\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        fprintf(to, "FFQ\t%d", ibase + 1);
        for (iqual = 0; iqual <= s->max_qual; iqual++) fprintf(to, "\t%llu", (unsigned long long)s->quals_1st[(size_t)ibase * s->nquals + iqual]);
        fprintf(to, "\n");
    }
    fprintf(to, "# Last Fragment Qualities. Use `grep ^LFQ | cut -f 2-` to extract this part.\n# Columns correspond to qualities and rows to cycles. First column is the cycle number.\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        fprintf(to, "LFQ\t%d", ibase + 1);
        for (iqual = 0; iqual <= s->max_qual; iqual++) fprintf(to, "\t%llu", (unsigned long long)s->quals_2nd[(size_t)ibase * s->nquals + iqual]);
        fprintf(to, "\n");
    }
    if (s->mpc_buf && info->fai) {
        fprintf(to, "# Mismatches per cycle and quality. Use `grep ^MPC | cut -f 2-` to extract this part.\n# Columns correspond to qualities, rows to cycles. First column is the cycle number, second\n# is the number of N's and the rest is the number of mismatches\n");
        for (ibase = 0; ibase <= s->max_len; ibase++) {
            fprintf(to, "MPC\t%d", ibase + 1);
            for (iqual = 0; iqual <= s->max_qual; iqual++) fprintf(to, "\t%llu", (unsigned long long)s->mpc_buf[(size_t)ibase * s->nquals + iqual]);
            fprintf(to, "\n");
        }
    }
    fprintf(to, "# GC Content of first fragments. Use `grep ^GCF | cut -f 2-` to extract this part.\n");
    int ibase_prev = 0;
    for (ibase = 0; ibase < s->ngc; ibase++) {
        if (s->gc_1st[ibase] == s->gc_1st[ibase_prev]) continue;
        fprintf(to, "GCF\t%.2f\t%llu\n", (ibase + ibase_prev) * 0.5 * 100. / (s->ngc - 1), (unsigned long long)s->gc_1st[ibase_prev]);
        ibase_prev = ibase;
    }
    fprintf(to, "# GC Content of last fragments. Use `grep ^GCL | cut -f 2-` to extract this part.\n");
    ibase_prev = 0;
    for (ibase = 0; ibase < s->ngc; ibase++) {
        if (s->gc_2nd[ibase] == s->gc_2nd[ibase_prev]) continue;
        fprintf(to, "GCL\t%.2f\t%llu\n", (ibase + ibase_prev) * 0.5 * 100. / (s->ngc - 1), (unsigned long long)s->gc_2nd[ibase_prev]);
        ibase_prev = ibase;
    }
    fprintf(to, "# ACGT content per cycle. Use `grep ^GCC | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]; and N and O counts as a percentage of all A/C/G/T bases [%%]\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        acgtno_count_t *a1 = &s->acgtno_cycles_1st[ibase], *a2 = &s->acgtno_cycles_2nd[ibase];
        uint64_t a = a1->a + a2->a, c = a1->c + a2->c, g = a1->g + a2->g, t = a1->t + a2->t, n = a1->n + a2->n, o = a1->other + a2->other;
        uint64_t sum = a + c + g + t;
        if (!sum) continue;
        fprintf(to, "GCC\t%d\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\n", ibase + 1, 100. * a / sum, 100. * c / sum, 100. * g / sum, 100. * t / sum, 100. * n / sum, 100. * o / sum);
    }
    fprintf(to, "# ACGT content per cycle, read oriented. Use `grep ^GCT | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        acgtno_count_t *a1 = &s->acgtno_revcomp[ibase];
        uint64_t sum = a1->a + a1->c + a1->g + a1->t;
        if (!sum) continue;
        fprintf(to, "GCT\t%d\t%.2f\t%.2f\t%.2f\t%.2f\n", ibase + 1, 100. * a1->a / sum, 100. * a1->c / sum, 100. * a1->g / sum, 100. * a1->t / sum);
    }
    fprintf(to, "# ACGT content per cycle for first fragments. Use `grep ^FBC | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]; and N and O counts as a percentage of all A/C/G/T bases [%%]\n");
    uint64_t ta = 0, tc = 0, tg = 0, tt = 0, tn = 0;
    for (ibase = 0; ibase < s->max_len; ibase++) {
        acgtno_count_t *a1 = &s->acgtno_cycles_1st[ibase];
        ta += a1->a; tc += a1->c; tg += a1->g; tt += a1->t; tn += a1->n;
        uint64_t sum = a1->a + a1->c + a1->g + a1->t;
        if (!sum) continue;
        fprintf(to, "FBC\t%d\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\n", ibase + 1, 100. * a1->a / sum, 100. * a1->c / sum, 100. * a1->g / sum, 100. * a1->t / sum, 100. * a1->n / sum, 100. * a1->other / sum);
    }
    fprintf(to, "# ACGT raw counters for first fragments. Use `grep ^FTC | cut -f 2-` to extract this part. The columns are: A,C,G,T,N base counters\n");
    fprintf(to, "FTC\t%llu\t%llu\t%llu\t%llu\t%llu\n", (unsigned long long)ta, (unsigned long long)tc, (unsigned long long)tg, (unsigned long long)tt, (unsigned long long)tn);
    fprintf(to, "# ACGT content per cycle for last fragments. Use `grep ^LBC | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]; and N and O counts as a percentage of all A/C/G/T bases [%%]\n");
    ta = tc = tg = tt = tn = 0;
    for (ibase = 0; ibase < s->max_len; ibase++) {
        acgtno_count_t *a1 = &s->acgtno_cycles_2nd[ibase];
        ta += a1->a; tc += a1->c; tg += a1->g; tt += a1->t; tn += a1->n;
        uint64_t sum = a1->a + a1->c + a1->g + a1->t;
        if (!sum) continue;
        fprintf(to, "LBC\t%d\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\n", ibase + 1, 100. * a1->a / sum, 100. * a1->c / sum, 100. * a1->g / sum, 100. * a1->t / sum, 100. * a1->n / sum, 100. * a1->other / sum);
    }
    fprintf(to, "# ACGT raw counters for last fragments. Use `grep ^LTC | cut -f 2-` to extract this part. The columns are: A,C,G,T,N base counters\n");
    fprintf(to, "LTC\t%llu\t%llu\t%llu\t%llu\t%llu\n", (unsigned long long)ta, (unsigned long long)tc, (unsigned long long)tg, (unsigned long long)tt, (unsigned long long)tn);
    fprintf(to, "# Insert sizes. Use `grep ^IS | cut -f 2-` to extract this part. The columns are: insert size, pairs total, inward oriented pairs, outward oriented pairs, other pairs\n");
    for (i = 0; i < ibulk; i++) {
        uint64_t tot = s->isize_inward[i] + s->isize_outward[i] + s->isize_other[i];
        if (info->sparse && !tot) continue;
        fprintf(to, "IS\t%d\t%llu\t%llu\t%llu\t%llu\n", i, (unsigned long long)tot, (unsigned long long)s->isize_inward[i], (unsigned long long)s->isize_outward[i], (unsigned long long)s->isize_other[i]);
    }
    fprintf(to, "# Read lengths. Use `grep ^RL | cut -f 2-` to extract this part. The columns are: read length, count\n");
    int ilen;
    for (ilen = 0; ilen < s->nbases; ilen++) if (s->read_lengths[ilen] > 0) fprintf(to, "RL\t%d\t%llu\n", ilen, (unsigned long long)s->read_lengths[ilen]);
    fprintf(to, "# Read lengths - first fragments. Use `grep ^FRL | cut -f 2-` to extract this part. The columns are: read length, count\n");
    for (ilen = 0; ilen < s->nbases; ilen++) if (s->read_lengths_1st[ilen] > 0) fprintf(to, "FRL\t%d\t%llu\n", ilen, (unsigned long long)s->read_lengths_1st[ilen]);
    fprintf(to, "# Read lengths - last fragments. Use `grep ^LRL | cut -f 2-` to extract this part. The columns are: read length, count\n");
    for (ilen = 0; ilen < s->nbases; ilen++) if (s->read_lengths_2nd[ilen] > 0) fprintf(to, "LRL\t%d\t%llu\n", ilen, (unsigned long long)s->read_lengths_2nd[ilen]);
    fprintf(to, "# Mapping qualities for reads !(UNMAP|SECOND|SUPPL|QCFAIL|DUP). Use `grep ^MAPQ | cut -f 2-` to extract this part. The columns are: mapq, count\n");
    for (i = 0; i < s->nquals; i++) if (s->mapq[i] > 0) fprintf(to, "MAPQ\t%d\t%llu\n", i, (unsigned long long)s->mapq[i]);
    fprintf(to, "# Indel distribution. Use `grep ^ID | cut -f 2-` to extract this part. The columns are: length, number of insertions, number of deletions\n");
    for (ilen = 0; ilen < s->nindels; ilen++) if (s->insertions[ilen] > 0 || s->deletions[ilen] > 0) fprintf(to, "ID\t%d\t%llu\t%llu\n", ilen + 1, (unsigned long long)s->insertions[ilen], (unsigned long long)s->deletions[ilen]);
    fprintf(to, "# Indels per cycle. Use `grep ^IC | cut -f 2-` to extract this part. The columns are: cycle, number of insertions (fwd), .. (rev) , number of deletions (fwd), .. (rev)\n");
    for (ilen = 0; ilen <= s->nbases; ilen++) {
        if (ilen >= s->nbases) break;
        if (s->ins_cycles_1st[ilen] > 0 || s->ins_cycles_2nd[ilen] > 0 || s->del_cycles_1st[ilen] > 0 || s->del_cycles_2nd[ilen] > 0)
            fprintf(to, "IC\t%d\t%llu\t%llu\t%llu\t%llu\n", ilen + 1, (unsigned long long)s->ins_cycles_1st[ilen], (unsigned long long)s->ins_cycles_2nd[ilen], (unsigned long long)s->del_cycles_1st[ilen], (unsigned long long)s->del_cycles_2nd[ilen]);
    }
    fprintf(to, "# Coverage distribution. Use `grep ^COV | cut -f 2-` to extract this part.\n");
    if (s->cov[0]) fprintf(to, "COV\t[<%d]\t%d\t%llu\n", info->cov_min, info->cov_min - 1, (unsigned long long)s->cov[0]);
    for (int icov = 1; icov < s->ncov - 1; icov++)
        if (s->cov[icov]) fprintf(to, "COV\t[%d-%d]\t%d\t%llu\n", info->cov_min + (icov - 1) * info->cov_step, info->cov_min + icov * info->cov_step - 1, info->cov_min + icov * info->cov_step - 1, (unsigned long long)s->cov[icov]);
    if (s->cov[s->ncov - 1]) fprintf(to, "COV\t[%d<]\t%d\t%llu\n", info->cov_max - 1, info->cov_max - 1, (unsigned long long)s->cov[s->ncov - 1]);
    fprintf(to, "# GC-depth. Use `grep ^GCD | cut -f 2-` to extract this part. The columns are: GC%%, unique sequence percentiles, 10th, 25th, 50th, 75th and 90th depth percentile\n");
    /* add dummy */
    s->igcd++;
    if (s->igcd >= s->ngcd) { uint32_t o = s->ngcd; s->ngcd = s->ngcd ? s->ngcd * 2 : 1024; s->gcd = realloc(s->gcd, s->ngcd * sizeof(gc_depth_t)); memset(s->gcd + o, 0, (s->ngcd - o) * sizeof(gc_depth_t)); }
    s->gcd[s->igcd].gc = 0; s->gcd[s->igcd].depth = 0;
    qsort(s->gcd, s->igcd + 1, sizeof(gc_depth_t), gcd_cmp);
    uint32_t igcd = 0;
    while (igcd < s->igcd) {
        uint32_t nbins = 0, itmp = igcd;
        float gc = s->gcd[igcd].gc;
        while (itmp < s->igcd && fabs(s->gcd[itmp].gc - gc) < 0.1) { nbins++; itmp++; }
        fprintf(to, "GCD\t%.1f\t%.3f\t%.3f\t%.3f\t%.3f\t%.3f\t%.3f\n", gc, (igcd + nbins) * 100. / s->igcd,
                gcd_percentile(&s->gcd[igcd], nbins, 10) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[igcd], nbins, 25) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[igcd], nbins, 50) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[igcd], nbins, 75) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[igcd], nbins, 90) * avg_read_length / s->gcd_bin_size);
        igcd += nbins;
    }
}

static stats_t *stats_init(stats_info_t *info, sam_hdr_t *hdr) {
    stats_t *s = calloc(1, sizeof(stats_t));
    s->info = info; s->hdr = hdr;
    s->nquals = 256; s->nbases = 0; s->nisize = info->nisize; s->ngc = 200;
    s->is_sorted = 1; s->tid = -1; s->gcd_pos = -1; s->rseq_pos = -1; s->rseq_tid = -1;
    s->gcd_bin_size = info->ngc_depth_bin;
    s->ncov = (info->cov_max - info->cov_min) / info->cov_step + 3;
    s->cov = calloc(s->ncov, sizeof(uint64_t));
    s->mapq = calloc(s->nquals, sizeof(uint64_t));
    s->gc_1st = calloc(s->ngc, sizeof(uint64_t)); s->gc_2nd = calloc(s->ngc, sizeof(uint64_t));
    s->isize_inward = calloc(s->nisize + 1, sizeof(uint64_t)); s->isize_outward = calloc(s->nisize + 1, sizeof(uint64_t)); s->isize_other = calloc(s->nisize + 1, sizeof(uint64_t));
    s->ngcd = 1024; s->gcd = calloc(s->ngcd, sizeof(gc_depth_t)); s->igcd = 0;
    s->cov_rbuf.size = 2048; s->cov_rbuf.buffer = calloc(s->cov_rbuf.size, sizeof(int32_t));
    realloc_buffers(s, 300);
    return s;
}

static void stats_destroy(stats_t *s) {
    free(s->quals_1st); free(s->quals_2nd); free(s->mpc_buf); free(s->acgtno_cycles_1st); free(s->acgtno_cycles_2nd); free(s->acgtno_revcomp);
    free(s->read_lengths); free(s->read_lengths_1st); free(s->read_lengths_2nd); free(s->insertions); free(s->deletions);
    free(s->ins_cycles_1st); free(s->ins_cycles_2nd); free(s->del_cycles_1st); free(s->del_cycles_2nd);
    free(s->isize_inward); free(s->isize_outward); free(s->isize_other); free(s->cov); free(s->mapq); free(s->gc_1st); free(s->gc_2nd);
    free(s->gcd); free(s->cov_rbuf.buffer); free(s->rseq_buf); strmap_free(s->rg_hash);
    free(s);
}

static void stats_usage(FILE *fp) {
    fprintf(fp,
"About: The program collects statistics from BAM files. The output can be visualized using plot-bamstats.\n"
"Usage: samtools stats [OPTIONS] file.bam\n"
"       samtools stats [OPTIONS] file.bam chr:from-to\n"
"Options:\n"
"    -c, --coverage <int>,<int>,<int>    Coverage distribution min,max,step [1,1000,1]\n"
"    -d, --remove-dups                   Exclude from statistics reads marked as duplicates\n"
"    -X, --customized-index-file         Use a customized index file\n"
"    -f, --required-flag  <str|int>      Required flag, 0 for unset. See also `samtools flags` [0]\n"
"    -F, --filtering-flag <str|int>      Filtering flag, 0 for unset. See also `samtools flags` [0]\n"
"        --GC-depth <float>              the size of GC-depth bins (decreasing bin size increases memory requirement) [2e4]\n"
"    -h, --help                          This help message\n"
"    -i, --insert-size <int>             Maximum insert size [8000]\n"
"    -I, --id <string>                   Include only listed read group or sample name\n"
"    -l, --read-length <int>             Include in the statistics only reads with the given read length [-1]\n"
"    -m, --most-inserts <float>          Report only the main part of inserts [0.99]\n"
"    -P, --split-prefix <str>            Path or string prefix for filepaths output by -S (default is input filename)\n"
"    -q, --trim-quality <int>            The BWA trimming parameter [0]\n"
"    -r, --ref-seq <file>                Reference sequence (required for GC-depth and mismatches-per-cycle calculation).\n"
"    -s, --sam                           Ignored (input format is auto-detected).\n"
"    -S, --split <tag>                   Also write statistics to separate files split by tagged field.\n"
"    -t, --target-regions <file>         Do stats in these regions only. Tab-delimited file chr,from,to, 1-based, inclusive.\n"
"    -x, --sparse                        Suppress outputting IS rows where there are no insertions.\n"
"    -p, --remove-overlaps               Remove overlaps of paired-end reads from coverage and base count computations.\n"
"    -g, --cov-threshold <int>           Only bases with coverage above this value will be included in the target percentage computation [0]\n"
"        --ref-stats                     Create statistics on reference data.\n"
"        --ref-stats-chunk <int>         Reference retrival chunk size, in Mbs, for reference statistics [1].\n");
    sam_global_opt_help(fp, ".-..-@.-");
    fprintf(fp, "\n");
}

int main_stats(int argc, char **argv) {
    stats_info_t info; memset(&info, 0, sizeof info);
    info.nisize = 8000; info.isize_main_bulk = 0.99; info.ngc_depth_bin = 20000; info.cov_min = 1; info.cov_max = 1000; info.cov_step = 1; info.filter_readlen = -1;
    info.argc = argc; info.argv = argv;
    int c, has_index_file = 0;
    static const struct option lopts[] = {
        { "help", no_argument, NULL, 'h' }, { "remove-dups", no_argument, NULL, 'd' }, { "customized-index-file", no_argument, NULL, 'X' },
        { "sam", no_argument, NULL, 's' }, { "ref-seq", required_argument, NULL, 'r' }, { "coverage", required_argument, NULL, 'c' },
        { "read-length", required_argument, NULL, 'l' }, { "insert-size", required_argument, NULL, 'i' }, { "most-inserts", required_argument, NULL, 'm' },
        { "split-prefix", required_argument, NULL, 'P' }, { "trim-quality", required_argument, NULL, 'q' }, { "target-regions", required_argument, NULL, 't' },
        { "required-flag", required_argument, NULL, 'f' }, { "filtering-flag", required_argument, NULL, 'F' }, { "id", required_argument, NULL, 'I' },
        { "GC-depth", required_argument, NULL, 1 }, { "gc-depth", required_argument, NULL, 1 }, { "split", required_argument, NULL, 'S' }, { "sparse", no_argument, NULL, 'x' },
        { "remove-overlaps", no_argument, NULL, 'p' }, { "cov-threshold", required_argument, NULL, 'g' }, { "ref-stats", no_argument, NULL, 2 }, { "ref-stats-chunk", required_argument, NULL, 3 },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "reference", required_argument, NULL, 1005 }, { "threads", required_argument, NULL, '@' }, { "verbosity", required_argument, NULL, 1008 },
        { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "c:dsxpr:f:F:l:i:m:q:t:I:S:P:g:hX@:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'f': info.flag_require = bam_str2flag(optarg); if (info.flag_require < 0) { fprintf(stderr, "Unknown flag %s\n", optarg); return 1; } break;
        case 'F': info.flag_filter = bam_str2flag(optarg); if (info.flag_filter < 0) { fprintf(stderr, "Unknown flag %s\n", optarg); return 1; } break;
        case 'd': info.flag_filter |= BAM_FDUP; break;
        case 's': break;
        case 'r': info.ref_fn = optarg; break;
        case 1: info.ngc_depth_bin = (int)atof(optarg); break;
        case 'c': if (sscanf(optarg, "%d,%d,%d", &info.cov_min, &info.cov_max, &info.cov_step) != 3) { fprintf(stderr, "Unable to parse -c %s\n", optarg); return 1; } break;
        case 'l': info.filter_readlen = atoi(optarg); break;
        case 'i': info.nisize = atoi(optarg); break;
        case 'm': info.isize_main_bulk = atof(optarg); break;
        case 'q': info.trim_qual = atoi(optarg); break;
        case 't': info.targets_fn = optarg; break;
        case 'I': info.rg_id = optarg; break;
        case 'S': info.split_tag = optarg; break;
        case 'P': info.split_prefix = optarg; break;
        case 'x': info.sparse = 1; break;
        case 'p': info.remove_overlaps = 1; break;
        case 'g': info.cov_threshold = atoi(optarg); break;
        case 2: case 3: break;
        case 'X': has_index_file = 1; break;
        case 'h': stats_usage(stdout); return 0;
        case '@': case 1002: case 1005: break;
        case 1008: hts_verbose = atoi(optarg); break;
        default:
            if (optopt) fprintf(stderr, "stats: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "stats: unrecognized option '%s'\n", argv[optind-1]);
            stats_usage(stderr); return 1;
        }
    }
    const char *fn = optind < argc ? argv[optind] : "-";
    const char *fnidx = NULL; int reg_start = optind + 1;
    if (has_index_file) { if (optind + 1 < argc) { fnidx = argv[optind + 1]; reg_start = optind + 2; } }
    samfile_t *fp = sam_open_read_nohdr(fn);
    if (!fp) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn, strerror(errno)); print_error_errno("stats", "failed to open \"%s\"", fn); return 1; }
    if (sam_read_header(fp) < 0) { print_error("stats", "failed to read header for \"%s\"", fn); sam_close(fp); return 1; }
    sam_hdr_t *h = fp->hdr;
    if (info.ref_fn) {
        info.fai = fai_load3(info.ref_fn, NULL, NULL, 1, FAI_FASTA);
        if (!info.fai) { print_error("stats", "Could not load faidx: %s", info.ref_fn); sam_close(fp); return 1; }
    }
    stats_t *s = stats_init(&info, h);
    if (info.targets_fn) {
        s->targets = bed_read(info.targets_fn);
        if (!s->targets) { print_error_errno("stats", "Could not read file \"%s\"", info.targets_fn); stats_destroy(s); sam_close(fp); return 1; }
    }
    if (info.rg_id) {
        s->rg_hash = strmap_new();
        /* match RG ID or SM */
        int found = 0;
        for (int i = 0; i < h->n_lines; i++) if (sam_hdr_line_type_is(h->lines[i], "RG")) {
            char *id = hdr_line_tag(h->lines[i], "ID"), *sm = hdr_line_tag(h->lines[i], "SM");
            if ((id && strcmp(id, info.rg_id) == 0) || (sm && strcmp(sm, info.rg_id) == 0)) { if (id) { strmap_set(s->rg_hash, id, 1); found = 1; } }
            free(id); free(sm);
        }
        (void)found;
    }
    bam1_t *b = bam_init1();
    int ret = 0, r;
    if (reg_start < argc) {
        hts_idx_t *idx = NULL;
        if (fp->fmt == FMT_BAM && bgzf_is_bgzf(fp->bg)) idx = sam_index_load2(fn, fnidx);
        if (!idx) {
            if (!fnidx) log_error("idx_find_and_load", "Could not retrieve index file for '%s'", fn);
            fprintf(stderr, "Random alignment retrieval only works for indexed files\n"); ret = 1;
        } else {
            for (int i = reg_start; i < argc && !ret; i++) {
                hts_itr_t *itr = sam_itr_querys(idx, h, argv[i]);
                if (!itr) { fprintf(stderr, "Could not parse region \"%s\"\n", argv[i]); ret = 1; break; }
                while ((r = sam_itr_next(fp, itr, b)) >= 0) collect_stats(b, s);
                hts_itr_destroy(itr);
                if (r < -1) { print_error("stats", "error reading from \"%s\"", fn); ret = 1; }
            }
            hts_idx_destroy(idx);
        }
    } else {
        while ((r = sam_read1(fp, h, b)) >= 0) collect_stats(b, s);
        if (r < -1) { print_error("stats", "error reading from \"%s\"", fn); ret = 1; }
    }
    if (!ret) {
        round_buffer_flush(s, -1);
        if (s->targets) {
            /* bases inside target */
            s->nbases_target = bed_total_len(s->targets);
        }
        output_stats(s, stdout);
    }
    bam_destroy1(b);
    if (s->targets) bed_destroy(s->targets);
    stats_destroy(s);
    if (info.fai) fai_destroy(info.fai);
    sam_close(fp);
    return ret;
}
EOF
sed -i '/STUB(main_stats, "stats")/d' src/stubs.c && make -j8 build/samtools 2>&1 | grep -E "error" | head; cd /tmp/w; C=./cmp.sh; DIFFLINES=10 $C stats /tmp/w/toy.sam; DIFFLINES=10 $C stats /tmp/w/ex1.bam"}

actions.command:
cd /workspace && cat > src/stats.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <errno.h>
#include <math.h>
#include <zlib.h>
#include "samtools.h"
#include "index.h"
#include "faidx.h"
#include "bedidx.h"
#include "strmap.h"
#include "log.h"

#define BWA_MIN_RDLEN 35

typedef struct { uint64_t a, c, g, t, n, other; } acgtno_count_t;
typedef struct { float gc; uint32_t depth; } gc_depth_t;
typedef struct { int32_t *buffer; int size, start; int64_t pos; } round_buffer_t;

typedef struct {
    int flag_require, flag_filter;
    int trim_qual, filter_readlen, nisize, ngc_depth_bin;
    double isize_main_bulk;
    int cov_min, cov_max, cov_step, cov_threshold;
    int remove_dups, sparse, remove_overlaps;
    char *ref_fn, *targets_fn, *split_tag, *split_prefix, *rg_id;
    faidx_t *fai;
    char **argv; int argc;
} stats_info_t;

typedef struct {
    stats_info_t *info;
    sam_hdr_t *hdr;
    int nquals, nbases, nisize, ngc, nindels;
    uint64_t *quals_1st, *quals_2nd, *gc_1st, *gc_2nd, *mapq;
    acgtno_count_t *acgtno_cycles_1st, *acgtno_cycles_2nd, *acgtno_revcomp;
    uint64_t *read_lengths, *read_lengths_1st, *read_lengths_2nd;
    uint64_t *insertions, *deletions, *ins_cycles_1st, *ins_cycles_2nd, *del_cycles_1st, *del_cycles_2nd;
    uint64_t *isize_inward, *isize_outward, *isize_other;
    uint64_t *mpc_buf;
    int max_len, max_qual, is_sorted;
    uint64_t total_len, total_len_dup, total_len_1st, total_len_2nd, nreads_1st, nreads_2nd, nreads_filtered, nreads_dup, nreads_unmapped, nreads_single_mapped, nreads_paired_and_mapped, nreads_properly_paired, nreads_paired_tech, nreads_anomalous, nreads_mq0, nreads_qc_failed, nreads_secondary, nreads_supplementary, nreads_mapped;
    uint64_t nbases_mapped, nbases_mapped_cigar, nbases_trimmed, nmismatches;
    int max_len_1st, max_len_2nd;
    double sum_qual;
    /* gcd */
    uint32_t ngcd, igcd, gcd_bin_size; int64_t gcd_pos; gc_depth_t *gcd; int tid; int64_t pos;
    /* coverage */
    int ncov; uint64_t *cov; round_buffer_t cov_rbuf;
    /* ref */
    char *rseq_buf; int64_t rseq_pos, nrseq_buf; int rseq_tid;
    uint32_t chk_names, chk_seqs, chk_quals;
    /* targets */
    bed_t *targets; uint64_t nbases_target, ntarget_cov_above;
    strmap_t *rg_hash;
} stats_t;

static void realloc_buffers(stats_t *s, int seq_len) {
    int n = 2 * seq_len; if (n < 2 * s->nbases) n = 2 * s->nbases;
    if (n <= s->nbases) return;
    int old = s->nbases;
#define GROW(arr, mult) do { arr = realloc(arr, (size_t)n * (mult) * sizeof(*arr)); memset(arr + (size_t)old * (mult), 0, ((size_t)(n - old)) * (mult) * sizeof(*arr)); } while (0)
    GROW(s->quals_1st, s->nquals); GROW(s->quals_2nd, s->nquals); GROW(s->mpc_buf, s->nquals);
    GROW(s->acgtno_cycles_1st, 1); GROW(s->acgtno_cycles_2nd, 1); GROW(s->acgtno_revcomp, 1);
    GROW(s->read_lengths, 1); GROW(s->read_lengths_1st, 1); GROW(s->read_lengths_2nd, 1);
    GROW(s->insertions, 1); GROW(s->deletions, 1);
    GROW(s->ins_cycles_1st, 1); GROW(s->ins_cycles_2nd, 1); GROW(s->del_cycles_1st, 1); GROW(s->del_cycles_2nd, 1);
#undef GROW
    s->nbases = n;
    s->nindels = n;
    /* coverage buffer must also be large enough */
    if (s->cov_rbuf.size < n) {
        int32_t *nb = calloc(n, sizeof(int32_t));
        /* re-linearize existing buffer */
        for (int i = 0; i < s->cov_rbuf.size; i++) nb[i] = s->cov_rbuf.buffer[(s->cov_rbuf.start + i) % s->cov_rbuf.size];
        free(s->cov_rbuf.buffer); s->cov_rbuf.buffer = nb; s->cov_rbuf.size = n; s->cov_rbuf.start = 0;
    }
}

static inline int coverage_idx(int min, int max, int n, int step, int depth) {
    if (depth < min) return 0;
    if (depth > max) return n - 1;
    return 1 + (depth - min) / step;
}

static void round_buffer_flush(stats_t *s, int64_t pos) {
    round_buffer_t *rb = &s->cov_rbuf;
    if (pos == rb->pos) return;
    int64_t new_pos = pos;
    if (pos == -1 || pos - rb->pos >= rb->size) pos = rb->pos + rb->size - 1;
    if (pos < rb->pos) return;
    int ifrom = rb->start;
    int64_t n = pos - rb->pos; if (n > rb->size) n = rb->size;
    for (int64_t k = 0; k < n; k++) {
        int ibuf = (int)((ifrom + k) % rb->size);
        if (rb->buffer[ibuf] == 0) continue;
        int icov = coverage_idx(s->info->cov_min, s->info->cov_max, s->ncov, s->info->cov_step, rb->buffer[ibuf]);
        s->cov[icov]++;
        rb->buffer[ibuf] = 0;
    }
    rb->start = (int)((rb->start + n) % rb->size);
    rb->pos = new_pos == -1 ? 0 : new_pos;
    if (new_pos == -1) { rb->start = 0; rb->pos = 0; }
}

static void round_buffer_insert_read(round_buffer_t *rb, int64_t from, int64_t to) {
    if (to - rb->pos >= rb->size) return;
    for (int64_t p = from; p <= to; p++) {
        if (p < rb->pos) continue;
        int ibuf = (int)((rb->start + (p - rb->pos)) % rb->size);
        rb->buffer[ibuf]++;
    }
}

static int bwa_trim_read(int trim_qual, uint8_t *quals, int len, int reverse) {
    if (len < BWA_MIN_RDLEN) return 0;
    int max_trimmed = len - BWA_MIN_RDLEN + 1;
    int l, sum = 0, max_sum = 0, max_l = 0;
    for (l = 0; l < max_trimmed; l++) {
        sum += trim_qual - quals[reverse ? l : len - 1 - l];
        if (sum < 0) break;
        if (sum > max_sum) { max_sum = sum; max_l = l + 1; }
    }
    return max_l;
}

static void count_indels(stats_t *s, bam1_t *b) {
    int is_fwd = (b->core.flag & BAM_FREVERSE) ? 0 : 1;
    int is_1st = (b->core.flag & BAM_FREAD2) ? 0 : 1;
    int icycle = 0, read_len = b->core.l_qseq;
    uint32_t *cig = bam_get_cigar(b);
    for (uint32_t k = 0; k < b->core.n_cigar; k++) {
        int op = bam_cigar_op(cig[k]), n = bam_cigar_oplen(cig[k]);
        if (!n) continue;
        if (op == BAM_CINS) {
            int idx = is_fwd ? icycle : read_len - icycle - n;
            if (idx >= 0 && idx < s->nbases) { if (is_1st) s->ins_cycles_1st[idx]++; else s->ins_cycles_2nd[idx]++; }
            icycle += n;
            if (n <= s->nindels) s->insertions[n-1]++;
            continue;
        }
        if (op == BAM_CDEL) {
            int idx = is_fwd ? icycle - 1 : read_len - icycle - 1;
            if (idx < 0) continue;
            if (idx < s->nbases) { if (is_1st) s->del_cycles_1st[idx]++; else s->del_cycles_2nd[idx]++; }
            if (n <= s->nindels) s->deletions[n-1]++;
            continue;
        }
        if (op != BAM_CREF_SKIP && op != BAM_CHARD_CLIP && op != BAM_CPAD) icycle += n;
    }
}

static void read_ref_seq(stats_t *s, int tid, int64_t pos) {
    if (!s->info->fai) return;
    free(s->rseq_buf); s->rseq_buf = NULL; s->nrseq_buf = 0;
    const char *name = sam_hdr_tid2name(s->hdr, tid);
    int64_t len;
    int64_t fetch_len = s->gcd_bin_size > 1000000 ? s->gcd_bin_size : 1000000;
    char *seq = name ? faidx_fetch_seq64(s->info->fai, name, pos, pos + fetch_len, &len) : NULL;
    if (!seq || len <= 0) { free(seq); s->rseq_pos = pos; s->rseq_tid = tid; return; }
    s->rseq_buf = malloc(len);
    for (int64_t i = 0; i < len; i++) s->rseq_buf[i] = (char)seq_nt16_table[(unsigned char)seq[i]];
    free(seq);
    s->nrseq_buf = len; s->rseq_pos = pos; s->rseq_tid = tid;
}

static float fai_gc_content(stats_t *s, int64_t pos, int len) {
    uint32_t gc = 0, count = 0;
    int64_t i = pos - s->rseq_pos, i_end = i + len;
    if (i_end > s->nrseq_buf) i_end = s->nrseq_buf;
    for (; i < i_end; i++) {
        unsigned char c = (unsigned char)s->rseq_buf[i];
        if (c == 2 || c == 4) gc++;
        if (c == 1 || c == 2 || c == 4 || c == 8) count++;
    }
    return count ? (float)gc / count : 0;
}

static void count_mismatches_per_cycle(stats_t *s, bam1_t *b) {
    int is_fwd = (b->core.flag & BAM_FREVERSE) ? 0 : 1;
    int iread = 0, icycle = 0;
    int64_t iref = b->core.pos - s->rseq_pos;
    int read_len = b->core.l_qseq;
    uint8_t *read = bam_get_seq(b), *quals = bam_get_qual(b);
    uint32_t *cig = bam_get_cigar(b);
    for (uint32_t k = 0; k < b->core.n_cigar; k++) {
        int op = bam_cigar_op(cig[k]), n = bam_cigar_oplen(cig[k]);
        if (op == BAM_CINS) { iread += n; icycle += n; continue; }
        if (op == BAM_CDEL) { iref += n; continue; }
        if (op == BAM_CSOFT_CLIP) { icycle += n; iread += n; continue; }
        if (op == BAM_CREF_SKIP || op == BAM_CHARD_CLIP || op == BAM_CPAD) { if (op == BAM_CREF_SKIP) iref += n; continue; }
        if (op != BAM_CMATCH && op != BAM_CEQUAL && op != BAM_CDIFF) continue;
        for (int im = 0; im < n; im++) {
            if (iref < 0 || iref >= s->nrseq_buf) { iref++; iread++; icycle++; continue; }
            uint8_t cread = iread < read_len ? bam_seqi(read, iread) : 15;
            uint8_t cref = (uint8_t)s->rseq_buf[iref];
            int idx = is_fwd ? icycle : read_len - icycle - 1;
            if (idx < 0 || idx > s->max_len || idx >= s->nbases) { iref++; iread++; icycle++; continue; }
            if (cread == 15) s->mpc_buf[(size_t)idx * s->nquals]++;
            else if (cref && cread && cref != cread) {
                int q = (iread < read_len ? quals[iread] : 0) + 1;
                if (q < s->nquals) s->mpc_buf[(size_t)idx * s->nquals + q]++;
            }
            iref++; iread++; icycle++;
        }
    }
}

static void collect_stats(bam1_t *b, stats_t *s) {
    stats_info_t *info = s->info;
    if (s->rg_hash) {
        uint8_t *rg = bam_aux_get(b, "RG");
        if (!rg || !strmap_find(s->rg_hash, (char*)rg + 1)) return;
    }
    int flag = b->core.flag;
    if (info->flag_require && (flag & info->flag_require) != info->flag_require) { s->nreads_filtered++; return; }
    if (info->flag_filter && (flag & info->flag_filter)) { s->nreads_filtered++; return; }
    if (s->targets) {
        if (b->core.tid < 0 || !bed_overlap(s->targets, sam_hdr_tid2name(s->hdr, b->core.tid), b->core.pos, bam_endpos(b))) return;
    }
    if (info->filter_readlen != -1 && b->core.l_qseq != info->filter_readlen) return;
    if (flag & BAM_FQCFAIL) s->nreads_qc_failed++;
    if (flag & BAM_FPAIRED) s->nreads_paired_tech++;
    if (flag & BAM_FSECONDARY) { s->nreads_secondary++; return; }
    if (flag & BAM_FSUPPLEMENTARY) { s->nreads_supplementary++; return; }
    /* checksums */
    s->chk_names += crc32(0, (uint8_t*)bam_get_qname(b), b->core.l_qname - 1 - b->core.l_extranul);
    s->chk_seqs += crc32(0, bam_get_seq(b), (b->core.l_qseq + 1) / 2);
    s->chk_quals += crc32(0, bam_get_qual(b), b->core.l_qseq);

    int seq_len = b->core.l_qseq;
    if (!seq_len) return;
    int read_len = seq_len;
    uint32_t *cig = bam_get_cigar(b);
    for (uint32_t k = 0; k < b->core.n_cigar; k++) if (bam_cigar_op(cig[k]) == BAM_CHARD_CLIP) read_len += bam_cigar_oplen(cig[k]);
    int need = read_len > seq_len ? read_len : seq_len;
    if (need >= s->nbases) realloc_buffers(s, need + 1);
    if (s->max_len < seq_len) s->max_len = seq_len;

    int is_1st = (flag & BAM_FREAD2) ? 0 : 1;
    uint64_t *quals; acgtno_count_t *acgtno; uint64_t *gc_arr;
    if (is_1st) { s->nreads_1st++; s->total_len_1st += seq_len; if (s->max_len_1st < seq_len) s->max_len_1st = seq_len; quals = s->quals_1st; acgtno = s->acgtno_cycles_1st; gc_arr = s->gc_1st; s->read_lengths_1st[read_len]++; }
    else { s->nreads_2nd++; s->total_len_2nd += seq_len; if (s->max_len_2nd < seq_len) s->max_len_2nd = seq_len; quals = s->quals_2nd; acgtno = s->acgtno_cycles_2nd; gc_arr = s->gc_2nd; s->read_lengths_2nd[read_len]++; }
    s->read_lengths[read_len]++;
    s->total_len += seq_len;
    if (flag & BAM_FDUP) { s->nreads_dup++; s->total_len_dup += seq_len; }

    int reverse = (flag & BAM_FREVERSE) ? 1 : 0;
    uint8_t *seq = bam_get_seq(b), *bq = bam_get_qual(b);
    int gc_count = 0;
    for (int i = 0; i < seq_len; i++) {
        int base = bam_seqi(seq, i);
        int cycle = reverse ? seq_len - i - 1 : i;
        acgtno_count_t *fwd = &acgtno[i];
        switch (base) {
        case 1: fwd->a++; break; case 2: fwd->c++; gc_count++; break; case 4: fwd->g++; gc_count++; break; case 8: fwd->t++; break;
        case 15: fwd->n++; break; default: fwd->other++; break;
        }
        /* read-oriented table: complement for reverse */
        acgtno_count_t *ro = &s->acgtno_revcomp[cycle];
        int rbase = reverse ? (base == 1 ? 8 : base == 2 ? 4 : base == 4 ? 2 : base == 8 ? 1 : base) : base;
        switch (rbase) {
        case 1: ro->a++; break; case 2: ro->c++; break; case 4: ro->g++; break; case 8: ro->t++; break;
        case 15: ro->n++; break; default: ro->other++; break;
        }
        int q = bq[i];
        if (q > s->max_qual) s->max_qual = q;
        quals[(size_t)cycle * s->nquals + q]++;
        s->sum_qual += q;
    }
    {
        int gc_idx_min = gc_count * (s->ngc - 1) / seq_len;
        int gc_idx_max = (gc_count + 1) * (s->ngc - 1) / seq_len;
        if (gc_idx_max >= s->ngc) gc_idx_max = s->ngc - 1;
        for (int i = gc_idx_min; i < gc_idx_max; i++) gc_arr[i]++;
    }
    if (info->trim_qual > 0) s->nbases_trimmed += bwa_trim_read(info->trim_qual, bq, seq_len, reverse);

    if (flag & BAM_FUNMAP) { s->nreads_unmapped++; return; }
    if (!b->core.qual) s->nreads_mq0++;
    if (!(flag & BAM_FQCFAIL) && !(flag & BAM_FDUP)) s->mapq[b->core.qual]++;
    count_indels(s, b);
    if (!(flag & BAM_FPAIRED) || (flag & BAM_FMUNMAP)) s->nreads_single_mapped++;
    else {
        s->nreads_paired_and_mapped++;
        if (b->core.tid != b->core.mtid) s->nreads_anomalous++;
        else {
            int64_t isize = b->core.isize; if (isize < 0) isize = -isize;
            if (isize > s->nisize) isize = s->nisize;
            if (isize > 0) {
                int64_t pos_fst = b->core.mpos - b->core.pos;
                int is_fst = (flag & BAM_FREAD1) ? 1 : -1;
                int is_fwd = (flag & BAM_FREVERSE) ? -1 : 1;
                int is_mfwd = (flag & BAM_FMREVERSE) ? -1 : 1;
                if (is_fwd * is_mfwd > 0) s->isize_other[isize]++;
                else if (is_fst * pos_fst > 0) { if (is_fst * is_fwd > 0) s->isize_inward[isize]++; else s->isize_outward[isize]++; }
                else if (is_fst * pos_fst < 0) { if (is_fst * is_fwd > 0) s->isize_outward[isize]++; else s->isize_inward[isize]++; }
            }
        }
    }
    if (flag & BAM_FPROPER_PAIR) s->nreads_properly_paired++;
    s->nreads_mapped++;
    s->nbases_mapped += seq_len;
    for (uint32_t k = 0; k < b->core.n_cigar; k++) { int op = bam_cigar_op(cig[k]); if (op == BAM_CMATCH || op == BAM_CINS || op == BAM_CEQUAL || op == BAM_CDIFF) s->nbases_mapped_cigar += bam_cigar_oplen(cig[k]); }
    uint8_t *nm = bam_aux_get(b, "NM");
    if (nm && bam_aux_is_int(nm)) s->nmismatches += bam_aux2i(nm);

    if (s->tid == b->core.tid && b->core.pos < s->pos) s->is_sorted = 0;
    s->pos = b->core.pos;
    if (s->is_sorted) {
        if (s->tid == -1 || s->tid != b->core.tid) round_buffer_flush(s, -1);
        if (info->fai) {
            int inc_ref = 0, inc_gcd = 0;
            if (s->rseq_pos == -1 || s->tid != b->core.tid) { inc_ref = 1; inc_gcd = 1; }
            else if (s->rseq_pos + s->nrseq_buf < b->core.pos + read_len) { inc_ref = 1; inc_gcd = 1; }
            else if (s->gcd_pos + (int64_t)s->gcd_bin_size < b->core.pos + read_len) {
                inc_gcd = 1;
                if (s->rseq_pos + s->nrseq_buf < b->core.pos + (int64_t)s->gcd_bin_size) inc_ref = 1;
            }
            if (inc_gcd) {
                s->igcd++;
                if (s->igcd >= s->ngcd) { uint32_t o = s->ngcd; s->ngcd = s->ngcd ? s->ngcd * 2 : 1024; s->gcd = realloc(s->gcd, s->ngcd * sizeof(gc_depth_t)); memset(s->gcd + o, 0, (s->ngcd - o) * sizeof(gc_depth_t)); }
                if (inc_ref) read_ref_seq(s, b->core.tid, b->core.pos);
                s->gcd_pos = b->core.pos;
                s->gcd[s->igcd].gc = fai_gc_content(s, s->gcd_pos, s->gcd_bin_size);
            }
            count_mismatches_per_cycle(s, b);
        } else if (s->gcd_pos == -1 || s->tid != b->core.tid || b->core.pos - s->gcd_pos > (int64_t)s->gcd_bin_size) {
            /* finalise previous bin */
            if (s->gcd_pos != -1 && s->gcd[s->igcd].depth) s->gcd[s->igcd].gc = s->gcd[s->igcd].gc / s->gcd[s->igcd].depth * 100;
            s->tid = b->core.tid;
            s->gcd_pos = b->core.pos;
            s->igcd++;
            if (s->igcd >= s->ngcd) { uint32_t o = s->ngcd; s->ngcd = s->ngcd ? s->ngcd * 2 : 1024; s->gcd = realloc(s->gcd, s->ngcd * sizeof(gc_depth_t)); memset(s->gcd + o, 0, (s->ngcd - o) * sizeof(gc_depth_t)); }
        }
        s->gcd[s->igcd].depth++;
        if (!info->fai) s->gcd[s->igcd].gc += (float)gc_count / seq_len;
        /* coverage */
        round_buffer_flush(s, b->core.pos);
        int64_t rpos = b->core.pos;
        for (uint32_t k = 0; k < b->core.n_cigar; k++) {
            int op = bam_cigar_op(cig[k]), n = bam_cigar_oplen(cig[k]);
            if (op == BAM_CMATCH || op == BAM_CEQUAL || op == BAM_CDIFF) { round_buffer_insert_read(&s->cov_rbuf, rpos, rpos + n - 1); rpos += n; }
            else if (op == BAM_CDEL || op == BAM_CREF_SKIP) rpos += n;
        }
    }
    s->tid = b->core.tid;
}

static float gcd_percentile(gc_depth_t *gcd, int N, int p) {
    float n = p * (N + 1) / 100.f;
    int k = (int)n;
    if (k <= 0) return gcd[0].depth;
    if (k >= N) return gcd[N-1].depth;
    float d = n - k;
    return gcd[k-1].depth + d * (gcd[k].depth - gcd[k-1].depth);
}
static int gcd_cmp(const void *a, const void *b) {
    const gc_depth_t *x = a, *y = b;
    if (x->gc < y->gc) return -1; if (x->gc > y->gc) return 1;
    if (x->depth < y->depth) return -1; if (x->depth > y->depth) return 1;
    return 0;
}

static void output_stats(stats_t *s, FILE *to) {
    stats_info_t *info = s->info;
    int i;
    fprintf(to, "# This file was produced by samtools stats (%s+htslib-%s) and can be plotted using plot-bamstats\n", SAMTOOLS_VERSION, HTSLIB_VERSION);
    if (info->rg_id) fprintf(to, "# This file contains statistics for reads with RG tag %s\n", info->rg_id);
    else fprintf(to, "# This file contains statistics for all reads.\n");
    fprintf(to, "# The command line was:  ");
    for (i = 0; i < info->argc; i++) fprintf(to, "%s%s", i ? " " : "", info->argv[i]);
    fprintf(to, "\n");
    fprintf(to, "# CHK, Checksum\t[2]Read Names\t[3]Sequences\t[4]Qualities\n");
    fprintf(to, "# CHK, CRC32 of reads which passed filtering followed by addition (32bit overflow)\n");
    fprintf(to, "CHK\t%08x\t%08x\t%08x\n", s->chk_names, s->chk_seqs, s->chk_quals);
    fprintf(to, "# Summary Numbers. Use `grep ^SN | cut -f 2-` to extract this part.\n");
    uint64_t nreads = s->nreads_1st + s->nreads_2nd;
    fprintf(to, "SN\traw total sequences:\t%llu\t# excluding supplementary and secondary reads\n", (unsigned long long)(s->nreads_filtered + nreads));
    fprintf(to, "SN\tfiltered sequences:\t%llu\n", (unsigned long long)s->nreads_filtered);
    fprintf(to, "SN\tsequences:\t%llu\n", (unsigned long long)nreads);
    fprintf(to, "SN\tis sorted:\t%d\t# sorted by coordinate\n", s->is_sorted ? 1 : 0);
    fprintf(to, "SN\t1st fragments:\t%llu\n", (unsigned long long)s->nreads_1st);
    fprintf(to, "SN\tlast fragments:\t%llu\n", (unsigned long long)s->nreads_2nd);
    fprintf(to, "SN\treads mapped:\t%llu\n", (unsigned long long)s->nreads_mapped);
    fprintf(to, "SN\treads mapped and paired:\t%llu\t# paired-end technology bit set + both mates mapped\n", (unsigned long long)s->nreads_paired_and_mapped);
    fprintf(to, "SN\treads unmapped:\t%llu\n", (unsigned long long)s->nreads_unmapped);
    fprintf(to, "SN\treads properly paired:\t%llu\t# proper-pair bit set\n", (unsigned long long)s->nreads_properly_paired);
    fprintf(to, "SN\treads paired:\t%llu\t# paired-end technology bit set\n", (unsigned long long)s->nreads_paired_tech);
    fprintf(to, "SN\treads duplicated:\t%llu\t# PCR or optical duplicate bit set\n", (unsigned long long)s->nreads_dup);
    fprintf(to, "SN\treads MQ0:\t%llu\t# mapped and MQ=0\n", (unsigned long long)s->nreads_mq0);
    fprintf(to, "SN\treads QC failed:\t%llu\n", (unsigned long long)s->nreads_qc_failed);
    fprintf(to, "SN\tnon-primary alignments:\t%llu\n", (unsigned long long)s->nreads_secondary);
    fprintf(to, "SN\tsupplementary alignments:\t%llu\n", (unsigned long long)s->nreads_supplementary);
    fprintf(to, "SN\ttotal length:\t%llu\t# ignores clipping\n", (unsigned long long)s->total_len);
    fprintf(to, "SN\ttotal first fragment length:\t%llu\t# ignores clipping\n", (unsigned long long)s->total_len_1st);
    fprintf(to, "SN\ttotal last fragment length:\t%llu\t# ignores clipping\n", (unsigned long long)s->total_len_2nd);
    fprintf(to, "SN\tbases mapped:\t%llu\t# ignores clipping\n", (unsigned long long)s->nbases_mapped);
    fprintf(to, "SN\tbases mapped (cigar):\t%llu\t# more accurate\n", (unsigned long long)s->nbases_mapped_cigar);
    fprintf(to, "SN\tbases trimmed:\t%llu\n", (unsigned long long)s->nbases_trimmed);
    fprintf(to, "SN\tbases duplicated:\t%llu\n", (unsigned long long)s->total_len_dup);
    fprintf(to, "SN\tmismatches:\t%llu\t# from NM fields\n", (unsigned long long)s->nmismatches);
    fprintf(to, "SN\terror rate:\t%e\t# mismatches / bases mapped (cigar)\n", s->nbases_mapped_cigar ? (double)s->nmismatches / s->nbases_mapped_cigar : 0.0);
    float avg_read_length = nreads ? (float)s->total_len / nreads : 0;
    float avg_read_length_1st = s->nreads_1st ? (float)s->total_len_1st / s->nreads_1st : 0;
    float avg_read_length_2nd = s->nreads_2nd ? (float)s->total_len_2nd / s->nreads_2nd : 0;
    fprintf(to, "SN\taverage length:\t%.0f\n", floorf(avg_read_length));
    fprintf(to, "SN\taverage first fragment length:\t%.0f\n", floorf(avg_read_length_1st));
    fprintf(to, "SN\taverage last fragment length:\t%.0f\n", floorf(avg_read_length_2nd));
    fprintf(to, "SN\tmaximum length:\t%d\n", s->max_len);
    fprintf(to, "SN\tmaximum first fragment length:\t%d\n", s->max_len_1st);
    fprintf(to, "SN\tmaximum last fragment length:\t%d\n", s->max_len_2nd);
    fprintf(to, "SN\taverage quality:\t%.1f\n", s->total_len ? s->sum_qual / s->total_len : 0);
    /* insert sizes */
    int nitems = s->nisize + 1;
    uint64_t nisize = 0, nisize_inward = 0, nisize_outward = 0, nisize_other = 0;
    for (i = 0; i < nitems; i++) {
        s->isize_inward[i] /= 2; s->isize_outward[i] /= 2; s->isize_other[i] /= 2;
        nisize_inward += s->isize_inward[i]; nisize_outward += s->isize_outward[i]; nisize_other += s->isize_other[i];
        nisize += s->isize_inward[i] + s->isize_outward[i] + s->isize_other[i];
    }
    double bulk = 0, avg_isize = 0, sd_isize = 0;
    int ibulk = 0;
    for (i = 0; i < nitems; i++) {
        uint64_t tot = s->isize_inward[i] + s->isize_outward[i] + s->isize_other[i];
        bulk += tot; avg_isize += (double)i * tot;
        if (nisize && bulk / nisize > info->isize_main_bulk) { ibulk = i + 1; nisize = (uint64_t)bulk; break; }
    }
    avg_isize /= nisize ? nisize : 1;
    for (i = 1; i < ibulk; i++) { uint64_t tot = s->isize_inward[i] + s->isize_outward[i] + s->isize_other[i]; sd_isize += tot * (i - avg_isize) * (i - avg_isize) / (nisize ? nisize : 1); }
    sd_isize = sqrt(sd_isize);
    fprintf(to, "SN\tinsert size average:\t%.1f\n", avg_isize);
    fprintf(to, "SN\tinsert size standard deviation:\t%.1f\n", sd_isize);
    fprintf(to, "SN\tinward oriented pairs:\t%llu\n", (unsigned long long)nisize_inward);
    fprintf(to, "SN\toutward oriented pairs:\t%llu\n", (unsigned long long)nisize_outward);
    fprintf(to, "SN\tpairs with other orientation:\t%llu\n", (unsigned long long)nisize_other);
    fprintf(to, "SN\tpairs on different chromosomes:\t%llu\n", (unsigned long long)(s->nreads_anomalous / 2));
    fprintf(to, "SN\tpercentage of properly paired reads (%%):\t%.1f\n", nreads ? (float)(100.0 * s->nreads_properly_paired / nreads) : 0);
    if (s->targets) {
        fprintf(to, "SN\tbases inside the target:\t%llu\n", (unsigned long long)s->nbases_target);
        fprintf(to, "SN\tpercentage of target genome with coverage > %d (%%):\t%.2f\n", info->cov_threshold, s->nbases_target ? 100.0 * s->ntarget_cov_above / s->nbases_target : 0.0);
    }
    int ibase, iqual;
    fprintf(to, "# First Fragment Qualities. Use `grep ^FFQ | cut -f 2-` to extract this part.\n# Columns correspond to qualities and rows to cycles. First column is the cycle number.\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        fprintf(to, "FFQ\t%d", ibase + 1);
        for (iqual = 0; iqual <= s->max_qual; iqual++) fprintf(to, "\t%llu", (unsigned long long)s->quals_1st[(size_t)ibase * s->nquals + iqual]);
        fprintf(to, "\n");
    }
    fprintf(to, "# Last Fragment Qualities. Use `grep ^LFQ | cut -f 2-` to extract this part.\n# Columns correspond to qualities and rows to cycles. First column is the cycle number.\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        fprintf(to, "LFQ\t%d", ibase + 1);
        for (iqual = 0; iqual <= s->max_qual; iqual++) fprintf(to, "\t%llu", (unsigned long long)s->quals_2nd[(size_t)ibase * s->nquals + iqual]);
        fprintf(to, "\n");
    }
    if (s->mpc_buf && info->fai) {
        fprintf(to, "# Mismatches per cycle and quality. Use `grep ^MPC | cut -f 2-` to extract this part.\n# Columns correspond to qualities, rows to cycles. First column is the cycle number, second\n# is the number of N's and the rest is the number of mismatches\n");
        for (ibase = 0; ibase <= s->max_len; ibase++) {
            fprintf(to, "MPC\t%d", ibase + 1);
            for (iqual = 0; iqual <= s->max_qual; iqual++) fprintf(to, "\t%llu", (unsigned long long)s->mpc_buf[(size_t)ibase * s->nquals + iqual]);
            fprintf(to, "\n");
        }
    }
    fprintf(to, "# GC Content of first fragments. Use `grep ^GCF | cut -f 2-` to extract this part.\n");
    int ibase_prev = 0;
    for (ibase = 0; ibase < s->ngc; ibase++) {
        if (s->gc_1st[ibase] == s->gc_1st[ibase_prev]) continue;
        fprintf(to, "GCF\t%.2f\t%llu\n", (ibase + ibase_prev) * 0.5 * 100. / (s->ngc - 1), (unsigned long long)s->gc_1st[ibase_prev]);
        ibase_prev = ibase;
    }
    fprintf(to, "# GC Content of last fragments. Use `grep ^GCL | cut -f 2-` to extract this part.\n");
    ibase_prev = 0;
    for (ibase = 0; ibase < s->ngc; ibase++) {
        if (s->gc_2nd[ibase] == s->gc_2nd[ibase_prev]) continue;
        fprintf(to, "GCL\t%.2f\t%llu\n", (ibase + ibase_prev) * 0.5 * 100. / (s->ngc - 1), (unsigned long long)s->gc_2nd[ibase_prev]);
        ibase_prev = ibase;
    }
    fprintf(to, "# ACGT content per cycle. Use `grep ^GCC | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]; and N and O counts as a percentage of all A/C/G/T bases [%%]\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        acgtno_count_t *a1 = &s->acgtno_cycles_1st[ibase], *a2 = &s->acgtno_cycles_2nd[ibase];
        uint64_t a = a1->a + a2->a, c = a1->c + a2->c, g = a1->g + a2->g, t = a1->t + a2->t, n = a1->n + a2->n, o = a1->other + a2->other;
        uint64_t sum = a + c + g + t;
        if (!sum) continue;
        fprintf(to, "GCC\t%d\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\n", ibase + 1, 100. * a / sum, 100. * c / sum, 100. * g / sum, 100. * t / sum, 100. * n / sum, 100. * o / sum);
    }
    fprintf(to, "# ACGT content per cycle, read oriented. Use `grep ^GCT | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        acgtno_count_t *a1 = &s->acgtno_revcomp[ibase];
        uint64_t sum = a1->a + a1->c + a1->g + a1->t;
        if (!sum) continue;
        fprintf(to, "GCT\t%d\t%.2f\t%.2f\t%.2f\t%.2f\n", ibase + 1, 100. * a1->a / sum, 100. * a1->c / sum, 100. * a1->g / sum, 100. * a1->t / sum);
    }
    fprintf(to, "# ACGT content per cycle for first fragments. Use `grep ^FBC | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]; and N and O counts as a percentage of all A/C/G/T bases [%%]\n");
    uint64_t ta = 0, tc = 0, tg = 0, tt = 0, tn = 0;
    for (ibase = 0; ibase < s->max_len; ibase++) {
        acgtno_count_t *a1 = &s->acgtno_cycles_1st[ibase];
        ta += a1->a; tc += a1->c; tg += a1->g; tt += a1->t; tn += a1->n;
        uint64_t sum = a1->a + a1->c + a1->g + a1->t;
        if (!sum) continue;
        fprintf(to, "FBC\t%d\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\n", ibase + 1, 100. * a1->a / sum, 100. * a1->c / sum, 100. * a1->g / sum, 100. * a1->t / sum, 100. * a1->n / sum, 100. * a1->other / sum);
    }
    fprintf(to, "# ACGT raw counters for first fragments. Use `grep ^FTC | cut -f 2-` to extract this part. The columns are: A,C,G,T,N base counters\n");
    fprintf(to, "FTC\t%llu\t%llu\t%llu\t%llu\t%llu\n", (unsigned long long)ta, (unsigned long long)tc, (unsigned long long)tg, (unsigned long long)tt, (unsigned long long)tn);
    fprintf(to, "# ACGT content per cycle for last fragments. Use `grep ^LBC | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]; and N and O counts as a percentage of all A/C/G/T bases [%%]\n");
    ta = tc = tg = tt = tn = 0;
    for (ibase = 0; ibase < s->max_len; ibase++) {
        acgtno_count_t *a1 = &s->acgtno_cycles_2nd[ibase];
        ta += a1->a; tc += a1->c; tg += a1->g; tt += a1->t; tn += a1->n;
        uint64_t sum = a1->a + a1->c + a1->g + a1->t;
        if (!sum) continue;
        fprintf(to, "LBC\t%d\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\n", ibase + 1, 100. * a1->a / sum, 100. * a1->c / sum, 100. * a1->g / sum, 100. * a1->t / sum, 100. * a1->n / sum, 100. * a1->other / sum);
    }
    fprintf(to, "# ACGT raw counters for last fragments. Use `grep ^LTC | cut -f 2-` to extract this part. The columns are: A,C,G,T,N base counters\n");
    fprintf(to, "LTC\t%llu\t%llu\t%llu\t%llu\t%llu\n", (unsigned long long)ta, (unsigned long long)tc, (unsigned long long)tg, (unsigned long long)tt, (unsigned long long)tn);
    fprintf(to, "# Insert sizes. Use `grep ^IS | cut -f 2-` to extract this part. The columns are: insert size, pairs total, inward oriented pairs, outward oriented pairs, other pairs\n");
    for (i = 0; i < ibulk; i++) {
        uint64_t tot = s->isize_inward[i] + s->isize_outward[i] + s->isize_other[i];
        if (info->sparse && !tot) continue;
        fprintf(to, "IS\t%d\t%llu\t%llu\t%llu\t%llu\n", i, (unsigned long long)tot, (unsigned long long)s->isize_inward[i], (unsigned long long)s->isize_outward[i], (unsigned long long)s->isize_other[i]);
    }
    fprintf(to, "# Read lengths. Use `grep ^RL | cut -f 2-` to extract this part. The columns are: read length, count\n");
    int ilen;
    for (ilen = 0; ilen < s->nbases; ilen++) if (s->read_lengths[ilen] > 0) fprintf(to, "RL\t%d\t%llu\n", ilen, (unsigned long long)s->read_lengths[ilen]);
    fprintf(to, "# Read lengths - first fragments. Use `grep ^FRL | cut -f 2-` to extract this part. The columns are: read length, count\n");
    for (ilen = 0; ilen < s->nbases; ilen++) if (s->read_lengths_1st[ilen] > 0) fprintf(to, "FRL\t%d\t%llu\n", ilen, (unsigned long long)s->read_lengths_1st[ilen]);
    fprintf(to, "# Read lengths - last fragments. Use `grep ^LRL | cut -f 2-` to extract this part. The columns are: read length, count\n");
    for (ilen = 0; ilen < s->nbases; ilen++) if (s->read_lengths_2nd[ilen] > 0) fprintf(to, "LRL\t%d\t%llu\n", ilen, (unsigned long long)s->read_lengths_2nd[ilen]);
    fprintf(to, "# Mapping qualities for reads !(UNMAP|SECOND|SUPPL|QCFAIL|DUP). Use `grep ^MAPQ | cut -f 2-` to extract this part. The columns are: mapq, count\n");
    for (i = 0; i < s->nquals; i++) if (s->mapq[i] > 0) fprintf(to, "MAPQ\t%d\t%llu\n", i, (unsigned long long)s->mapq[i]);
    fprintf(to, "# Indel distribution. Use `grep ^ID | cut -f 2-` to extract this part. The columns are: length, number of insertions, number of deletions\n");
    for (ilen = 0; ilen < s->nindels; ilen++) if (s->insertions[ilen] > 0 || s->deletions[ilen] > 0) fprintf(to, "ID\t%d\t%llu\t%llu\n", ilen + 1, (unsigned long long)s->insertions[ilen], (unsigned long long)s->deletions[ilen]);
    fprintf(to, "# Indels per cycle. Use `grep ^IC | cut -f 2-` to extract this part. The columns are: cycle, number of insertions (fwd), .. (rev) , number of deletions (fwd), .. (rev)\n");
    for (ilen = 0; ilen <= s->nbases; ilen++) {
        if (ilen >= s->nbases) break;
        if (s->ins_cycles_1st[ilen] > 0 || s->ins_cycles_2nd[ilen] > 0 || s->del_cycles_1st[ilen] > 0 || s->del_cycles_2nd[ilen] > 0)
            fprintf(to, "IC\t%d\t%llu\t%llu\t%llu\t%llu\n", ilen + 1, (unsigned long long)s->ins_cycles_1st[ilen], (unsigned long long)s->ins_cycles_2nd[ilen], (unsigned long long)s->del_cycles_1st[ilen], (unsigned long long)s->del_cycles_2nd[ilen]);
    }
    fprintf(to, "# Coverage distribution. Use `grep ^COV | cut -f 2-` to extract this part.\n");
    if (s->cov[0]) fprintf(to, "COV\t[<%d]\t%d\t%llu\n", info->cov_min, info->cov_min - 1, (unsigned long long)s->cov[0]);
    for (int icov = 1; icov < s->ncov - 1; icov++)
        if (s->cov[icov]) fprintf(to, "COV\t[%d-%d]\t%d\t%llu\n", info->cov_min + (icov - 1) * info->cov_step, info->cov_min + icov * info->cov_step - 1, info->cov_min + icov * info->cov_step - 1, (unsigned long long)s->cov[icov]);
    if (s->cov[s->ncov - 1]) fprintf(to, "COV\t[%d<]\t%d\t%llu\n", info->cov_max - 1, info->cov_max - 1, (unsigned long long)s->cov[s->ncov - 1]);
    fprintf(to, "# GC-depth. Use `grep ^GCD | cut -f 2-` to extract this part. The columns are: GC%%, unique sequence percentiles, 10th, 25th, 50th, 75th and 90th depth percentile\n");
    /* add dummy */
    s->igcd++;
    if (s->igcd >= s->ngcd) { uint32_t o = s->ngcd; s->ngcd = s->ngcd ? s->ngcd * 2 : 1024; s->gcd = realloc(s->gcd, s->ngcd * sizeof(gc_depth_t)); memset(s->gcd + o, 0, (s->ngcd - o) * sizeof(gc_depth_t)); }
    s->gcd[s->igcd].gc = 0; s->gcd[s->igcd].depth = 0;
    qsort(s->gcd, s->igcd + 1, sizeof(gc_depth_t), gcd_cmp);
    uint32_t igcd = 0;
    while (igcd < s->igcd) {
        uint32_t nbins = 0, itmp = igcd;
        float gc = s->gcd[igcd].gc;
        while (itmp < s->igcd && fabs(s->gcd[itmp].gc - gc) < 0.1) { nbins++; itmp++; }
        fprintf(to, "GCD\t%.1f\t%.3f\t%.3f\t%.3f\t%.3f\t%.3f\t%.3f\n", gc, (igcd + nbins) * 100. / s->igcd,
                gcd_percentile(&s->gcd[igcd], nbins, 10) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[igcd], nbins, 25) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[igcd], nbins, 50) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[igcd], nbins, 75) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[igcd], nbins, 90) * avg_read_length / s->gcd_bin_size);
        igcd += nbins;
    }
}

static stats_t *stats_init(stats_info_t *info, sam_hdr_t *hdr) {
    stats_t *s = calloc(1, sizeof(stats_t));
    s->info = info; s->hdr = hdr;
    s->nquals = 256; s->nbases = 0; s->nisize = info->nisize; s->ngc = 200;
    s->is_sorted = 1; s->tid = -1; s->gcd_pos = -1; s->rseq_pos = -1; s->rseq_tid = -1;
    s->gcd_bin_size = info->ngc_depth_bin;
    s->ncov = (info->cov_max - info->cov_min) / info->cov_step + 3;
    s->cov = calloc(s->ncov, sizeof(uint64_t));
    s->mapq = calloc(s->nquals, sizeof(uint64_t));
    s->gc_1st = calloc(s->ngc, sizeof(uint64_t)); s->gc_2nd = calloc(s->ngc, sizeof(uint64_t));
    s->isize_inward = calloc(s->nisize + 1, sizeof(uint64_t)); s->isize_outward = calloc(s->nisize + 1, sizeof(uint64_t)); s->isize_other = calloc(s->nisize + 1, sizeof(uint64_t));
    s->ngcd = 1024; s->gcd = calloc(s->ngcd, sizeof(gc_depth_t)); s->igcd = 0;
    s->cov_rbuf.size = 2048; s->cov_rbuf.buffer = calloc(s->cov_rbuf.size, sizeof(int32_t));
    realloc_buffers(s, 300);
    return s;
}

static void stats_destroy(stats_t *s) {
    free(s->quals_1st); free(s->quals_2nd); free(s->mpc_buf); free(s->acgtno_cycles_1st); free(s->acgtno_cycles_2nd); free(s->acgtno_revcomp);
    free(s->read_lengths); free(s->read_lengths_1st); free(s->read_lengths_2nd); free(s->insertions); free(s->deletions);
    free(s->ins_cycles_1st); free(s->ins_cycles_2nd); free(s->del_cycles_1st); free(s->del_cycles_2nd);
    free(s->isize_inward); free(s->isize_outward); free(s->isize_other); free(s->cov); free(s->mapq); free(s->gc_1st); free(s->gc_2nd);
    free(s->gcd); free(s->cov_rbuf.buffer); free(s->rseq_buf); strmap_free(s->rg_hash);
    free(s);
}

static void stats_usage(FILE *fp) {
    fprintf(fp,
"About: The program collects statistics from BAM files. The output can be visualized using plot-bamstats.\n"
"Usage: samtools stats [OPTIONS] file.bam\n"
"       samtools stats [OPTIONS] file.bam chr:from-to\n"
"Options:\n"
"    -c, --coverage <int>,<int>,<int>    Coverage distribution min,max,step [1,1000,1]\n"
"    -d, --remove-dups                   Exclude from statistics reads marked as duplicates\n"
"    -X, --customized-index-file         Use a customized index file\n"
"    -f, --required-flag  <str|int>      Required flag, 0 for unset. See also `samtools flags` [0]\n"
"    -F, --filtering-flag <str|int>      Filtering flag, 0 for unset. See also `samtools flags` [0]\n"
"        --GC-depth <float>              the size of GC-depth bins (decreasing bin size increases memory requirement) [2e4]\n"
"    -h, --help                          This help message\n"
"    -i, --insert-size <int>             Maximum insert size [8000]\n"
"    -I, --id <string>                   Include only listed read group or sample name\n"
"    -l, --read-length <int>             Include in the statistics only reads with the given read length [-1]\n"
"    -m, --most-inserts <float>          Report only the main part of inserts [0.99]\n"
"    -P, --split-prefix <str>            Path or string prefix for filepaths output by -S (default is input filename)\n"
"    -q, --trim-quality <int>            The BWA trimming parameter [0]\n"
"    -r, --ref-seq <file>                Reference sequence (required for GC-depth and mismatches-per-cycle calculation).\n"
"    -s, --sam                           Ignored (input format is auto-detected).\n"
"    -S, --split <tag>                   Also write statistics to separate files split by tagged field.\n"
"    -t, --target-regions <file>         Do stats in these regions only. Tab-delimited file chr,from,to, 1-based, inclusive.\n"
"    -x, --sparse                        Suppress outputting IS rows where there are no insertions.\n"
"    -p, --remove-overlaps               Remove overlaps of paired-end reads from coverage and base count computations.\n"
"    -g, --cov-threshold <int>           Only bases with coverage above this value will be included in the target percentage computation [0]\n"
"        --ref-stats                     Create statistics on reference data.\n"
"        --ref-stats-chunk <int>         Reference retrival chunk size, in Mbs, for reference statistics [1].\n");
    sam_global_opt_help(fp, ".-..-@.-");
    fprintf(fp, "\n");
}

int main_stats(int argc, char **argv) {
    stats_info_t info; memset(&info, 0, sizeof info);
    info.nisize = 8000; info.isize_main_bulk = 0.99; info.ngc_depth_bin = 20000; info.cov_min = 1; info.cov_max = 1000; info.cov_step = 1; info.filter_readlen = -1;
    info.argc = argc; info.argv = argv;
    int c, has_index_file = 0;
    static const struct option lopts[] = {
        { "help", no_argument, NULL, 'h' }, { "remove-dups", no_argument, NULL, 'd' }, { "customized-index-file", no_argument, NULL, 'X' },
        { "sam", no_argument, NULL, 's' }, { "ref-seq", required_argument, NULL, 'r' }, { "coverage", required_argument, NULL, 'c' },
        { "read-length", required_argument, NULL, 'l' }, { "insert-size", required_argument, NULL, 'i' }, { "most-inserts", required_argument, NULL, 'm' },
        { "split-prefix", required_argument, NULL, 'P' }, { "trim-quality", required_argument, NULL, 'q' }, { "target-regions", required_argument, NULL, 't' },
        { "required-flag", required_argument, NULL, 'f' }, { "filtering-flag", required_argument, NULL, 'F' }, { "id", required_argument, NULL, 'I' },
        { "GC-depth", required_argument, NULL, 1 }, { "gc-depth", required_argument, NULL, 1 }, { "split", required_argument, NULL, 'S' }, { "sparse", no_argument, NULL, 'x' },
        { "remove-overlaps", no_argument, NULL, 'p' }, { "cov-threshold", required_argument, NULL, 'g' }, { "ref-stats", no_argument, NULL, 2 }, { "ref-stats-chunk", required_argument, NULL, 3 },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "reference", required_argument, NULL, 1005 }, { "threads", required_argument, NULL, '@' }, { "verbosity", required_argument, NULL, 1008 },
        { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "c:dsxpr:f:F:l:i:m:q:t:I:S:P:g:hX@:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'f': info.flag_require = bam_str2flag(optarg); if (info.flag_require < 0) { fprintf(stderr, "Unknown flag %s\n", optarg); return 1; } break;
        case 'F': info.flag_filter = bam_str2flag(optarg); if (info.flag_filter < 0) { fprintf(stderr, "Unknown flag %s\n", optarg); return 1; } break;
        case 'd': info.flag_filter |= BAM_FDUP; break;
        case 's': break;
        case 'r': info.ref_fn = optarg; break;
        case 1: info.ngc_depth_bin = (int)atof(optarg); break;
        case 'c': if (sscanf(optarg, "%d,%d,%d", &info.cov_min, &info.cov_max, &info.cov_step) != 3) { fprintf(stderr, "Unable to parse -c %s\n", optarg); return 1; } break;
        case 'l': info.filter_readlen = atoi(optarg); break;
        case 'i': info.nisize = atoi(optarg); break;
        case 'm': info.isize_main_bulk = atof(optarg); break;
        case 'q': info.trim_qual = atoi(optarg); break;
        case 't': info.targets_fn = optarg; break;
        case 'I': info.rg_id = optarg; break;
        case 'S': info.split_tag = optarg; break;
        case 'P': info.split_prefix = optarg; break;
        case 'x': info.sparse = 1; break;
        case 'p': info.remove_overlaps = 1; break;
        case 'g': info.cov_threshold = atoi(optarg); break;
        case 2: case 3: break;
        case 'X': has_index_file = 1; break;
        case 'h': stats_usage(stdout); return 0;
        case '@': case 1002: case 1005: break;
        case 1008: hts_verbose = atoi(optarg); break;
        default:
            if (optopt) fprintf(stderr, "stats: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "stats: unrecognized option '%s'\n", argv[optind-1]);
            stats_usage(stderr); return 1;
        }
    }
    const char *fn = optind < argc ? argv[optind] : "-";
    const char *fnidx = NULL; int reg_start = optind + 1;
    if (has_index_file) { if (optind + 1 < argc) { fnidx = argv[optind + 1]; reg_start = optind + 2; } }
    samfile_t *fp = sam_open_read_nohdr(fn);
    if (!fp) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn, strerror(errno)); print_error_errno("stats", "failed to open \"%s\"", fn); return 1; }
    if (sam_read_header(fp) < 0) { print_error("stats", "failed to read header for \"%s\"", fn); sam_close(fp); return 1; }
    sam_hdr_t *h = fp->hdr;
    if (info.ref_fn) {
        info.fai = fai_load3(info.ref_fn, NULL, NULL, 1, FAI_FASTA);
        if (!info.fai) { print_error("stats", "Could not load faidx: %s", info.ref_fn); sam_close(fp); return 1; }
    }
    stats_t *s = stats_init(&info, h);
    if (info.targets_fn) {
        s->targets = bed_read(info.targets_fn);
        if (!s->targets) { print_error_errno("stats", "Could not read file \"%s\"", info.targets_fn); stats_destroy(s); sam_close(fp); return 1; }
    }
    if (info.rg_id) {
        s->rg_hash = strmap_new();
        /* match RG ID or SM */
        int found = 0;
        for (int i = 0; i < h->n_lines; i++) if (sam_hdr_line_type_is(h->lines[i], "RG")) {
            char *id = hdr_line_tag(h->lines[i], "ID"), *sm = hdr_line_tag(h->lines[i], "SM");
            if ((id && strcmp(id, info.rg_id) == 0) || (sm && strcmp(sm, info.rg_id) == 0)) { if (id) { strmap_set(s->rg_hash, id, 1); found = 1; } }
            free(id); free(sm);
        }
        (void)found;
    }
    bam1_t *b = bam_init1();
    int ret = 0, r;
    if (reg_start < argc) {
        hts_idx_t *idx = NULL;
        if (fp->fmt == FMT_BAM && bgzf_is_bgzf(fp->bg)) idx = sam_index_load2(fn, fnidx);
        if (!idx) {
            if (!fnidx) log_error("idx_find_and_load", "Could not retrieve index file for '%s'", fn);
            fprintf(stderr, "Random alignment retrieval only works for indexed files\n"); ret = 1;
        } else {
            for (int i = reg_start; i < argc && !ret; i++) {
                hts_itr_t *itr = sam_itr_querys(idx, h, argv[i]);
                if (!itr) { fprintf(stderr, "Could not parse region \"%s\"\n", argv[i]); ret = 1; break; }
                while ((r = sam_itr_next(fp, itr, b)) >= 0) collect_stats(b, s);
                hts_itr_destroy(itr);
                if (r < -1) { print_error("stats", "error reading from \"%s\"", fn); ret = 1; }
            }
            hts_idx_destroy(idx);
        }
    } else {
        while ((r = sam_read1(fp, h, b)) >= 0) collect_stats(b, s);
        if (r < -1) { print_error("stats", "error reading from \"%s\"", fn); ret = 1; }
    }
    if (!ret) {
        round_buffer_flush(s, -1);
        if (s->targets) {
            /* bases inside target */
            s->nbases_target = bed_total_len(s->targets);
        }
        output_stats(s, stdout);
    }
    bam_destroy1(b);
    if (s->targets) bed_destroy(s->targets);
    stats_destroy(s);
    if (info.fai) fai_destroy(info.fai);
    sam_close(fp);
    return ret;
}
