    for (int i = 0; i < seq_len; i++) { int base = bam_seqi(seq, i); if (base == 2 || base == 4) gc_count++; }

    if (!(flag & BAM_FUNMAP)) {
        count_indels(s, b);
        if (s->targets) {
            const char *tname = sam_hdr_tid2name(s->hdr, b->core.tid);
            int64_t x = b->core.pos;
            for (uint32_t k = 0; k < b->core.n_cigar; k++) {
                int op = bam_cigar_op(cig[k]), n = bam_cigar_oplen(cig[k]);
                if (op == BAM_CMATCH || op == BAM_CEQUAL || op == BAM_CDIFF) { for (int i = 0; i < n; i++) if (bed_overlap(s->targets, tname, x + i, x + i + 1)) s->nbases_mapped_cigar++; x += n; }
                else if (op == BAM_CINS) { if (bed_overlap(s->targets, tname, x, x + 1)) s->nbases_mapped_cigar += n; }
                else if (op == BAM_CDEL || op == BAM_CREF_SKIP) x += n;
            }
        } else {
            for (uint32_t k = 0; k < b->core.n_cigar; k++) { int op = bam_cigar_op(cig[k]); if (op == BAM_CMATCH || op == BAM_CINS || op == BAM_CEQUAL || op == BAM_CDIFF) s->nbases_mapped_cigar += bam_cigar_oplen(cig[k]); }
        }
        uint8_t *nm = bam_aux_get(b, "NM");
        if (nm && bam_aux_is_int(nm)) s->nmismatches += bam_aux2i(nm);

        if (s->tid == b->core.tid && b->core.pos < s->pos) s->is_sorted = 0;
        s->pos = b->core.pos;
        if (s->is_sorted) {
            if (s->tid == -1 || s->tid != b->core.tid) round_buffer_flush(s, -1);
            if (info->fai) {
                int inc_ref = 0, inc_gcd = 0;
                if (s->rseq_pos == -1 || s->tid != b->core.tid) { inc_ref = 1; inc_gcd = 1; }
                else if (s->rseq_pos + s->nrseq_buf < b->core.pos + read_len) { inc_ref = 1; inc_gcd = 1; }
                else if (s->gcd_pos + (int64_t)s->gcd_bin_size < b->core.pos + read_len) {
                    inc_gcd = 1;
                    if (s->rseq_pos + s->nrseq_buf < b->core.pos + (int64_t)s->gcd_bin_size) inc_ref = 1;
                }
                if (inc_gcd) {
                    s->igcd++;
                    if (s->igcd >= s->ngcd) { uint32_t o = s->ngcd; s->ngcd = s->ngcd ? s->ngcd * 2 : 1024; s->gcd = realloc(s->gcd, s->ngcd * sizeof(gc_depth_t)); memset(s->gcd + o, 0, (s->ngcd - o) * sizeof(gc_depth_t)); }
                    if (inc_ref) read_ref_seq(s, b->core.tid, b->core.pos);
                    s->gcd_pos = b->core.pos;
                    s->gcd[s->igcd].gc = fai_gc_content(s, s->gcd_pos, s->gcd_bin_size);
                }
                count_mismatches_per_cycle(s, b);
            } else if (s->gcd_pos == -1 || s->tid != b->core.tid || b->core.pos - s->gcd_pos > (int64_t)s->gcd_bin_size) {
                if (s->gcd_pos != -1 && s->gcd[s->igcd].depth) s->gcd[s->igcd].gc = (float)(int)((double)s->gcd[s->igcd].gc / s->gcd[s->igcd].depth * 100.0 + 0.5);
                s->tid = b->core.tid;
                s->gcd_pos = b->core.pos;
                s->igcd++;
                if (s->igcd >= s->ngcd) { uint32_t o = s->ngcd; s->ngcd = s->ngcd ? s->ngcd * 2 : 1024; s->gcd = realloc(s->gcd, s->ngcd * sizeof(gc_depth_t)); memset(s->gcd + o, 0, (s->ngcd - o) * sizeof(gc_depth_t)); }
            }
            s->gcd[s->igcd].depth++;
            if (!info->fai) s->gcd[s->igcd].gc += (float)gc_count / seq_len;
            round_buffer_flush(s, b->core.pos);
            int64_t rpos = b->core.pos;
            for (uint32_t k = 0; k < b->core.n_cigar; k++) {
                int op = bam_cigar_op(cig[k]), n = bam_cigar_oplen(cig[k]);
                if (op == BAM_CMATCH || op == BAM_CEQUAL || op == BAM_CDIFF) { round_buffer_insert_read(&s->cov_rbuf, rpos, rpos + n - 1); rpos += n; }
                else if (op == BAM_CDEL || op == BAM_CREF_SKIP) rpos += n;
            }
        }
        s->tid = b->core.tid;
    }
    if (flag & BAM_FSUPPLEMENTARY) { s->nreads_supplementary++; return; }

    if (flag & BAM_FQCFAIL) s->nreads_qc_failed++;
    if (flag & BAM_FPAIRED) s->nreads_paired_tech++;
    s->nreads++;
    if (s->max_len < read_len) s->max_len = read_len;

    int frag = 1;
    if (flag & BAM_FPAIRED) {
        if ((flag & BAM_FREAD1) && !(flag & BAM_FREAD2)) frag = 1;
        else if ((flag & BAM_FREAD2) && !(flag & BAM_FREAD1)) frag = 2;
        else frag = 0;
    }
    s->read_lengths[read_len]++;
    s->total_len += seq_len;
    if (flag & BAM_FDUP) { s->nreads_dup++; s->total_len_dup += seq_len; }
    int reverse = (flag & BAM_FREVERSE) ? 1 : 0;
    if (frag) {
        uint64_t *quals; acgtno_count_t *acgtno; uint64_t *gc_arr;
        if (frag == 1) { s->nreads_1st++; s->total_len_1st += seq_len; if (s->max_len_1st < read_len) s->max_len_1st = read_len; s->read_lengths_1st[read_len]++; quals = s->quals_1st; acgtno = s->acgtno_cycles_1st; gc_arr = s->gc_1st; }
        else { s->nreads_2nd++; s->total_len_2nd += seq_len; if (s->max_len_2nd < read_len) s->max_len_2nd = read_len; s->read_lengths_2nd[read_len]++; quals = s->quals_2nd; acgtno = s->acgtno_cycles_2nd; gc_arr = s->gc_2nd; }
        for (int i = 0; i < seq_len; i++) {
            int base = bam_seqi(seq, i);
            int cycle = reverse ? seq_len - i - 1 : i;
            acgtno_count_t *fwd = &acgtno[cycle];
            switch (base) {
            case 1: fwd->a++; break; case 2: fwd->c++; break; case 4: fwd->g++; break; case 8: fwd->t++; break;
            case 15: fwd->n++; break; default: fwd->other++; break;
            }
            acgtno_count_t *ro = &s->acgtno_revcomp[cycle];
            int rbase = reverse ? (base == 1 ? 8 : base == 2 ? 4 : base == 4 ? 2 : base == 8 ? 1 : base) : base;
            switch (rbase) {
            case 1: ro->a++; break; case 2: ro->c++; break; case 4: ro->g++; break; case 8: ro->t++; break;
            case 15: ro->n++; break; default: ro->other++; break;
            }
            int q = bq[i];
            if (q + 1 > s->max_qual) s->max_qual = q + 1 < s->nquals ? q + 1 : s->nquals - 1;
            quals[(size_t)cycle * s->nquals + q]++;
            s->sum_qual += q;
        }
        int gc_idx_min = gc_count * (s->ngc - 1) / seq_len;
        int gc_idx_max = (gc_count + 1) * (s->ngc - 1) / seq_len;
        if (gc_idx_max >= s->ngc) gc_idx_max = s->ngc - 1;
        for (int i = gc_idx_min; i < gc_idx_max; i++) gc_arr[i]++;
    }
    if (info->trim_qual > 0) s->nbases_trimmed += bwa_trim_read(info->trim_qual, bq, seq_len, reverse);

    if (flag & BAM_FUNMAP) { s->nreads_unmapped++; return; }
    if (!b->core.qual) s->nreads_mq0++;
    if (!(flag & BAM_FQCFAIL) && !(flag & BAM_FDUP)) s->mapq[b->core.qual]++;
    if (!(flag & BAM_FPAIRED) || (flag & BAM_FMUNMAP)) s->nreads_single_mapped++;
    else {
        s->nreads_paired_and_mapped++;
        if (b->core.tid != b->core.mtid) s->nreads_anomalous++;
        else {
            int64_t isize = b->core.isize; if (isize < 0) isize = -isize;
            if (isize > s->nisize) isize = s->nisize;
            if (isize > 0) {
                int64_t pos_fst = b->core.mpos - b->core.pos;
                int is_fst = (flag & BAM_FREAD1) ? 1 : -1;
                int is_fwd = (flag & BAM_FREVERSE) ? -1 : 1;
                int is_mfwd = (flag & BAM_FMREVERSE) ? -1 : 1;
                if (is_fwd * is_mfwd > 0) s->isize_other[isize]++;
                else if (is_fst * pos_fst > 0) { if (is_fst * is_fwd > 0) s->isize_inward[isize]++; else s->isize_outward[isize]++; }
                else if (is_fst * pos_fst < 0) { if (is_fst * is_fwd > 0) s->isize_outward[isize]++; else s->isize_inward[isize]++; }
            }
        }
    }
    if (flag & BAM_FPROPER_PAIR) s->nreads_properly_paired++;
    s->nreads_mapped++;
    s->nbases_mapped += seq_len;
}

