static void qc_usage(FILE *fp) {
    fprintf(fp,
"Usage: samtools quickcheck [options] <input> [...]\n"
"Options:\n"
"  -v              verbose output (repeat for more verbosity)\n"
"  -q              suppress warning messages\n"
"  -u              unmapped input (do not require targets in header)\n"
"\n"
"Notes:\n"
"\n"
"1. By default quickcheck will emit a warning message if and only if a file\n"
"   fails the checks, in which case the exit status is non-zero.  Under normal\n"
"   behaviour with valid data it will be silent and has a zero exit status.\n"
"   The warning messages are purely for manual inspection and should not be \n"
"   parsed by scripts.\n"
"\n"
"2. In order to use this command programmatically, you should check its exit\n"
"   status.  One way to use quickcheck might be as a check that all BAM files in\n"
"   a directory are okay:\n"
"\n"
"\tsamtools quickcheck *.bam && echo 'all ok' \\\n"
"\t   || echo 'fail!'\n"
"\n"
"   The first level of verbosity lists only files that fail to stdout.\n"
"   To obtain a parsable list of files that have failed, use this option:\n"
"\n"
"\tsamtools quickcheck -qv *.bam > bad_bams.fofn \\\n"
"\t   && echo 'all ok' \\\n"
"\t   || echo 'some files failed check, see bad_bams.fofn'\n");
}

int main_quickcheck(int argc, char **argv) {
    int verbose = 0, quiet = 0, unmapped = 0, c;
    opterr = 0;
    while ((c = getopt(argc, argv, "vqu")) >= 0) {
        switch (c) {
        case 'v': verbose++; break;
        case 'q': quiet = 1; break;
        case 'u': unmapped = 1; break;
        default:
            if (optopt) fprintf(stderr, "quickcheck: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "quickcheck: unrecognized option '%s'\n", argv[optind-1]);
            qc_usage(stderr); return 1;
        }
    }
    if (optind == argc) { qc_usage(stderr); return 1; }
    if (verbose >= 2) fprintf(stderr, "verbosity set to %d\n", verbose);
    int ret = 0;
    int saved_verbose = hts_verbose;
    hts_verbose = 0;
    for (int i = optind; i < argc; i++) {
        const char *fn = argv[i];
        int file_state = 0;
        if (verbose >= 3) fprintf(stderr, "checking %s\n", fn);
        samfile_t *fp = sam_open_read_nohdr(fn);
        if (!fp) {
            if (!quiet) fprintf(stderr, "%s could not be opened for reading.\n", fn);
            file_state = 2;
        } else {
            if (verbose >= 3) fprintf(stderr, "opened %s\n", fn);
            int is_seq = (fp->fmt == FMT_SAM || fp->fmt == FMT_BAM || fp->fmt == FMT_CRAM || fp->fmt == FMT_FASTA || fp->fmt == FMT_FASTQ);
            if (!is_seq) {
                if (!quiet) fprintf(stderr, "%s was not identified as sequence data.\n", fn);
                file_state = 4;
            } else {
                if (verbose >= 3) fprintf(stderr, "%s is sequence data\n", fn);
                if (sam_read_header(fp) < 0) {
                    if (!quiet) fprintf(stderr, "%s caused an error whilst reading its header.\n", fn);
                    file_state = 4;
                } else {
                    int nt = fp->hdr->n_targets;
                    if (nt == 0 && !unmapped) {
                        if (!quiet) fprintf(stderr, "%s had no targets in header.\n", fn);
                        file_state = 8;
                    } else if (verbose >= 3) fprintf(stderr, "%s has %d targets in header.\n", fn, nt);
                    if (fp->fmt == FMT_BAM || (fp->fmt == FMT_SAM && bgzf_is_bgzf(fp->bg))) {
                        int eof = bgzf_check_EOF(fp->bg);
                        if (eof == 0) {
                            if (!quiet) fprintf(stderr, "%s was missing EOF block when one should be present.\n", fn);
                            file_state |= 16;
                        } else if (eof == 1 && verbose >= 3) fprintf(stderr, "%s has good EOF block.\n", fn);
                    }
                }
            }
            sam_close(fp);
        }
        if (file_state > 0 && verbose >= 1) printf("%s\n", fn);
        ret |= file_state;
    }
    hts_verbose = saved_verbose;
    return ret;
}
