static void cat_usage(FILE *fp) {
    fprintf(fp,
"Usage: samtools cat [options] <in1.bam>  [... <inN.bam>]\n"
"       samtools cat [options] <in1.cram> [... <inN.cram>]\n"
"\n"
"Concatenate BAM or CRAM files, first those in <bamlist.fofn>, then those\n"
"on the command line.\n"
"\n"
"Options: -b FILE  list of input BAM/CRAM file names, one per line\n"
"         -h FILE  copy the header from FILE [default is 1st input file]\n"
"         -o FILE  output BAM/CRAM\n"
"         --no-PG  do not add a PG line\n"
"\n"
"CRAM only options for filtering:\n"
"         -r REG   filter to region REG.\n"
"                  REG can also be #:cstart-cend for specific container numbers\n"
"         -p N/M   Specify part N of M (where N is 1 to M inclusive)\n"
"         -f       Fast mode: don't filter containers to exactly match region\n"
"         -q       Query the total number of indexed containers\n"
"\n"
"Standard options:\n");
    sam_global_opt_help(fp, "...-...-");
}

static int write_raw(int fd, const uint8_t *buf, size_t len) {
    while (len) { ssize_t n = write(fd, buf, len); if (n < 0) { if (errno == EINTR) continue; return -1; } buf += n; len -= n; }
    return 0;
}

static int bam_cat(int nfn, char **fn, sam_hdr_t *h, const char *outbam, char *arg_list, int no_pg) {
    bgzf_t *fp = bgzf_open_write(outbam, -1);
    if (!fp) { fprintf(stderr, "[%s] ERROR: fail to open output file '%s'.\n", "bam_cat", outbam); return -1; }
    if (h) {
        if (!no_pg) sam_hdr_add_pg(h, "samtools", samtools_version(), arg_list, NULL);
        if (bam_hdr_write(fp, h) < 0) { fprintf(stderr, "[%s] ERROR: couldn't write header\n", "bam_cat"); bgzf_close(fp); return -1; }
    }
    const int es = 28;
    uint8_t ebuf[28];
    uint8_t *buf = malloc(0x10000);
    for (int i = 0; i < nfn; i++) {
        bgzf_t *in = bgzf_open_read(fn[i]);
        if (!in) { fprintf(stderr, "[%s] ERROR: fail to open file '%s'.\n", "bam_cat", fn[i]); free(buf); bgzf_close(fp); return -1; }
        sam_hdr_t *old = NULL;
        if (bam_hdr_read(in, &old) < 0) { fprintf(stderr, "[%s] ERROR: couldn't read header for '%s'.\n", "bam_cat", fn[i]); bgzf_close(in); free(buf); bgzf_close(fp); return -1; }
        if (h == 0 && i == 0) {
            if (!no_pg) sam_hdr_add_pg(old, "samtools", samtools_version(), arg_list, NULL);
            if (bam_hdr_write(fp, old) < 0) { sam_hdr_destroy(old); bgzf_close(in); free(buf); bgzf_close(fp); return -1; }
        }
        if (in->ublock_off < in->ublock_len) {
            if (bgzf_write(fp, in->ubuf + in->ublock_off, in->ublock_len - in->ublock_off) < 0) goto write_fail;
            if (bgzf_flush(fp) != 0) goto write_fail;
            in->ublock_off = in->ublock_len;
        }
        /* raw copy from current raw position */
        int j = 0;
        off_t cur = in->rpos + in->rbuf_off;
        lseek(in->fd, cur, SEEK_SET);
        ssize_t len;
        while ((len = read(in->fd, buf, 0x10000)) > 0) {
            if (len < es) {
                int diff = es - (int)len;
                if (j == 0) { fprintf(stderr, "[%s] ERROR: truncated file?: '%s'.\n", "bam_cat", fn[i]); goto write_fail; }
                if (write_raw(fp->fd, ebuf, len) < 0) goto write_fail;
                memmove(ebuf, ebuf + len, diff);
                memcpy(ebuf + diff, buf, len);
            } else {
                if (write_raw(fp->fd, ebuf, j) < 0) goto write_fail;
                memcpy(ebuf, buf + len - es, es);
                if (write_raw(fp->fd, buf, len - es) < 0) goto write_fail;
                j = es;
            }
        }
        if (j > 0) {
            uint32_t isize; memcpy(&isize, ebuf + es - 4, 4);
            if (ebuf[0] != 0x1f || ebuf[1] != 0x8b || isize != 0) {
                fprintf(stderr, "[%s] WARNING: Unexpected block structure in file '%s'.", "bam_cat", fn[i]);
                fprintf(stderr, " Possible output corruption.\n");
                if (write_raw(fp->fd, ebuf, es) < 0) goto write_fail;
            }
        }
        fp->waddr = lseek(fp->fd, 0, SEEK_CUR);
        sam_hdr_destroy(old);
        bgzf_close(in);
        continue;
write_fail:
        fprintf(stderr, "[%s] Error writing to '%s'.\n", "bam_cat", outbam);
        sam_hdr_destroy(old); bgzf_close(in); free(buf); bgzf_close(fp);
        return -1;
    }
    free(buf);
    if (bgzf_close(fp) < 0) { fprintf(stderr, "[%s] Error on closing '%s'.\n", "bam_cat", outbam); return -1; }
    return 0;
}

int main_cat(int argc, char **argv) {
    sam_hdr_t *h = NULL;
    const char *outfn = NULL, *bamlist = NULL;
    int c, no_pg = 0, ret;
    static const struct option lopts[] = { { "no-PG", no_argument, NULL, 1 }, { "output-fmt-option", required_argument, NULL, 1004 }, { "verbosity", required_argument, NULL, 1008 }, { NULL, 0, NULL, 0 } };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "h:o:b:r:p:fq", lopts, NULL)) >= 0) {
        switch (c) {
        case 'h': {
            samfile_t *fph = sam_open_read_nohdr(optarg);
            if (!fph || sam_read_header(fph) < 0) { fprintf(stderr, "[%s] ERROR: fail to read the header from '%s'.\n", "main_cat", optarg); if (fph) sam_close(fph); return 1; }
            h = sam_hdr_dup(fph->hdr); sam_close(fph);
            break;
        }
        case 'o': outfn = optarg; break;
        case 'b': bamlist = optarg; break;
        case 'r': case 'p': case 'f': case 'q': break;
        case 1: no_pg = 1; break;
        case 1004: case 1008: break;
        default:
            if (optopt) fprintf(stderr, "cat: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "cat: unrecognized option '%s'\n", argv[optind-1]);
            cat_usage(stderr); return 1;
        }
    }
    int nfn = 0; char **fn = NULL;
    if (bamlist) {
        textfile_t *t = text_open(bamlist);
        if (!t) { fprintf(stderr, "[%s] ERROR: fail to open file list '%s'.\n", "main_cat", bamlist); return 1; }
        while (text_getline(t) >= 0) { if (!t->line[0]) continue; fn = realloc(fn, (nfn + 1) * sizeof(char*)); fn[nfn++] = strdup(t->line); }
        text_close(t);
    }
    for (int i = optind; i < argc; i++) { fn = realloc(fn, (nfn + 1) * sizeof(char*)); fn[nfn++] = strdup(argv[i]); }
    if (nfn == 0) { cat_usage(stderr); if (h) sam_hdr_destroy(h); return 1; }
    /* check format of first input */
    samfile_t *fp0 = sam_open_read_nohdr(fn[0]);
    if (!fp0) { fprintf(stderr, "[%s] ERROR: fail to open file '%s'.\n", "main_cat", fn[0]); return 1; }
    int fmt = fp0->fmt; sam_close(fp0);
    if (fmt == FMT_CRAM) { fprintf(stderr, "[%s] ERROR: CRAM not supported by this build\n", "main_cat"); return 1; }
    if (fmt != FMT_BAM) { fprintf(stderr, "[%s] ERROR: input is not BAM or CRAM\n", "main_cat"); return 1; }
    char *arg_list = no_pg ? NULL : stringify_argv(argc + 1, argv - 1);
    ret = bam_cat(nfn, fn, h, outfn ? outfn : "-", arg_list, no_pg);
    free(arg_list);
    for (int i = 0; i < nfn; i++) free(fn[i]); free(fn);
    if (h) sam_hdr_destroy(h);
    return ret < 0 ? 1 : 0;
}
