    if (bam_hdr_read(in, &old) < 0) { fprintf(stderr, "[%s] failed to read the header of the input file.\n", "bam_reheader"); return -1; }
    bgzf_t *fp = bgzf_fdopen_write(fd, -1);
    if (!no_pg) sam_hdr_add_pg(h, "samtools", samtools_version(), arg_list, NULL);
    if (bam_hdr_write(fp, h) < 0) { sam_hdr_destroy(old); bgzf_close(fp); return -1; }
    if (in->ublock_off < in->ublock_len) {
        if (bgzf_write(fp, in->ubuf + in->ublock_off, in->ublock_len - in->ublock_off) < 0) { sam_hdr_destroy(old); bgzf_close(fp); return -1; }
        if (bgzf_flush(fp) < 0) { sam_hdr_destroy(old); bgzf_close(fp); return -1; }
        in->ublock_off = in->ublock_len;
    }
    off_t cur = in->rpos + in->rbuf_off;
    lseek(in->fd, cur, SEEK_SET);
    uint8_t *buf = malloc(0x10000); ssize_t len;
    while ((len = read(in->fd, buf, 0x10000)) > 0) { if (write_raw(fp->fd, buf, len) < 0) { free(buf); sam_hdr_destroy(old); return -1; } }
    free(buf);
    /* the input's EOF block was copied; do not add another */
    fp->is_compressed = 0; fp->wbuf_len = 0;
    bgzf_close(fp);
    sam_hdr_destroy(old);
    return 0;
}

int main_reheader(int argc, char **argv) {
    int inplace = 0, no_pg = 0, c;
    const char *cmd = NULL;
    static const struct option lopts[] = { { "no-PG", no_argument, NULL, 'P' }, { "in-place", no_argument, NULL, 'i' }, { "command", required_argument, NULL, 'c' }, { NULL, 0, NULL, 0 } };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "hPic:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'P': no_pg = 1; break;
        case 'i': inplace = 1; break;
        case 'c': cmd = optarg; break;
        case 'h': reheader_usage(stdout); return 0;
        default: reheader_usage(stderr); return 1;
        }
    }
    if (argc - optind != (cmd ? 1 : 2)) { reheader_usage(stderr); return 1; }
    sam_hdr_t *h = NULL;
    const char *fn_bam;
    if (!cmd) {
        const char *fn_hdr = argv[optind]; fn_bam = argv[optind + 1];
        samfile_t *fph = sam_open_read_nohdr(fn_hdr);
        if (!fph) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn_hdr, strerror(errno)); print_error_errno("reheader", "fail to read the header from '%s'", fn_hdr); return 1; }
        if (sam_read_header(fph) < 0) { print_error("reheader", "fail to read the header from '%s'", fn_hdr); sam_close(fph); return 1; }
        h = sam_hdr_dup(fph->hdr); sam_close(fph);
    } else fn_bam = argv[optind];
    bgzf_t *in = bgzf_open_read(fn_bam);
    if (!in) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn_bam, strerror(errno)); print_error_errno("reheader", "fail to open file '%s'", fn_bam); if (h) sam_hdr_destroy(h); return 1; }
    { uint8_t p[4]; int n = bgzf_peek(in, p, 4); if (n < 4 || memcmp(p, "BAM\1", 4) != 0) { print_error("reheader", "input file '%s' must be BAM or CRAM", fn_bam); bgzf_close(in); if (h) sam_hdr_destroy(h); return 1; } }
    if (cmd) {
        sam_hdr_t *old = NULL;
        bgzf_t *in2 = bgzf_open_read(fn_bam);
        if (bam_hdr_read(in2, &old) < 0) { bgzf_close(in2); bgzf_close(in); return 1; }
        bgzf_close(in2);
        char tmpname[] = "/tmp/reheaderXXXXXX";
        int tfd = mkstemp(tmpname);
        if (tfd < 0) { print_error_errno("reheader", "could not create temporary file"); sam_hdr_destroy(old); bgzf_close(in); return 1; }
        const char *t = sam_hdr_str(old); size_t tl = sam_hdr_length(old);
        write_raw(tfd, (uint8_t*)t, tl); close(tfd);
        char *full = malloc(strlen(cmd) + strlen(tmpname) + 16);
        sprintf(full, "( %s ) < %s", cmd, tmpname);
        FILE *pp = popen(full, "r");
        kstring_t ks = KS_INITIALIZE; char buf[4096]; size_t n;
        if (pp) { while ((n = fread(buf, 1, sizeof buf, pp)) > 0) kputsn(buf, n, &ks); }
        int rc = pp ? pclose(pp) : -1;
        unlink(tmpname);
        h = sam_hdr_init();
        if (ks.l == 0 || sam_hdr_parse_text(h, ks.s, ks.l) < 0) {
            fprintf(stderr, "[external_reheader] failed to read the header from the temp file.\n");
            if (rc != 0) { print_error("reheader", "Non-zero exit code returned by command '%s'\n", full); }
            fprintf(stderr, "[main_reheader] failed to read the header from '%s'.\n", cmd);
            free(full); free(ks.s); sam_hdr_destroy(h); sam_hdr_destroy(old); bgzf_close(in); return 1;
        }
        free(full); free(ks.s); sam_hdr_destroy(old);
    }
    (void)inplace;
    char *arg_list = no_pg ? NULL : stringify_argv(argc + 1, argv - 1);
    int ret = bam_reheader(in, h, dup(1), arg_list, no_pg);
    free(arg_list);
    bgzf_close(in);
    sam_hdr_destroy(h);
    return ret < 0 ? 1 : 0;
}
