        { "threads", required_argument, NULL, '@' }, { "write-index", no_argument, NULL, 1007 }, { "verbosity", required_argument, NULL, 1008 }, { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "r:R:m:o:O:h@:uw", lopts, NULL)) >= 0) {
        switch (c) {
        case 'r': {
            if (rg_line.l) kputc('\t', &rg_line);
            /* convert literal \t */
            for (const char *p = optarg; *p; p++) { if (p[0] == '\\' && p[1] == 't') { kputc('\t', &rg_line); p++; } else kputc(*p, &rg_line); }
            break;
        }
        case 'R': rg_id = optarg; break;
        case 'm':
            if (strcmp(optarg, "overwrite_all") == 0) mode_overwrite = 1;
            else if (strcmp(optarg, "orphan_only") == 0) mode_overwrite = 0;
            else { arg_usage(stderr); return 1; }
            break;
        case 'o': outfn = optarg; break;
        case 'u': uncompressed = 1; break;
        case 'w': overwrite_hdr = 1; break;
        case 'h': arg_usage(stdout); return 0;
        case 1: no_pg = 1; break;
        case 'O': c = 1003; /* fallthrough */
        case 1001: case 1002: case 1003: case 1004: case 1005: case 1008: if (parse_sam_global_opt(c, optarg, NULL, &ga) < 0) { arg_usage(stderr); return 1; } break;
        case '@': ga.nthreads = atoi(optarg); break;
        case 1007: ga.write_index = 1; break;
        default: arg_usage(stderr); return 1;
        }
    }
    if (rg_line.l && rg_id) { fprintf(stderr, "The options -r and -R are mutually exclusive.\n"); free(rg_line.s); return 1; }
    if (argc - optind != 1) { arg_usage(stderr); free(rg_line.s); return 1; }
    const char *fn = argv[optind];
    char *line = NULL, *id = NULL;
    if (rg_line.l) {
        if (strncmp(rg_line.s, "@RG\t", 4) == 0) line = strdup(rg_line.s);
        else { line = malloc(rg_line.l + 5); sprintf(line, "@RG\t%s", rg_line.s); }
        id = hdr_line_tag(line, "ID");
        if (!id) { fprintf(stderr, "[parse_args] The supplied RG line lacks an ID tag.\n"); free(line); free(rg_line.s); return 1; }
    }
    free(rg_line.s);
    samfile_t *in = sam_open_read_nohdr(fn);
    if (!in) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn, strerror(errno)); print_error_errno("addreplacerg", "could not open \"%s\"", fn); free(line); free(id); return 1; }
    if (sam_read_header(in) < 0) { print_error("addreplacerg", "could not read header for \"%s\"", fn); sam_close(in); free(line); free(id); return 1; }
    sam_hdr_t *h = in->hdr;
    if (rg_id) {
        if (sam_hdr_find_line_id(h, "RG", "ID", rg_id) < 0) { fprintf(stderr, "RG ID supplied does not exist in header. Supply full @RG line with -r instead?\n"); sam_close(in); return 1; }
        id = strdup(rg_id);
    } else if (line) {
        if (sam_hdr_find_line_id(h, "RG", "ID", id) >= 0) {
            if (!overwrite_hdr) { fprintf(stderr, "[init] RG line with ID:%s already present in the header. Use -w to overwrite.\n", id); sam_close(in); free(line); free(id); return 1; }
            sam_hdr_remove_lines_type(h, "RG");
        }
        if (sam_hdr_add_line_str(h, line) < 0) { print_error("addreplacerg", "could not add RG line"); sam_close(in); free(line); free(id); return 1; }
    }
    if (!no_pg) { char *al = stringify_argv(argc + 1, argv - 1); sam_hdr_add_pg(h, "samtools", samtools_version(), al, NULL); free(al); }
    if (uncompressed && ga.out_level < 0) ga.out_level = 0;
    const char *fo = outfn ? outfn : "-";
    samfile_t *out = sam_open_output(fo, "w", &ga, 0);
    if (!out) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fo, strerror(errno)); print_error_errno("addreplacerg", "could not create \"%s\"", fo); sam_close(in); free(line); free(id); return 1; }
    int ret = 0;
    if (sam_write_hdr(out, h) < 0) { print_error("addreplacerg", "could not write header"); ret = 1; }
    bam1_t *b = bam_init1(); int r;
    while (!ret && (r = sam_read1(in, h, b)) >= 0) {
        if (id) {
            uint8_t *rg = bam_aux_get(b, "RG");
            if (mode_overwrite) { if (rg) bam_aux_del(b, rg); bam_aux_update_str(b, "RG", (int)strlen(id) + 1, id); }
            else if (!rg) bam_aux_update_str(b, "RG", (int)strlen(id) + 1, id);
        }
        if (sam_write1(out, h, b) < 0) { print_error_errno("addreplacerg", "could not write record"); ret = 1; }
    }
    if (!ret && r < -1) { print_error("addreplacerg", "error reading from \"%s\"", fn); ret = 1; }
    bam_destroy1(b);
    if (sam_close(out) < 0 && !ret) { print_error_errno("addreplacerg", "error closing output"); ret = 1; }
    sam_close(in); free(line); free(id); sam_global_args_free(&ga);
    return ret;
}
