#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include "khash_u32.h"

static inline uint32_t khstr_hash(const char *s) {
    uint32_t h = 2166136261u;
    for (; *s; s++) { h ^= (unsigned char)*s; h *= 16777619u; }
    return h;
}

typedef struct {
    uint32_t n_buckets, size, n_occupied, upper_bound;
    uint32_t *flags; char **keys; void **vals; int64_t *ivals;
} khstr_t;

static inline khstr_t *khstr_init(void) { return calloc(1, sizeof(khstr_t)); }
static inline void khstr_destroy(khstr_t *h, int free_keys) {
    if (!h) return;
    if (free_keys && h->keys) for (uint32_t i = 0; i < h->n_buckets; i++) if (!kh32_iseither(h->flags, i)) free(h->keys[i]);
    free(h->keys); free(h->flags); free(h->vals); free(h->ivals); free(h);
}
#define khstr_exist(h, x) (!kh32_iseither((h)->flags, (x)))
#define khstr_key(h, x) ((h)->keys[x])
#define khstr_val(h, x) ((h)->vals[x])
#define khstr_ival(h, x) ((h)->ivals[x])
#define khstr_end(h) ((h)->n_buckets)
#define khstr_size(h) ((h)->size)

static inline uint32_t khstr_get(const khstr_t *h, const char *key) {
    if (h->n_buckets) {
        uint32_t k, i, last, mask, step = 0;
        mask = h->n_buckets - 1;
        k = khstr_hash(key); i = k & mask;
        last = i;
        while (!kh32_isempty(h->flags, i) && (kh32_isdel(h->flags, i) || strcmp(h->keys[i], key) != 0)) {
            i = (i + (++step)) & mask;
            if (i == last) return h->n_buckets;
        }
        return kh32_iseither(h->flags, i) ? h->n_buckets : i;
    }
    return 0;
}

static inline void khstr_resize(khstr_t *h, uint32_t new_n_buckets) {
    uint32_t *new_flags = NULL; uint32_t j = 1;
    --new_n_buckets; new_n_buckets |= new_n_buckets>>1; new_n_buckets |= new_n_buckets>>2; new_n_buckets |= new_n_buckets>>4; new_n_buckets |= new_n_buckets>>8; new_n_buckets |= new_n_buckets>>16; ++new_n_buckets;
    if (new_n_buckets < 4) new_n_buckets = 4;
    if (h->size >= (uint32_t)(new_n_buckets * 0.77 + 0.5)) j = 0;
    else {
        new_flags = malloc(kh32_fsize(new_n_buckets) * sizeof(uint32_t));
        memset(new_flags, 0xaa, kh32_fsize(new_n_buckets) * sizeof(uint32_t));
        if (h->n_buckets < new_n_buckets) {
            h->keys = realloc(h->keys, new_n_buckets * sizeof(char*));
            h->vals = realloc(h->vals, new_n_buckets * sizeof(void*));
            h->ivals = realloc(h->ivals, new_n_buckets * sizeof(int64_t));
        }
    }
    if (j) {
        for (j = 0; j != h->n_buckets; ++j) {
            if (kh32_iseither(h->flags, j) == 0) {
                char *key = h->keys[j]; void *val = h->vals[j]; int64_t ival = h->ivals[j];
                uint32_t new_mask = new_n_buckets - 1;
                kh32_set_isdel_true(h->flags, j);
                while (1) {
                    uint32_t k, i, step = 0;
                    k = khstr_hash(key); i = k & new_mask;
                    while (!kh32_isempty(new_flags, i)) i = (i + (++step)) & new_mask;
                    kh32_set_isempty_false(new_flags, i);
                    if (i < h->n_buckets && kh32_iseither(h->flags, i) == 0) {
                        { char *t = h->keys[i]; h->keys[i] = key; key = t; }
                        { void *t = h->vals[i]; h->vals[i] = val; val = t; }
                        { int64_t t = h->ivals[i]; h->ivals[i] = ival; ival = t; }
                        kh32_set_isdel_true(h->flags, i);
                    } else { h->keys[i] = key; h->vals[i] = val; h->ivals[i] = ival; break; }
                }
            }
        }
        if (h->n_buckets > new_n_buckets) {
            h->keys = realloc(h->keys, new_n_buckets * sizeof(char*));
            h->vals = realloc(h->vals, new_n_buckets * sizeof(void*));
            h->ivals = realloc(h->ivals, new_n_buckets * sizeof(int64_t));
        }
        free(h->flags); h->flags = new_flags; h->n_buckets = new_n_buckets;
        h->n_occupied = h->size; h->upper_bound = (uint32_t)(h->n_buckets * 0.77 + 0.5);
    }
}

/* key is stored as given (caller owns / or strdup before) */
static inline uint32_t khstr_put(khstr_t *h, char *key, int *ret) {
    uint32_t x;
    if (h->n_occupied >= h->upper_bound) {
        if (h->n_buckets > (h->size<<1)) khstr_resize(h, h->n_buckets - 1);
        else khstr_resize(h, h->n_buckets + 1);
    }
    {
        uint32_t k, i, site, last, mask = h->n_buckets - 1, step = 0;
        x = site = h->n_buckets; k = khstr_hash(key); i = k & mask;
        if (kh32_isempty(h->flags, i)) x = i;
        else {
            last = i;
            while (!kh32_isempty(h->flags, i) && (kh32_isdel(h->flags, i) || strcmp(h->keys[i], key) != 0)) {
                if (kh32_isdel(h->flags, i)) site = i;
                i = (i + (++step)) & mask;
                if (i == last) { x = site; break; }
            }
            if (x == h->n_buckets) { if (kh32_isempty(h->flags, i) && site != h->n_buckets) x = site; else x = i; }
        }
    }
    if (kh32_isempty(h->flags, x)) { h->keys[x] = key; h->vals[x] = NULL; h->ivals[x] = 0; kh32_set_isboth_false(h->flags, x); ++h->size; ++h->n_occupied; *ret = 1; }
    else if (kh32_isdel(h->flags, x)) { h->keys[x] = key; h->vals[x] = NULL; h->ivals[x] = 0; kh32_set_isboth_false(h->flags, x); ++h->size; *ret = 2; }
    else *ret = 0;
    return x;
}
static inline void khstr_del(khstr_t *h, uint32_t x) { if (x != h->n_buckets && !kh32_iseither(h->flags, x)) { kh32_set_isdel_true(h->flags, x); --h->size; } }
#endif
