#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <errno.h>
#include <sys/stat.h>
#include "samtools.h"
#include "khstr.h"
#include "index.h"
#include "faidx.h"
#include "log.h"

static void samples_usage(FILE *fp) {
    fprintf(fp,
"Usage: samtools samples [options] <input> [...]\n"
"       samtools samples [options] -X f1.bam f2.bam f1.bam.bai f2.bai \n"
"       find dir1 dir2 -type f \\(-name \"*.bam\" -o -name \"*.cram\" \\) | samtools samples [options]\n"
"       find dir1 dir2 -type f \\(-name \"*.bam\" -o -name \"*.bai\" \\) | sort | paste - - | samtools samples -X [options]\n"
"\n"
"Options:\n"
"  -?              print help and exit\n"
"  -h              add the columns header before printing the results\n"
"  -i              test if the file is indexed.\n"
"  -T <tag>        provide the sample tag name from the @RG line [SM].\n"
"  -o <file>       output file [stdout].\n"
"  -f <file.fa>    load an indexed fasta file in the collection of references. Can be used multiple times.\n"
"  -F <file.txt>   read a file containing the paths to indexed fasta files. One path per line.\n"
"  -X              use a custom index file.\n"
"\n"
" Using -f or -F will add a column containing the path to the reference or \".\" if the reference was not found.\n"
"\n");
}

typedef struct { char *fn; faidx_t *fai; } refs_t;

static int process_file(FILE *out, const char *fn, const char *fnidx, int test_index, const char *tag, refs_t *refs, int nrefs, int use_refs) {
    samfile_t *fp = sam_open_read_nohdr(fn);
    if (!fp) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn, strerror(errno)); print_error_errno("samples", "Failed to open \"%s\" for reading", fn); return -1; }
    if (sam_read_header(fp) < 0) { print_error("samples", "Failed to read header for \"%s\"", fn); sam_close(fp); return -1; }
    sam_hdr_t *h = fp->hdr;
    khstr_t *set = khstr_init();
    for (int i = 0; i < h->n_lines; i++) {
        if (!sam_hdr_line_type_is(h->lines[i], "RG")) continue;
        char *v = hdr_line_tag(h->lines[i], tag);
        if (!v) continue;
        int r; uint32_t k = khstr_put(set, v, &r);
        if (!r) free(v); (void)k;
    }
    const char *idx_col = "";
    char *found_idx = NULL;
    if (test_index) {
        if (fnidx) { struct stat st; idx_col = stat(fnidx, &st) == 0 ? "Y" : "N"; }
        else { found_idx = sam_index_find_fn(fn); idx_col = found_idx ? "Y" : "N"; }
    }
    const char *ref_col = ".";
    if (use_refs) {
        for (int r = 0; r < nrefs && h->n_targets > 0; r++) {
            int ok = 1;
            for (int t = 0; t < h->n_targets; t++) {
                int64_t l = fai_seq_len(refs[r].fai, h->targets[t].name);
                if (l < 0 || l != h->targets[t].len) { ok = 0; break; }
            }
            if (ok) { ref_col = refs[r].fn; break; }
        }
    }
    if (khstr_size(set) == 0) {
        fprintf(out, ".\t%s", fn);
        if (test_index) fprintf(out, "\t%s", idx_col);
        if (use_refs) fprintf(out, "\t%s", ref_col);
        fputc('\n', out);
    } else {
        for (uint32_t k = 0; k < khstr_end(set); k++) {
            if (!khstr_exist(set, k)) continue;
            fprintf(out, "%s\t%s", khstr_key(set, k), fn);
            if (test_index) fprintf(out, "\t%s", idx_col);
            if (use_refs) fprintf(out, "\t%s", ref_col);
            fputc('\n', out);
        }
    }
    khstr_destroy(set, 1);
    free(found_idx);
    sam_close(fp);
    return 0;
}

int main_samples(int argc, char **argv) {
    int c, header = 0, test_index = 0, custom_idx = 0;
    const char *tag = "SM", *outfn = NULL;
    refs_t *refs = NULL; int nrefs = 0; int use_refs = 0;
    opterr = 0;
    while ((c = getopt(argc, argv, "?hiT:o:f:F:X")) >= 0) {
        switch (c) {
        case '?': samples_usage(stdout); return 0;
        case 'h': header = 1; break;
        case 'i': test_index = 1; break;
        case 'T': tag = optarg; break;
        case 'o': outfn = optarg; break;
        case 'f': refs = realloc(refs, (nrefs + 1) * sizeof(refs_t)); refs[nrefs].fn = strdup(optarg); refs[nrefs].fai = fai_load3(optarg, NULL, NULL, 1, FAI_FASTA); if (!refs[nrefs].fai) { print_error("samples", "Cannot load reference \"%s\"", optarg); return 1; } nrefs++; use_refs = 1; break;
        case 'F': {
            textfile_t *t = text_open(optarg);
            if (!t) { print_error_errno("samples", "Cannot open \"%s\"", optarg); return 1; }
            while (text_getline(t) >= 0) { if (!t->line[0]) continue; refs = realloc(refs, (nrefs + 1) * sizeof(refs_t)); refs[nrefs].fn = strdup(t->line); refs[nrefs].fai = fai_load3(t->line, NULL, NULL, 1, FAI_FASTA); if (!refs[nrefs].fai) { print_error("samples", "Cannot load reference \"%s\"", t->line); return 1; } nrefs++; }
            text_close(t); use_refs = 1;
            break;
        }
        case 'X': custom_idx = 1; break;
        default: samples_usage(stderr); return 1;
        }
    }
    FILE *out = stdout;
    if (outfn) { out = fopen(outfn, "w"); if (!out) { print_error_errno("samples", "Cannot open \"%s\" for writing", outfn); return 1; } }
    if (header) { fprintf(out, "#%s\tPATH", tag); if (test_index) fprintf(out, "\tINDEX"); if (use_refs) fprintf(out, "\tREF"); fputc('\n', out); }
    int ret = 0;
    if (optind == argc) {
        /* read file names from stdin */
        char *line = NULL; size_t cap = 0; ssize_t n;
        while ((n = getline(&line, &cap, stdin)) > 0) {
            while (n > 0 && (line[n-1] == '\n' || line[n-1] == '\r')) line[--n] = 0;
            if (!line[0]) continue;
            char *fnidx = NULL;
            if (custom_idx) { char *tab = strchr(line, '\t'); if (tab) { *tab = 0; fnidx = tab + 1; } }
            if (process_file(out, line, fnidx, test_index, tag, refs, nrefs, use_refs) < 0) { ret = 1; break; }
        }
        free(line);
    } else {
        int n = argc - optind;
        if (custom_idx) {
            if (n % 2) { print_error("samples", "Odd number of filenames detected! Each BAM file should have an index file"); ret = 1; }
            else { int half = n / 2; for (int i = 0; i < half && !ret; i++) if (process_file(out, argv[optind + i], argv[optind + half + i], test_index, tag, refs, nrefs, use_refs) < 0) ret = 1; }
        } else {
            for (int i = optind; i < argc && !ret; i++) if (process_file(out, argv[i], NULL, test_index, tag, refs, nrefs, use_refs) < 0) ret = 1;
        }
    }
    for (int i = 0; i < nrefs; i++) { free(refs[i].fn); fai_destroy(refs[i].fai); }
    free(refs);
    if (outfn) fclose(out);
    return ret;
}
