static void split_usage(FILE *fp) {
    fprintf(fp,
"Usage: samtools split [-u <unaccounted.bam>] [-h <unaccounted_header.sam>]\n"
"                      [-f <format_string>] [-v] <merged.bam>\n"
"Options:\n"
"  -f STRING           output filename format string [\"%%*_%%#.%%.\"]\n"
"  -u FILE1            put left-over reads in FILE1\n"
"  -h FILE2            ... and override the header with FILE2 (-u file only)\n"
"  -d TAG              split by TAG value. TAG value must be a string.\n"
"  -p NUMBER           zero-pad numbers in filenames to NUMBER digits\n"
"  -M,--max-split NUM  limit number of output files from -d to NUM [100]\n"
"  -v                  verbose output\n"
"  --no-PG             do not add a PG line\n");
    sam_global_opt_help(fp, ".--.-@--");
    fprintf(fp,
"\n"
"Format string expansions:\n"
"  %%%%     %%\n"
"  %%*     basename\n"
"  %%#     index (of @RG in the header, or count of TAG values seen so far)\n"
"  %%!     @RG ID or TAG value\n"
"  %%.     filename extension for output format\n");
}

static char *expand_format(const char *fmt, const char *basename, int idx, int pad, const char *id, const char *ext) {
    kstring_t ks = KS_INITIALIZE;
    for (const char *p = fmt; *p; p++) {
        if (*p != '%') { kputc(*p, &ks); continue; }
        p++;
        switch (*p) {
        case '%': kputc('%', &ks); break;
        case '*': kputs(basename, &ks); break;
        case '#': { char buf[32]; snprintf(buf, sizeof buf, "%0*d", pad, idx); kputs(buf, &ks); break; }
        case '!': kputs(id, &ks); break;
        case '.': kputs(ext, &ks); break;
        case 0: p--; break;
        default: kputc('%', &ks); kputc(*p, &ks); break;
        }
    }
    return ks.s;
}

typedef struct { samfile_t *fp; char *fn; sam_hdr_t *hdr; } outfile_t;

int main_split(int argc, char **argv) {
    sam_global_args ga = SAM_GLOBAL_ARGS_INIT;
    const char *fmt = NULL, *unaccounted = NULL, *un_hdr = NULL, *tag = NULL;
    int verbose = 0, no_pg = 0, pad = 0, max_split = 100, c;
    static const struct option lopts[] = {
        { "max-split", required_argument, NULL, 'M' }, { "no-PG", no_argument, NULL, 1 },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "output-fmt", required_argument, NULL, 1003 }, { "output-fmt-option", required_argument, NULL, 1004 },
        { "reference", required_argument, NULL, 1005 }, { "threads", required_argument, NULL, '@' }, { "write-index", no_argument, NULL, 1007 }, { "verbosity", required_argument, NULL, 1008 }, { NULL, 0, NULL, 0 }
