        else if (val >= INT16_MIN) { field[2] = 's'; int16_t v = (int16_t)val; memcpy(field + 3, &v, 2); len = 5; }
        else { field[2] = 'i'; int32_t v = (int32_t)val; memcpy(field + 3, &v, 4); len = 7; }
    } else {
        if (val <= UINT8_MAX) { field[2] = 'C'; uint8_t v = (uint8_t)val; field[3] = v; len = 4; }
        else if (val <= UINT16_MAX) { field[2] = 'S'; uint16_t v = (uint16_t)val; memcpy(field + 3, &v, 2); len = 5; }
        else { field[2] = 'I'; uint32_t v = (uint32_t)val; memcpy(field + 3, &v, 4); len = 7; }
    }
    return aux_replace(b, s, field, len);
}

int bam_aux_update_str(bam1_t *b, const char tag[2], int len, const char *data) {
    int dlen = (len > 0 && data[len-1] == 0) ? len - 1 : len;
    uint8_t *s = bam_aux_get(b, tag);
    if (!s) {
        if (bam_set_data_cap(b, b->l_data + 4 + dlen) < 0) return -1;
        uint8_t *p = b->data + b->l_data;
        p[0] = tag[0]; p[1] = tag[1]; p[2] = 'Z'; memcpy(p + 3, data, dlen); p[3 + dlen] = 0;
