    field[0] = tag[0]; field[1] = tag[1]; field[2] = 'Z'; memcpy(field + 3, data, dlen); field[3 + dlen] = 0;
    int r = aux_replace(b, s, field, 4 + dlen);
    free(field);
    return r;
