int bam_aux_update_float(bam1_t *b, const char tag[2], float val) {
    uint8_t *s = bam_aux_get(b, tag);
    if (!s) return bam_aux_append(b, tag, 'f', 4, (uint8_t*)&val);
    uint8_t field[7]; field[0] = tag[0]; field[1] = tag[1]; field[2] = 'f'; memcpy(field + 3, &val, 4);
    return aux_replace(b, s, field, 7);
}

