#include "sanitize.h"
#include "samtools.h"
#include <string.h>
#include <strings.h>

int bam_sanitize_options(const char *str) {
    int opt = 0;
    const char *p = str;
    while (*p) {
        const char *e = strchr(p, ','); size_t l = e ? (size_t)(e - p) : strlen(p);
        if (l == 3 && strncasecmp(p, "all", 3) == 0) opt |= FIX_ALL;
        else if (l == 4 && strncasecmp(p, "none", 4) == 0) opt = 0;
        else if (l == 3 && strncasecmp(p, "off", 3) == 0) opt = 0;
        else if (l == 3 && strncasecmp(p, "pos", 3) == 0) opt |= FIX_POS;
        else if (l == 5 && strncasecmp(p, "mqual", 5) == 0) opt |= FIX_MQUAL;
        else if (l == 5 && strncasecmp(p, "unmap", 5) == 0) opt |= FIX_UNMAP;
        else if (l == 5 && strncasecmp(p, "cigar", 5) == 0) opt |= FIX_CIGAR;
        else if (l == 3 && strncasecmp(p, "aux", 3) == 0) opt |= FIX_AUX;
        else if (l == 6 && strncasecmp(p, "cigdup", 6) == 0) opt |= FIX_CIGDUP;
        else if (l == 6 && strncasecmp(p, "cigarx", 6) == 0) opt |= FIX_CIGARX;
        else { print_error("sanitize", "Unrecognised keyword %.*s", (int)l, p); return -1; }
        if (!e) break;
        p = e + 1;
    }
    return opt;
}

int bam_sanitize(sam_hdr_t *h, bam1_t *b, int flags) {
    if (flags & FIX_POS) {
        if (b->core.tid < 0 || b->core.pos < 0) { b->core.flag |= BAM_FUNMAP; b->core.tid = -1; b->core.pos = -1; }
        else if (b->core.tid < h->n_targets && b->core.pos >= sam_hdr_tid2len(h, b->core.tid) && !(b->core.flag & BAM_FUNMAP)) {
            b->core.flag |= BAM_FUNMAP; b->core.tid = -1; b->core.pos = -1;
        }
        if (b->core.mtid < 0 || b->core.mpos < 0) { b->core.mtid = -1; b->core.mpos = -1; }
    }
    if ((flags & FIX_UNMAP) && (b->core.flag & BAM_FUNMAP)) {
        if (flags & FIX_MQUAL) b->core.qual = 0;
        if (flags & FIX_CIGAR) { if (b->core.n_cigar) bam_set_cigar(b, NULL, 0); }
    }
    if ((flags & FIX_CIGAR) && !(b->core.flag & BAM_FUNMAP) && b->core.n_cigar && b->core.tid >= 0 && b->core.tid < h->n_targets) {
        int64_t rlen = sam_hdr_tid2len(h, b->core.tid);
        int64_t pos = b->core.pos;
        uint32_t *c = bam_get_cigar(b); uint32_t n = b->core.n_cigar;
        uint32_t *nc = malloc((n + 2) * 4); uint32_t j = 0; uint32_t sclip = 0; int beyond = 0;
        for (uint32_t i = 0; i < n; i++) {
            int op = bam_cigar_op(c[i]); uint32_t l = bam_cigar_oplen(c[i]);
            if (beyond) {
                if (op == BAM_CHARD_CLIP) { if (sclip) { nc[j++] = bam_cigar_gen(sclip, BAM_CSOFT_CLIP); sclip = 0; } nc[j++] = c[i]; }
                else sclip += l;
                continue;
            }
            int consumes_ref = (bam_cigar_type(op) & 2) != 0;
            if (consumes_ref && pos + l > rlen) {
                uint32_t keep = rlen > pos ? (uint32_t)(rlen - pos) : 0;
                if (keep && (op == BAM_CMATCH || op == BAM_CEQUAL || op == BAM_CDIFF || op == BAM_CDEL || op == BAM_CREF_SKIP)) nc[j++] = bam_cigar_gen(keep, op);
                sclip += l - keep;
                beyond = 1;
                pos += l;
                continue;
            }
            nc[j++] = c[i];
            if (consumes_ref) pos += l;
        }
        if (sclip) nc[j++] = bam_cigar_gen(sclip, BAM_CSOFT_CLIP);
        if (beyond) {
            /* merge adjacent identical ops */
            uint32_t k = 0;
            for (uint32_t i = 0; i < j; i++) { if (k > 0 && bam_cigar_op(nc[k-1]) == bam_cigar_op(nc[i])) nc[k-1] = bam_cigar_gen(bam_cigar_oplen(nc[k-1]) + bam_cigar_oplen(nc[i]), bam_cigar_op(nc[i])); else nc[k++] = nc[i]; }
            bam_set_cigar(b, nc, k);
        }
        free(nc);
    }
    if ((flags & FIX_CIGDUP) && b->core.n_cigar > 1) {
        uint32_t *c = bam_get_cigar(b); uint32_t n = b->core.n_cigar, j = 0;
        uint32_t *nc = malloc(n * 4);
        for (uint32_t i = 0; i < n; i++) {
            if (j > 0 && bam_cigar_op(nc[j-1]) == bam_cigar_op(c[i])) nc[j-1] = bam_cigar_gen(bam_cigar_oplen(nc[j-1]) + bam_cigar_oplen(c[i]), bam_cigar_op(c[i]));
            else nc[j++] = c[i];
        }
        if (j != n) bam_set_cigar(b, nc, j);
        free(nc);
    }
    if ((flags & FIX_CIGARX) && b->core.n_cigar) {
        uint32_t *c = bam_get_cigar(b);
        for (uint32_t i = 0; i < b->core.n_cigar; i++) if (bam_cigar_op(c[i]) == BAM_CEQUAL || bam_cigar_op(c[i]) == BAM_CDIFF) c[i] = bam_cigar_gen(bam_cigar_oplen(c[i]), BAM_CMATCH);
        uint32_t n = b->core.n_cigar, j = 0; uint32_t *nc = malloc(n * 4);
        for (uint32_t i = 0; i < n; i++) {
            if (j > 0 && bam_cigar_op(nc[j-1]) == bam_cigar_op(c[i])) nc[j-1] = bam_cigar_gen(bam_cigar_oplen(nc[j-1]) + bam_cigar_oplen(c[i]), bam_cigar_op(c[i]));
            else nc[j++] = c[i];
        }
        if (j != n) bam_set_cigar(b, nc, j);
        free(nc);
    }
    return 0;
}
