#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <errno.h>
#include "samtools.h"
#include "sanitize.h"
#include "log.h"

static void fixmate_usage(FILE *fp) {
    fprintf(fp,
"Usage: samtools fixmate <in.nameSrt.bam> <out.nameSrt.bam>\n"
"Options:\n"
"  -r           Remove unmapped reads and secondary alignments\n"
"  -p           Disable FR proper pair check\n"
"  -c           Add template cigar ct tag\n"
"  -m           Add mate score tag\n"
"  -u           Uncompressed output\n"
"  -z, --sanitize FLAG[,FLAG]\n"
"               Sanitize alignment fields [defaults to all types]\n"
"  -M           Fix base modification tags (MM/ML/MN)\n"
"  --no-PG      do not add a PG line\n");
    sam_global_opt_help(fp, ".-O--@.-");
    fprintf(fp,
"\n"
"As elsewhere in samtools, use '-' as the filename for stdin/stdout. The input\n"
"file must be grouped by read name (e.g. sorted by name). Coordinated sorted\n"
"input is not accepted.\n");
}

static void sync_unmapped_pos_inner(bam1_t *src, bam1_t *dest) {
    if ((dest->core.flag & BAM_FUNMAP) && !(src->core.flag & BAM_FUNMAP)) { dest->core.tid = src->core.tid; dest->core.pos = src->core.pos; }
}

static void sync_mate_inner(bam1_t *src, bam1_t *dest) {
    dest->core.mtid = src->core.tid; dest->core.mpos = src->core.pos;
    if (src->core.flag & BAM_FREVERSE) dest->core.flag |= BAM_FMREVERSE; else dest->core.flag &= ~BAM_FMREVERSE;
    if (src->core.flag & BAM_FUNMAP) dest->core.flag |= BAM_FMUNMAP;
    /* MQ and MC */
    if (!(src->core.flag & BAM_FUNMAP)) bam_aux_update_int32(dest, "MQ", src->core.qual);
    else { uint8_t *p = bam_aux_get(dest, "MQ"); if (p) bam_aux_del(dest, p); }
    kstring_t ks = KS_INITIALIZE;
    if (src->core.flag & BAM_FUNMAP) kputc('*', &ks); else bam_cigar_str(src, &ks);
    bam_aux_update_str(dest, "MC", (int)ks.l + 1, ks.s);
    free(ks.s);
}

static void sync_mate(bam1_t *a, bam1_t *b) {
    sync_unmapped_pos_inner(a, b); sync_unmapped_pos_inner(b, a);
    sync_mate_inner(a, b); sync_mate_inner(b, a);
}

static int plausibly_properly_paired(bam1_t *a, bam1_t *b) {
    if ((a->core.flag & BAM_FUNMAP) || (b->core.flag & BAM_FUNMAP)) return 0;
    if (a->core.tid != b->core.tid) return 0;
    bam1_t *first = a, *second = b;
    int64_t a_pos = (a->core.flag & BAM_FREVERSE) ? bam_endpos(a) : a->core.pos;
    int64_t b_pos = (b->core.flag & BAM_FREVERSE) ? bam_endpos(b) : b->core.pos;
    if (a_pos > b_pos) { first = b; second = a; }
    if (!(first->core.flag & BAM_FREVERSE) && (second->core.flag & BAM_FREVERSE)) return 1;
    return 0;
}

static void bam_template_cigar(bam1_t *b1, bam1_t *b2, kstring_t *str) {
    str->l = 0;
    if (b1->core.tid != b2->core.tid || b1->core.tid < 0 || b1->core.pos < 0 || b2->core.pos < 0 || (b1->core.flag & BAM_FUNMAP) || (b2->core.flag & BAM_FUNMAP)) return;
    if (b1->core.pos > b2->core.pos) { bam1_t *t = b1; b1 = b2; b2 = t; }
    kputw((b1->core.flag & BAM_FREAD1) ? 1 : 2, str); kputc((b1->core.flag & BAM_FREVERSE) ? 'R' : 'F', str);
    bam_cigar_str(b1, str);
    int64_t end = bam_endpos(b1);
    kputl(b2->core.pos - end, str); kputc('T', str);
    kputw((b2->core.flag & BAM_FREAD1) ? 1 : 2, str); kputc((b2->core.flag & BAM_FREVERSE) ? 'R' : 'F', str);
    bam_cigar_str(b2, str);
    bam_aux_update_str(b1, "ct", (int)str->l + 1, str->s);
}

static uint32_t calc_mate_score(bam1_t *b) {
    uint32_t score = 0; uint8_t *qual = bam_get_qual(b);
    for (int i = 0; i < b->core.l_qseq; i++) if (qual[i] >= 15) score += qual[i];
    return score;
}

static void add_mate_score(bam1_t *src, bam1_t *dest) {
    uint32_t ms = calc_mate_score(src);
    bam_aux_update_int32(dest, "ms", (int32_t)ms);
}

static void clear_unpaired(bam1_t *pre) {
    if (pre->core.tid < 0 || pre->core.pos < 0 || (pre->core.flag & BAM_FUNMAP)) { pre->core.flag |= BAM_FUNMAP; pre->core.tid = -1; pre->core.pos = -1; }
    pre->core.mtid = -1; pre->core.mpos = -1; pre->core.isize = 0;
    pre->core.flag &= ~(BAM_FMREVERSE | BAM_FPROPER_PAIR);
}

int bam_fixmate(int argc, char **argv) {
    sam_global_args ga = SAM_GLOBAL_ARGS_INIT;
    int c, remove_reads = 0, proper_pair_check = 1, add_ct = 0, mate_score = 0, no_pg = 0, sanitize = FIX_ALL, base_mod = 0;
    static const struct option lopts[] = {
        { "no-PG", no_argument, NULL, 1 }, { "sanitize", required_argument, NULL, 'z' },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "output-fmt", required_argument, NULL, 1003 }, { "output-fmt-option", required_argument, NULL, 1004 },
        { "reference", required_argument, NULL, 1005 }, { "threads", required_argument, NULL, '@' }, { "verbosity", required_argument, NULL, 1008 }, { NULL, 0, NULL, 0 }
    };
