        case 'p': proper_pair_check = 0; break;
        case 'c': add_ct = 1; break;
        case 'm': mate_score = 1; break;
        case 'u': ga.out_level = 0; break;
        case 'z': sanitize = bam_sanitize_options(optarg); if (sanitize < 0) return 1; break;
        case 'M': base_mod = 1; break;
