    if (!in) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn_in, strerror(errno)); print_error_errno("fixmate", "cannot open input file"); return 1; }
    if (sam_read_header(in) < 0) { print_error("fixmate", "cannot read header"); sam_close(in); return 1; }
    sam_hdr_t *h = in->hdr;
    if (ga.out_fmt == 0 && strcmp(fn_out, "-") == 0) ga.out_fmt = FMT_BAM;
    samfile_t *out = sam_open_output(fn_out, "w", &ga, 0);
