                if (remove_reads) {
                    if (pre->core.flag & BAM_FUNMAP) cur->core.flag &= ~(BAM_FPAIRED | BAM_FMREVERSE | BAM_FPROPER_PAIR);
                    if (cur->core.flag & BAM_FUNMAP) pre->core.flag &= ~(BAM_FPAIRED | BAM_FMREVERSE | BAM_FPROPER_PAIR);
