            }
            int consumes_ref = (bam_cigar_type(op) & 2) != 0;
            if (consumes_ref && pos + l > rlen) {
                uint32_t keep = rlen > pos ? (uint32_t)(rlen - pos) : 0;
                if (keep && (op == BAM_CMATCH || op == BAM_CEQUAL || op == BAM_CDIFF || op == BAM_CDEL || op == BAM_CREF_SKIP)) nc[j++] = bam_cigar_gen(keep, op);
