        /* sequence-start based: use starts for forward, ends for reverse of each read */
        if (leftmost) {
            if (bam_is_rev(b) == bam_is_mrev(b)) { orientation = bam_is_rev(b) ? ((b->core.flag & BAM_FREAD1) ? O_RR : O_FF) : ((b->core.flag & BAM_FREAD1) ? O_FF : O_RR); if (bam_is_rev(b)) { this_coord = this_end; other_coord = other_end; } }
            else { if (!bam_is_rev(b)) { orientation = O_FR; other_coord = other_end; } else { orientation = O_RF; this_coord = this_end; } }
        } else {
            if (bam_is_rev(b) == bam_is_mrev(b)) { orientation = bam_is_rev(b) ? ((b->core.flag & BAM_FREAD1) ? O_FF : O_RR) : ((b->core.flag & BAM_FREAD1) ? O_RR : O_FF); if (bam_is_rev(b)) { this_coord = this_end; other_coord = other_end; } }
            else { if (!bam_is_rev(b)) { orientation = O_RF; other_coord = other_end; } else { orientation = O_FR; this_coord = this_end; } }
        }
    } else if (leftmost) {
        if (bam_is_rev(b) == bam_is_mrev(b)) {
            other_coord = other_end;
            if (!bam_is_rev(b)) orientation = (b->core.flag & BAM_FREAD1) ? O_FF : O_RR;
            else orientation = (b->core.flag & BAM_FREAD1) ? O_RR : O_FF;
        } else {
            if (!bam_is_rev(b)) { orientation = O_FR; other_coord = other_end; }
            else { orientation = O_RF; this_coord = this_end; }
        }
    } else {
        if (bam_is_rev(b) == bam_is_mrev(b)) {
            this_coord = this_end;
            if (!bam_is_rev(b)) orientation = (b->core.flag & BAM_FREAD1) ? O_RR : O_FF;
            else orientation = (b->core.flag & BAM_FREAD1) ? O_FF : O_RR;
        } else {
            if (!bam_is_rev(b)) { orientation = O_RF; other_coord = other_end; }
            else { orientation = O_FR; this_coord = this_end; }
        }
    }
    key->single = 0; key->this_ref = this_ref; key->this_coord = this_coord; key->other_ref = other_ref; key->other_coord = other_coord;
    key->leftmost = leftmost ? 1 : 0; key->orientation = orientation;
    return 0;
}

static void make_single_key(key_data_t *key, bam1_t *b) {
    key->single = 1; key->this_ref = b->core.tid + 1; key->other_ref = 0; key->other_coord = 0; key->leftmost = 0;
    if (bam_is_rev(b)) { key->this_coord = unclipped_end(b); key->orientation = O_RR; }
    else { key->this_coord = unclipped_start(b); key->orientation = O_FF; }
}

static void key_str(const key_data_t *k, const char *extra, char *out, size_t sz) {
    snprintf(out, sz, "%d:%d:%lld:%d:%lld:%d:%d:%s", k->single, k->this_ref, (long long)k->this_coord, k->other_ref, (long long)k->other_coord, k->leftmost, k->orientation, extra ? extra : "");
}

static void markdup_usage(FILE *fp) {
    fprintf(fp,
"\n"
"Usage:  samtools markdup <input.bam> <output.bam>\n\n"
"Option: \n"
"  -r                 Remove duplicate reads\n"
"  -l INT             Max read length (default 300 bases)\n"
"  -S                 Mark supplementary alignments of duplicates as duplicates (slower).\n"
"  -s                 Report stats.\n"
"  -f NAME            Write stats to named file.  Implies -s.\n"
"  --json             Output stats in JSON.  Also implies -s\n"
"  -T PREFIX          Write temporary files to PREFIX.samtools.nnnn.nnnn.tmp.\n"
"  -d INT             Optical distance (if set, marks with dt tag)\n"
"  -c                 Clear previous duplicate settings and tags.\n"
"  -m --mode TYPE     Duplicate decision method for paired reads.\n"
"                     TYPE = t measure positions based on template start/end (default).\n"
"                            s measure positions based on sequence start.\n"
"  -u                 Output uncompressed data\n"
"  --include-fails    Include quality check failed reads.\n"
"  --no-PG            Do not add a PG line\n"
"  --no-multi-dup     Reduced duplicates of duplicates checking.\n"
"  --read-coords STR  Regex for coords from read name.\n"
"  --coords-order STR Order of regex elements. txy (default).  With t being a part of\n"
"                     the read names that must be equal and x/y being coordinates.\n"
"  --barcode-tag STR  Use barcode a tag that duplicates much match.\n"
"  --barcode-name     Use the UMI/barcode in the read name (eigth colon delimited part).\n"
"  --barcode-rgx STR  Regex for barcode in the readname (alternative to --barcode-name).\n"
"  --use-read-groups  Use the read group tags in duplicate matching.\n"
"  -t                 Mark primary duplicates with the name of the original in a 'do' tag. Mainly for information and debugging.\n"
"  --duplicate-count  Record the original primary read duplication count(include itself) in a 'dc' tag.\n");
    sam_global_opt_help(fp, ".-O--@--");
    fprintf(fp, "\nThe input file must be coordinate sorted and must have gone through fixmates with the mate scoring option on.\n");
}

/* optical duplicate check: parse name for x,y coordinates (last two colon fields) */
static int get_coordinates(const char *name, long *x, long *y, char *tile, size_t tsz) {
    /* expect ...:x:y at end, tile = everything before the x */
    const char *end = name + strlen(name);
    const char *p = end;
    while (p > name && p[-1] != ':') p--;
    if (p == name) return -1;
    char *e; long yy = strtol(p, &e, 10); if (e != end) return -1;
    const char *q = p - 1; while (q > name && q[-1] != ':') q--;
    if (q == name) return -1;
    long xx = strtol(q, &e, 10); if (e != p - 1) return -1;
    size_t tl = (size_t)(q - 1 - name); if (tl >= tsz) tl = tsz - 1;
    memcpy(tile, name, tl); tile[tl] = 0;
    *x = xx; *y = yy;
    return 0;
}

static int is_optical(bam1_t *a, bam1_t *b, int dist) {
    long ax, ay, bx, by; char ta[256], tb[256];
    if (get_coordinates(bam_get_qname(a), &ax, &ay, ta, sizeof ta) < 0) return 0;
    if (get_coordinates(bam_get_qname(b), &bx, &by, tb, sizeof tb) < 0) return 0;
    if (strcmp(ta, tb) != 0) return 0;
    long dx = labs(ax - bx), dy = labs(ay - by);
    return dx <= dist && dy <= dist;
}

static long estimate_library_size(long paired_reads, long paired_duplicate_reads, long optical) {
    long estimated_size = 0;
    long read_pairs = paired_reads / 2, duplicate_pairs = paired_duplicate_reads / 2 - optical / 2;
    long unique_read_pairs = read_pairs - duplicate_pairs;
    if (read_pairs > duplicate_pairs && duplicate_pairs > 0) {
        double m = 1.0, M = 100.0;
#define F(x, c, n) ((c) / (x) - 1 + exp(-(n) / (x)))
        double c = unique_read_pairs, n = read_pairs;
        if (F(M * c, c, n) > 0) { while (F(M * c, c, n) > 0) M *= 10.0; }
        for (int i = 0; i < 40; i++) {
            double r = (m + M) / 2.0;
            double u = F(r * c, c, n);
            if (u == 0) break;
            else if (u > 0) m = r;
            else M = r;
        }
        estimated_size = (long)(c * (m + M) / 2.0);
#undef F
    } else {
        fprintf(stderr, "samtools markdup: warning, unable to calculate estimated library size. Read pairs %ld should be greater than duplicate pairs %ld, which should both be non zero.\n", read_pairs, duplicate_pairs);
    }
    return estimated_size;
}

int bam_markdup(int argc, char **argv) {
    sam_global_args ga = SAM_GLOBAL_ARGS_INIT;
    int c, remove_dups = 0, max_length = 300, supp = 0, do_stats = 0, json = 0, opt_dist = 0, clear = 0, mode_seq = 0, include_fails = 0, no_pg = 0, no_multi = 0, tag_orig = 0, dup_count = 0, use_rg = 0;
    const char *stats_file = NULL, *barcode_tag = NULL;
    static const struct option lopts[] = {
        { "json", no_argument, NULL, 1 }, { "mode", required_argument, NULL, 'm' }, { "include-fails", no_argument, NULL, 2 }, { "no-PG", no_argument, NULL, 3 },
        { "no-multi-dup", no_argument, NULL, 4 }, { "read-coords", required_argument, NULL, 5 }, { "coords-order", required_argument, NULL, 6 }, { "barcode-tag", required_argument, NULL, 7 },
        { "barcode-name", no_argument, NULL, 8 }, { "barcode-rgx", required_argument, NULL, 9 }, { "use-read-groups", no_argument, NULL, 10 }, { "duplicate-count", no_argument, NULL, 11 },
        { "input-fmt-option", required_argument, NULL, 1002 }, { "output-fmt", required_argument, NULL, 1003 }, { "output-fmt-option", required_argument, NULL, 1004 },
        { "reference", required_argument, NULL, 1005 }, { "threads", required_argument, NULL, '@' }, { "write-index", no_argument, NULL, 1007 }, { "verbosity", required_argument, NULL, 1008 }, { NULL, 0, NULL, 0 }
    };
    opterr = 0;
    while ((c = getopt_long(argc, argv, "rsl:StT:O:@:f:d:cm:u", lopts, NULL)) >= 0) {
        switch (c) {
        case 'r': remove_dups = 1; break;
        case 's': do_stats = 1; break;
        case 'l': max_length = atoi(optarg); break;
        case 'S': supp = 1; break;
        case 't': tag_orig = 1; break;
        case 'T': break;
        case 'f': stats_file = optarg; do_stats = 1; break;
        case 'd': opt_dist = atoi(optarg); break;
        case 'c': clear = 1; break;
        case 'm': if (strcmp(optarg, "s") == 0) mode_seq = 1; else if (strcmp(optarg, "t") == 0) mode_seq = 0; else { print_error("markdup", "error, unknown mode '%s'.\n", optarg); markdup_usage(stderr); return 1; } break;
        case 'u': ga.out_level = 0; break;
        case 1: json = 1; do_stats = 1; break;
        case 2: include_fails = 1; break;
        case 3: no_pg = 1; break;
        case 4: no_multi = 1; break;
        case 5: case 6: case 9: break;
        case 7: barcode_tag = optarg; break;
        case 8: break;
        case 10: use_rg = 1; break;
        case 11: dup_count = 1; break;
        case 'O': c = 1003; /* fallthrough */
        case 1002: case 1003: case 1004: case 1005: case 1008: if (parse_sam_global_opt(c, optarg, NULL, &ga) < 0) { markdup_usage(stderr); return 1; } break;
        case '@': ga.nthreads = atoi(optarg); break;
        case 1007: ga.write_index = 1; break;
        default:
            if (optopt) fprintf(stderr, "markdup: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "markdup: unrecognized option '%s'\n", argv[optind-1]);
            markdup_usage(stderr); return 1;
        }
    }
    (void)no_multi; (void)barcode_tag;
    if (optind + 2 > argc) { markdup_usage(stderr); return 1; }
    const char *fn_in = argv[optind], *fn_out = argv[optind + 1];
    samfile_t *in = sam_open_read_nohdr(fn_in);
    if (!in) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn_in, strerror(errno)); print_error_errno("markdup", "error, cannot open \"%s\" for reading", fn_in); return 1; }
    if (sam_read_header(in) < 0) { print_error("markdup", "error, cannot read header"); sam_close(in); return 1; }
    sam_hdr_t *h = in->hdr;
    if (ga.out_fmt == 0 && strcmp(fn_out, "-") == 0) ga.out_fmt = FMT_BAM;
    samfile_t *out = sam_open_output(fn_out, "w", &ga, 0);
    if (!out) { log_error("hts_open_format", "Failed to open file \"%s\" : %s", fn_out, strerror(errno)); print_error_errno("markdup", "error, cannot open \"%s\" for writing", fn_out); sam_close(in); return 1; }
    char *arg_list = stringify_argv(argc + 1, argv - 1);
    if (!no_pg) sam_hdr_add_pg(h, "samtools", samtools_version(), arg_list, NULL);
    int ret = 0;
    if (sam_write_hdr(out, h) < 0) { print_error_errno("markdup", "error writing header"); ret = 1; goto end; }
    {
        stats_t st; memset(&st, 0, sizeof st);
        strmap_t *pair_hash = strmap_new(), *single_hash = strmap_new();
        read_entry_t *head = NULL, *tail = NULL;
        bam1_t *b = bam_init1(); int r;
        int at_eof = 0;
        while (!at_eof) {
            r = sam_read1(in, h, b);
            if (r < -1) { print_error("markdup", "error reading input"); ret = 1; break; }
            at_eof = r < 0;
            /* flush */
            while (head && (at_eof || head->b->core.tid != b->core.tid || head->b->core.pos + max_length < b->core.pos)) {
                read_entry_t *e = head; head = e->next; if (!head) tail = NULL;
                if (e->in_pair_hash) { strmap_entry_t *x = strmap_find(pair_hash, e->pkey); if (x && x->ptr == e) strmap_del(pair_hash, e->pkey); }
                if (e->in_single_hash) { strmap_entry_t *x = strmap_find(single_hash, e->skey); if (x && x->ptr == e) strmap_del(single_hash, e->skey); }
                if (e->is_dup) e->b->core.flag |= BAM_FDUP;
                if (dup_count && e->examined && !e->is_dup && e->dup_count > 0) bam_aux_update_int(e->b, "dc", e->dup_count);
                if (!(remove_dups && (e->b->core.flag & BAM_FDUP))) {
                    if (sam_write1(out, h, e->b) < 0) { print_error_errno("markdup", "error writing output"); ret = 1; }
                    st.writing++;
                }
                bam_destroy1(e->b); free(e);
            }
            if (at_eof || ret) break;
            st.reading++;
            read_entry_t *e = calloc(1, sizeof(read_entry_t));
            e->b = bam_dup1(b);
            if (clear) {
                e->b->core.flag &= ~BAM_FDUP;
                uint8_t *t;
                if ((t = bam_aux_get(e->b, "dt"))) bam_aux_del(e->b, t);
                if ((t = bam_aux_get(e->b, "do"))) bam_aux_del(e->b, t);
                if ((t = bam_aux_get(e->b, "dc"))) bam_aux_del(e->b, t);
            }
            if (tail) tail->next = e; else head = e; tail = e;
            int flag = e->b->core.flag;
            if ((flag & (BAM_FSECONDARY | BAM_FSUPPLEMENTARY | BAM_FUNMAP)) || (!include_fails && (flag & BAM_FQCFAIL))) { st.excluded++; e->excluded = 1; continue; }
            e->examined = 1;
            char extra[256] = "";
            if (use_rg) { uint8_t *rg = bam_aux_get(e->b, "RG"); if (rg && *rg == 'Z') snprintf(extra, sizeof extra, "%s", (char*)rg + 1); }
            key_data_t pk, sk;
            make_single_key(&sk, e->b); key_str(&sk, extra, e->skey, sizeof e->skey);
            if ((flag & BAM_FPAIRED) && !(flag & BAM_FMUNMAP)) {
                st.pair++;
                e->paired = 1;
                if (make_pair_key(&pk, e->b, mode_seq)) { print_error("markdup", "error, unable to assign pair hash key."); ret = 1; break; }
                key_str(&pk, extra, e->pkey, sizeof e->pkey);
                uint8_t *ms = bam_aux_get(e->b, "ms");
                if (!ms) { print_error("markdup", "error, no ms score tag. Please run samtools fixmate on file first.\n"); ret = 1; break; }
                e->score = calc_score(e->b) + bam_aux2i(ms);
                int is_new; strmap_entry_t *x = strmap_put(pair_hash, e->pkey, &is_new);
                if (is_new) { x->ptr = e; e->in_pair_hash = 1; e->dup_count = 1; }
                else {
                    read_entry_t *bp = x->ptr;
                    read_entry_t *dup;
                    if (e->score > bp->score) { dup = bp; bp->in_pair_hash = 0; x->ptr = e; e->in_pair_hash = 1; e->dup_count = bp->dup_count + 1; }
                    else { dup = e; bp->dup_count++; }
                    read_entry_t *orig = (dup == e) ? bp : e;
                    dup->is_dup = 1; st.pair_dup++;
                    if (tag_orig) bam_aux_update_str(dup->b, "do", (int)strlen(bam_get_qname(orig->b)) + 1, bam_get_qname(orig->b));
                    if (opt_dist) {
                        int opt = is_optical(dup->b, orig->b, opt_dist);
                        if (opt) { st.optical++; bam_aux_update_str(dup->b, "dt", 3, "SQ"); } else bam_aux_update_str(dup->b, "dt", 3, "LB");
                    }
                }
                /* single hash: pairs beat singles */
                x = strmap_put(single_hash, e->skey, &is_new);
                if (is_new) { x->ptr = e; e->in_single_hash = 1; }
                else {
                    read_entry_t *bp = x->ptr;
                    if (!bp->paired) {
                        if (!bp->is_dup) { bp->is_dup = 1; st.single_dup++; if (tag_orig) bam_aux_update_str(bp->b, "do", (int)strlen(bam_get_qname(e->b)) + 1, bam_get_qname(e->b)); if (opt_dist) { int opt = is_optical(bp->b, e->b, opt_dist); if (opt) { st.single_optical++; bam_aux_update_str(bp->b, "dt", 3, "SQ"); } else bam_aux_update_str(bp->b, "dt", 3, "LB"); } }
                        bp->in_single_hash = 0; x->ptr = e; e->in_single_hash = 1;
                        if (dup_count) e->dup_count += bp->dup_count ? bp->dup_count : 1;
                    }
                }
            } else {
                st.single++;
                e->score = calc_score(e->b);
                int is_new; strmap_entry_t *x = strmap_put(single_hash, e->skey, &is_new);
                if (is_new) { x->ptr = e; e->in_single_hash = 1; e->dup_count = 1; }
                else {
                    read_entry_t *bp = x->ptr;
                    read_entry_t *dup, *orig;
                    if (bp->paired) { dup = e; orig = bp; bp->dup_count++; }
                    else if (e->score > bp->score) { dup = bp; orig = e; bp->in_single_hash = 0; x->ptr = e; e->in_single_hash = 1; e->dup_count = bp->dup_count + 1; }
                    else { dup = e; orig = bp; bp->dup_count++; }
                    dup->is_dup = 1; st.single_dup++;
                    if (tag_orig) bam_aux_update_str(dup->b, "do", (int)strlen(bam_get_qname(orig->b)) + 1, bam_get_qname(orig->b));
                    if (opt_dist) { int opt = is_optical(dup->b, orig->b, opt_dist); if (opt) { st.single_optical++; bam_aux_update_str(dup->b, "dt", 3, "SQ"); } else bam_aux_update_str(dup->b, "dt", 3, "LB"); }
                }
            }
        }
        /* flush remaining */
        while (head) {
            read_entry_t *e = head; head = e->next;
            if (e->is_dup) e->b->core.flag |= BAM_FDUP;
            if (dup_count && e->examined && !e->is_dup && e->dup_count > 0) bam_aux_update_int(e->b, "dc", e->dup_count);
            if (!ret && !(remove_dups && (e->b->core.flag & BAM_FDUP))) { if (sam_write1(out, h, e->b) < 0) { ret = 1; } st.writing++; }
            bam_destroy1(e->b); free(e);
        }
        bam_destroy1(b);
        strmap_free(pair_hash); strmap_free(single_hash);
        (void)supp;
        if (do_stats && !ret) {
            long examined = st.reading - st.excluded;
            long est = estimate_library_size(st.pair, st.pair_dup, st.optical);
            FILE *fp = stderr;
            if (stats_file) { fp = fopen(stats_file, "w"); if (!fp) { print_error_errno("markdup", "error, cannot write stats file \"%s\"", stats_file); fp = stderr; } }
            if (json) {
                fprintf(fp, "{\n    \"COMMAND\": \"%s\",\n    \"READ\": %ld,\n    \"WRITTEN\": %ld,\n    \"EXCLUDED\": %ld,\n    \"EXAMINED\": %ld,\n    \"PAIRED\": %ld,\n    \"SINGLE\": %ld,\n    \"DUPLICATE PAIR\": %ld,\n    \"DUPLICATE SINGLE\": %ld,\n    \"DUPLICATE PAIR OPTICAL\": %ld,\n    \"DUPLICATE SINGLE OPTICAL\": %ld,\n    \"DUPLICATE NON PRIMARY\": %ld,\n    \"DUPLICATE NON PRIMARY OPTICAL\": %ld,\n    \"DUPLICATE PRIMARY TOTAL\": %ld,\n    \"DUPLICATE TOTAL\": %ld,\n    \"ESTIMATED_LIBRARY_SIZE\": %ld\n}\n",
                        arg_list, st.reading, st.writing, st.excluded, examined, st.pair, st.single, st.pair_dup, st.single_dup, st.optical, st.single_optical, st.np_duplicate, st.np_opt_duplicate, st.pair_dup + st.single_dup, st.pair_dup + st.single_dup + st.np_duplicate, est);
            } else {
                fprintf(fp, "\nCOMMAND: %s\nREAD: %ld\nWRITTEN: %ld\nEXCLUDED: %ld\nEXAMINED: %ld\nPAIRED: %ld\nSINGLE: %ld\nDUPLICATE PAIR: %ld\nDUPLICATE SINGLE: %ld\nDUPLICATE PAIR OPTICAL: %ld\nDUPLICATE SINGLE OPTICAL: %ld\nDUPLICATE NON PRIMARY: %ld\nDUPLICATE NON PRIMARY OPTICAL: %ld\nDUPLICATE PRIMARY TOTAL: %ld\nDUPLICATE TOTAL: %ld\nESTIMATED_LIBRARY_SIZE: %ld\n",
                        arg_list, st.reading, st.writing, st.excluded, examined, st.pair, st.single, st.pair_dup, st.single_dup, st.optical, st.single_optical, st.np_duplicate, st.np_opt_duplicate, st.pair_dup + st.single_dup, st.pair_dup + st.single_dup + st.np_duplicate, est);
            }
            if (fp != stderr) fclose(fp);
        }
    }
end:
    free(arg_list);
    if (sam_close(out) < 0 && !ret) { print_error_errno("markdup", "error closing output"); ret = 1; }
    sam_close(in); sam_global_args_free(&ga);
    return ret;
}
